-- CanopyProof OS sovereign-grade PostgreSQL contract.
-- This file is intentionally SQL-first because the target architecture uses
-- PostgreSQL schemas as governance boundaries, not only ORM model groupings.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE SCHEMA IF NOT EXISTS identity;
CREATE SCHEMA IF NOT EXISTS organizations;
CREATE SCHEMA IF NOT EXISTS projects;
CREATE SCHEMA IF NOT EXISTS evidence;
CREATE SCHEMA IF NOT EXISTS verification;
CREATE SCHEMA IF NOT EXISTS certificates;
CREATE SCHEMA IF NOT EXISTS satellite;
CREATE SCHEMA IF NOT EXISTS impact;
CREATE SCHEMA IF NOT EXISTS funding;
CREATE SCHEMA IF NOT EXISTS governance;
CREATE SCHEMA IF NOT EXISTS reporting;
CREATE SCHEMA IF NOT EXISTS audit;

CREATE TABLE IF NOT EXISTS identity.participants (
  id text PRIMARY KEY,
  participant_type text NOT NULL CHECK (participant_type IN ('human', 'agent', 'organization', 'device')),
  display_name text NOT NULL,
  owner_id text,
  organization_id text,
  roles text[] NOT NULL DEFAULT ARRAY['observer']::text[],
  verification_status text NOT NULL DEFAULT 'pending',
  reputation_score integer NOT NULL DEFAULT 0 CHECK (reputation_score >= 0),
  credential_commitments text[] NOT NULL DEFAULT ARRAY[]::text[],
  public_key text,
  public_key_hash text,
  subject_hash text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE identity.participants
  ADD COLUMN IF NOT EXISTS owner_id text,
  ADD COLUMN IF NOT EXISTS organization_id text,
  ADD COLUMN IF NOT EXISTS roles text[] NOT NULL DEFAULT ARRAY['observer']::text[],
  ADD COLUMN IF NOT EXISTS verification_status text NOT NULL DEFAULT 'pending',
  ADD COLUMN IF NOT EXISTS credential_commitments text[] NOT NULL DEFAULT ARRAY[]::text[],
  ADD COLUMN IF NOT EXISTS public_key_hash text,
  ADD COLUMN IF NOT EXISTS subject_hash text,
  ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();

CREATE UNIQUE INDEX IF NOT EXISTS identity_participants_subject_hash_unique
  ON identity.participants (subject_hash)
  WHERE subject_hash IS NOT NULL;

CREATE TABLE IF NOT EXISTS identity.reputation_snapshots (
  id text PRIMARY KEY,
  participant_id text NOT NULL REFERENCES identity.participants(id),
  previous_score integer NOT NULL CHECK (previous_score >= 0 AND previous_score <= 100),
  new_score integer NOT NULL CHECK (new_score >= 0 AND new_score <= 100),
  source text NOT NULL CHECK (
    source IN (
      'evidence_contribution',
      'human_review',
      'governance_review',
      'device_attestation',
      'challenge_outcome',
      'manual_adjustment'
    )
  ),
  reason text NOT NULL CHECK (length(btrim(reason)) >= 12),
  recorded_by text NOT NULL REFERENCES identity.participants(id),
  recorded_at timestamptz NOT NULL,
  snapshot_hash text NOT NULL UNIQUE CHECK (snapshot_hash ~ '^[0-9a-f]{64}$'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$')
);

CREATE INDEX IF NOT EXISTS identity_reputation_snapshots_participant_time
  ON identity.reputation_snapshots (participant_id, recorded_at DESC, id DESC);

CREATE TABLE IF NOT EXISTS identity.agent_profiles (
  id text PRIMARY KEY REFERENCES identity.participants(id),
  agent_type text NOT NULL CHECK (agent_type IN ('evidence', 'verification', 'esg', 'funding', 'risk', 'community')),
  layer text NOT NULL CHECK (layer IN ('Evidence', 'Verification', 'Governance', 'Impact')),
  capabilities text[] NOT NULL,
  allowed_actions text[] NOT NULL,
  human_review_required boolean NOT NULL DEFAULT true,
  final_authority boolean NOT NULL DEFAULT false CHECK (final_authority IS false),
  status text NOT NULL CHECK (status IN ('active', 'paused', 'quarantined')),
  registry_hash text NOT NULL
);

CREATE TABLE IF NOT EXISTS identity.device_attestations (
  id text PRIMARY KEY,
  organization_id text NOT NULL,
  subject_id text NOT NULL REFERENCES identity.participants(id),
  subject_root text NOT NULL CHECK (subject_root ~ '^[0-9a-f]{64}$'),
  subject_authority_root text NOT NULL CHECK (subject_authority_root ~ '^[0-9a-f]{64}$'),
  device_fingerprint_hash text NOT NULL,
  consent_receipt_id text NOT NULL,
  consent_receipt_root text NOT NULL CHECK (consent_receipt_root ~ '^[0-9a-f]{64}$'),
  attestation_type text NOT NULL CHECK (attestation_type IN ('secure_enclave', 'webauthn', 'platform_key', 'manual_field_kit', 'sensor_gateway')),
  provider text NOT NULL CHECK (provider IN ('apple_app_attest', 'webauthn', 'android_key_attestation', 'manual_field_kit_registry', 'sensor_gateway_registry')),
  provider_key_id text NOT NULL,
  provider_receipt_hash text NOT NULL CHECK (provider_receipt_hash ~ '^[0-9a-f]{64}$'),
  provider_verification_state text NOT NULL CHECK (provider_verification_state IN ('modeled_only', 'verified')),
  public_key_hash text NOT NULL,
  attestation_hash text NOT NULL,
  reputation_score integer NOT NULL CHECK (reputation_score >= 0 AND reputation_score <= 100),
  risk_flags text[] NOT NULL,
  actor_snapshot jsonb NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  subject_sequence bigint NOT NULL CHECK (subject_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  device_hash text NOT NULL UNIQUE CHECK (device_hash ~ '^[0-9a-f]{64}$'),
  attestation_root text NOT NULL UNIQUE,
  issued_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  created_by text NOT NULL REFERENCES identity.participants(id),
  safety jsonb NOT NULL,
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (subject_id, subject_sequence),
  CHECK (issued_at < expires_at),
  CHECK (jsonb_typeof(actor_snapshot) = 'object'),
  CHECK (jsonb_typeof(safety) = 'object')
);

CREATE TABLE IF NOT EXISTS organizations.organizations (
  id text PRIMARY KEY,
  name text,
  organization_type text NOT NULL CHECK (
    organization_type IN (
      'un_agency',
      'research_institution',
      'ngo',
      'university',
      'government',
      'corporate',
      'community_organization',
      'auditor',
      'investor',
      'restoration_operator',
      'climate_fund',
      'operator'
    )
  ),
  legal_name text NOT NULL,
  jurisdiction text NOT NULL,
  public_contact text,
  operating_regions text[] NOT NULL DEFAULT ARRAY[]::text[],
  verification_capabilities text[] NOT NULL DEFAULT ARRAY[]::text[],
  registration_number text,
  verification_status text NOT NULL DEFAULT 'pending' CHECK (verification_status IN ('pending', 'document_review', 'verified', 'suspended', 'revoked')),
  trust_level text NOT NULL DEFAULT 'unverified' CHECK (trust_level IN ('unverified', 'basic', 'verified', 'institutional', 'suspended')),
  documents jsonb NOT NULL DEFAULT '[]'::jsonb,
  authorized_users jsonb NOT NULL DEFAULT '[]'::jsonb,
  accreditation_status text NOT NULL DEFAULT 'pending',
  data_sharing_policy text NOT NULL DEFAULT 'restricted',
  profile_hash text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE organizations.organizations
  ADD COLUMN IF NOT EXISTS name text,
  ADD COLUMN IF NOT EXISTS public_contact text,
  ADD COLUMN IF NOT EXISTS operating_regions text[] NOT NULL DEFAULT ARRAY[]::text[],
  ADD COLUMN IF NOT EXISTS verification_capabilities text[] NOT NULL DEFAULT ARRAY[]::text[],
  ADD COLUMN IF NOT EXISTS data_sharing_policy text NOT NULL DEFAULT 'restricted',
  ADD COLUMN IF NOT EXISTS profile_hash text;

CREATE UNIQUE INDEX IF NOT EXISTS organizations_profile_hash_unique
  ON organizations.organizations (profile_hash)
  WHERE profile_hash IS NOT NULL;

CREATE TABLE IF NOT EXISTS organizations.roles (
  id text PRIMARY KEY,
  role_name text NOT NULL UNIQUE CHECK (role_name IN ('owner', 'admin', 'verifier', 'researcher', 'community', 'observer')),
  description text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS organizations.permissions (
  id text PRIMARY KEY,
  role_id text NOT NULL REFERENCES organizations.roles(id),
  resource text NOT NULL CHECK (resource IN ('organization', 'membership', 'accreditation', 'data_sharing_agreement', 'evidence', 'report', 'audit')),
  action text NOT NULL CHECK (action IN ('create', 'read', 'update', 'approve', 'challenge', 'export')),
  permission_hash text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (role_id, resource, action)
);

CREATE TABLE IF NOT EXISTS organizations.memberships (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  actor_id text NOT NULL REFERENCES identity.participants(id),
  role text NOT NULL CHECK (role IN ('owner', 'admin', 'verifier', 'researcher', 'community', 'observer')),
  status text NOT NULL CHECK (status IN ('active', 'suspended', 'revoked')),
  conflict_disclosure text NOT NULL,
  granted_by text NOT NULL REFERENCES identity.participants(id),
  granted_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  audit_event_root text NOT NULL,
  UNIQUE (organization_id, actor_id, role)
);

CREATE TABLE IF NOT EXISTS organizations.verification_documents (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  document_type text NOT NULL CHECK (document_type IN ('registration', 'tax', 'accreditation', 'mandate', 'audit_letter', 'other')),
  document_hash text NOT NULL,
  issued_by text,
  uploaded_at timestamptz NOT NULL,
  uploaded_by text NOT NULL REFERENCES identity.participants(id),
  audit_event_root text NOT NULL,
  UNIQUE (organization_id, document_hash)
);

CREATE TABLE IF NOT EXISTS organizations.accreditations (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  status text NOT NULL CHECK (status IN ('pending', 'approved', 'suspended', 'revoked')),
  scope text[] NOT NULL,
  decided_by text NOT NULL REFERENCES identity.participants(id),
  decided_at timestamptz NOT NULL,
  rationale text NOT NULL,
  evidence_hash text NOT NULL,
  audit_event_root text NOT NULL UNIQUE
);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'identity_participants_owner_fk'
      AND conrelid = 'identity.participants'::regclass
  ) THEN
    ALTER TABLE identity.participants
      ADD CONSTRAINT identity_participants_owner_fk
      FOREIGN KEY (owner_id) REFERENCES identity.participants(id)
      DEFERRABLE INITIALLY DEFERRED;
  END IF;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'identity_participants_reputation_score_check'
      AND conrelid = 'identity.participants'::regclass
  ) THEN
    ALTER TABLE identity.participants
      ADD CONSTRAINT identity_participants_reputation_score_check
      CHECK (reputation_score >= 0 AND reputation_score <= 100);
  END IF;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'identity_participants_public_key_hash_check'
      AND conrelid = 'identity.participants'::regclass
  ) THEN
    ALTER TABLE identity.participants
      ADD CONSTRAINT identity_participants_public_key_hash_check
      CHECK (public_key_hash IS NULL OR public_key_hash ~ '^(sha256:)?[0-9a-f]{64}$');
  END IF;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'identity_participants_subject_hash_check'
      AND conrelid = 'identity.participants'::regclass
  ) THEN
    ALTER TABLE identity.participants
      ADD CONSTRAINT identity_participants_subject_hash_check
      CHECK (subject_hash IS NULL OR subject_hash ~ '^[0-9a-f]{64}$');
  END IF;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'identity_participants_organization_fk'
      AND conrelid = 'identity.participants'::regclass
  ) THEN
    ALTER TABLE identity.participants
      ADD CONSTRAINT identity_participants_organization_fk
      FOREIGN KEY (organization_id) REFERENCES organizations.organizations(id)
      DEFERRABLE INITIALLY DEFERRED;
  END IF;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'organizations_data_sharing_policy_check'
      AND conrelid = 'organizations.organizations'::regclass
  ) THEN
    ALTER TABLE organizations.organizations
      ADD CONSTRAINT organizations_data_sharing_policy_check
      CHECK (data_sharing_policy IN ('open', 'restricted', 'private'));
  END IF;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'organizations_profile_hash_check'
      AND conrelid = 'organizations.organizations'::regclass
  ) THEN
    ALTER TABLE organizations.organizations
      ADD CONSTRAINT organizations_profile_hash_check
      CHECK (profile_hash IS NULL OR profile_hash ~ '^[0-9a-f]{64}$');
  END IF;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'identity_participants_roles_check'
      AND conrelid = 'identity.participants'::regclass
  ) THEN
    ALTER TABLE identity.participants
      ADD CONSTRAINT identity_participants_roles_check
      CHECK (
        cardinality(roles) > 0 AND
        roles <@ ARRAY['owner', 'admin', 'verifier', 'researcher', 'community', 'observer', 'agent']::text[]
      );
  END IF;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'identity_participants_verification_status_check'
      AND conrelid = 'identity.participants'::regclass
  ) THEN
    ALTER TABLE identity.participants
      ADD CONSTRAINT identity_participants_verification_status_check
      CHECK (verification_status IN ('unverified', 'pending', 'verified', 'suspended', 'revoked'));
  END IF;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'organizations_accreditation_status_check'
      AND conrelid = 'organizations.organizations'::regclass
  ) THEN
    ALTER TABLE organizations.organizations
      ADD CONSTRAINT organizations_accreditation_status_check
      CHECK (accreditation_status IN ('pending', 'approved', 'suspended', 'revoked'));
  END IF;
END;
$$;

CREATE INDEX IF NOT EXISTS identity_participants_authorization_idx
  ON identity.participants (verification_status, id);

CREATE INDEX IF NOT EXISTS organization_memberships_authorization_idx
  ON organizations.memberships (actor_id, organization_id, role, status);

CREATE INDEX IF NOT EXISTS organization_accreditations_latest_idx
  ON organizations.accreditations (organization_id, decided_at DESC, id DESC);

CREATE OR REPLACE FUNCTION identity.resolve_authorization_binding(
  requested_actor_id text,
  requested_role text,
  requested_organization_id text
)
RETURNS TABLE (
  participant_id text,
  participant_type text,
  participant_roles text[],
  participant_verification_status text,
  participant_organization_id text,
  bound_organization_id text,
  organization_verification_status text,
  organization_accreditation_status text,
  membership_id text,
  membership_role text,
  membership_status text,
  latest_accreditation_id text,
  latest_accreditation_status text
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = pg_catalog, identity, organizations
AS $$
  SELECT
    participant.id,
    participant.participant_type,
    participant.roles,
    participant.verification_status,
    participant.organization_id,
    organization.id,
    organization.verification_status,
    organization.accreditation_status,
    membership.id,
    membership.role,
    membership.status,
    latest_accreditation.id,
    latest_accreditation.status
  FROM identity.participants AS participant
  LEFT JOIN organizations.organizations AS organization
    ON organization.id = requested_organization_id
  LEFT JOIN organizations.memberships AS membership
    ON membership.organization_id = requested_organization_id
   AND membership.actor_id = participant.id
   AND membership.role = requested_role
  LEFT JOIN LATERAL (
    SELECT accreditation.id, accreditation.status
    FROM organizations.accreditations AS accreditation
    WHERE accreditation.organization_id = requested_organization_id
    ORDER BY accreditation.decided_at DESC, accreditation.id DESC
    LIMIT 1
  ) AS latest_accreditation ON true
  WHERE participant.id = requested_actor_id;
$$;

CREATE OR REPLACE FUNCTION audit.is_sha256_hash_array(values_to_check text[])
RETURNS boolean
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT
    cardinality(values_to_check) > 0 AND
    NOT EXISTS (
      SELECT 1
      FROM unnest(values_to_check) AS hash_value
      WHERE hash_value !~ '^[0-9a-f]{64}$'
    );
$$;

CREATE OR REPLACE FUNCTION audit.is_sorted_unique_text_array(values_to_check text[])
RETURNS boolean
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT values_to_check = ARRAY(
    SELECT DISTINCT value
    FROM unnest(values_to_check) AS value
    ORDER BY value
  );
$$;

CREATE OR REPLACE FUNCTION audit.is_bounded_text_array(
  values_to_check text[],
  minimum_length integer,
  maximum_length integer,
  maximum_items integer
)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT
    cardinality(values_to_check) <= maximum_items AND
    NOT EXISTS (
      SELECT 1
      FROM unnest(values_to_check) AS value
      WHERE length(btrim(value)) < minimum_length
         OR length(btrim(value)) > maximum_length
         OR value <> btrim(value)
    );
$$;

CREATE TABLE IF NOT EXISTS organizations.data_sharing_agreements (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  dataset_scopes text[] NOT NULL CONSTRAINT data_sharing_agreements_dataset_scopes_nonempty CHECK (cardinality(dataset_scopes) > 0),
  privacy_tier text NOT NULL CHECK (privacy_tier IN ('public', 'restricted', 'confidential')),
  permitted_uses text[] NOT NULL CONSTRAINT data_sharing_agreements_permitted_uses_nonempty CHECK (cardinality(permitted_uses) > 0),
  revoked boolean NOT NULL DEFAULT false,
  expires_at timestamptz,
  created_by text NOT NULL REFERENCES identity.participants(id),
  created_at timestamptz NOT NULL,
  agreement_hash text NOT NULL UNIQUE CONSTRAINT data_sharing_agreements_hash_shape CHECK (agreement_hash ~ '^[0-9a-f]{64}$'),
  audit_event_root text NOT NULL UNIQUE CONSTRAINT data_sharing_agreements_event_root_shape CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  CONSTRAINT data_sharing_agreements_expiry_after_creation CHECK (expires_at IS NULL OR expires_at > created_at)
);

CREATE TABLE IF NOT EXISTS organizations.data_sharing_agreement_revocations (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  agreement_id text NOT NULL REFERENCES organizations.data_sharing_agreements(id),
  rationale text NOT NULL CONSTRAINT data_sharing_agreement_revocations_rationale_length CHECK (length(btrim(rationale)) >= 12),
  evidence_event_roots text[] NOT NULL CONSTRAINT data_sharing_agreement_revocations_evidence_roots CHECK (audit.is_sha256_hash_array(evidence_event_roots)),
  revoked_by text NOT NULL REFERENCES identity.participants(id),
  revoked_at timestamptz NOT NULL,
  revocation_hash text NOT NULL UNIQUE CONSTRAINT data_sharing_agreement_revocations_hash_shape CHECK (revocation_hash ~ '^[0-9a-f]{64}$'),
  revocation_root text NOT NULL UNIQUE CONSTRAINT data_sharing_agreement_revocations_root_shape CHECK (revocation_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (
    safety @> '{
      "agreementBound": true,
      "separateRevocationRecord": true,
      "futureAccessBlocked": true,
      "futureDeliveryBlocked": true,
      "appendOnly": true,
      "noRawDataEmbedded": true,
      "noPrivateContactData": true,
      "notFinalProofAuthority": true,
      "notCarbonCredit": true,
      "notFinancialAsset": true,
      "notTaxOffset": true,
      "notGuaranteedYield": true
    }'::jsonb
  ),
  audit_event_root text NOT NULL UNIQUE CONSTRAINT data_sharing_agreement_revocations_event_root_shape CHECK (audit_event_root ~ '^[0-9a-f]{64}$')
);

CREATE TABLE IF NOT EXISTS organizations.data_sharing_agreement_supersessions (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  predecessor_agreement_id text NOT NULL REFERENCES organizations.data_sharing_agreements(id),
  predecessor_agreement_hash text NOT NULL CONSTRAINT data_sharing_agreement_supersessions_predecessor_hash_shape CHECK (predecessor_agreement_hash ~ '^[0-9a-f]{64}$'),
  successor_agreement_id text NOT NULL REFERENCES organizations.data_sharing_agreements(id),
  successor_agreement_hash text NOT NULL CONSTRAINT data_sharing_agreement_supersessions_successor_hash_shape CHECK (successor_agreement_hash ~ '^[0-9a-f]{64}$'),
  transition_type text NOT NULL CHECK (transition_type IN ('renewal', 'supersession')),
  rationale text NOT NULL CONSTRAINT data_sharing_agreement_supersessions_rationale_length CHECK (length(btrim(rationale)) >= 12),
  evidence_event_roots text[] NOT NULL CONSTRAINT data_sharing_agreement_supersessions_evidence_roots CHECK (audit.is_sha256_hash_array(evidence_event_roots)),
  superseded_by text NOT NULL REFERENCES identity.participants(id),
  superseded_at timestamptz NOT NULL,
  supersession_hash text NOT NULL UNIQUE CONSTRAINT data_sharing_agreement_supersessions_hash_shape CHECK (supersession_hash ~ '^[0-9a-f]{64}$'),
  supersession_root text NOT NULL UNIQUE CONSTRAINT data_sharing_agreement_supersessions_root_shape CHECK (supersession_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (
    safety @> '{
      "predecessorBound": true,
      "successorBound": true,
      "scopeExpansionBlocked": true,
      "privacyEscalationBlocked": true,
      "priorAgreementFutureAccessBlocked": true,
      "priorAgreementFutureDeliveryBlocked": true,
      "appendOnly": true,
      "noRawDataEmbedded": true,
      "noPrivateContactData": true,
      "notFinalProofAuthority": true,
      "notCarbonCredit": true,
      "notFinancialAsset": true,
      "notTaxOffset": true,
      "notGuaranteedYield": true
    }'::jsonb
  ),
  audit_event_root text NOT NULL UNIQUE CONSTRAINT data_sharing_agreement_supersessions_event_root_shape CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (predecessor_agreement_id),
  UNIQUE (successor_agreement_id),
  CHECK (predecessor_agreement_id <> successor_agreement_id)
);

CREATE INDEX IF NOT EXISTS organizations_data_sharing_agreements_org_time
  ON organizations.data_sharing_agreements (organization_id, created_at DESC, id DESC);

CREATE UNIQUE INDEX IF NOT EXISTS organizations_data_sharing_agreement_revocations_agreement_unique
  ON organizations.data_sharing_agreement_revocations (agreement_id);

CREATE INDEX IF NOT EXISTS organizations_data_sharing_agreement_revocations_agreement_time
  ON organizations.data_sharing_agreement_revocations (agreement_id, revoked_at DESC, id DESC);

CREATE INDEX IF NOT EXISTS organizations_data_sharing_agreement_supersessions_successor
  ON organizations.data_sharing_agreement_supersessions (successor_agreement_id, superseded_at DESC, id DESC);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreements_dataset_scopes_nonempty'
      AND conrelid = 'organizations.data_sharing_agreements'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreements
      ADD CONSTRAINT data_sharing_agreements_dataset_scopes_nonempty
      CHECK (cardinality(dataset_scopes) > 0) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreements_permitted_uses_nonempty'
      AND conrelid = 'organizations.data_sharing_agreements'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreements
      ADD CONSTRAINT data_sharing_agreements_permitted_uses_nonempty
      CHECK (cardinality(permitted_uses) > 0) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreements_hash_shape'
      AND conrelid = 'organizations.data_sharing_agreements'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreements
      ADD CONSTRAINT data_sharing_agreements_hash_shape
      CHECK (agreement_hash ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreements_event_root_shape'
      AND conrelid = 'organizations.data_sharing_agreements'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreements
      ADD CONSTRAINT data_sharing_agreements_event_root_shape
      CHECK (audit_event_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreements_expiry_after_creation'
      AND conrelid = 'organizations.data_sharing_agreements'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreements
      ADD CONSTRAINT data_sharing_agreements_expiry_after_creation
      CHECK (expires_at IS NULL OR expires_at > created_at) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreement_revocations_rationale_length'
      AND conrelid = 'organizations.data_sharing_agreement_revocations'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreement_revocations
      ADD CONSTRAINT data_sharing_agreement_revocations_rationale_length
      CHECK (length(btrim(rationale)) >= 12) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreement_revocations_evidence_roots'
      AND conrelid = 'organizations.data_sharing_agreement_revocations'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreement_revocations
      ADD CONSTRAINT data_sharing_agreement_revocations_evidence_roots
      CHECK (audit.is_sha256_hash_array(evidence_event_roots)) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreement_revocations_hash_shape'
      AND conrelid = 'organizations.data_sharing_agreement_revocations'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreement_revocations
      ADD CONSTRAINT data_sharing_agreement_revocations_hash_shape
      CHECK (revocation_hash ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreement_revocations_root_shape'
      AND conrelid = 'organizations.data_sharing_agreement_revocations'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreement_revocations
      ADD CONSTRAINT data_sharing_agreement_revocations_root_shape
      CHECK (revocation_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreement_revocations_event_root_shape'
      AND conrelid = 'organizations.data_sharing_agreement_revocations'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreement_revocations
      ADD CONSTRAINT data_sharing_agreement_revocations_event_root_shape
      CHECK (audit_event_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreement_supersessions_predecessor_hash_shape'
      AND conrelid = 'organizations.data_sharing_agreement_supersessions'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreement_supersessions
      ADD CONSTRAINT data_sharing_agreement_supersessions_predecessor_hash_shape
      CHECK (predecessor_agreement_hash ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreement_supersessions_successor_hash_shape'
      AND conrelid = 'organizations.data_sharing_agreement_supersessions'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreement_supersessions
      ADD CONSTRAINT data_sharing_agreement_supersessions_successor_hash_shape
      CHECK (successor_agreement_hash ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreement_supersessions_rationale_length'
      AND conrelid = 'organizations.data_sharing_agreement_supersessions'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreement_supersessions
      ADD CONSTRAINT data_sharing_agreement_supersessions_rationale_length
      CHECK (length(btrim(rationale)) >= 12) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreement_supersessions_evidence_roots'
      AND conrelid = 'organizations.data_sharing_agreement_supersessions'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreement_supersessions
      ADD CONSTRAINT data_sharing_agreement_supersessions_evidence_roots
      CHECK (audit.is_sha256_hash_array(evidence_event_roots)) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreement_supersessions_hash_shape'
      AND conrelid = 'organizations.data_sharing_agreement_supersessions'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreement_supersessions
      ADD CONSTRAINT data_sharing_agreement_supersessions_hash_shape
      CHECK (supersession_hash ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreement_supersessions_root_shape'
      AND conrelid = 'organizations.data_sharing_agreement_supersessions'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreement_supersessions
      ADD CONSTRAINT data_sharing_agreement_supersessions_root_shape
      CHECK (supersession_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_sharing_agreement_supersessions_event_root_shape'
      AND conrelid = 'organizations.data_sharing_agreement_supersessions'::regclass
  ) THEN
    ALTER TABLE organizations.data_sharing_agreement_supersessions
      ADD CONSTRAINT data_sharing_agreement_supersessions_event_root_shape
      CHECK (audit_event_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_sharing_agreement_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.created_by THEN
    RAISE EXCEPTION 'data-sharing agreement insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.expires_at IS NOT NULL AND NEW.expires_at <= NEW.created_at THEN
    RAISE EXCEPTION 'data-sharing agreement expiry must follow creation' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_sharing_agreements_validate_insert ON organizations.data_sharing_agreements;
CREATE TRIGGER organizations_data_sharing_agreements_validate_insert
BEFORE INSERT ON organizations.data_sharing_agreements
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_sharing_agreement_insert();

CREATE OR REPLACE FUNCTION organizations.validate_data_sharing_agreement_revocation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  agreement organizations.data_sharing_agreements%ROWTYPE;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.revoked_by THEN
    RAISE EXCEPTION 'data-sharing agreement revocation requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT agreement
  FROM organizations.data_sharing_agreements
  WHERE id = NEW.agreement_id
  FOR UPDATE;

  IF agreement.organization_id <> NEW.organization_id THEN
    RAISE EXCEPTION 'data-sharing agreement revocation organization mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF agreement.revoked OR EXISTS (
    SELECT 1
    FROM organizations.data_sharing_agreement_revocations existing
    WHERE existing.agreement_id = agreement.id
  ) THEN
    RAISE EXCEPTION 'data-sharing agreement already has a revocation record' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM organizations.data_sharing_agreement_supersessions supersession
    WHERE supersession.predecessor_agreement_id = agreement.id
  ) THEN
    RAISE EXCEPTION 'superseded data-sharing agreement cannot be revoked' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.revoked_at <= agreement.created_at THEN
    RAISE EXCEPTION 'data-sharing agreement revocation must follow creation' USING ERRCODE = 'check_violation';
  END IF;
  IF agreement.expires_at IS NOT NULL AND agreement.expires_at <= NEW.revoked_at THEN
    RAISE EXCEPTION 'expired data-sharing agreement cannot be revoked' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_sharing_agreement_revocations_validate ON organizations.data_sharing_agreement_revocations;
CREATE TRIGGER organizations_data_sharing_agreement_revocations_validate
BEFORE INSERT ON organizations.data_sharing_agreement_revocations
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_sharing_agreement_revocation();

CREATE OR REPLACE FUNCTION organizations.validate_data_sharing_agreement_supersession()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  predecessor organizations.data_sharing_agreements%ROWTYPE;
  successor organizations.data_sharing_agreements%ROWTYPE;
  predecessor_privacy_rank integer;
  successor_privacy_rank integer;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.superseded_by THEN
    RAISE EXCEPTION 'data-sharing agreement supersession requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT predecessor
  FROM organizations.data_sharing_agreements
  WHERE id = NEW.predecessor_agreement_id
  FOR UPDATE;

  SELECT * INTO STRICT successor
  FROM organizations.data_sharing_agreements
  WHERE id = NEW.successor_agreement_id
  FOR UPDATE;

  IF predecessor.organization_id <> NEW.organization_id OR successor.organization_id <> NEW.organization_id THEN
    RAISE EXCEPTION 'data-sharing agreement supersession must remain within one organization' USING ERRCODE = 'check_violation';
  END IF;
  IF predecessor.agreement_hash <> NEW.predecessor_agreement_hash OR successor.agreement_hash <> NEW.successor_agreement_hash THEN
    RAISE EXCEPTION 'data-sharing agreement supersession hash binding mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.superseded_at <= predecessor.created_at OR successor.created_at IS DISTINCT FROM NEW.superseded_at THEN
    RAISE EXCEPTION 'data-sharing agreement successor must become effective at supersession time' USING ERRCODE = 'check_violation';
  END IF;
  IF predecessor.revoked OR EXISTS (
    SELECT 1
    FROM organizations.data_sharing_agreement_revocations revocation
    WHERE revocation.agreement_id = predecessor.id
  ) THEN
    RAISE EXCEPTION 'revoked data-sharing agreement cannot be superseded' USING ERRCODE = 'check_violation';
  END IF;
  IF successor.expires_at IS NOT NULL AND successor.expires_at <= NEW.superseded_at THEN
    RAISE EXCEPTION 'successor data-sharing agreement must expire after supersession time' USING ERRCODE = 'check_violation';
  END IF;

  predecessor_privacy_rank := CASE predecessor.privacy_tier WHEN 'public' THEN 1 WHEN 'restricted' THEN 2 ELSE 3 END;
  successor_privacy_rank := CASE successor.privacy_tier WHEN 'public' THEN 1 WHEN 'restricted' THEN 2 ELSE 3 END;

  IF NEW.transition_type = 'renewal' THEN
    IF predecessor.expires_at IS NULL OR successor.expires_at IS NULL OR successor.expires_at <= predecessor.expires_at THEN
      RAISE EXCEPTION 'data-sharing agreement renewal must extend a finite predecessor expiry' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT (
      successor.dataset_scopes <@ predecessor.dataset_scopes AND predecessor.dataset_scopes <@ successor.dataset_scopes AND
      successor.permitted_uses <@ predecessor.permitted_uses AND predecessor.permitted_uses <@ successor.permitted_uses AND
      successor.privacy_tier = predecessor.privacy_tier
    ) THEN
      RAISE EXCEPTION 'data-sharing agreement renewal must preserve scope, use, and privacy tier' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF NOT (successor.dataset_scopes <@ predecessor.dataset_scopes) THEN
      RAISE EXCEPTION 'data-sharing agreement supersession cannot expand dataset scope' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT (successor.permitted_uses <@ predecessor.permitted_uses) THEN
      RAISE EXCEPTION 'data-sharing agreement supersession cannot expand permitted use' USING ERRCODE = 'check_violation';
    END IF;
    IF successor_privacy_rank > predecessor_privacy_rank THEN
      RAISE EXCEPTION 'data-sharing agreement supersession cannot escalate privacy tier' USING ERRCODE = 'check_violation';
    END IF;
    IF predecessor.expires_at IS NOT NULL AND (successor.expires_at IS NULL OR successor.expires_at > predecessor.expires_at) THEN
      RAISE EXCEPTION 'data-sharing agreement supersession cannot extend duration' USING ERRCODE = 'check_violation';
    END IF;
    IF
      successor.dataset_scopes <@ predecessor.dataset_scopes AND predecessor.dataset_scopes <@ successor.dataset_scopes AND
      successor.permitted_uses <@ predecessor.permitted_uses AND predecessor.permitted_uses <@ successor.permitted_uses AND
      successor.privacy_tier = predecessor.privacy_tier AND
      successor.expires_at IS NOT DISTINCT FROM predecessor.expires_at
    THEN
      RAISE EXCEPTION 'data-sharing agreement supersession must materially constrain its successor' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_sharing_agreement_supersessions_validate ON organizations.data_sharing_agreement_supersessions;
CREATE TRIGGER organizations_data_sharing_agreement_supersessions_validate
BEFORE INSERT ON organizations.data_sharing_agreement_supersessions
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_sharing_agreement_supersession();

CREATE TABLE IF NOT EXISTS organizations.data_access_requests (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  agreement_id text NOT NULL REFERENCES organizations.data_sharing_agreements(id),
  dataset_scopes text[] NOT NULL CONSTRAINT data_access_requests_dataset_scopes_nonempty CHECK (cardinality(dataset_scopes) > 0),
  permitted_uses text[] NOT NULL CONSTRAINT data_access_requests_permitted_uses_nonempty CHECK (cardinality(permitted_uses) > 0),
  privacy_tier text NOT NULL CHECK (privacy_tier IN ('public', 'restricted', 'confidential')),
  purpose text NOT NULL CONSTRAINT data_access_requests_purpose_length CHECK (length(btrim(purpose)) >= 12),
  status text NOT NULL CHECK (status IN ('pending', 'approved', 'denied', 'revoked', 'expired')),
  requested_by text NOT NULL REFERENCES identity.participants(id),
  requested_at timestamptz NOT NULL,
  decision_by text REFERENCES identity.participants(id),
  decided_at timestamptz,
  decision_rationale text,
  expires_at timestamptz,
  request_hash text NOT NULL UNIQUE CONSTRAINT data_access_requests_hash_shape CHECK (request_hash ~ '^[0-9a-f]{64}$'),
  access_root text NOT NULL UNIQUE CONSTRAINT data_access_requests_root_shape CHECK (access_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (
    safety @> '{
      "agreementBound": true,
      "scopeLimited": true,
      "humanDecisionRequired": true,
      "rawDataNotEmbedded": true,
      "noPrivateContactData": true,
      "notFinalProofAuthority": true,
      "notCarbonCredit": true,
      "notFinancialAsset": true,
      "notTaxOffset": true,
      "notGuaranteedYield": true
    }'::jsonb
  ),
  audit_event_root text NOT NULL UNIQUE CONSTRAINT data_access_requests_event_root_shape CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  CONSTRAINT data_access_requests_expiry_after_request CHECK (expires_at IS NULL OR expires_at > requested_at),
  CHECK (
    (status = 'pending' AND decision_by IS NULL AND decided_at IS NULL AND decision_rationale IS NULL) OR
    (status <> 'pending' AND decision_by IS NOT NULL AND decided_at IS NOT NULL AND decision_rationale IS NOT NULL)
  )
);

CREATE TABLE IF NOT EXISTS organizations.data_access_request_decisions (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  request_id text NOT NULL REFERENCES organizations.data_access_requests(id),
  agreement_id text NOT NULL REFERENCES organizations.data_sharing_agreements(id),
  previous_status text NOT NULL CHECK (previous_status IN ('pending', 'approved')),
  status text NOT NULL CHECK (status IN ('approved', 'denied', 'revoked', 'expired')),
  decision_by text NOT NULL REFERENCES identity.participants(id),
  decided_at timestamptz NOT NULL,
  rationale text NOT NULL CONSTRAINT data_access_request_decisions_rationale_length CHECK (length(btrim(rationale)) >= 12),
  decision_hash text NOT NULL UNIQUE CONSTRAINT data_access_request_decisions_hash_shape CHECK (decision_hash ~ '^[0-9a-f]{64}$'),
  decision_root text NOT NULL UNIQUE CONSTRAINT data_access_request_decisions_root_shape CHECK (decision_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (
    safety @> '{
      "requestBound": true,
      "agreementBound": true,
      "independentHumanDecision": true,
      "appendOnly": true,
      "rawDataNotEmbedded": true,
      "noPrivateContactData": true,
      "notFinalProofAuthority": true,
      "notCarbonCredit": true,
      "notFinancialAsset": true,
      "notTaxOffset": true,
      "notGuaranteedYield": true
    }'::jsonb
  ),
  audit_event_root text NOT NULL UNIQUE CONSTRAINT data_access_request_decisions_event_root_shape CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (request_id, previous_status),
  CHECK (
    (previous_status = 'pending' AND status IN ('approved', 'denied', 'expired')) OR
    (previous_status = 'approved' AND status IN ('revoked', 'expired'))
  )
);

CREATE INDEX IF NOT EXISTS organizations_data_access_requests_org_time
  ON organizations.data_access_requests (organization_id, requested_at DESC, id DESC);

CREATE INDEX IF NOT EXISTS organizations_data_access_request_decisions_request_time
  ON organizations.data_access_request_decisions (request_id, decided_at ASC, id ASC);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_access_requests_dataset_scopes_nonempty'
      AND conrelid = 'organizations.data_access_requests'::regclass
  ) THEN
    ALTER TABLE organizations.data_access_requests
      ADD CONSTRAINT data_access_requests_dataset_scopes_nonempty
      CHECK (cardinality(dataset_scopes) > 0) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_access_requests_permitted_uses_nonempty'
      AND conrelid = 'organizations.data_access_requests'::regclass
  ) THEN
    ALTER TABLE organizations.data_access_requests
      ADD CONSTRAINT data_access_requests_permitted_uses_nonempty
      CHECK (cardinality(permitted_uses) > 0) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_access_requests_purpose_length'
      AND conrelid = 'organizations.data_access_requests'::regclass
  ) THEN
    ALTER TABLE organizations.data_access_requests
      ADD CONSTRAINT data_access_requests_purpose_length
      CHECK (length(btrim(purpose)) >= 12) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_access_requests_hash_shape'
      AND conrelid = 'organizations.data_access_requests'::regclass
  ) THEN
    ALTER TABLE organizations.data_access_requests
      ADD CONSTRAINT data_access_requests_hash_shape
      CHECK (request_hash ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_access_requests_root_shape'
      AND conrelid = 'organizations.data_access_requests'::regclass
  ) THEN
    ALTER TABLE organizations.data_access_requests
      ADD CONSTRAINT data_access_requests_root_shape
      CHECK (access_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_access_requests_event_root_shape'
      AND conrelid = 'organizations.data_access_requests'::regclass
  ) THEN
    ALTER TABLE organizations.data_access_requests
      ADD CONSTRAINT data_access_requests_event_root_shape
      CHECK (audit_event_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'data_access_requests_expiry_after_request'
      AND conrelid = 'organizations.data_access_requests'::regclass
  ) THEN
    ALTER TABLE organizations.data_access_requests
      ADD CONSTRAINT data_access_requests_expiry_after_request
      CHECK (expires_at IS NULL OR expires_at > requested_at) NOT VALID;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_access_request_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  organization_record organizations.organizations%ROWTYPE;
  agreement_record organizations.data_sharing_agreements%ROWTYPE;
  request_privacy_rank integer;
  agreement_privacy_rank integer;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.requested_by THEN
    RAISE EXCEPTION 'data access request insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.status <> 'pending' OR NEW.decision_by IS NOT NULL OR
    NEW.decided_at IS NOT NULL OR NEW.decision_rationale IS NOT NULL
  THEN
    RAISE EXCEPTION 'data access request source row must remain an immutable pending fact' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO organization_record
  FROM organizations.organizations
  WHERE id = NEW.organization_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data access request organization does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF organization_record.verification_status <> 'verified' OR organization_record.trust_level NOT IN ('verified', 'institutional') THEN
    RAISE EXCEPTION 'data access request requires a verified organization trust state' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.organization_id
      AND membership.actor_id = NEW.requested_by
      AND membership.status = 'active'
      AND membership.role IN ('owner', 'admin', 'verifier', 'researcher')
  ) THEN
    RAISE EXCEPTION 'data access requester lacks an active organization membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO agreement_record
  FROM organizations.data_sharing_agreements
  WHERE id = NEW.agreement_id
  FOR UPDATE;
  IF NOT FOUND OR agreement_record.organization_id <> NEW.organization_id THEN
    RAISE EXCEPTION 'data access request agreement organization mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF agreement_record.revoked OR EXISTS (
    SELECT 1 FROM organizations.data_sharing_agreement_revocations revocation
    WHERE revocation.agreement_id = NEW.agreement_id
  ) THEN
    RAISE EXCEPTION 'data access request cannot use a revoked agreement' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM organizations.data_sharing_agreement_supersessions supersession
    WHERE supersession.predecessor_agreement_id = NEW.agreement_id
  ) THEN
    RAISE EXCEPTION 'data access request cannot use a superseded agreement' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.requested_at < agreement_record.created_at THEN
    RAISE EXCEPTION 'data access request cannot predate its agreement' USING ERRCODE = 'check_violation';
  END IF;
  IF agreement_record.expires_at IS NOT NULL AND NEW.requested_at >= agreement_record.expires_at THEN
    RAISE EXCEPTION 'data access request cannot use an expired agreement' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.expires_at IS NOT NULL AND NEW.expires_at <= NEW.requested_at THEN
    RAISE EXCEPTION 'data access request expiry must follow submission' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.expires_at IS NOT NULL AND agreement_record.expires_at IS NOT NULL AND
    NEW.expires_at > agreement_record.expires_at
  THEN
    RAISE EXCEPTION 'data access request cannot outlive its agreement' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT (NEW.dataset_scopes <@ agreement_record.dataset_scopes) THEN
    RAISE EXCEPTION 'data access request dataset scope exceeds its agreement' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT (NEW.permitted_uses <@ agreement_record.permitted_uses) THEN
    RAISE EXCEPTION 'data access request permitted use exceeds its agreement' USING ERRCODE = 'check_violation';
  END IF;

  request_privacy_rank := CASE NEW.privacy_tier WHEN 'public' THEN 1 WHEN 'restricted' THEN 2 WHEN 'confidential' THEN 3 ELSE 99 END;
  agreement_privacy_rank := CASE agreement_record.privacy_tier WHEN 'public' THEN 1 WHEN 'restricted' THEN 2 WHEN 'confidential' THEN 3 ELSE 0 END;
  IF request_privacy_rank > agreement_privacy_rank THEN
    RAISE EXCEPTION 'data access request privacy tier exceeds its agreement' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.privacy_tier = 'confidential' AND organization_record.trust_level <> 'institutional' THEN
    RAISE EXCEPTION 'confidential data access requires institutional trust' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_access_requests_validate_insert ON organizations.data_access_requests;
CREATE TRIGGER organizations_data_access_requests_validate_insert
BEFORE INSERT ON organizations.data_access_requests
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_access_request_insert();

CREATE TABLE IF NOT EXISTS organizations.data_access_delivery_receipts (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  request_id text NOT NULL REFERENCES organizations.data_access_requests(id),
  agreement_id text NOT NULL REFERENCES organizations.data_sharing_agreements(id),
  manifest_id text NOT NULL,
  manifest_requester_organization_id text NOT NULL REFERENCES organizations.organizations(id),
  manifest_hash text NOT NULL CONSTRAINT data_access_delivery_manifest_hash_shape CHECK (manifest_hash ~ '^[0-9a-f]{64}$'),
  manifest_entry_root text NOT NULL CONSTRAINT data_access_delivery_manifest_root_shape CHECK (manifest_entry_root ~ '^[0-9a-f]{64}$'),
  manifest_classification text NOT NULL CHECK (manifest_classification IN ('public', 'internal', 'restricted', 'confidential')),
  channel text NOT NULL CHECK (channel IN ('audit_export_manifest', 'partner_api', 'regulator_portal', 'research_data_room')),
  recipient_actor_id text NOT NULL REFERENCES identity.participants(id),
  delivered_by text NOT NULL REFERENCES identity.participants(id),
  delivered_at timestamptz NOT NULL,
  purpose text NOT NULL CONSTRAINT data_access_delivery_purpose_length CHECK (length(btrim(purpose)) BETWEEN 12 AND 1000),
  access_root text NOT NULL CONSTRAINT data_access_delivery_access_root_shape CHECK (access_root ~ '^[0-9a-f]{64}$'),
  receipt_hash text NOT NULL UNIQUE CONSTRAINT data_access_delivery_receipt_hash_shape CHECK (receipt_hash ~ '^[0-9a-f]{64}$'),
  delivery_root text NOT NULL UNIQUE CONSTRAINT data_access_delivery_root_shape CHECK (delivery_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CONSTRAINT data_access_delivery_safety_boundary CHECK (
    safety = '{
      "approvedRequestBound": true,
      "agreementBound": true,
      "manifestHashOnly": true,
      "redactionPolicyEnforced": true,
      "rawDataNotEmbedded": true,
      "noPrivateContactData": true,
      "humanDecisionRequired": true,
      "notFinalProofAuthority": true,
      "notCarbonCredit": true,
      "notFinancialAsset": true,
      "notTaxOffset": true,
      "notGuaranteedYield": true
    }'::jsonb
  ),
  audit_event_root text NOT NULL UNIQUE CONSTRAINT data_access_delivery_event_root_shape CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  CONSTRAINT data_access_delivery_manifest_organization_match CHECK (organization_id = manifest_requester_organization_id),
  CONSTRAINT data_access_delivery_actor_separation CHECK (delivered_by <> recipient_actor_id)
);

