CREATE TABLE IF NOT EXISTS organizations.data_use_attestations (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  request_id text NOT NULL REFERENCES organizations.data_access_requests(id),
  delivery_id text NOT NULL REFERENCES organizations.data_access_delivery_receipts(id),
  manifest_id text NOT NULL,
  usage_state text NOT NULL CHECK (usage_state IN ('within_scope', 'no_use', 'misuse_challenged', 'revocation_requested')),
  use_case text NOT NULL CONSTRAINT data_use_attestation_use_case_length CHECK (length(btrim(use_case)) BETWEEN 12 AND 2000),
  output_hashes text[] NOT NULL DEFAULT ARRAY[]::text[] CONSTRAINT data_use_attestation_output_hashes_shape CHECK (
    cardinality(output_hashes) <= 128 AND
    (cardinality(output_hashes) = 0 OR audit.is_sha256_hash_array(output_hashes)) AND
    audit.is_sorted_unique_text_array(output_hashes)
  ),
  evidence_event_roots text[] NOT NULL DEFAULT ARRAY[]::text[] CONSTRAINT data_use_attestation_evidence_roots_shape CHECK (
    cardinality(evidence_event_roots) <= 128 AND
    (cardinality(evidence_event_roots) = 0 OR audit.is_sha256_hash_array(evidence_event_roots)) AND
    audit.is_sorted_unique_text_array(evidence_event_roots)
  ),
  limitations text[] NOT NULL DEFAULT ARRAY[]::text[] CONSTRAINT data_use_attestation_limitations_shape CHECK (
    audit.is_bounded_text_array(limitations, 4, 500, 32) AND
    audit.is_sorted_unique_text_array(limitations)
  ),
  attested_by text NOT NULL REFERENCES identity.participants(id),
  attested_at timestamptz NOT NULL,
  attestation_hash text NOT NULL UNIQUE CONSTRAINT data_use_attestation_hash_shape CHECK (attestation_hash ~ '^[0-9a-f]{64}$'),
  usage_root text NOT NULL UNIQUE CONSTRAINT data_use_attestation_root_shape CHECK (usage_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CONSTRAINT data_use_attestation_safety_boundary CHECK (
    safety = '{
      "deliveryReceiptBound": true,
      "approvedRequestBound": true,
      "purposeBound": true,
      "outputHashOnly": true,
      "noRawDataEmbedded": true,
      "noPrivateContactData": true,
      "notFinalProofAuthority": true,
      "notCarbonCredit": true,
      "notFinancialAsset": true,
      "notTaxOffset": true,
      "notGuaranteedYield": true
    }'::jsonb
  ),
  audit_event_root text NOT NULL UNIQUE CONSTRAINT data_use_attestation_event_root_shape CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  CONSTRAINT data_use_attestation_within_scope_outputs CHECK (
    (usage_state = 'within_scope' AND cardinality(output_hashes) > 0) OR usage_state <> 'within_scope'
  ),
  CONSTRAINT data_use_attestation_no_use_outputs CHECK (
    (usage_state = 'no_use' AND cardinality(output_hashes) = 0) OR usage_state <> 'no_use'
  ),
  CONSTRAINT data_use_attestation_challenge_evidence CHECK (
    (usage_state IN ('misuse_challenged', 'revocation_requested') AND cardinality(evidence_event_roots) > 0) OR
    usage_state NOT IN ('misuse_challenged', 'revocation_requested')
  )
);

