CREATE TABLE IF NOT EXISTS organizations.data_use_enforcement_cases (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  request_id text NOT NULL REFERENCES organizations.data_access_requests(id),
  delivery_id text NOT NULL REFERENCES organizations.data_access_delivery_receipts(id),
  attestation_id text NOT NULL REFERENCES organizations.data_use_attestations(id),
  manifest_id text NOT NULL,
  case_state text NOT NULL CONSTRAINT data_use_enforcement_case_state CHECK (
    case_state IN (
      'opened',
      'under_review',
      'action_required',
      'access_suspended',
      'access_revoked',
      'remediation_required',
      'resolved',
      'rejected'
    )
  ),
  enforcement_action text NOT NULL CONSTRAINT data_use_enforcement_action CHECK (
    enforcement_action IN ('notify_partner', 'suspend_data_access', 'revoke_data_access', 'require_remediation', 'legal_hold')
  ),
  rationale text NOT NULL CONSTRAINT data_use_enforcement_rationale_length CHECK (length(btrim(rationale)) BETWEEN 12 AND 2000),
  evidence_event_roots text[] NOT NULL CONSTRAINT data_use_enforcement_evidence_roots_shape CHECK (
    cardinality(evidence_event_roots) BETWEEN 1 AND 128 AND
    audit.is_sha256_hash_array(evidence_event_roots) AND
    audit.is_sorted_unique_text_array(evidence_event_roots)
  ),
  reviewer_id text NOT NULL REFERENCES identity.participants(id),
  reviewed_at timestamptz NOT NULL,
  enforcement_hash text NOT NULL UNIQUE CONSTRAINT data_use_enforcement_hash_shape CHECK (enforcement_hash ~ '^[0-9a-f]{64}$'),
  enforcement_root text NOT NULL UNIQUE CONSTRAINT data_use_enforcement_root_shape CHECK (enforcement_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CONSTRAINT data_use_enforcement_safety_boundary CHECK (
    safety = '{
      "challengedAttestationBound": true,
      "deliveryReceiptBound": true,
      "approvedRequestBound": true,
      "humanDecisionRequired": true,
      "independentReviewerRequired": true,
      "accessMutationRequiresSeparateApproval": true,
      "noRawDataEmbedded": true,
      "noPrivateContactData": true,
      "appendOnly": true,
      "notFinalProofAuthority": true,
      "notCarbonCredit": true,
      "notFinancialAsset": true,
      "notTaxOffset": true,
      "notGuaranteedYield": true
    }'::jsonb
  ),
  audit_event_root text NOT NULL UNIQUE CONSTRAINT data_use_enforcement_event_root_shape CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  CONSTRAINT data_use_enforcement_state_action CHECK (
    (case_state IN ('opened', 'under_review') AND enforcement_action IN ('notify_partner', 'legal_hold')) OR
    (case_state = 'action_required' AND enforcement_action IN ('notify_partner', 'require_remediation', 'legal_hold')) OR
    (case_state = 'access_suspended' AND enforcement_action IN ('suspend_data_access', 'legal_hold')) OR
    (case_state = 'access_revoked' AND enforcement_action IN ('revoke_data_access', 'legal_hold')) OR
    (case_state = 'remediation_required' AND enforcement_action IN ('require_remediation', 'notify_partner')) OR
    (case_state = 'resolved' AND enforcement_action IN ('notify_partner', 'require_remediation')) OR
    (case_state = 'rejected' AND enforcement_action = 'notify_partner')
  )
);

