CREATE TABLE IF NOT EXISTS organizations.data_access_restrictions (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  request_id text NOT NULL REFERENCES organizations.data_access_requests(id),
  enforcement_case_id text NOT NULL REFERENCES organizations.data_use_enforcement_cases(id),
  attestation_id text NOT NULL REFERENCES organizations.data_use_attestations(id),
  delivery_id text NOT NULL REFERENCES organizations.data_access_delivery_receipts(id),
  previous_restriction_id text REFERENCES organizations.data_access_restrictions(id),
  previous_restriction_root text,
  previous_restriction_state text,
  restriction_state text NOT NULL CONSTRAINT data_access_restriction_state CHECK (
    restriction_state IN ('remediation_hold', 'suspended', 'revoked', 'restored')
  ),
  rationale text NOT NULL CONSTRAINT data_access_restriction_rationale_length CHECK (length(btrim(rationale)) BETWEEN 12 AND 2000),
  evidence_event_roots text[] NOT NULL CONSTRAINT data_access_restriction_evidence_roots_shape CHECK (
    cardinality(evidence_event_roots) BETWEEN 1 AND 128 AND
    audit.is_sha256_hash_array(evidence_event_roots) AND
    audit.is_sorted_unique_text_array(evidence_event_roots)
  ),
  decided_by text NOT NULL REFERENCES identity.participants(id),
  decided_at timestamptz NOT NULL,
  expires_at timestamptz,
  restriction_hash text NOT NULL UNIQUE CONSTRAINT data_access_restriction_hash_shape CHECK (restriction_hash ~ '^[0-9a-f]{64}$'),
  restriction_root text NOT NULL UNIQUE CONSTRAINT data_access_restriction_root_shape CHECK (restriction_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CONSTRAINT data_access_restriction_safety_boundary CHECK (
    safety = '{
      "enforcementCaseBound": true,
      "approvedRequestBound": true,
      "separateApprovalPath": true,
      "independentDecisionRequired": true,
      "reviewerSeparationRequired": true,
      "deliveryBlockingEnforced": true,
      "appendOnly": true,
      "noRawDataEmbedded": true,
      "noPrivateContactData": true,
      "notFinalProofAuthority": true,
      "notCarbonCredit": true,
      "notFinancialAsset": true,
      "notTaxOffset": true,
      "notGuaranteedYield": true
    }'::jsonb
  ),
  audit_event_root text NOT NULL UNIQUE CONSTRAINT data_access_restriction_event_root_shape CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  CONSTRAINT data_access_restriction_predecessor_shape CHECK (
    (
      previous_restriction_id IS NULL AND
      previous_restriction_root IS NULL AND
      previous_restriction_state IS NULL
    ) OR (
      previous_restriction_id IS NOT NULL AND
      previous_restriction_root ~ '^[0-9a-f]{64}$' AND
      previous_restriction_state IN ('remediation_hold', 'suspended', 'revoked', 'restored') AND
      previous_restriction_id <> id
    )
  ),
  CONSTRAINT data_access_restriction_expiry_shape CHECK (
    (expires_at IS NULL OR expires_at > decided_at) AND
    (restriction_state <> 'restored' OR expires_at IS NULL)
  )
);

ALTER TABLE organizations.data_access_restrictions
  ADD COLUMN IF NOT EXISTS previous_restriction_id text;

ALTER TABLE organizations.data_access_restrictions
  ADD COLUMN IF NOT EXISTS previous_restriction_root text;

ALTER TABLE organizations.data_access_restrictions
  ADD COLUMN IF NOT EXISTS previous_restriction_state text;

CREATE UNIQUE INDEX IF NOT EXISTS organizations_data_access_restriction_initial_request
  ON organizations.data_access_restrictions (request_id)
  WHERE previous_restriction_id IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS organizations_data_access_restriction_successor
  ON organizations.data_access_restrictions (previous_restriction_id)
  WHERE previous_restriction_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS organizations_data_access_restriction_request_time
  ON organizations.data_access_restrictions (request_id, decided_at ASC, id ASC);

CREATE INDEX IF NOT EXISTS organizations_data_access_restriction_enforcement_time
  ON organizations.data_access_restrictions (enforcement_case_id, decided_at ASC, id ASC);

CREATE INDEX IF NOT EXISTS organizations_data_access_restriction_organization_time
  ON organizations.data_access_restrictions (organization_id, decided_at DESC, id ASC);

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_restriction_previous_id_fk') THEN
    ALTER TABLE organizations.data_access_restrictions
      ADD CONSTRAINT data_access_restriction_previous_id_fk
      FOREIGN KEY (previous_restriction_id)
      REFERENCES organizations.data_access_restrictions(id)
      NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_restriction_state') THEN
    ALTER TABLE organizations.data_access_restrictions
      ADD CONSTRAINT data_access_restriction_state
      CHECK (restriction_state IN ('remediation_hold', 'suspended', 'revoked', 'restored')) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_restriction_rationale_length') THEN
    ALTER TABLE organizations.data_access_restrictions
      ADD CONSTRAINT data_access_restriction_rationale_length
      CHECK (length(btrim(rationale)) BETWEEN 12 AND 2000) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_restriction_evidence_roots_shape') THEN
    ALTER TABLE organizations.data_access_restrictions
      ADD CONSTRAINT data_access_restriction_evidence_roots_shape
      CHECK (
        cardinality(evidence_event_roots) BETWEEN 1 AND 128 AND
        audit.is_sha256_hash_array(evidence_event_roots) AND
        audit.is_sorted_unique_text_array(evidence_event_roots)
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_restriction_hash_shape') THEN
    ALTER TABLE organizations.data_access_restrictions
      ADD CONSTRAINT data_access_restriction_hash_shape
      CHECK (restriction_hash ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_restriction_root_shape') THEN
    ALTER TABLE organizations.data_access_restrictions
      ADD CONSTRAINT data_access_restriction_root_shape
      CHECK (restriction_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_restriction_safety_boundary') THEN
    ALTER TABLE organizations.data_access_restrictions
      ADD CONSTRAINT data_access_restriction_safety_boundary
      CHECK (
        safety = '{
          "enforcementCaseBound": true,
          "approvedRequestBound": true,
          "separateApprovalPath": true,
          "independentDecisionRequired": true,
          "reviewerSeparationRequired": true,
          "deliveryBlockingEnforced": true,
          "appendOnly": true,
          "noRawDataEmbedded": true,
          "noPrivateContactData": true,
          "notFinalProofAuthority": true,
          "notCarbonCredit": true,
          "notFinancialAsset": true,
          "notTaxOffset": true,
          "notGuaranteedYield": true
        }'::jsonb
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_restriction_event_root_shape') THEN
    ALTER TABLE organizations.data_access_restrictions
      ADD CONSTRAINT data_access_restriction_event_root_shape
      CHECK (audit_event_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_restriction_predecessor_shape') THEN
    ALTER TABLE organizations.data_access_restrictions
      ADD CONSTRAINT data_access_restriction_predecessor_shape
      CHECK (
        (
          previous_restriction_id IS NULL AND
          previous_restriction_root IS NULL AND
          previous_restriction_state IS NULL
        ) OR (
          previous_restriction_id IS NOT NULL AND
          previous_restriction_root ~ '^[0-9a-f]{64}$' AND
          previous_restriction_state IN ('remediation_hold', 'suspended', 'revoked', 'restored') AND
          previous_restriction_id <> id
        )
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_restriction_expiry_shape') THEN
    ALTER TABLE organizations.data_access_restrictions
      ADD CONSTRAINT data_access_restriction_expiry_shape
      CHECK (
        (expires_at IS NULL OR expires_at > decided_at) AND
        (restriction_state <> 'restored' OR expires_at IS NULL)
      ) NOT VALID;
  END IF;
END;
$$;

CREATE TABLE IF NOT EXISTS organizations.data_access_accountability_packets (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  request_id text NOT NULL REFERENCES organizations.data_access_requests(id),
  agreement_id text NOT NULL REFERENCES organizations.data_sharing_agreements(id),
  generated_by text NOT NULL REFERENCES identity.participants(id),
  generated_at timestamptz NOT NULL,
  intended_audience text NOT NULL,
  request_status text NOT NULL CHECK (request_status IN ('pending', 'approved', 'denied', 'revoked', 'expired')),
  counts jsonb NOT NULL CHECK (
    counts ? 'agreementRevocationCount' AND
    counts ? 'agreementSupersessionCount' AND
    counts ? 'deliveryReceiptCount' AND
    counts ? 'dataUseAttestationCount' AND
    counts ? 'enforcementCaseCount' AND
    counts ? 'activeRestrictionCount' AND
    counts ? 'totalRestrictionCount'
  ),
  lineage_roots jsonb NOT NULL CHECK (
    lineage_roots ? 'accessRoot' AND
    lineage_roots ? 'agreementRevocationRoots' AND
    lineage_roots ? 'agreementSupersessionRoots' AND
    lineage_roots ? 'deliveryRoots' AND
    lineage_roots ? 'usageRoots' AND
    lineage_roots ? 'enforcementRoots' AND
    lineage_roots ? 'restrictionRoots'
  ),
  packet_hash text NOT NULL UNIQUE,
  packet_root text NOT NULL UNIQUE,
  safety jsonb NOT NULL CHECK (
    safety @> '{
      "requestBound": true,
      "appendOnlyLedgerDerived": true,
      "hashOnlyLineage": true,
      "noRawDataEmbedded": true,
      "noPrivateContactData": true,
      "observerReadable": true,
      "notFinalProofAuthority": true,
      "notCarbonCredit": true,
      "notFinancialAsset": true,
      "notTaxOffset": true,
      "notGuaranteedYield": true
    }'::jsonb
  ),
  audit_event_root text NOT NULL UNIQUE
);

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_counts_are_valid(value_to_check jsonb)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
STRICT
AS $$
DECLARE
  required_keys constant text[] := ARRAY[
    'agreementRevocationCount',
    'agreementSupersessionCount',
    'deliveryReceiptCount',
    'dataUseAttestationCount',
    'enforcementCaseCount',
    'activeRestrictionCount',
    'totalRestrictionCount'
  ];
  required_key text;
  numeric_value numeric;
BEGIN
  IF jsonb_typeof(value_to_check) <> 'object' OR (
    SELECT count(*) FROM jsonb_object_keys(value_to_check)
  ) <> cardinality(required_keys) THEN
    RETURN false;
  END IF;
  FOREACH required_key IN ARRAY required_keys LOOP
    IF NOT value_to_check ? required_key OR jsonb_typeof(value_to_check -> required_key) <> 'number' THEN
      RETURN false;
    END IF;
    BEGIN
      numeric_value := (value_to_check ->> required_key)::numeric;
    EXCEPTION WHEN OTHERS THEN
      RETURN false;
    END;
    IF numeric_value < 0 OR numeric_value <> trunc(numeric_value) OR numeric_value > 2147483647 THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN (value_to_check ->> 'activeRestrictionCount')::integer <= 1;
END;
$$;

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_lineage_roots_are_valid(value_to_check jsonb)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
STRICT
AS $$
DECLARE
  required_keys constant text[] := ARRAY[
    'accessRoot',
    'agreementRevocationRoots',
    'agreementSupersessionRoots',
    'deliveryRoots',
    'usageRoots',
    'enforcementRoots',
    'restrictionRoots'
  ];
  array_keys constant text[] := ARRAY[
    'agreementRevocationRoots',
    'agreementSupersessionRoots',
    'deliveryRoots',
    'usageRoots',
    'enforcementRoots',
    'restrictionRoots'
  ];
  array_key text;
  root_values text[];
BEGIN
  IF jsonb_typeof(value_to_check) <> 'object' OR (
    SELECT count(*) FROM jsonb_object_keys(value_to_check)
  ) <> cardinality(required_keys) THEN
    RETURN false;
  END IF;
  IF
    NOT value_to_check ? 'accessRoot' OR
    jsonb_typeof(value_to_check -> 'accessRoot') <> 'string' OR
    (value_to_check ->> 'accessRoot') !~ '^[0-9a-f]{64}$'
  THEN
    RETURN false;
  END IF;
  FOREACH array_key IN ARRAY array_keys LOOP
    IF
      NOT value_to_check ? array_key OR
      jsonb_typeof(value_to_check -> array_key) <> 'array' OR
      jsonb_array_length(value_to_check -> array_key) > 1024 OR
      EXISTS (
        SELECT 1
        FROM jsonb_array_elements(value_to_check -> array_key) AS element(value)
        WHERE jsonb_typeof(element.value) <> 'string' OR trim(both '"' from element.value::text) !~ '^[0-9a-f]{64}$'
      )
    THEN
      RETURN false;
    END IF;
    SELECT COALESCE(array_agg(entry.value ORDER BY entry.ordinality), ARRAY[]::text[])
    INTO root_values
    FROM jsonb_array_elements_text(value_to_check -> array_key) WITH ORDINALITY AS entry(value, ordinality);
    IF root_values <> ARRAY(SELECT DISTINCT root FROM unnest(root_values) AS root ORDER BY root) THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_packets_audience_length') THEN
    ALTER TABLE organizations.data_access_accountability_packets
      ADD CONSTRAINT data_access_accountability_packets_audience_length
      CHECK (length(btrim(intended_audience)) BETWEEN 3 AND 300) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_packets_counts_shape') THEN
    ALTER TABLE organizations.data_access_accountability_packets
      ADD CONSTRAINT data_access_accountability_packets_counts_shape
      CHECK (organizations.data_access_accountability_counts_are_valid(counts)) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_packets_lineage_shape') THEN
    ALTER TABLE organizations.data_access_accountability_packets
      ADD CONSTRAINT data_access_accountability_packets_lineage_shape
      CHECK (organizations.data_access_accountability_lineage_roots_are_valid(lineage_roots)) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_packets_hash_shape') THEN
    ALTER TABLE organizations.data_access_accountability_packets
      ADD CONSTRAINT data_access_accountability_packets_hash_shape
      CHECK (packet_hash ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_packets_root_shape') THEN
    ALTER TABLE organizations.data_access_accountability_packets
      ADD CONSTRAINT data_access_accountability_packets_root_shape
      CHECK (packet_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_packets_event_root_shape') THEN
    ALTER TABLE organizations.data_access_accountability_packets
      ADD CONSTRAINT data_access_accountability_packets_event_root_shape
      CHECK (audit_event_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_packets_safety_boundary') THEN
    ALTER TABLE organizations.data_access_accountability_packets
      ADD CONSTRAINT data_access_accountability_packets_safety_boundary
      CHECK (
        safety = '{
          "requestBound": true,
          "appendOnlyLedgerDerived": true,
          "hashOnlyLineage": true,
          "noRawDataEmbedded": true,
          "noPrivateContactData": true,
          "observerReadable": true,
          "notFinalProofAuthority": true,
          "notCarbonCredit": true,
          "notFinancialAsset": true,
          "notTaxOffset": true,
          "notGuaranteedYield": true
        }'::jsonb
      ) NOT VALID;
  END IF;
END;
$$;

