CREATE TABLE IF NOT EXISTS organizations.data_access_accountability_verifications (
  id text PRIMARY KEY,
  packet_id text NOT NULL REFERENCES organizations.data_access_accountability_packets(id),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  request_id text NOT NULL REFERENCES organizations.data_access_requests(id),
  valid boolean NOT NULL,
  issues text[] NOT NULL DEFAULT ARRAY[]::text[],
  expected_packet_root text,
  packet_hash text NOT NULL,
  recomputed_packet_hash text NOT NULL,
  packet_root text NOT NULL,
  recomputed_packet_root text NOT NULL,
  verified_by text NOT NULL REFERENCES identity.participants(id),
  verified_at timestamptz NOT NULL,
  verification_root text NOT NULL UNIQUE,
  safety jsonb NOT NULL CHECK (
    safety @> '{
      "replayVerification": true,
      "hashOnlyLineage": true,
      "noRawDataEmbedded": true,
      "noPrivateContactData": true,
      "notFinalProofAuthority": true,
      "notCarbonCredit": true,
      "notFinancialAsset": true,
      "notTaxOffset": true,
      "notGuaranteedYield": true
    }'::jsonb
  ),
  audit_event_root text NOT NULL UNIQUE,
  CHECK (
    issues <@ ARRAY[
      'packet_hash_mismatch',
      'packet_root_mismatch',
      'lineage_stale',
      'expected_root_mismatch',
      'safety_boundary_violation'
    ]::text[]
  ),
  CHECK ((valid = true AND cardinality(issues) = 0) OR (valid = false AND cardinality(issues) > 0))
);

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_verifications_issue_shape') THEN
    ALTER TABLE organizations.data_access_accountability_verifications
      ADD CONSTRAINT data_access_accountability_verifications_issue_shape
      CHECK (
        cardinality(issues) <= 5 AND
        audit.is_sorted_unique_text_array(issues) AND
        issues <@ ARRAY[
          'packet_hash_mismatch',
          'packet_root_mismatch',
          'lineage_stale',
          'expected_root_mismatch',
          'safety_boundary_violation'
        ]::text[]
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_verifications_expected_root_shape') THEN
    ALTER TABLE organizations.data_access_accountability_verifications
      ADD CONSTRAINT data_access_accountability_verifications_expected_root_shape
      CHECK (expected_packet_root IS NULL OR expected_packet_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_verifications_hash_shape') THEN
    ALTER TABLE organizations.data_access_accountability_verifications
      ADD CONSTRAINT data_access_accountability_verifications_hash_shape
      CHECK (
        packet_hash ~ '^[0-9a-f]{64}$' AND
        recomputed_packet_hash ~ '^[0-9a-f]{64}$' AND
        packet_root ~ '^[0-9a-f]{64}$' AND
        recomputed_packet_root ~ '^[0-9a-f]{64}$' AND
        verification_root ~ '^[0-9a-f]{64}$' AND
        audit_event_root ~ '^[0-9a-f]{64}$'
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_verifications_safety_boundary') THEN
    ALTER TABLE organizations.data_access_accountability_verifications
      ADD CONSTRAINT data_access_accountability_verifications_safety_boundary
      CHECK (
        safety = '{
          "replayVerification": true,
          "hashOnlyLineage": true,
          "noRawDataEmbedded": true,
          "noPrivateContactData": true,
          "notFinalProofAuthority": true,
          "notCarbonCredit": true,
          "notFinancialAsset": true,
          "notTaxOffset": true,
          "notGuaranteedYield": true
        }'::jsonb
      ) NOT VALID;
  END IF;
END;
$$;

