CREATE OR REPLACE FUNCTION organizations.validate_data_access_accountability_disclosure()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  packet organizations.data_access_accountability_packets%ROWTYPE;
  verification organizations.data_access_accountability_verifications%ROWTYPE;
BEGIN
  SELECT * INTO STRICT packet
  FROM organizations.data_access_accountability_packets
  WHERE id = NEW.packet_id;

  SELECT * INTO STRICT verification
  FROM organizations.data_access_accountability_verifications
  WHERE id = NEW.verification_id;

  IF packet.organization_id <> NEW.organization_id OR verification.organization_id <> NEW.organization_id THEN
    RAISE EXCEPTION 'accountability disclosure organization binding mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF verification.packet_id <> packet.id OR verification.request_id <> packet.request_id THEN
    RAISE EXCEPTION 'accountability disclosure verification does not bind to packet' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.valid OR cardinality(verification.issues) <> 0 THEN
    RAISE EXCEPTION 'accountability disclosure requires valid replay verification' USING ERRCODE = 'check_violation';
  END IF;
  IF
    packet.packet_hash <> NEW.packet_hash OR
    packet.packet_root <> NEW.packet_root OR
    verification.packet_hash <> packet.packet_hash OR
    verification.recomputed_packet_hash <> packet.packet_hash OR
    verification.packet_root <> packet.packet_root OR
    verification.recomputed_packet_root <> packet.packet_root OR
    verification.verification_root <> NEW.verification_root
  THEN
    RAISE EXCEPTION 'accountability disclosure hash binding mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF packet.generated_by = verification.verified_by OR packet.generated_by = NEW.published_by OR verification.verified_by = NEW.published_by THEN
    RAISE EXCEPTION 'accountability disclosure requires three separate actors' USING ERRCODE = 'check_violation';
  END IF;
  IF verification.verified_at < packet.generated_at OR NEW.published_at < verification.verified_at THEN
    RAISE EXCEPTION 'accountability disclosure chronology is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT (
    packet.safety @> '{"hashOnlyLineage": true, "noRawDataEmbedded": true, "noPrivateContactData": true}'::jsonb AND
    verification.safety @> '{"replayVerification": true, "hashOnlyLineage": true, "noRawDataEmbedded": true, "noPrivateContactData": true}'::jsonb
  ) THEN
    RAISE EXCEPTION 'accountability disclosure source safety boundary is invalid' USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_access_accountability_disclosures_validate ON organizations.data_access_accountability_disclosures;
CREATE TRIGGER organizations_data_access_accountability_disclosures_validate
BEFORE INSERT ON organizations.data_access_accountability_disclosures
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_access_accountability_disclosure();

CREATE TABLE IF NOT EXISTS organizations.data_access_accountability_disclosure_challenges (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  disclosure_id text NOT NULL REFERENCES organizations.data_access_accountability_disclosures(id),
  disclosure_root text NOT NULL,
  reason text NOT NULL CHECK (
    reason IN ('lineage_stale', 'incorrect_metadata', 'privacy_risk', 'governance_violation', 'source_verification_disputed', 'other')
  ),
  statement text NOT NULL,
  evidence_event_roots text[] NOT NULL,
  challenged_by text NOT NULL REFERENCES identity.participants(id),
  challenger_role text NOT NULL CHECK (challenger_role IN ('owner', 'admin', 'verifier', 'researcher', 'community', 'observer')),
  challenged_at timestamptz NOT NULL,
  challenge_hash text NOT NULL UNIQUE,
  challenge_root text NOT NULL UNIQUE,
  safety jsonb NOT NULL CHECK (
    safety @> '{
      "disclosureBound": true,
      "publicStatement": true,
      "appendOnly": true,
      "humanResolutionRequired": true,
      "noRawDataEmbedded": true,
      "noPrivateContactData": true,
      "notFinalProofAuthority": true,
      "notCarbonCredit": true,
      "notFinancialAsset": true,
      "notTaxOffset": true,
      "notGuaranteedYield": true
    }'::jsonb
  ),
  audit_event_root text NOT NULL UNIQUE,
  UNIQUE (disclosure_id, challenged_by, reason),
  CHECK (cardinality(evidence_event_roots) > 0)
);

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_disclosure_challenges_text_shape') THEN
    ALTER TABLE organizations.data_access_accountability_disclosure_challenges
      ADD CONSTRAINT data_access_accountability_disclosure_challenges_text_shape
      CHECK (
        length(statement) BETWEEN 24 AND 2000 AND
        statement = btrim(statement)
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_disclosure_challenges_evidence_shape') THEN
    ALTER TABLE organizations.data_access_accountability_disclosure_challenges
      ADD CONSTRAINT data_access_accountability_disclosure_challenges_evidence_shape
      CHECK (
        cardinality(evidence_event_roots) BETWEEN 1 AND 128 AND
        audit.is_sorted_unique_text_array(evidence_event_roots) AND
        audit.is_sha256_hash_array(evidence_event_roots)
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_disclosure_challenges_hash_shape') THEN
    ALTER TABLE organizations.data_access_accountability_disclosure_challenges
      ADD CONSTRAINT data_access_accountability_disclosure_challenges_hash_shape
      CHECK (
        id ~ '^cp_data_access_disclosure_challenge_[0-9a-f]{24}$' AND
        disclosure_root ~ '^[0-9a-f]{64}$' AND
        challenge_hash ~ '^[0-9a-f]{64}$' AND
        challenge_root ~ '^[0-9a-f]{64}$' AND
        audit_event_root ~ '^[0-9a-f]{64}$'
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_disclosure_challenges_timestamp_precision') THEN
    ALTER TABLE organizations.data_access_accountability_disclosure_challenges
      ADD CONSTRAINT data_access_accountability_disclosure_challenges_timestamp_precision
      CHECK (challenged_at = date_trunc('milliseconds', challenged_at)) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_accountability_disclosure_challenges_exact_safety') THEN
    ALTER TABLE organizations.data_access_accountability_disclosure_challenges
      ADD CONSTRAINT data_access_accountability_disclosure_challenges_exact_safety
      CHECK (
        safety = '{
          "disclosureBound": true,
          "publicStatement": true,
          "appendOnly": true,
          "humanResolutionRequired": true,
          "noRawDataEmbedded": true,
          "noPrivateContactData": true,
          "notFinalProofAuthority": true,
          "notCarbonCredit": true,
          "notFinancialAsset": true,
          "notTaxOffset": true,
          "notGuaranteedYield": true
        }'::jsonb
      ) NOT VALID;
  END IF;
END;
$$;

