CREATE OR REPLACE FUNCTION organizations.validate_data_access_accountability_disclosure_challenge()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  disclosure organizations.data_access_accountability_disclosures%ROWTYPE;
BEGIN
  SELECT * INTO STRICT disclosure
  FROM organizations.data_access_accountability_disclosures
  WHERE id = NEW.disclosure_id;

  IF disclosure.organization_id <> NEW.organization_id OR disclosure.disclosure_root <> NEW.disclosure_root THEN
    RAISE EXCEPTION 'accountability disclosure challenge binding mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.challenged_at < disclosure.published_at THEN
    RAISE EXCEPTION 'accountability disclosure challenge cannot predate publication' USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;

