  previous_resolution_root text,
  reviewed_by text NOT NULL REFERENCES identity.participants(id),
  reviewer_role text NOT NULL CHECK (reviewer_role IN ('owner', 'admin', 'verifier')),
  reviewed_at timestamptz NOT NULL,
  resolution_hash text NOT NULL UNIQUE,
  resolution_root text NOT NULL UNIQUE,
  safety jsonb NOT NULL CHECK (
    safety @> '{
      "challengeBound": true,
      "independentHumanReviewRequired": true,
      "appendOnly": true,
      "historyPreserved": true,
      "noAutomatedFinalAuthority": true,
      "noRawDataEmbedded": true,
      "noPrivateContactData": true,
      "notFinalProofAuthority": true,
      "notCarbonCredit": true,
      "notFinancialAsset": true,
      "notTaxOffset": true,
      "notGuaranteedYield": true
    }'::jsonb
  ),
  audit_event_root text NOT NULL UNIQUE,
  CHECK (length(rationale) BETWEEN 24 AND 2000 AND rationale = btrim(rationale)),
  CHECK (
    cardinality(evidence_event_roots) BETWEEN 1 AND 128 AND
    audit.is_sorted_unique_text_array(evidence_event_roots) AND
    audit.is_sha256_hash_array(evidence_event_roots)
  ),
  CHECK (id ~ '^cp_data_access_disclosure_resolution_[a-f0-9]{24}$'),
  CHECK (resolution_hash ~ '^[a-f0-9]{64}$'),
  CHECK (resolution_root ~ '^[a-f0-9]{64}$'),
  CHECK (audit_event_root ~ '^[a-f0-9]{64}$'),
  CHECK (previous_resolution_root IS NULL OR previous_resolution_root ~ '^[a-f0-9]{64}$'),
  CHECK (date_trunc('milliseconds', reviewed_at) = reviewed_at),
  CHECK (
    (decision = 'upheld' AND remedial_action IN ('publish_correction', 'publish_withdrawal_notice')) OR
    (decision IN ('dismissed', 'needs_more_evidence') AND remedial_action = 'none')
  ),
  CHECK (
    (previous_resolution_id IS NULL AND previous_resolution_root IS NULL) OR
    (previous_resolution_id IS NOT NULL AND previous_resolution_root IS NOT NULL)
  )
);

