      ) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_disclosure_resolution_hash_shape') THEN
    ALTER TABLE organizations.data_access_accountability_disclosure_resolutions
      ADD CONSTRAINT data_access_disclosure_resolution_hash_shape
      CHECK (
        id ~ '^cp_data_access_disclosure_resolution_[a-f0-9]{24}$' AND
