        (previous_resolution_root IS NULL OR previous_resolution_root ~ '^[a-f0-9]{64}$')
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_disclosure_resolution_timestamp_precision') THEN
    ALTER TABLE organizations.data_access_accountability_disclosure_resolutions
      ADD CONSTRAINT data_access_disclosure_resolution_timestamp_precision
      CHECK (date_trunc('milliseconds', reviewed_at) = reviewed_at) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_disclosure_resolution_exact_safety') THEN
    ALTER TABLE organizations.data_access_accountability_disclosure_resolutions
      ADD CONSTRAINT data_access_disclosure_resolution_exact_safety
      CHECK (
        safety = '{
          "appendOnly": true,
          "challengeBound": true,
          "historyPreserved": true,
          "independentHumanReviewRequired": true,
          "noAutomatedFinalAuthority": true,
          "noPrivateContactData": true,
          "noRawDataEmbedded": true,
          "notCarbonCredit": true,
          "notFinalProofAuthority": true,
          "notFinancialAsset": true,
