CREATE OR REPLACE FUNCTION organizations.validate_data_access_accountability_disclosure_resolution()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  challenge organizations.data_access_accountability_disclosure_challenges%ROWTYPE;
  disclosure organizations.data_access_accountability_disclosures%ROWTYPE;
  previous_resolution organizations.data_access_accountability_disclosure_resolutions%ROWTYPE;
BEGIN
  SELECT * INTO STRICT challenge
  FROM organizations.data_access_accountability_disclosure_challenges
  WHERE id = NEW.challenge_id;

  SELECT * INTO STRICT disclosure
  FROM organizations.data_access_accountability_disclosures
  WHERE id = NEW.disclosure_id;

  IF challenge.disclosure_id <> disclosure.id OR challenge.organization_id <> NEW.organization_id OR disclosure.organization_id <> NEW.organization_id THEN
    RAISE EXCEPTION 'accountability disclosure resolution binding mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reviewed_by = challenge.challenged_by OR NEW.reviewed_by = disclosure.published_by THEN
    RAISE EXCEPTION 'accountability disclosure resolution requires independent reviewer' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reviewed_at < challenge.challenged_at THEN
    RAISE EXCEPTION 'accountability disclosure resolution cannot predate challenge' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM organizations.data_access_accountability_disclosure_resolutions existing
    WHERE existing.challenge_id = challenge.id AND existing.decision <> 'needs_more_evidence'
  ) THEN
    RAISE EXCEPTION 'accountability disclosure challenge already has final resolution' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.previous_resolution_id IS NULL THEN
    IF EXISTS (
      SELECT 1 FROM organizations.data_access_accountability_disclosure_resolutions existing
      WHERE existing.challenge_id = challenge.id
    ) THEN
      RAISE EXCEPTION 'accountability disclosure follow-up resolution must bind previous resolution' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    SELECT * INTO STRICT previous_resolution
    FROM organizations.data_access_accountability_disclosure_resolutions
    WHERE id = NEW.previous_resolution_id;

    IF
      previous_resolution.challenge_id <> challenge.id OR
      previous_resolution.resolution_root <> NEW.previous_resolution_root OR
      previous_resolution.decision <> 'needs_more_evidence' OR
      NEW.reviewed_at <= previous_resolution.reviewed_at OR
      EXISTS (
        SELECT 1 FROM organizations.data_access_accountability_disclosure_resolutions later
        WHERE later.challenge_id = challenge.id AND later.reviewed_at > previous_resolution.reviewed_at
      )
    THEN
      RAISE EXCEPTION 'accountability disclosure previous resolution lineage is invalid' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_access_accountability_disclosure_resolutions ON organizations.data_access_accountability_disclosure_resolutions;
DROP TRIGGER IF EXISTS org_data_access_disclosure_resolution_validate ON organizations.data_access_accountability_disclosure_resolutions;
CREATE TRIGGER org_data_access_disclosure_resolution_validate
BEFORE INSERT ON organizations.data_access_accountability_disclosure_resolutions
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_access_accountability_disclosure_resolution();

