      CHECK (length(statement) BETWEEN 24 AND 2000 AND statement = btrim(statement)) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_disclosure_notice_evidence_shape') THEN
    ALTER TABLE organizations.data_access_accountability_disclosure_notices
      ADD CONSTRAINT data_access_disclosure_notice_evidence_shape
      CHECK (
        cardinality(evidence_event_roots) BETWEEN 1 AND 128 AND
        audit.is_sorted_unique_text_array(evidence_event_roots) AND
        audit.is_sha256_hash_array(evidence_event_roots)
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_disclosure_notice_hash_shape') THEN
    ALTER TABLE organizations.data_access_accountability_disclosure_notices
      ADD CONSTRAINT data_access_disclosure_notice_hash_shape
      CHECK (
        id ~ '^cp_data_access_disclosure_notice_[0-9a-f]{24}$' AND
        notice_hash ~ '^[0-9a-f]{64}$' AND
        notice_root ~ '^[0-9a-f]{64}$' AND
        audit_event_root ~ '^[0-9a-f]{64}$'
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_disclosure_notice_timestamp_precision') THEN
    ALTER TABLE organizations.data_access_accountability_disclosure_notices
      ADD CONSTRAINT data_access_disclosure_notice_timestamp_precision
      CHECK (published_at = date_trunc('milliseconds', published_at)) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_access_disclosure_notice_exact_safety') THEN
    ALTER TABLE organizations.data_access_accountability_disclosure_notices
      ADD CONSTRAINT data_access_disclosure_notice_exact_safety
      CHECK (
        safety = '{
          "appendOnly": true,
          "noPrivateContactData": true,
          "noRawDataEmbedded": true,
          "notCarbonCredit": true,
          "notFinalProofAuthority": true,
          "notFinancialAsset": true,
          "notGuaranteedYield": true,
          "notTaxOffset": true,
          "originalDisclosurePreserved": true,
          "publicStatement": true,
          "resolutionBound": true
        }'::jsonb
      ) NOT VALID;
  END IF;
END;
