CREATE INDEX IF NOT EXISTS data_access_disclosure_notices_disclosure_event
  ON organizations.data_access_accountability_disclosure_notices (disclosure_id, published_at DESC, id ASC);
CREATE INDEX IF NOT EXISTS data_access_disclosure_notices_organization_event
  ON organizations.data_access_accountability_disclosure_notices (organization_id, published_at DESC, id ASC);

CREATE OR REPLACE FUNCTION organizations.validate_data_access_accountability_disclosure_notice()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  resolution organizations.data_access_accountability_disclosure_resolutions%ROWTYPE;
  challenge organizations.data_access_accountability_disclosure_challenges%ROWTYPE;
  disclosure organizations.data_access_accountability_disclosures%ROWTYPE;
  replacement organizations.data_access_accountability_disclosures%ROWTYPE;
BEGIN
  SELECT * INTO STRICT resolution
  FROM organizations.data_access_accountability_disclosure_resolutions
  WHERE id = NEW.resolution_id;

  SELECT * INTO STRICT challenge
  FROM organizations.data_access_accountability_disclosure_challenges
  WHERE id = NEW.challenge_id;

  SELECT * INTO STRICT disclosure
  FROM organizations.data_access_accountability_disclosures
  WHERE id = NEW.disclosure_id;

  IF
    resolution.challenge_id <> challenge.id OR
    resolution.disclosure_id <> disclosure.id OR
    resolution.organization_id <> NEW.organization_id OR
    challenge.organization_id <> NEW.organization_id OR
    disclosure.organization_id <> NEW.organization_id
  THEN
    RAISE EXCEPTION 'accountability disclosure notice binding mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF resolution.decision <> 'upheld' OR
    (resolution.remedial_action = 'publish_correction' AND NEW.notice_type <> 'correction') OR
    (resolution.remedial_action = 'publish_withdrawal_notice' AND NEW.notice_type <> 'withdrawal') OR
    resolution.remedial_action = 'none'
  THEN
    RAISE EXCEPTION 'accountability disclosure notice does not match resolution' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.published_by = disclosure.published_by OR NEW.published_by = challenge.challenged_by THEN
    RAISE EXCEPTION 'accountability disclosure notice requires independent publisher' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.published_at < resolution.reviewed_at THEN
    RAISE EXCEPTION 'accountability disclosure notice cannot predate resolution' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.notice_type = 'correction' THEN
    SELECT * INTO STRICT replacement
    FROM organizations.data_access_accountability_disclosures
    WHERE id = NEW.replacement_disclosure_id;
    IF replacement.id = disclosure.id OR replacement.organization_id <> disclosure.organization_id THEN
      RAISE EXCEPTION 'accountability correction replacement disclosure is invalid' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_access_accountability_disclosure_notices_val ON organizations.data_access_accountability_disclosure_notices;
DROP TRIGGER IF EXISTS org_data_access_disclosure_notice_validate ON organizations.data_access_accountability_disclosure_notices;
CREATE TRIGGER org_data_access_disclosure_notice_validate
BEFORE INSERT ON organizations.data_access_accountability_disclosure_notices
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_access_accountability_disclosure_notice();

CREATE OR REPLACE FUNCTION audit.stable_json(document jsonb)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
STRICT
AS $$
DECLARE
  encoded text;
BEGIN
  CASE jsonb_typeof(document)
    WHEN 'object' THEN
      SELECT '{' || COALESCE(
        string_agg(to_json(key_name)::text || ':' || audit.stable_json(key_value), ',' ORDER BY key_name),
        ''
      ) || '}'
      INTO encoded
      FROM jsonb_each(document) AS item(key_name, key_value);
    WHEN 'array' THEN
      SELECT '[' || COALESCE(
        string_agg(audit.stable_json(item_value), ',' ORDER BY item_position),
        ''
      ) || ']'
      INTO encoded
      FROM jsonb_array_elements(document) WITH ORDINALITY AS item(item_value, item_position);
    ELSE
      encoded := document::text;
  END CASE;
  RETURN encoded;
END;
$$;

CREATE OR REPLACE FUNCTION audit.sha256_stable_json(document jsonb)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(digest(convert_to(audit.stable_json(document), 'UTF8'), 'sha256'), 'hex');
$$;

CREATE OR REPLACE FUNCTION audit.iso8601_millis(timestamp_value timestamptz)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT to_char(timestamp_value AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
$$;

CREATE TABLE IF NOT EXISTS projects.projects (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  region_id text NOT NULL,
  title text NOT NULL,
  project_type text NOT NULL CHECK (project_type IN ('reforestation', 'ecosystem_restoration', 'biodiversity', 'water', 'soil_regeneration', 'climate_observation')),
  status text NOT NULL DEFAULT 'submitted' CHECK (status IN ('submitted', 'under_review', 'active', 'monitored', 'challenged', 'suspended', 'archived')),
  location jsonb NOT NULL,
  area_hectares numeric(18, 6) NOT NULL DEFAULT 0 CHECK (area_hectares >= 0),
  target_tree_count bigint NOT NULL DEFAULT 0 CHECK (target_tree_count >= 0),
  biodiversity_indicators text[] NOT NULL DEFAULT ARRAY[]::text[],
  water_indicators text[] NOT NULL DEFAULT ARRAY[]::text[],
  climate_risk_indicators text[] NOT NULL DEFAULT ARRAY[]::text[],
  monitoring_cadence_days integer NOT NULL DEFAULT 90 CHECK (monitoring_cadence_days > 0),
  governance_policy_id text,
  governance_approval_id text,
  created_by text NOT NULL REFERENCES identity.participants(id),
  created_by_role text NOT NULL CHECK (created_by_role IN ('owner', 'admin', 'verifier')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  project_hash text NOT NULL UNIQUE,
  project_root text NOT NULL UNIQUE CHECK (project_root ~ '^[0-9a-f]{64}$'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  audit_history jsonb NOT NULL,
  claim_boundary jsonb NOT NULL,
  CHECK (project_hash ~ '^[0-9a-f]{64}$'),
  CHECK (status = 'submitted'),
  CHECK (governance_approval_id IS NULL),
  CHECK (updated_at = created_at)
);

ALTER TABLE projects.projects
  ADD COLUMN IF NOT EXISTS created_by_role text,
  ADD COLUMN IF NOT EXISTS project_root text,
  ADD COLUMN IF NOT EXISTS audit_event_root text;

CREATE UNIQUE INDEX IF NOT EXISTS projects_project_root_unique
  ON projects.projects (project_root)
  WHERE project_root IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS projects_audit_event_root_unique
  ON projects.projects (audit_event_root)
  WHERE audit_event_root IS NOT NULL;

CREATE TABLE IF NOT EXISTS projects.project_status_transitions (
  id text PRIMARY KEY,
  project_id text NOT NULL REFERENCES projects.projects(id),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  previous_status text NOT NULL CHECK (previous_status IN ('submitted', 'under_review', 'active', 'monitored', 'challenged', 'suspended', 'archived')),
  status text NOT NULL CHECK (status IN ('submitted', 'under_review', 'active', 'monitored', 'challenged', 'suspended', 'archived')),
  previous_project_root text NOT NULL CHECK (previous_project_root ~ '^[0-9a-f]{64}$'),
  governance_approval_id text,
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 12 AND 2000),
  updated_by text NOT NULL REFERENCES identity.participants(id),
  updater_role text NOT NULL CHECK (updater_role IN ('owner', 'admin', 'verifier')),
  updated_at timestamptz NOT NULL,
  transition_hash text NOT NULL UNIQUE CHECK (transition_hash ~ '^[0-9a-f]{64}$'),
  transition_root text NOT NULL UNIQUE CHECK (transition_root ~ '^[0-9a-f]{64}$'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$')
);

CREATE INDEX IF NOT EXISTS project_status_transitions_project_time
  ON projects.project_status_transitions (project_id, updated_at, id);

CREATE TABLE IF NOT EXISTS projects.monitoring_events (
  id text PRIMARY KEY,
  project_id text NOT NULL REFERENCES projects.projects(id),
  organization_id text NOT NULL,
  event_type text NOT NULL CHECK (event_type IN ('field_observation', 'terra_scene_review', 'biodiversity_survey', 'water_measurement', 'survival_check', 'risk_signal')),
  observed_at timestamptz NOT NULL,
  observed_by text NOT NULL REFERENCES identity.participants(id),
  observer_role text NOT NULL CHECK (observer_role IN ('owner', 'admin', 'verifier', 'researcher')),
  previous_status text NOT NULL CHECK (previous_status IN ('submitted', 'under_review', 'active', 'monitored', 'challenged', 'suspended', 'archived')),
  project_status text NOT NULL CHECK (project_status IN ('submitted', 'under_review', 'active', 'monitored', 'challenged', 'suspended', 'archived')),
  previous_project_root text NOT NULL CHECK (previous_project_root ~ '^[0-9a-f]{64}$'),
  evidence_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  terra_scene_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  biodiversity_indicators text[] NOT NULL DEFAULT ARRAY[]::text[],
  water_indicators text[] NOT NULL DEFAULT ARRAY[]::text[],
  climate_risk_indicators text[] NOT NULL DEFAULT ARRAY[]::text[],
  metrics jsonb NOT NULL DEFAULT '{}'::jsonb,
  state text NOT NULL CHECK (state IN ('submitted', 'accepted', 'needs_review', 'challenged')),
  rationale text NOT NULL,
  event_hash text NOT NULL UNIQUE,
  monitoring_root text NOT NULL UNIQUE CHECK (monitoring_root ~ '^[0-9a-f]{64}$'),
  audit_event_root text NOT NULL UNIQUE,
  CHECK (event_hash ~ '^[0-9a-f]{64}$'),
  CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  CHECK (length(btrim(rationale)) BETWEEN 12 AND 2000),
  CHECK (cardinality(evidence_ids) > 0 OR cardinality(terra_scene_ids) > 0)
);

ALTER TABLE projects.monitoring_events
  ADD COLUMN IF NOT EXISTS organization_id text,
  ADD COLUMN IF NOT EXISTS observer_role text,
  ADD COLUMN IF NOT EXISTS previous_status text,
  ADD COLUMN IF NOT EXISTS project_status text,
  ADD COLUMN IF NOT EXISTS previous_project_root text,
  ADD COLUMN IF NOT EXISTS monitoring_root text;

CREATE INDEX IF NOT EXISTS project_monitoring_events_project_time
  ON projects.monitoring_events (project_id, observed_at, id);

CREATE TABLE IF NOT EXISTS evidence.evidence_objects (
  id text PRIMARY KEY,
  project_id text NOT NULL REFERENCES projects.projects(id),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_root_at_submission text NOT NULL CHECK (project_root_at_submission ~ '^[0-9a-f]{64}$'),
  project_status_at_submission text NOT NULL CHECK (project_status_at_submission IN ('submitted', 'under_review', 'active', 'monitored', 'challenged', 'suspended')),
  project_region_id_at_submission text NOT NULL CHECK (length(btrim(project_region_id_at_submission)) BETWEEN 1 AND 160),
  project_authority_updated_at_at_submission timestamptz NOT NULL,
  evidence_type text NOT NULL CHECK (evidence_type IN ('tree_planting', 'restoration', 'biodiversity', 'water_project', 'soil_regeneration', 'climate_observation')),
  location jsonb NOT NULL,
  observed_at timestamptz NOT NULL,
  contributor_id text NOT NULL REFERENCES identity.participants(id),
  contributor_role text NOT NULL CHECK (contributor_role IN ('owner', 'admin', 'verifier', 'researcher', 'community')),
  media_hash text NOT NULL UNIQUE CHECK (media_hash ~ '^[0-9a-f]{64}$'),
  gps_hash text NOT NULL CHECK (gps_hash ~ '^[0-9a-f]{64}$'),
  offline_sync_id text,
  device_fingerprint_hash text CHECK (device_fingerprint_hash IS NULL OR device_fingerprint_hash ~ '^[0-9a-f]{64}$'),
  exif_hash text CHECK (exif_hash IS NULL OR exif_hash ~ '^[0-9a-f]{64}$'),
  verification_status text NOT NULL CHECK (verification_status IN ('validated', 'challenged')),
  confidence_score integer NOT NULL DEFAULT 0 CHECK (confidence_score >= 0 AND confidence_score <= 100),
  reviewers text[] NOT NULL DEFAULT ARRAY[]::text[] CHECK (cardinality(reviewers) = 0),
  validation_issues text[] NOT NULL DEFAULT ARRAY[]::text[],
  created_at timestamptz NOT NULL,
  evidence_hash text NOT NULL UNIQUE CHECK (evidence_hash ~ '^[0-9a-f]{64}$'),
  evidence_root text NOT NULL UNIQUE CHECK (evidence_root ~ '^[0-9a-f]{64}$'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  audit_history jsonb NOT NULL,
  claim_boundary jsonb NOT NULL,
  CHECK (observed_at <= created_at)
);

ALTER TABLE evidence.evidence_objects
  ADD COLUMN IF NOT EXISTS organization_id text,
  ADD COLUMN IF NOT EXISTS project_root_at_submission text,
  ADD COLUMN IF NOT EXISTS project_status_at_submission text,
  ADD COLUMN IF NOT EXISTS project_region_id_at_submission text,
  ADD COLUMN IF NOT EXISTS project_authority_updated_at_at_submission timestamptz,
  ADD COLUMN IF NOT EXISTS contributor_role text,
  ADD COLUMN IF NOT EXISTS offline_sync_id text,
  ADD COLUMN IF NOT EXISTS reviewers text[] DEFAULT ARRAY[]::text[],
  ADD COLUMN IF NOT EXISTS validation_issues text[] DEFAULT ARRAY[]::text[],
  ADD COLUMN IF NOT EXISTS evidence_hash text,
  ADD COLUMN IF NOT EXISTS evidence_root text,
  ADD COLUMN IF NOT EXISTS audit_event_root text,
  ADD COLUMN IF NOT EXISTS audit_history jsonb,
  ADD COLUMN IF NOT EXISTS claim_boundary jsonb;

CREATE UNIQUE INDEX IF NOT EXISTS evidence_objects_media_hash_unique
  ON evidence.evidence_objects (media_hash)
  WHERE evidence_root IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS evidence_objects_evidence_hash_unique
  ON evidence.evidence_objects (evidence_hash)
  WHERE evidence_hash IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS evidence_objects_evidence_root_unique
  ON evidence.evidence_objects (evidence_root)
  WHERE evidence_root IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS evidence_objects_audit_event_root_unique
  ON evidence.evidence_objects (audit_event_root)
  WHERE audit_event_root IS NOT NULL;

CREATE INDEX IF NOT EXISTS evidence_objects_project_time
  ON evidence.evidence_objects (project_id, created_at DESC, id);

CREATE INDEX IF NOT EXISTS evidence_objects_contributor_time
  ON evidence.evidence_objects (contributor_id, created_at DESC, id);

CREATE INDEX IF NOT EXISTS evidence_objects_status_type
  ON evidence.evidence_objects (verification_status, evidence_type, created_at DESC, id);

CREATE TABLE IF NOT EXISTS evidence.media_upload_intents (
  id text PRIMARY KEY,
  project_id text NOT NULL REFERENCES projects.projects(id),
  evidence_id text NOT NULL,
  content_hash text NOT NULL,
  content_type text NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp', 'application/json')),
  byte_length bigint NOT NULL CHECK (byte_length > 0 AND byte_length <= 52428800),
  object_key text NOT NULL UNIQUE,
  upload_url text NOT NULL,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL,
  created_by text NOT NULL REFERENCES identity.participants(id)
);

CREATE TABLE IF NOT EXISTS evidence.media_objects (
  id text PRIMARY KEY,
  intent_id text NOT NULL REFERENCES evidence.media_upload_intents(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  evidence_id text NOT NULL,
  content_hash text NOT NULL,
  content_type text NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp', 'application/json')),
  byte_length bigint NOT NULL CHECK (byte_length > 0 AND byte_length <= 52428800),
  object_key text NOT NULL,
  storage_provider text NOT NULL CHECK (storage_provider IN ('cloudflare_r2', 's3', 'gcs', 'ipfs_archive')),
  encryption_mode text NOT NULL CHECK (encryption_mode IN ('r2_managed', 'sse_kms', 'client_side')),
  encryption_key_ref text,
  malware_scan_status text NOT NULL CHECK (malware_scan_status IN ('clean', 'pending', 'quarantined')),
  malware_scanner text NOT NULL,
  malware_scanned_at timestamptz,
  malware_signature_version text,
  media_state text NOT NULL CHECK (media_state IN ('available', 'pending_scan', 'quarantined', 'duplicate')),
  duplicate_of_media_object_id text REFERENCES evidence.media_objects(id),
  exif_hash text,
  gps_hash text,
  integrity_root text NOT NULL UNIQUE,
  stored_at timestamptz NOT NULL,
  confirmed_by text NOT NULL REFERENCES identity.participants(id),
  UNIQUE (intent_id),
  UNIQUE (object_key)
);

CREATE TABLE IF NOT EXISTS evidence.consent_receipts (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  subject_id text NOT NULL REFERENCES identity.participants(id),
  subject_root text NOT NULL CHECK (subject_root ~ '^[0-9a-f]{64}$'),
  subject_authority_root text NOT NULL CHECK (subject_authority_root ~ '^[0-9a-f]{64}$'),
  device_fingerprint_hash text,
  purposes text[] NOT NULL,
  lawful_basis text NOT NULL CHECK (lawful_basis IN ('consent', 'public_interest', 'legitimate_interest')),
  privacy_mode text NOT NULL CHECK (privacy_mode IN ('precise', 'masked', 'restricted')),
  policy_version text NOT NULL,
  evidence_hash text NOT NULL,
  retention_days integer NOT NULL CHECK (retention_days > 0 AND retention_days <= 3650),
  actor_snapshot jsonb NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  subject_sequence bigint NOT NULL CHECK (subject_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  receipt_hash text NOT NULL UNIQUE CHECK (receipt_hash ~ '^[0-9a-f]{64}$'),
  receipt_root text NOT NULL UNIQUE,
  granted_at timestamptz NOT NULL,
  expires_at timestamptz,
  revoked_at timestamptz,
  revocation_reason text,
  created_by text NOT NULL REFERENCES identity.participants(id),
  safety jsonb NOT NULL,
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (subject_id, subject_sequence),
  CHECK (expires_at IS NULL OR granted_at < expires_at),
  CHECK (revoked_at IS NULL AND revocation_reason IS NULL),
  CHECK (jsonb_typeof(actor_snapshot) = 'object'),
  CHECK (jsonb_typeof(safety) = 'object')
);

CREATE TABLE IF NOT EXISTS evidence.consent_revocations (
  id text PRIMARY KEY,
  receipt_id text NOT NULL UNIQUE REFERENCES evidence.consent_receipts(id),
  receipt_root text NOT NULL CHECK (receipt_root ~ '^[0-9a-f]{64}$'),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  subject_id text NOT NULL REFERENCES identity.participants(id),
  subject_root text NOT NULL CHECK (subject_root ~ '^[0-9a-f]{64}$'),
  reason_hash text NOT NULL CHECK (reason_hash ~ '^[0-9a-f]{64}$'),
  revoked_at timestamptz NOT NULL,
  actor_snapshot jsonb NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  subject_sequence bigint NOT NULL CHECK (subject_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  revocation_hash text NOT NULL UNIQUE CHECK (revocation_hash ~ '^[0-9a-f]{64}$'),
  revocation_root text NOT NULL UNIQUE CHECK (revocation_root ~ '^[0-9a-f]{64}$'),
  revoked_by text NOT NULL REFERENCES identity.participants(id),
  safety jsonb NOT NULL,
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (subject_id, subject_sequence),
  CHECK (jsonb_typeof(actor_snapshot) = 'object'),
  CHECK (jsonb_typeof(safety) = 'object')
);

ALTER TABLE evidence.consent_receipts
  ADD COLUMN IF NOT EXISTS organization_id text,
  ADD COLUMN IF NOT EXISTS subject_root text,
  ADD COLUMN IF NOT EXISTS subject_authority_root text,
  ADD COLUMN IF NOT EXISTS actor_snapshot jsonb,
  ADD COLUMN IF NOT EXISTS command_hash text,
  ADD COLUMN IF NOT EXISTS subject_sequence bigint,
  ADD COLUMN IF NOT EXISTS previous_event_root text,
  ADD COLUMN IF NOT EXISTS receipt_hash text,
  ADD COLUMN IF NOT EXISTS safety jsonb,
  ADD COLUMN IF NOT EXISTS audit_event_root text;

ALTER TABLE identity.device_attestations
  ADD COLUMN IF NOT EXISTS organization_id text,
  ADD COLUMN IF NOT EXISTS subject_root text,
  ADD COLUMN IF NOT EXISTS subject_authority_root text,
  ADD COLUMN IF NOT EXISTS consent_receipt_root text,
  ADD COLUMN IF NOT EXISTS provider text,
  ADD COLUMN IF NOT EXISTS provider_key_id text,
  ADD COLUMN IF NOT EXISTS provider_receipt_hash text,
  ADD COLUMN IF NOT EXISTS provider_verification_state text,
  ADD COLUMN IF NOT EXISTS actor_snapshot jsonb,
  ADD COLUMN IF NOT EXISTS command_hash text,
  ADD COLUMN IF NOT EXISTS subject_sequence bigint,
  ADD COLUMN IF NOT EXISTS previous_event_root text,
  ADD COLUMN IF NOT EXISTS device_hash text,
  ADD COLUMN IF NOT EXISTS safety jsonb,
  ADD COLUMN IF NOT EXISTS audit_event_root text;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'device_attestations_organization_fk'
      AND conrelid = 'identity.device_attestations'::regclass
  ) THEN
    ALTER TABLE identity.device_attestations
      ADD CONSTRAINT device_attestations_organization_fk
      FOREIGN KEY (organization_id) REFERENCES organizations.organizations(id);
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'device_attestations_consent_receipt_fk'
      AND conrelid = 'identity.device_attestations'::regclass
  ) THEN
    ALTER TABLE identity.device_attestations
      ADD CONSTRAINT device_attestations_consent_receipt_fk
      FOREIGN KEY (consent_receipt_id) REFERENCES evidence.consent_receipts(id);
  END IF;
END;
$$;

CREATE UNIQUE INDEX IF NOT EXISTS evidence_consent_receipts_command_hash_unique
  ON evidence.consent_receipts (command_hash) WHERE command_hash IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS evidence_consent_receipts_subject_sequence_unique
  ON evidence.consent_receipts (subject_id, subject_sequence) WHERE subject_sequence IS NOT NULL;
CREATE INDEX IF NOT EXISTS evidence_consent_receipts_org_subject_time
  ON evidence.consent_receipts (organization_id, subject_id, granted_at DESC, id);
CREATE INDEX IF NOT EXISTS evidence_consent_revocations_org_subject_time
  ON evidence.consent_revocations (organization_id, subject_id, revoked_at DESC, id);
CREATE UNIQUE INDEX IF NOT EXISTS identity_device_attestations_command_hash_unique
  ON identity.device_attestations (command_hash) WHERE command_hash IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS identity_device_attestations_subject_sequence_unique
  ON identity.device_attestations (subject_id, subject_sequence) WHERE subject_sequence IS NOT NULL;
CREATE INDEX IF NOT EXISTS identity_device_attestations_org_subject_time
  ON identity.device_attestations (organization_id, subject_id, issued_at DESC, id);

CREATE TABLE IF NOT EXISTS evidence.media_metadata_extractions (
  id text PRIMARY KEY,
  media_object_id text NOT NULL REFERENCES evidence.media_objects(id),
  evidence_id text NOT NULL,
  consent_receipt_id text NOT NULL REFERENCES evidence.consent_receipts(id),
  device_attestation_id text NOT NULL REFERENCES identity.device_attestations(id),
  extractor_version text NOT NULL,
  exif_hash text NOT NULL,
  gps_hash text NOT NULL,
  location jsonb NOT NULL,
  sensor_metadata jsonb NOT NULL,
  extraction_state text NOT NULL CHECK (extraction_state IN ('accepted', 'needs_review')),
  issues text[] NOT NULL,
  metadata_root text NOT NULL UNIQUE,
  observed_at timestamptz NOT NULL,
  extracted_at timestamptz NOT NULL,
  extracted_by text NOT NULL REFERENCES identity.participants(id)
);

CREATE TABLE IF NOT EXISTS evidence.review_tasks (
  id text PRIMARY KEY,
  source_type text NOT NULL CHECK (source_type IN ('media_object', 'media_metadata_extraction', 'offline_sync_batch', 'community_attestation')),
  source_id text NOT NULL,
  evidence_id text,
  reason_codes text[] NOT NULL,
  severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  status text NOT NULL CHECK (status IN ('open', 'assigned', 'resolved', 'escalated')),
  assigned_to text REFERENCES identity.participants(id),
  policy_id text,
  task_root text NOT NULL UNIQUE,
  opened_at timestamptz NOT NULL,
  due_at timestamptz,
  resolved_at timestamptz,
  resolved_by text REFERENCES identity.participants(id),
  decision text CHECK (decision IN ('accept', 'reject', 'quarantine', 'escalate', 'retain_non_final')),
  rationale text,
  created_by text NOT NULL REFERENCES identity.participants(id)
);

CREATE TABLE IF NOT EXISTS evidence.retention_policy_decisions (
  id text PRIMARY KEY,
  source_type text NOT NULL CHECK (source_type IN ('consent_receipt', 'media_metadata_extraction', 'media_object')),
  source_id text NOT NULL,
  evidence_id text,
  subject_id text REFERENCES identity.participants(id),
  basis text NOT NULL CHECK (basis IN ('consent_retention', 'expired_consent', 'revoked_consent', 'safety_review', 'legal_hold')),
  disposition text NOT NULL CHECK (disposition IN ('retain', 'minimize', 'tombstone_after_retention', 'legal_hold')),
  retain_until timestamptz,
  legal_hold boolean NOT NULL DEFAULT false,
  evaluated_at timestamptz NOT NULL,
  rationale text NOT NULL,
  decision_root text NOT NULL UNIQUE,
  created_by text NOT NULL REFERENCES identity.participants(id)
);

CREATE TABLE IF NOT EXISTS evidence.offline_sync_batches (
  id text PRIMARY KEY,
  idempotency_key text NOT NULL,
  submitted_by text NOT NULL REFERENCES identity.participants(id),
  device_fingerprint_hash text NOT NULL,
  project_id text REFERENCES projects.projects(id),
  status text NOT NULL CHECK (status IN ('accepted', 'partial_review', 'conflict_review')),
  accepted_count integer NOT NULL DEFAULT 0 CHECK (accepted_count >= 0),
  challenged_count integer NOT NULL DEFAULT 0 CHECK (challenged_count >= 0),
  duplicate_count integer NOT NULL DEFAULT 0 CHECK (duplicate_count >= 0),
  conflict_count integer NOT NULL DEFAULT 0 CHECK (conflict_count >= 0),
  sync_root text NOT NULL UNIQUE,
  received_at timestamptz NOT NULL,
  UNIQUE (submitted_by, idempotency_key)
);

CREATE TABLE IF NOT EXISTS evidence.offline_sync_items (
  id text PRIMARY KEY,
  batch_id text NOT NULL REFERENCES evidence.offline_sync_batches(id),
  evidence_id text NOT NULL,
  result_status text NOT NULL CHECK (result_status IN ('accepted', 'challenged', 'duplicate', 'conflict')),
  issue_codes text[] NOT NULL,
  item_root text NOT NULL
);

CREATE TABLE IF NOT EXISTS evidence.community_attestations (
  id text PRIMARY KEY,
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  attester_id text NOT NULL REFERENCES identity.participants(id),
  stance text NOT NULL CHECK (stance IN ('support', 'challenge', 'needs_review')),
  note text NOT NULL,
  confidence_score integer NOT NULL CHECK (confidence_score >= 0 AND confidence_score <= 100),
  media_hash text,
  gps_hash text,
  device_fingerprint_hash text,
  attestation_root text NOT NULL UNIQUE,
  observed_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS evidence.custody_events (
  id text PRIMARY KEY,
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  action text NOT NULL CHECK (action IN ('captured', 'uploaded', 'stored', 'metadata_extracted', 'review_opened', 'review_resolved', 'retention_decided', 'offline_synced', 'community_attested')),
  artifact_type text NOT NULL CHECK (artifact_type IN ('evidence', 'media_upload_intent', 'media_object', 'media_metadata_extraction', 'review_task', 'retention_policy_decision', 'offline_sync_batch', 'community_attestation')),
  artifact_id text NOT NULL,
  source_root text NOT NULL,
  previous_custody_root text NOT NULL,
  custodian_id text NOT NULL REFERENCES identity.participants(id),
  custodian_organization_id text,
  custody_note text NOT NULL,
  occurred_at timestamptz NOT NULL,
  policy_id text,
  custody_root text NOT NULL UNIQUE,
  custody_hash text NOT NULL UNIQUE,
  safety jsonb NOT NULL,
  event_root text NOT NULL UNIQUE,
  CHECK (jsonb_typeof(safety) = 'object'),
  CHECK ((safety->>'appendOnly')::boolean IS TRUE),
  CHECK ((safety->>'sourceRootBound')::boolean IS TRUE),
  CHECK ((safety->>'previousRootLinked')::boolean IS TRUE),
  CHECK ((safety->>'noRawPrivateContactData')::boolean IS TRUE),
  CHECK ((safety->>'notFinalProofAuthority')::boolean IS TRUE),
  CHECK ((safety->>'notCarbonCredit')::boolean IS TRUE),
  CHECK ((safety->>'notFinancialAsset')::boolean IS TRUE),
  CHECK ((safety->>'notTaxOffset')::boolean IS TRUE),
  CHECK ((safety->>'notGuaranteedYield')::boolean IS TRUE)
);

CREATE TABLE IF NOT EXISTS verification.ai_analyses (
  id text PRIMARY KEY,
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  model_version text NOT NULL,
  advisory_only boolean NOT NULL DEFAULT true CHECK (advisory_only IS true),
  capabilities text[] NOT NULL,
  findings jsonb NOT NULL DEFAULT '[]'::jsonb,
  recommended_status text NOT NULL CHECK (recommended_status IN ('needs_human_review', 'rejected')),
  confidence_score integer NOT NULL CHECK (confidence_score >= 0 AND confidence_score <= 100),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS verification.work_items (
  id text PRIMARY KEY,
  evidence_id text NOT NULL,
  project_id text NOT NULL,
  stage text NOT NULL CHECK (stage IN ('validation', 'ai_analysis', 'terra_crosscheck', 'human_review', 'proof_issuance')),
  priority text NOT NULL CHECK (priority IN ('low', 'normal', 'high', 'critical')),
  status text NOT NULL CHECK (status IN ('queued', 'running', 'blocked', 'completed', 'escalated')),
  dependency_ids text[] NOT NULL,
  reason_codes text[] NOT NULL,
  assigned_role text CHECK (assigned_role IN ('agent', 'verifier', 'researcher', 'governance')),
  available_at timestamptz NOT NULL,
  due_at timestamptz,
  queued_at timestamptz NOT NULL,
  started_at timestamptz,
  completed_at timestamptz,
  blocked_at timestamptz,
  transitioned_by text REFERENCES identity.participants(id),
  work_root text NOT NULL UNIQUE,
  created_by text NOT NULL REFERENCES identity.participants(id)
);

CREATE TABLE IF NOT EXISTS verification.human_reviews (
  id text PRIMARY KEY,
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  reviewer_id text NOT NULL REFERENCES identity.participants(id),
  reviewer_role text NOT NULL CHECK (reviewer_role IN ('verifier', 'ngo', 'government', 'un_agency', 'researcher')),
  decision text NOT NULL CHECK (decision IN ('approve', 'reject', 'challenge')),
  rationale text NOT NULL,
  reviewed_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS verification.quality_scorecards (
  id text PRIMARY KEY,
  subject_type text NOT NULL CHECK (subject_type IN ('evidence', 'proof_record', 'project', 'reporting_package', 'terra_scene')),
  subject_id text NOT NULL,
  methodology_id text,
  evidence_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  source_roots text[] NOT NULL,
  source_root text NOT NULL,
  quality_signals jsonb NOT NULL,
  dimension_scores jsonb NOT NULL,
  findings jsonb NOT NULL DEFAULT '[]'::jsonb,
  finding_root text NOT NULL,
  decision text NOT NULL CHECK (decision IN ('pass', 'needs_review', 'blocked')),
  quality_hash text NOT NULL UNIQUE,
  notes text[] NOT NULL DEFAULT ARRAY[]::text[],
  safety jsonb NOT NULL,
  created_by text NOT NULL REFERENCES identity.participants(id),
  created_at timestamptz NOT NULL,
  event_root text NOT NULL UNIQUE,
  CHECK (array_length(source_roots, 1) > 0),
  CHECK (jsonb_typeof(quality_signals) = 'object'),
  CHECK (jsonb_typeof(dimension_scores) = 'object'),
  CHECK (jsonb_typeof(findings) = 'array'),
  CHECK (jsonb_typeof(safety) = 'object')
);

CREATE TABLE IF NOT EXISTS verification.decision_dossiers (
  id text PRIMARY KEY,
  subject_type text NOT NULL CHECK (subject_type IN ('evidence', 'proof_record', 'project', 'reporting_package', 'terra_scene')),
  subject_id text NOT NULL,
  decision text NOT NULL CHECK (decision IN ('approve', 'reject', 'challenge', 'request_changes')),
  reviewer_id text NOT NULL REFERENCES identity.participants(id),
  reviewer_role text NOT NULL CHECK (reviewer_role IN ('owner', 'admin', 'verifier', 'researcher')),
  evidence_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  ai_analysis_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  terra_scene_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  quality_scorecard_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  human_review_work_item_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  governance_approval_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  audit_event_roots text[] NOT NULL,
  quality_gate_state text NOT NULL CHECK (quality_gate_state IN ('pass', 'needs_review', 'blocked')),
  source_root text NOT NULL,
  rationale text NOT NULL,
  limitations text[] NOT NULL DEFAULT ARRAY[]::text[],
  decision_hash text NOT NULL UNIQUE,
  decided_at timestamptz NOT NULL,
  safety jsonb NOT NULL,
  event_root text NOT NULL UNIQUE,
  CHECK (array_length(audit_event_roots, 1) > 0),
  CHECK (decision <> 'approve' OR quality_gate_state <> 'blocked'),
  CHECK (decision <> 'approve' OR array_length(evidence_ids, 1) > 0),
  CHECK (decision <> 'approve' OR array_length(ai_analysis_ids, 1) > 0),
  CHECK (decision <> 'approve' OR array_length(quality_scorecard_ids, 1) > 0),
  CHECK (decision <> 'approve' OR array_length(human_review_work_item_ids, 1) > 0),
  CHECK (jsonb_typeof(safety) = 'object')
);

CREATE TABLE IF NOT EXISTS verification.challenge_cases (
  id text PRIMARY KEY,
  subject_type text NOT NULL CHECK (subject_type IN ('evidence', 'proof_record', 'project', 'quality_scorecard', 'verification_decision', 'methodology', 'terra_scene', 'reporting_package', 'funding_allocation')),
  subject_id text NOT NULL,
  reason text NOT NULL CHECK (reason IN ('fake_evidence', 'duplicate_planting', 'gps_spoofing', 'satellite_contradiction', 'methodology_gap', 'audit_gap', 'privacy_risk', 'governance_conflict', 'unsafe_claim', 'other')),
  severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  status text NOT NULL CHECK (status IN ('open', 'under_review', 'accepted', 'rejected', 'needs_more_evidence', 'withdrawn')),
  title text NOT NULL,
  description text NOT NULL,
  opened_by text NOT NULL REFERENCES identity.participants(id),
  opened_at timestamptz NOT NULL,
  assigned_role text NOT NULL CHECK (assigned_role IN ('verifier', 'researcher', 'governance')),
  evidence_root text NOT NULL,
  related_audit_roots text[] NOT NULL DEFAULT ARRAY[]::text[],
  challenge_hash text NOT NULL UNIQUE,
  resolution jsonb,
  safety jsonb NOT NULL,
  event_root text NOT NULL UNIQUE,
  CHECK (jsonb_typeof(safety) = 'object'),
  CHECK (resolution IS NULL OR jsonb_typeof(resolution) = 'object')
);

CREATE TABLE IF NOT EXISTS verification.challenge_evidence (
  id text PRIMARY KEY,
  challenge_case_id text NOT NULL REFERENCES verification.challenge_cases(id),
  evidence_type text NOT NULL CHECK (evidence_type IN ('media_hash', 'gps_hash', 'device_attestation', 'satellite_scene', 'quality_scorecard', 'audit_root', 'governance_record', 'document_hash', 'other')),
  content_hash text NOT NULL,
  source_id text,
  description text NOT NULL,
  submitted_by text NOT NULL REFERENCES identity.participants(id),
  submitted_at timestamptz NOT NULL,
  UNIQUE (challenge_case_id, content_hash, evidence_type)
);

CREATE TABLE IF NOT EXISTS certificates.environmental_proof_records (
  id text PRIMARY KEY,
  record_type text NOT NULL DEFAULT 'environmental_proof_record' CHECK (record_type = 'environmental_proof_record'),
  project_id text NOT NULL REFERENCES projects.projects(id),
  location jsonb NOT NULL,
  evidence_root text NOT NULL,
  evidence_ids text[] NOT NULL,
  verification_history jsonb NOT NULL,
  monitoring_timeline jsonb NOT NULL,
  monitoring_event_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  contributors text[] NOT NULL,
  governance_approvals text[] NOT NULL,
  confidence_score integer NOT NULL CHECK (confidence_score >= 0 AND confidence_score <= 100),
  status text NOT NULL CHECK (status IN ('issued', 'challenged', 'revoked')),
  record_hash text NOT NULL,
  claim_boundary jsonb NOT NULL,
  issued_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS certificates.public_records (
  id text PRIMARY KEY,
  record_id text NOT NULL REFERENCES certificates.environmental_proof_records(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  status text NOT NULL CHECK (status IN ('issued', 'challenged', 'revoked')),
  public_location jsonb NOT NULL,
  evidence_count integer NOT NULL CHECK (evidence_count >= 0),
  evidence_root text NOT NULL,
  monitoring_event_count integer NOT NULL CHECK (monitoring_event_count >= 0),
  monitoring_event_root text NOT NULL,
  governance_approval_count integer NOT NULL CHECK (governance_approval_count >= 0),
  governance_approval_root text NOT NULL,
  challenge_root text NOT NULL,
  source_record_hash text NOT NULL,
  public_record_hash text NOT NULL UNIQUE,
  claim_boundary jsonb NOT NULL,
  issued_at timestamptz NOT NULL,
  published_at timestamptz NOT NULL,
  CHECK ((claim_boundary->>'notCarbonCredit')::boolean IS TRUE),
  CHECK ((claim_boundary->>'notFinancialAsset')::boolean IS TRUE),
  CHECK ((claim_boundary->>'notTaxOffset')::boolean IS TRUE),
  CHECK ((claim_boundary->>'notGuaranteedYield')::boolean IS TRUE),
  CHECK ((claim_boundary->>'notAutomaticCanopyDistribution')::boolean IS TRUE)
);

CREATE TABLE IF NOT EXISTS certificates.certificate_transparency_entries (
  id text PRIMARY KEY,
  certificate_id text NOT NULL UNIQUE,
  certificate_version text NOT NULL CHECK (certificate_version = 'canopyproof_certificate_artifact_v1'),
  record_id text NOT NULL REFERENCES certificates.environmental_proof_records(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  certificate_hash text NOT NULL UNIQUE,
  source_record_hash text NOT NULL,
  evidence_root text NOT NULL,
  monitoring_event_root text NOT NULL,
  governance_approval_root text NOT NULL,
  challenge_root text NOT NULL,
  claim_boundary_root text NOT NULL,
  status text NOT NULL CHECK (status IN ('active', 'challenged', 'revoked')),
  issued_at timestamptz NOT NULL,
  published_at timestamptz NOT NULL,
  published_by text NOT NULL REFERENCES identity.participants(id),
  entry_hash text NOT NULL UNIQUE,
  safety jsonb NOT NULL,
  event_root text NOT NULL UNIQUE,
  CHECK (jsonb_typeof(safety) = 'object')
);

CREATE TABLE IF NOT EXISTS certificates.certificate_verifications (
  id text PRIMARY KEY,
  certificate_id text NOT NULL,
  record_id text NOT NULL,
  verifier_id text NOT NULL REFERENCES identity.participants(id),
  certificate_hash text NOT NULL,
  recomputed_certificate_hash text NOT NULL,
  expected_entry_hash text,
  recomputed_entry_hash text NOT NULL,
  valid boolean NOT NULL,
  issues jsonb NOT NULL DEFAULT '[]'::jsonb,
  verified_at timestamptz NOT NULL,
  verification_root text NOT NULL UNIQUE,
  safety jsonb NOT NULL,
  event_root text NOT NULL UNIQUE,
  CHECK (jsonb_typeof(issues) = 'array'),
  CHECK (jsonb_typeof(safety) = 'object')
);

CREATE TABLE IF NOT EXISTS certificates.proof_record_challenges (
  id text PRIMARY KEY,
  record_id text NOT NULL REFERENCES certificates.environmental_proof_records(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  challenger_id text NOT NULL REFERENCES identity.participants(id),
  reason text NOT NULL CHECK (reason IN ('fake_evidence', 'duplicate_claim', 'gps_spoofing', 'satellite_contradiction', 'governance_conflict', 'unsafe_public_claim', 'methodology_error', 'other')),
  severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  status text NOT NULL CHECK (status IN ('open', 'accepted', 'rejected')),
  description text NOT NULL,
  evidence_ids text[] NOT NULL,
  evidence_hashes text[] NOT NULL,
  evidence_root text NOT NULL,
  abuse_control_policy_id text NOT NULL,
  bond_required boolean NOT NULL DEFAULT false,
  bond_waived_reason text NOT NULL,
  public_outcome text NOT NULL,
  challenge_hash text NOT NULL UNIQUE,
  submitted_at timestamptz NOT NULL,
  resolved_at timestamptz,
  resolved_by text REFERENCES identity.participants(id),
  resolution_rationale text
);

CREATE TABLE IF NOT EXISTS satellite.observations (
  id text PRIMARY KEY,
  project_id text NOT NULL REFERENCES projects.projects(id),
  provider text NOT NULL CHECK (provider IN ('sentinel', 'landsat', 'nasa', 'open_climate')),
  layer_type text NOT NULL CHECK (layer_type IN ('imagery', 'ndvi', 'vegetation', 'water', 'drought', 'wildfire', 'land_change')),
  acquired_at timestamptz NOT NULL,
  source_uri text NOT NULL,
  observation_hash text NOT NULL,
  contradiction_status text NOT NULL DEFAULT 'neutral'
);

CREATE TABLE IF NOT EXISTS impact.metrics (
  id text PRIMARY KEY,
  project_id text NOT NULL REFERENCES projects.projects(id),
  metric_type text NOT NULL CHECK (metric_type IN ('tree_count', 'biodiversity', 'water', 'soil', 'carbon_estimate', 'risk')),
  metric_value numeric NOT NULL,
  methodology_version text NOT NULL,
  evidence_root text NOT NULL,
  computed_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS impact.global_command_center_snapshots (
  id text PRIMARY KEY,
  generated_at timestamptz NOT NULL,
  metric_summary jsonb NOT NULL,
  regional_summaries jsonb NOT NULL,
  impact_indicators jsonb NOT NULL,
  recent_activity jsonb NOT NULL,
  lineage jsonb NOT NULL,
  safety_boundary jsonb NOT NULL,
  dashboard_root text NOT NULL UNIQUE,
  created_by text NOT NULL REFERENCES identity.participants(id),
  CHECK ((safety_boundary->>'readOnly')::boolean IS TRUE),
  CHECK ((safety_boundary->>'notCertifiedCarbonCredit')::boolean IS TRUE),
  CHECK ((safety_boundary->>'notCarbonTaxOffset')::boolean IS TRUE),
  CHECK ((safety_boundary->>'notFinancialAsset')::boolean IS TRUE),
  CHECK ((safety_boundary->>'notGuaranteedYield')::boolean IS TRUE)
);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'impact_global_command_center_snapshot_json_shape'
      AND conrelid = 'impact.global_command_center_snapshots'::regclass
  ) THEN
    ALTER TABLE impact.global_command_center_snapshots
      ADD CONSTRAINT impact_global_command_center_snapshot_json_shape CHECK (
        jsonb_typeof(metric_summary) = 'object' AND
        jsonb_typeof(regional_summaries) = 'array' AND
        jsonb_typeof(impact_indicators) = 'object' AND
        jsonb_typeof(recent_activity) = 'array' AND
        jsonb_typeof(lineage) = 'object' AND
        jsonb_typeof(safety_boundary) = 'object'
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'impact_global_command_center_snapshot_root_binding'
      AND conrelid = 'impact.global_command_center_snapshots'::regclass
  ) THEN
    ALTER TABLE impact.global_command_center_snapshots
      ADD CONSTRAINT impact_global_command_center_snapshot_root_binding CHECK (
        dashboard_root ~ '^[0-9a-f]{64}$' AND
        lineage->>'dashboardRoot' = dashboard_root
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'impact_global_command_center_snapshot_safety_boundary'
      AND conrelid = 'impact.global_command_center_snapshots'::regclass
  ) THEN
    ALTER TABLE impact.global_command_center_snapshots
      ADD CONSTRAINT impact_global_command_center_snapshot_safety_boundary CHECK (
        (safety_boundary->>'readOnly')::boolean IS TRUE AND
        (safety_boundary->>'humanReviewRequiredForFinalProof')::boolean IS TRUE AND
        (safety_boundary->>'aiAdvisoryOnly')::boolean IS TRUE AND
        (safety_boundary->>'noMainnetFunds')::boolean IS TRUE AND
        (safety_boundary->>'noAutomaticCanopyDistribution')::boolean IS TRUE AND
        (safety_boundary->>'notCertifiedCarbonCredit')::boolean IS TRUE AND
        (safety_boundary->>'notCarbonTaxOffset')::boolean IS TRUE AND
        (safety_boundary->>'notFinancialAsset')::boolean IS TRUE AND
        (safety_boundary->>'notGuaranteedYield')::boolean IS TRUE
      ) NOT VALID;
  END IF;
END
$$;

ALTER TABLE impact.global_command_center_snapshots
  VALIDATE CONSTRAINT impact_global_command_center_snapshot_json_shape;
ALTER TABLE impact.global_command_center_snapshots
  VALIDATE CONSTRAINT impact_global_command_center_snapshot_root_binding;
ALTER TABLE impact.global_command_center_snapshots
  VALIDATE CONSTRAINT impact_global_command_center_snapshot_safety_boundary;

CREATE OR REPLACE FUNCTION impact.global_command_center_regions_have_spatial(value jsonb)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
  SELECT CASE
    WHEN jsonb_typeof(value) <> 'array' THEN FALSE
    ELSE COALESCE((
      SELECT bool_and(COALESCE(
        jsonb_typeof(region->'spatial') = 'object' AND
        region->'spatial'->>'visibility' IN ('withheld', 'generalized') AND
        region->'spatial'->>'spatialRoot' ~ '^[0-9a-f]{64}$',
        FALSE
      ))
      FROM jsonb_array_elements(value) AS region
    ), TRUE)
  END
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'impact_global_command_center_snapshot_spatial_shape'
      AND conrelid = 'impact.global_command_center_snapshots'::regclass
  ) THEN
    ALTER TABLE impact.global_command_center_snapshots
      ADD CONSTRAINT impact_global_command_center_snapshot_spatial_shape CHECK (
        impact.global_command_center_regions_have_spatial(regional_summaries)
      ) NOT VALID;
  END IF;
END
$$;

CREATE TABLE IF NOT EXISTS impact.risk_signals (
  id text PRIMARY KEY,
  risk_class text NOT NULL CHECK (risk_class IN ('drought', 'wildfire', 'flooding', 'ecosystem_degradation')),
  region_id text NOT NULL,
  project_id text REFERENCES projects.projects(id),
  source_type text NOT NULL CHECK (source_type IN ('terra_scene', 'field_evidence', 'community_report', 'open_climate')),
  source_id text NOT NULL,
  indicators jsonb NOT NULL,
  confidence_score integer NOT NULL CHECK (confidence_score >= 0 AND confidence_score <= 100),
  severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  summary text NOT NULL,
  signal_hash text NOT NULL,
  observed_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS impact.risk_alerts (
  id text PRIMARY KEY,
  risk_class text NOT NULL CHECK (risk_class IN ('drought', 'wildfire', 'flooding', 'ecosystem_degradation')),
  region_id text NOT NULL,
  project_id text REFERENCES projects.projects(id),
  severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  status text NOT NULL CHECK (status IN ('watch', 'review_required', 'acknowledged', 'escalated', 'resolved', 'challenged')),
  audience text[] NOT NULL,
  signal_ids text[] NOT NULL,
  summary text NOT NULL,
  public_message text,
  public_release jsonb NOT NULL,
  alert_hash text NOT NULL,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS impact.risk_responses (
  id text PRIMARY KEY,
  alert_id text NOT NULL REFERENCES impact.risk_alerts(id),
  response_type text NOT NULL CHECK (response_type IN ('acknowledge', 'escalate')),
  actor_id text NOT NULL REFERENCES identity.participants(id),
  audience text[] NOT NULL,
  note text NOT NULL,
  created_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS impact.risk_alert_dispatch_receipts (
  id text PRIMARY KEY,
  alert_id text NOT NULL REFERENCES impact.risk_alerts(id),
  risk_class text NOT NULL CHECK (risk_class IN ('drought', 'wildfire', 'flooding', 'ecosystem_degradation')),
  region_id text NOT NULL,
  project_id text REFERENCES projects.projects(id),
  recipient_audience text NOT NULL CHECK (recipient_audience IN ('community', 'ngo', 'government', 'operator', 'verifier')),
  recipient_id text NOT NULL,
  organization_id text,
  region_scope text,
  channel text NOT NULL CHECK (channel IN ('dashboard', 'email', 'sms', 'webhook', 'field_ops', 'partner_api')),
  delivery_status text NOT NULL CHECK (delivery_status IN ('queued', 'delivered', 'failed', 'acknowledged')),
  message_hash text NOT NULL,
  policy_id text,
  delivery_root text NOT NULL UNIQUE,
  dispatch_hash text NOT NULL UNIQUE,
  dispatched_by text NOT NULL REFERENCES identity.participants(id),
  dispatched_at timestamptz NOT NULL,
  delivered_at timestamptz,
  safety jsonb NOT NULL,
  event_root text NOT NULL UNIQUE,
  CHECK (jsonb_typeof(safety) = 'object'),
  CHECK ((safety->>'noPrivateContactData')::boolean IS TRUE),
  CHECK ((safety->>'audienceScoped')::boolean IS TRUE),
  CHECK ((safety->>'noAutomatedEmergencyClaim')::boolean IS TRUE),
  CHECK ((safety->>'humanReviewRequiredForPublicRelease')::boolean IS TRUE),
  CHECK ((safety->>'notCarbonCredit')::boolean IS TRUE),
  CHECK ((safety->>'notFinancialAsset')::boolean IS TRUE)
);

CREATE TABLE IF NOT EXISTS impact.risk_response_playbooks (
  id text PRIMARY KEY,
  risk_class text NOT NULL CHECK (risk_class IN ('drought', 'wildfire', 'flooding', 'ecosystem_degradation')),
  severity_floor text NOT NULL CHECK (severity_floor IN ('low', 'medium', 'high', 'critical')),
  audience text[] NOT NULL,
  required_dispatch_audience text[] NOT NULL,
  title text NOT NULL,
  objective text NOT NULL,
  response_window_hours integer NOT NULL CHECK (response_window_hours > 0),
  governance_policy_id text NOT NULL,
  steps jsonb NOT NULL,
  safety jsonb NOT NULL,
  playbook_hash text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL,
  event_root text NOT NULL UNIQUE,
  CHECK (array_length(audience, 1) > 0),
  CHECK (array_length(required_dispatch_audience, 1) > 0),
  CHECK (jsonb_typeof(steps) = 'array'),
  CHECK (jsonb_array_length(steps) > 0),
  CHECK (jsonb_typeof(safety) = 'object'),
  CHECK ((safety->>'operationalOnly')::boolean IS TRUE),
  CHECK ((safety->>'notEmergencyDeclaration')::boolean IS TRUE),
  CHECK ((safety->>'humanAuthorityRequired')::boolean IS TRUE),
  CHECK ((safety->>'evidenceRequiredForClosure')::boolean IS TRUE),
  CHECK ((safety->>'notCarbonCredit')::boolean IS TRUE),
  CHECK ((safety->>'notFinancialAsset')::boolean IS TRUE)
);

CREATE TABLE IF NOT EXISTS impact.risk_response_activations (
  id text PRIMARY KEY,
  alert_id text NOT NULL REFERENCES impact.risk_alerts(id),
  playbook_id text NOT NULL REFERENCES impact.risk_response_playbooks(id),
  risk_class text NOT NULL CHECK (risk_class IN ('drought', 'wildfire', 'flooding', 'ecosystem_degradation')),
  severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  dispatch_receipt_ids text[] NOT NULL,
  assigned_audience text[] NOT NULL,
  assigned_organization_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  status text NOT NULL CHECK (status IN ('opened', 'in_progress', 'completed', 'challenged')),
  due_at timestamptz NOT NULL,
  evidence_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  note text NOT NULL,
  activated_by text NOT NULL REFERENCES identity.participants(id),
  activated_at timestamptz NOT NULL,
  activation_root text NOT NULL UNIQUE,
  activation_hash text NOT NULL UNIQUE,
  safety jsonb NOT NULL,
  event_root text NOT NULL UNIQUE,
  CHECK (array_length(dispatch_receipt_ids, 1) > 0),
  CHECK (array_length(assigned_audience, 1) > 0),
  CHECK (jsonb_typeof(safety) = 'object'),
  CHECK ((safety->>'operationalOnly')::boolean IS TRUE),
  CHECK ((safety->>'notEmergencyDeclaration')::boolean IS TRUE),
  CHECK ((safety->>'humanAuthorityRequired')::boolean IS TRUE),
  CHECK ((safety->>'evidenceRequiredForClosure')::boolean IS TRUE),
  CHECK ((safety->>'aiCannotClosePlaybook')::boolean IS TRUE),
  CHECK ((safety->>'notCarbonCredit')::boolean IS TRUE),
  CHECK ((safety->>'notFinancialAsset')::boolean IS TRUE)
);

CREATE TABLE IF NOT EXISTS impact.risk_response_closures (
  id text PRIMARY KEY,
  activation_id text NOT NULL REFERENCES impact.risk_response_activations(id),
  alert_id text NOT NULL REFERENCES impact.risk_alerts(id),
  playbook_id text NOT NULL REFERENCES impact.risk_response_playbooks(id),
  decision text NOT NULL CHECK (decision IN ('complete', 'challenge')),
  reviewer_id text NOT NULL REFERENCES identity.participants(id),
  reviewer_role text NOT NULL CHECK (reviewer_role IN ('owner', 'admin', 'verifier', 'researcher', 'community')),
  evidence_ids text[] NOT NULL,
  evidence_root text NOT NULL,
  dispatch_receipt_ids text[] NOT NULL,
  governance_approval_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  completion_summary text NOT NULL,
  unresolved_actions text[] NOT NULL DEFAULT ARRAY[]::text[],
  challenged_reason text,
  reviewed_at timestamptz NOT NULL,
  closure_root text NOT NULL UNIQUE,
  closure_hash text NOT NULL UNIQUE,
  safety jsonb NOT NULL,
  event_root text NOT NULL UNIQUE,
  CHECK (array_length(evidence_ids, 1) > 0),
  CHECK (array_length(dispatch_receipt_ids, 1) > 0),
  CHECK (decision <> 'challenge' OR challenged_reason IS NOT NULL),
  CHECK (decision <> 'complete' OR array_length(unresolved_actions, 1) IS NULL),
  CHECK (jsonb_typeof(safety) = 'object'),
  CHECK ((safety->>'operationalOnly')::boolean IS TRUE),
  CHECK ((safety->>'humanReviewRequired')::boolean IS TRUE),
  CHECK ((safety->>'evidenceBound')::boolean IS TRUE),
  CHECK ((safety->>'aiIsNeverFinalAuthority')::boolean IS TRUE),
  CHECK ((safety->>'notEmergencyDeclaration')::boolean IS TRUE),
  CHECK ((safety->>'notCarbonCredit')::boolean IS TRUE),
  CHECK ((safety->>'notFinancialAsset')::boolean IS TRUE),
  CHECK ((safety->>'notTaxOffset')::boolean IS TRUE),
  CHECK ((safety->>'notGuaranteedYield')::boolean IS TRUE)
);

CREATE TABLE IF NOT EXISTS impact.risk_after_action_reviews (
  id text PRIMARY KEY,
  closure_id text NOT NULL REFERENCES impact.risk_response_closures(id),
  activation_id text NOT NULL REFERENCES impact.risk_response_activations(id),
  alert_id text NOT NULL REFERENCES impact.risk_alerts(id),
  playbook_id text NOT NULL REFERENCES impact.risk_response_playbooks(id),
  outcome text NOT NULL CHECK (outcome IN ('accepted', 'needs_follow_up', 'escalated_to_governance')),
  reviewer_id text NOT NULL REFERENCES identity.participants(id),
  reviewer_role text NOT NULL CHECK (reviewer_role IN ('owner', 'admin', 'verifier', 'researcher')),
  evidence_ids text[] NOT NULL,
  evidence_root text NOT NULL,
  closure_root text NOT NULL,
  lessons_learned text[] NOT NULL,
  corrective_actions text[] NOT NULL DEFAULT ARRAY[]::text[],
  policy_recommendation_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  governance_approval_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  follow_up_due_at timestamptz,
  reviewed_at timestamptz NOT NULL,
  review_root text NOT NULL UNIQUE,
  review_hash text NOT NULL UNIQUE,
  safety jsonb NOT NULL,
  event_root text NOT NULL UNIQUE,
  CHECK (array_length(evidence_ids, 1) > 0),
  CHECK (array_length(lessons_learned, 1) > 0),
  CHECK (outcome = 'accepted' OR array_length(corrective_actions, 1) > 0),
  CHECK (outcome <> 'escalated_to_governance' OR array_length(policy_recommendation_ids, 1) > 0),
  CHECK (jsonb_typeof(safety) = 'object'),
  CHECK ((safety->>'postIncidentOnly')::boolean IS TRUE),
  CHECK ((safety->>'humanReviewRequired')::boolean IS TRUE),
  CHECK ((safety->>'evidenceBound')::boolean IS TRUE),
  CHECK ((safety->>'aiIsNeverFinalAuthority')::boolean IS TRUE),
  CHECK ((safety->>'notEmergencyDeclaration')::boolean IS TRUE),
  CHECK ((safety->>'notCarbonCredit')::boolean IS TRUE),
  CHECK ((safety->>'notFinancialAsset')::boolean IS TRUE),
  CHECK ((safety->>'notTaxOffset')::boolean IS TRUE),
  CHECK ((safety->>'notGuaranteedYield')::boolean IS TRUE)
);

CREATE TABLE IF NOT EXISTS funding.sources (
  id text PRIMARY KEY,
  source_type text NOT NULL CHECK (source_type IN ('donor', 'grant', 'public_budget', 'philanthropic_fund', 'climate_fund')),
  display_name text NOT NULL,
  jurisdiction text NOT NULL,
  commitment_amount numeric NOT NULL CHECK (commitment_amount >= 0),
  currency text NOT NULL DEFAULT 'USD',
  restriction text NOT NULL CHECK (restriction IN ('unrestricted', 'project_restricted', 'milestone_restricted')),
  public_memo text NOT NULL,
  source_hash text NOT NULL,
  pledged_at timestamptz NOT NULL,
  created_by text NOT NULL REFERENCES identity.participants(id)
);

CREATE TABLE IF NOT EXISTS funding.allocations (
  id text PRIMARY KEY,
  project_id text NOT NULL REFERENCES projects.projects(id),
  source_id text NOT NULL REFERENCES funding.sources(id),
  amount numeric NOT NULL CHECK (amount >= 0),
  currency text NOT NULL DEFAULT 'USD',
  purpose text NOT NULL,
  status text NOT NULL CHECK (status IN ('pledged', 'allocated', 'approved', 'released', 'reconciled', 'challenged')),
  dropin_allocation_id text,
  external_reference text,
  allocation_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by text NOT NULL REFERENCES identity.participants(id)
);

CREATE TABLE IF NOT EXISTS funding.milestones (
  id text PRIMARY KEY,
  allocation_id text NOT NULL REFERENCES funding.allocations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  title text NOT NULL,
  amount numeric NOT NULL CHECK (amount >= 0),
  currency text NOT NULL DEFAULT 'USD',
  due_at timestamptz NOT NULL,
  evidence_requirements text[] NOT NULL,
  status text NOT NULL CHECK (status IN ('planned', 'evidence_required', 'ready_for_review', 'settled', 'challenged')),
  milestone_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by text NOT NULL REFERENCES identity.participants(id)
);

CREATE TABLE IF NOT EXISTS funding.evidence_links (
  id text PRIMARY KEY,
  milestone_id text NOT NULL REFERENCES funding.milestones(id),
  evidence_id text NOT NULL,
  evidence_root text NOT NULL,
  review_decision_id text,
  proof_record_id text,
  note text NOT NULL,
  link_hash text NOT NULL,
  linked_at timestamptz NOT NULL,
  linked_by text NOT NULL REFERENCES identity.participants(id)
);

CREATE TABLE IF NOT EXISTS governance.approvals (
  id text PRIMARY KEY,
  subject_type text NOT NULL CHECK (subject_type IN ('organization', 'project', 'evidence', 'proof_record', 'esg_report', 'funding_allocation', 'risk_public_release', 'risk_response_playbook')),
  subject_id text NOT NULL,
  policy_id text NOT NULL,
  approver_id text NOT NULL REFERENCES identity.participants(id),
  approver_role text NOT NULL CHECK (approver_role IN ('owner', 'admin', 'verifier', 'researcher', 'community', 'observer', 'agent')),
  decision text NOT NULL CHECK (decision IN ('approve', 'reject', 'challenge')),
  rationale text NOT NULL,
  conflict_disclosure text NOT NULL,
  approval_hash text NOT NULL UNIQUE,
  decided_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS governance.methodologies (
  id text PRIMARY KEY,
  slug text NOT NULL,
  version text NOT NULL CHECK (version ~ '^v[0-9]+\.[0-9]+\.[0-9]+$'),
  title text NOT NULL,
  scope text NOT NULL CHECK (scope IN ('tree_planting', 'ecosystem_restoration', 'biodiversity', 'water_project', 'soil_regeneration', 'climate_observation', 'multi_scope')),
  status text NOT NULL CHECK (status IN ('draft', 'published', 'deprecated', 'challenged')),
  summary text NOT NULL,
  required_data_sources text[] NOT NULL,
  quality_gates text[] NOT NULL,
  minimum_gps_accuracy_meters numeric(12, 3) NOT NULL CHECK (minimum_gps_accuracy_meters > 0),
  monitoring_cadence_days integer NOT NULL CHECK (monitoring_cadence_days > 0),
  evidence_retention_days integer NOT NULL CHECK (evidence_retention_days > 0),
  governance_approval_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  supersedes text REFERENCES governance.methodologies(id),
  limitations text[] NOT NULL,
  claim_boundary jsonb NOT NULL,
  quality_gate_root text NOT NULL,
  methodology_hash text NOT NULL UNIQUE,
  created_by text NOT NULL REFERENCES identity.participants(id),
  created_at timestamptz NOT NULL,
  published_at timestamptz,
  event_root text NOT NULL UNIQUE,
  UNIQUE (slug, version),
  CHECK (array_length(required_data_sources, 1) > 0),
  CHECK (array_length(quality_gates, 1) > 0),
  CHECK (array_length(limitations, 1) > 0),
  CHECK (status <> 'published' OR array_length(governance_approval_ids, 1) > 0),
  CHECK (status <> 'published' OR published_at IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS governance.policies (
  id text PRIMARY KEY,
  title text NOT NULL,
  applies_to text[] NOT NULL,
  required_approvals integer NOT NULL CHECK (required_approvals > 0),
  allowed_reviewer_roles text[] NOT NULL,
  human_authority_required boolean NOT NULL DEFAULT true CHECK (human_authority_required IS true),
  conflict_disclosure_required boolean NOT NULL DEFAULT true CHECK (conflict_disclosure_required IS true),
  claim_boundary_enforced boolean NOT NULL DEFAULT true CHECK (claim_boundary_enforced IS true),
  policy_hash text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL
);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'projects_governance_policy_fk' AND conrelid = 'projects.projects'::regclass
  ) THEN
    ALTER TABLE projects.projects
      ADD CONSTRAINT projects_governance_policy_fk
      FOREIGN KEY (governance_policy_id) REFERENCES governance.policies(id);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'projects_governance_approval_fk' AND conrelid = 'projects.projects'::regclass
  ) THEN
    ALTER TABLE projects.projects
      ADD CONSTRAINT projects_governance_approval_fk
      FOREIGN KEY (governance_approval_id) REFERENCES governance.approvals(id);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'project_transition_governance_approval_fk'
      AND conrelid = 'projects.project_status_transitions'::regclass
  ) THEN
    ALTER TABLE projects.project_status_transitions
      ADD CONSTRAINT project_transition_governance_approval_fk
      FOREIGN KEY (governance_approval_id) REFERENCES governance.approvals(id);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'project_monitoring_organization_fk'
      AND conrelid = 'projects.monitoring_events'::regclass
  ) THEN
    ALTER TABLE projects.monitoring_events
      ADD CONSTRAINT project_monitoring_organization_fk
      FOREIGN KEY (organization_id) REFERENCES organizations.organizations(id);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'evidence_registration_organization_fk'
      AND conrelid = 'evidence.evidence_objects'::regclass
  ) THEN
    ALTER TABLE evidence.evidence_objects
      ADD CONSTRAINT evidence_registration_organization_fk
      FOREIGN KEY (organization_id) REFERENCES organizations.organizations(id);
  END IF;
END;
$$;

CREATE TABLE IF NOT EXISTS governance.conflict_disclosures (
  id text PRIMARY KEY,
  subject_type text NOT NULL CHECK (subject_type IN ('organization', 'project', 'evidence', 'proof_record', 'esg_report', 'funding_allocation', 'risk_public_release', 'risk_response_playbook')),
  subject_id text NOT NULL,
  actor_id text NOT NULL REFERENCES identity.participants(id),
  severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  status text NOT NULL CHECK (status IN ('open', 'review_required', 'cleared', 'waived')),
  disclosure text NOT NULL,
  disclosure_hash text NOT NULL UNIQUE,
  recorded_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS governance.proposals (
  id text PRIMARY KEY,
  proposal_type text NOT NULL CHECK (
    proposal_type IN (
      'policy_change',
      'project_governance',
      'partner_accreditation',
      'data_sharing',
      'funding_policy',
      'risk_policy',
      'release_governance'
    )
  ),
  subject_type text NOT NULL CHECK (subject_type IN ('organization', 'project', 'evidence', 'proof_record', 'esg_report', 'funding_allocation', 'risk_public_release', 'risk_response_playbook')),
  subject_id text NOT NULL,
  policy_id text REFERENCES governance.policies(id),
  title text NOT NULL,
  summary text NOT NULL,
  status text NOT NULL CHECK (status IN ('draft', 'open', 'approved', 'rejected', 'challenged', 'executed', 'withdrawn')),
  created_by text NOT NULL REFERENCES identity.participants(id),
  proposal_hash text NOT NULL UNIQUE,
  audit_event_root text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL,
  closes_at timestamptz,
  executed_at timestamptz
);

CREATE TABLE IF NOT EXISTS governance.votes (
  id text PRIMARY KEY,
  proposal_id text NOT NULL REFERENCES governance.proposals(id),
  voter_id text NOT NULL REFERENCES identity.participants(id),
  voter_role text NOT NULL CHECK (voter_role IN ('owner', 'admin', 'verifier', 'researcher', 'community', 'observer', 'agent')),
  decision text NOT NULL CHECK (decision IN ('approve', 'reject', 'abstain', 'challenge')),
  rationale text NOT NULL,
  conflict_disclosure text NOT NULL,
  vote_weight integer NOT NULL DEFAULT 1 CHECK (vote_weight > 0),
  vote_hash text NOT NULL UNIQUE,
  audit_event_root text NOT NULL UNIQUE,
  voted_at timestamptz NOT NULL,
  UNIQUE (proposal_id, voter_id)
);

CREATE TABLE IF NOT EXISTS governance.release_council_reviews (
  id text PRIMARY KEY,
  target text NOT NULL CHECK (target IN ('canopyproof-production', 'canopyproof-staging', 'dropin-production')),
  target_commit text NOT NULL CHECK (target_commit ~ '^[0-9a-f]{40}$'),
  workflow_name text NOT NULL,
  workflow_run_id text,
  reviewer_id text NOT NULL REFERENCES identity.participants(id),
  reviewer_role text NOT NULL CHECK (reviewer_role = 'release-council'),
  decision text NOT NULL CHECK (decision IN ('approve', 'reject', 'challenge')),
  rationale text NOT NULL,
  conflict_disclosure text NOT NULL,
  reviewed_at timestamptz NOT NULL,
  review_hash text NOT NULL UNIQUE,
  audit_event_root text NOT NULL UNIQUE,
  UNIQUE (target, target_commit, reviewer_id)
);

CREATE TABLE IF NOT EXISTS reporting.framework_packages (
  id text PRIMARY KEY,
  framework text NOT NULL CHECK (framework IN ('UN_SDG', 'UNFCCC', 'GRI', 'ISSB', 'TCFD')),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  period_start timestamptz NOT NULL,
  period_end timestamptz NOT NULL,
  proof_record_ids text[] NOT NULL,
  esg_report_ids text[] NOT NULL,
  metrics jsonb NOT NULL,
  sections jsonb NOT NULL,
  methodology text NOT NULL,
  confidence numeric NOT NULL CHECK (confidence >= 0 AND confidence <= 100),
  verification_references text[] NOT NULL,
  audit_references text[] NOT NULL,
  limitations text[] NOT NULL,
  claim_boundary jsonb NOT NULL,
  package_root text NOT NULL UNIQUE,
  generated_at timestamptz NOT NULL,
  generated_by text NOT NULL REFERENCES identity.participants(id),
  CHECK (period_start <= period_end),
  CHECK (jsonb_array_length(metrics) > 0)
);

CREATE TABLE IF NOT EXISTS reporting.investor_review_packages (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  period_start timestamptz NOT NULL,
  period_end timestamptz NOT NULL,
  project_portfolio jsonb NOT NULL,
  evidence_coverage jsonb NOT NULL,
  verification_statistics jsonb NOT NULL,
  risk_profile jsonb NOT NULL,
  audit_history jsonb NOT NULL,
  esg_report_ids text[] NOT NULL,
  proof_record_ids text[] NOT NULL,
  claim_boundary jsonb NOT NULL,
  package_root text NOT NULL UNIQUE,
  generated_at timestamptz NOT NULL,
