);

CREATE OR REPLACE FUNCTION audit.length_prefix(value text)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT octet_length(value)::text || ':' || value;
$$;

CREATE OR REPLACE FUNCTION audit.compute_event_log_hash(
  event_version text,
  stream_key text,
  schema_name text,
  table_name text,
  row_pk_hash text,
  sequence_no bigint,
  action text,
  actor_id text,
  recorded_at_unix_micros bigint,
  previous_event_hash text,
  before_state_hash text,
  after_state_hash text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      audit.length_prefix(event_version) ||
      audit.length_prefix(stream_key) ||
      audit.length_prefix(schema_name) ||
      audit.length_prefix(table_name) ||
      audit.length_prefix(row_pk_hash) ||
      audit.length_prefix(sequence_no::text) ||
      audit.length_prefix(action) ||
      audit.length_prefix(actor_id) ||
      audit.length_prefix(recorded_at_unix_micros::text) ||
      audit.length_prefix(previous_event_hash) ||
      audit.length_prefix(before_state_hash) ||
      audit.length_prefix(after_state_hash),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE TABLE IF NOT EXISTS audit.domain_events (
  id text PRIMARY KEY,
  stream_id text NOT NULL CHECK (length(btrim(stream_id)) > 0),
  sequence_no bigint NOT NULL DEFAULT 0 CHECK (sequence_no > 0),
  action text NOT NULL CHECK (action IN ('ASSERT', 'REASON', 'DELEGATE', 'FULFILL', 'CHALLENGE')),
  actor_id text NOT NULL REFERENCES identity.participants(id),
  entity_type text NOT NULL CHECK (length(btrim(entity_type)) > 0),
  entity_id text NOT NULL CHECK (length(btrim(entity_id)) > 0),
  previous_root text NOT NULL CHECK (previous_root ~ '^[0-9a-f]{64}$'),
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  event_root text NOT NULL UNIQUE CHECK (event_root ~ '^[0-9a-f]{64}$'),
  created_at timestamptz NOT NULL,
  rationale text NOT NULL CHECK (length(btrim(rationale)) > 0),
  UNIQUE (stream_id, sequence_no)
);

CREATE INDEX IF NOT EXISTS audit_domain_events_stream_page
  ON audit.domain_events (stream_id, sequence_no DESC);

CREATE INDEX IF NOT EXISTS audit_domain_events_actor_time
  ON audit.domain_events (actor_id, created_at DESC, id DESC);

CREATE TABLE IF NOT EXISTS audit.command_receipts (
  id text PRIMARY KEY,
  actor_id text NOT NULL REFERENCES identity.participants(id),
  operation text NOT NULL CHECK (length(btrim(operation)) > 0),
  idempotency_key_hash text NOT NULL CHECK (idempotency_key_hash ~ '^[0-9a-f]{64}$'),
  request_hash text NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
  result_entity_type text NOT NULL CHECK (length(btrim(result_entity_type)) > 0),
  result_entity_id text NOT NULL CHECK (length(btrim(result_entity_id)) > 0),
  response_hash text NOT NULL CHECK (response_hash ~ '^[0-9a-f]{64}$'),
  audit_event_root text NOT NULL CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  created_at timestamptz NOT NULL,
  UNIQUE (actor_id, operation, idempotency_key_hash)
);

CREATE INDEX IF NOT EXISTS audit_command_receipts_result
  ON audit.command_receipts (result_entity_type, result_entity_id, created_at DESC);

-- Mutable coordination only: canonical authority remains in append-only facts
-- and domain events. Writers advance this fence so a SERIALIZABLE transaction
-- that waited on an advisory lock cannot continue with a pre-lock snapshot.
CREATE TABLE IF NOT EXISTS audit.authority_fences (
  authority_key text PRIMARY KEY CHECK (length(btrim(authority_key)) BETWEEN 1 AND 512),
  revision bigint NOT NULL CHECK (revision > 0),
  updated_at timestamptz NOT NULL
);

CREATE INDEX IF NOT EXISTS audit_authority_fences_updated_at
  ON audit.authority_fences (updated_at DESC, authority_key ASC);

CREATE OR REPLACE FUNCTION audit.compute_domain_event_root(
  event_action text,
  event_actor text,
  event_entity_type text,
  event_entity_id text,
  event_previous_root text,
  event_payload_hash text,
  event_created_at timestamptz,
  event_rationale text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"action":' || to_json(event_action)::text ||
        ',"actor":' || to_json(event_actor)::text ||
        ',"createdAt":' || to_json(to_char(event_created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"entityId":' || to_json(event_entity_id)::text ||
        ',"entityType":' || to_json(event_entity_type)::text ||
        ',"kind":"canopyproof-audit-event-v1"' ||
        ',"payloadHash":' || to_json(event_payload_hash)::text ||
        ',"previousRoot":' || to_json(event_previous_root)::text ||
        ',"rationale":' || to_json(event_rationale)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION audit.validate_domain_event_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  prior_event_root text;
  prior_created_at timestamptz;
  next_sequence bigint;
  expected_event_root text;
  expected_event_id text;
  semantic_genesis_root constant text := 'f9eb6f91a48893e686f0b033bd12f0308b65918aa00c91d16d8146124600f6e4';
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.actor_id THEN
    RAISE EXCEPTION 'domain event insert requires matching app.actor_id transaction context' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.created_at <> date_trunc('milliseconds', NEW.created_at) THEN
    RAISE EXCEPTION 'domain event timestamp must use UTC millisecond precision' USING ERRCODE = 'check_violation';
  END IF;

  expected_event_root := audit.compute_domain_event_root(
    NEW.action,
    NEW.actor_id,
    NEW.entity_type,
    NEW.entity_id,
    NEW.previous_root,
    NEW.payload_hash,
    NEW.created_at,
    NEW.rationale
  );
  expected_event_id := 'cp_audit_' || left(expected_event_root, 24);
  IF NEW.event_root <> expected_event_root THEN
    RAISE EXCEPTION 'domain event root does not match canonical fields' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.id <> expected_event_id THEN
    RAISE EXCEPTION 'domain event id does not match canonical root' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('domain-event:' || NEW.stream_id, 0));

  SELECT sequence_no, event_root, created_at
  INTO next_sequence, prior_event_root, prior_created_at
  FROM audit.domain_events
  WHERE stream_id = NEW.stream_id
  ORDER BY sequence_no DESC
  LIMIT 1
  FOR UPDATE;

  IF prior_event_root IS NULL THEN
    NEW.sequence_no := 1;
    IF NEW.previous_root <> semantic_genesis_root THEN
      RAISE EXCEPTION 'first domain event must link to semantic audit genesis' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    NEW.sequence_no := next_sequence + 1;
    IF NEW.previous_root <> prior_event_root THEN
      RAISE EXCEPTION 'domain event predecessor is missing or mismatched' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.created_at < prior_created_at THEN
      RAISE EXCEPTION 'domain event timestamp cannot move backwards' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS audit_domain_events_validate_insert ON audit.domain_events;
CREATE TRIGGER audit_domain_events_validate_insert
BEFORE INSERT ON audit.domain_events
FOR EACH ROW EXECUTE FUNCTION audit.validate_domain_event_insert();

CREATE TABLE IF NOT EXISTS impact.global_command_center_publication_facts (
  id text PRIMARY KEY,
  snapshot_id text NOT NULL UNIQUE REFERENCES impact.global_command_center_snapshots(id),
  projection_schema text NOT NULL CHECK (projection_schema = 'canopyproof.global-command-center.snapshot.v2'),
  dashboard_root text NOT NULL UNIQUE CHECK (dashboard_root ~ '^[0-9a-f]{64}$'),
  snapshot_content_root text NOT NULL UNIQUE CHECK (snapshot_content_root ~ '^[0-9a-f]{64}$'),
  source_authority_root text NOT NULL CHECK (source_authority_root ~ '^[0-9a-f]{64}$'),
  policy_id text NOT NULL CHECK (length(btrim(policy_id)) > 0),
  policy_root text NOT NULL CHECK (policy_root ~ '^[0-9a-f]{64}$'),
  approval_root text NOT NULL CHECK (approval_root ~ '^[0-9a-f]{64}$'),
  publisher_id text NOT NULL REFERENCES identity.participants(id),
  publisher_snapshot jsonb NOT NULL,
  published_at timestamptz NOT NULL,
  publication_root text NOT NULL UNIQUE CHECK (publication_root ~ '^[0-9a-f]{64}$'),
  audit_event_root text NOT NULL UNIQUE REFERENCES audit.domain_events(event_root),
  fact_record jsonb NOT NULL,
  CHECK (jsonb_typeof(publisher_snapshot) = 'object'),
  CHECK (jsonb_typeof(fact_record) = 'object'),
  CHECK (fact_record->>'factType' = 'global_command_center_snapshot_publication'),
  CHECK (fact_record->>'id' = id),
  CHECK (fact_record->>'snapshotId' = snapshot_id),
  CHECK (fact_record->>'projectionSchema' = projection_schema),
  CHECK (fact_record->>'dashboardRoot' = dashboard_root),
  CHECK (fact_record->>'snapshotContentRoot' = snapshot_content_root),
  CHECK (fact_record->>'sourceAuthorityRoot' = source_authority_root),
  CHECK (fact_record->>'policyId' = policy_id),
  CHECK (fact_record->>'policyRoot' = policy_root),
  CHECK (fact_record->'governanceApproval'->>'approvalRoot' = approval_root),
  CHECK (fact_record->'publisher'->>'id' = publisher_id),
  CHECK (publisher_snapshot->>'id' = publisher_id),
  CHECK (publisher_snapshot = fact_record->'publisher'),
  CHECK (fact_record->'publisher'->>'membershipStatus' = 'active'),
  CHECK (fact_record->'publisher'->>'accreditationStatus' = 'approved'),
  CHECK ((fact_record->'publisher'->'accreditationScope') ? 'global_command_center:publish'),
  CHECK (fact_record->'governanceApproval'->'governor'->>'participantType' = 'human'),
  CHECK (fact_record->'governanceApproval'->'governor'->>'membershipStatus' = 'active'),
  CHECK (fact_record->'governanceApproval'->'governor'->>'accreditationStatus' = 'approved'),
  CHECK ((fact_record->'governanceApproval'->'governor'->'accreditationScope') ? 'global_command_center:govern'),
  CHECK (fact_record->'governanceApproval'->'governor'->>'id' <> publisher_id),
  CHECK (fact_record->>'publicationRoot' = publication_root),
  CHECK (fact_record->'auditEvent'->>'eventRoot' = audit_event_root),
  CHECK ((fact_record->'safety'->>'routeMounted')::boolean IS FALSE),
  CHECK ((fact_record->'safety'->>'schedulerMounted')::boolean IS FALSE),
  CHECK ((fact_record->'safety'->>'productionActivationEnabled')::boolean IS FALSE),
  CHECK ((fact_record->'safety'->>'independentHumanGovernanceRequired')::boolean IS TRUE),
  CHECK ((fact_record->'safety'->>'noMainnetFunds')::boolean IS TRUE),
  CHECK ((fact_record->'safety'->>'noAutomaticCanopyDistribution')::boolean IS TRUE),
  CHECK ((fact_record->'safety'->>'notCertifiedCarbonCredit')::boolean IS TRUE),
  CHECK ((fact_record->'safety'->>'notCarbonTaxOffset')::boolean IS TRUE),
  CHECK ((fact_record->'safety'->>'notFinancialAsset')::boolean IS TRUE),
  CHECK ((fact_record->'safety'->>'notGuaranteedYield')::boolean IS TRUE)
);

CREATE INDEX IF NOT EXISTS impact_global_command_center_publications_published
  ON impact.global_command_center_publication_facts (published_at DESC, id DESC);

CREATE OR REPLACE FUNCTION impact.validate_global_command_center_publication_fact()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  semantic_event audit.domain_events%ROWTYPE;
  snapshot_dashboard_root text;
BEGIN
  SELECT * INTO STRICT semantic_event
  FROM audit.domain_events
  WHERE event_root = NEW.audit_event_root;

  IF semantic_event.stream_id <> 'global-command-center:publications'
    OR semantic_event.action <> 'ASSERT'
    OR semantic_event.actor_id <> NEW.publisher_id
    OR semantic_event.entity_type <> 'global_command_center_snapshot'
    OR semantic_event.entity_id <> NEW.id
    OR semantic_event.previous_root <> NEW.fact_record->>'previousEventRoot'
    OR semantic_event.payload_hash <> NEW.fact_record->'auditEvent'->>'payloadHash'
    OR semantic_event.event_root <> NEW.fact_record->'auditEvent'->>'eventRoot'
    OR semantic_event.created_at <> NEW.published_at
  THEN
    RAISE EXCEPTION 'global command center publication semantic event binding is invalid'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT dashboard_root INTO STRICT snapshot_dashboard_root
  FROM impact.global_command_center_snapshots
  WHERE id = NEW.snapshot_id;
  IF snapshot_dashboard_root <> NEW.dashboard_root THEN
    RAISE EXCEPTION 'global command center publication snapshot binding is invalid'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS impact_global_command_center_publication_facts_validate
  ON impact.global_command_center_publication_facts;
CREATE TRIGGER impact_global_command_center_publication_facts_validate
BEFORE INSERT ON impact.global_command_center_publication_facts
FOR EACH ROW EXECUTE FUNCTION impact.validate_global_command_center_publication_fact();

CREATE OR REPLACE FUNCTION impact.require_global_command_center_snapshot_publication()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  publication_count integer;
BEGIN
  SELECT count(*)::integer INTO publication_count
  FROM impact.global_command_center_publication_facts publication
  WHERE publication.snapshot_id = NEW.id
    AND publication.dashboard_root = NEW.dashboard_root;
  IF publication_count <> 1 THEN
    RAISE EXCEPTION 'global command center snapshot requires exactly one governed publication fact'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS impact_global_command_center_snapshot_requires_publication
  ON impact.global_command_center_snapshots;
CREATE CONSTRAINT TRIGGER impact_global_command_center_snapshot_requires_publication
AFTER INSERT ON impact.global_command_center_snapshots
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION impact.require_global_command_center_snapshot_publication();

CREATE OR REPLACE FUNCTION projects.claim_boundary()
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT jsonb_build_object(
    'restorationProjectRegistryOnly', true,
    'notCertifiedCarbonCredit', true,
    'notCarbonTaxOffset', true,
    'notFinancialAsset', true,
    'notGuaranteedYield', true,
    'noMainnetFunds', true,
    'notAutomaticCanopyDistribution', true,
    'disclosure', 'This project profile is an environmental accountability registry record. It is not a certified carbon credit, carbon-tax offset, financial asset, guaranteed yield instrument, mainnet-fund movement, or automatic CANOPY distribution claim.'
  );
$$;

CREATE OR REPLACE FUNCTION projects.actor_has_project_role(
  actor_identifier text,
  organization_identifier text,
  actor_role text
)
RETURNS boolean
LANGUAGE sql
STABLE
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM identity.participants participant
    JOIN organizations.memberships membership
      ON membership.actor_id = participant.id
     AND membership.organization_id = organization_identifier
     AND membership.role = actor_role
     AND membership.status = 'active'
    JOIN organizations.organizations organization
      ON organization.id = membership.organization_id
     AND organization.verification_status = 'verified'
    WHERE participant.id = actor_identifier
      AND participant.participant_type = 'human'
      AND participant.verification_status = 'verified'
      AND actor_role = ANY(participant.roles)
      AND actor_role IN ('owner', 'admin', 'verifier', 'researcher')
  );
$$;

CREATE OR REPLACE FUNCTION projects.status_transition_allowed(previous_status text, next_status text)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT CASE previous_status
    WHEN 'submitted' THEN next_status = ANY(ARRAY['under_review', 'challenged', 'suspended', 'archived']::text[])
    WHEN 'under_review' THEN next_status = ANY(ARRAY['active', 'challenged', 'suspended', 'archived']::text[])
    WHEN 'active' THEN next_status = ANY(ARRAY['monitored', 'challenged', 'suspended', 'archived']::text[])
    WHEN 'monitored' THEN next_status = ANY(ARRAY['monitored', 'challenged', 'suspended', 'archived']::text[])
    WHEN 'challenged' THEN next_status = ANY(ARRAY['under_review', 'suspended', 'archived']::text[])
    WHEN 'suspended' THEN next_status = ANY(ARRAY['under_review', 'archived']::text[])
    ELSE false
  END;
$$;

CREATE OR REPLACE FUNCTION projects.current_authority(target_project_id text)
RETURNS TABLE (
  status text,
  project_root text,
  updated_at timestamptz,
  governance_approval_id text,
  audit_event_root text,
  sequence_no bigint
)
LANGUAGE sql
STABLE
AS $$
  WITH facts AS (
    SELECT
      registration.status,
      registration.project_root,
      registration.updated_at,
      registration.audit_event_root,
      event.sequence_no
    FROM projects.projects registration
    JOIN audit.domain_events event ON event.event_root = registration.audit_event_root
    WHERE registration.id = target_project_id
    UNION ALL
    SELECT
      transition.status,
      transition.transition_root,
      transition.updated_at,
      transition.audit_event_root,
      event.sequence_no
    FROM projects.project_status_transitions transition
    JOIN audit.domain_events event ON event.event_root = transition.audit_event_root
    WHERE transition.project_id = target_project_id
    UNION ALL
    SELECT
      monitoring.project_status,
      monitoring.monitoring_root,
      monitoring.observed_at,
      monitoring.audit_event_root,
      event.sequence_no
    FROM projects.monitoring_events monitoring
    JOIN audit.domain_events event ON event.event_root = monitoring.audit_event_root
    WHERE monitoring.project_id = target_project_id
  ), latest AS (
    SELECT * FROM facts ORDER BY sequence_no DESC LIMIT 1
  ), latest_approval AS (
    SELECT transition.governance_approval_id
    FROM projects.project_status_transitions transition
    JOIN audit.domain_events event ON event.event_root = transition.audit_event_root
    WHERE transition.project_id = target_project_id
      AND transition.governance_approval_id IS NOT NULL
    ORDER BY event.sequence_no DESC
    LIMIT 1
  )
  SELECT
    latest.status,
    latest.project_root,
    latest.updated_at,
    COALESCE(
      (SELECT approval.governance_approval_id FROM latest_approval approval),
      registration.governance_approval_id
    ),
    latest.audit_event_root,
    latest.sequence_no
  FROM latest
  JOIN projects.projects registration ON registration.id = target_project_id;
$$;

CREATE OR REPLACE FUNCTION projects.project_hash(project_record projects.projects)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-project-profile-v2',
    'id', project_record.id,
    'organizationId', project_record.organization_id,
    'title', project_record.title,
    'projectType', project_record.project_type,
    'regionId', project_record.region_id,
    'location', project_record.location,
    'targetTreeCount', project_record.target_tree_count,
    'biodiversityIndicators', to_jsonb(project_record.biodiversity_indicators),
    'waterIndicators', to_jsonb(project_record.water_indicators),
    'climateRiskIndicators', to_jsonb(project_record.climate_risk_indicators),
    'monitoringCadenceDays', project_record.monitoring_cadence_days,
    'governancePolicyId', project_record.governance_policy_id,
    'governanceApprovalId', project_record.governance_approval_id,
    'status', project_record.status,
    'createdAt', audit.iso8601_millis(project_record.created_at),
    'createdBy', project_record.created_by,
    'createdByRole', project_record.created_by_role,
    'claimBoundary', project_record.claim_boundary
  ));
$$;

