CREATE OR REPLACE FUNCTION projects.governance_approval_valid(
  target_project_id text,
  target_policy_id text,
  target_approval_id text,
  project_creator_id text,
  transition_actor_id text,
  transition_timestamp timestamptz
)
RETURNS boolean
LANGUAGE sql
STABLE
AS $$
  SELECT target_policy_id IS NOT NULL
    AND target_approval_id IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM governance.approvals approval
      JOIN governance.policies policy ON policy.id = approval.policy_id
      JOIN identity.participants approver ON approver.id = approval.approver_id
      WHERE approval.id = target_approval_id
        AND approval.subject_type = 'project'
        AND approval.subject_id = target_project_id
        AND approval.policy_id = target_policy_id
        AND approval.decision = 'approve'
        AND approval.approver_role = ANY(policy.allowed_reviewer_roles)
        AND 'project' = ANY(policy.applies_to)
        AND policy.human_authority_required IS true
        AND policy.conflict_disclosure_required IS true
        AND policy.claim_boundary_enforced IS true
        AND approver.participant_type = 'human'
        AND approver.verification_status = 'verified'
        AND approval.approver_role = ANY(approver.roles)
        AND approval.approver_id <> project_creator_id
        AND approval.approver_id <> transition_actor_id
        AND approval.decided_at <= transition_timestamp
        AND length(btrim(approval.conflict_disclosure)) > 0
    );
$$;

CREATE OR REPLACE FUNCTION projects.contains_unsafe_claim(values_to_check text[])
RETURNS boolean
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM unnest(values_to_check) value
    WHERE value ~* 'certified carbon credit|carbon[- ]?tax offset|guaranteed (rwa )?yield|automatic \$?canopy distribution|mainnet funds|(begin|end) (rsa |ec |openssh |private )?private key|private[_ -]?key|api[_ -]?secret|access[_ -]?secret|client[_ -]?secret|password'
  );
$$;

CREATE OR REPLACE FUNCTION projects.validate_registration_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.created_by THEN
    RAISE EXCEPTION 'project registration requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT projects.actor_has_project_role(NEW.created_by, NEW.organization_id, NEW.created_by_role) OR NEW.created_by_role NOT IN ('owner', 'admin', 'verifier') THEN
    RAISE EXCEPTION 'project registration requires a verified human with an exact active organization role' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> 'submitted' OR NEW.governance_approval_id IS NOT NULL OR NEW.updated_at <> NEW.created_at THEN
    RAISE EXCEPTION 'project registration must be an immutable submitted fact' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.created_at <> date_trunc('milliseconds', NEW.created_at) THEN
    RAISE EXCEPTION 'project registration timestamp must use UTC millisecond precision' USING ERRCODE = 'check_violation';
  END IF;
  IF length(btrim(NEW.title)) NOT BETWEEN 3 AND 240 OR length(btrim(NEW.region_id)) NOT BETWEEN 1 AND 160 THEN
    RAISE EXCEPTION 'project registration text fields are outside bounded limits' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.monitoring_cadence_days > 3650 OR NEW.target_tree_count > 9007199254740991 THEN
    RAISE EXCEPTION 'project registration numeric fields are outside bounded limits' USING ERRCODE = 'check_violation';
  END IF;
  IF jsonb_typeof(NEW.location) <> 'object'
     OR jsonb_typeof(NEW.location -> 'latitude') <> 'number'
     OR jsonb_typeof(NEW.location -> 'longitude') <> 'number'
     OR jsonb_typeof(NEW.location -> 'areaHectares') <> 'number'
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(NEW.location) key_name
       WHERE key_name <> ALL(ARRAY['latitude', 'longitude', 'areaHectares', 'boundaryHash']::text[])
     )
     OR (NEW.location ->> 'latitude')::double precision NOT BETWEEN -90 AND 90
     OR (NEW.location ->> 'longitude')::double precision NOT BETWEEN -180 AND 180
     OR (NEW.location ->> 'areaHectares')::numeric < 0
     OR (NEW.location ->> 'areaHectares')::numeric <> NEW.area_hectares
     OR (
       NEW.location ? 'boundaryHash'
       AND (
         jsonb_typeof(NEW.location -> 'boundaryHash') <> 'string'
         OR NEW.location ->> 'boundaryHash' !~ '^[0-9a-f]{64}$'
       )
     ) THEN
    RAISE EXCEPTION 'project registration location is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT audit.is_sorted_unique_text_array(NEW.biodiversity_indicators)
     OR NOT audit.is_sorted_unique_text_array(NEW.water_indicators)
     OR NOT audit.is_sorted_unique_text_array(NEW.climate_risk_indicators)
     OR NOT audit.is_bounded_text_array(NEW.biodiversity_indicators, 1, 240, 128)
     OR NOT audit.is_bounded_text_array(NEW.water_indicators, 1, 240, 128)
     OR NOT audit.is_bounded_text_array(NEW.climate_risk_indicators, 1, 240, 128) THEN
    RAISE EXCEPTION 'project registration indicators must be bounded sorted sets' USING ERRCODE = 'check_violation';
  END IF;
  IF projects.contains_unsafe_claim(ARRAY[
    NEW.organization_id,
    NEW.title,
    NEW.region_id,
    COALESCE(NEW.governance_policy_id, ''),
    COALESCE(NEW.governance_approval_id, '')
  ] || NEW.biodiversity_indicators || NEW.water_indicators || NEW.climate_risk_indicators) THEN
    RAISE EXCEPTION 'project registration contains an unsupported public claim or secret material' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.claim_boundary IS DISTINCT FROM projects.claim_boundary() THEN
    RAISE EXCEPTION 'project registration claim boundary is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.project_hash IS DISTINCT FROM projects.project_hash(NEW) THEN
    RAISE EXCEPTION 'project registration hash does not match canonical fields' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.project_root IS DISTINCT FROM projects.project_root(NEW) THEN
    RAISE EXCEPTION 'project registration root does not match canonical fields' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION projects.validate_transition_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  current_state record;
  registration projects.projects%ROWTYPE;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.updated_by THEN
    RAISE EXCEPTION 'project status transition requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('domain-event:' || NEW.project_id, 0));
  SELECT * INTO STRICT registration FROM projects.projects WHERE id = NEW.project_id;
  SELECT * INTO STRICT current_state FROM projects.current_authority(NEW.project_id);
  IF NEW.organization_id <> registration.organization_id
     OR NOT projects.actor_has_project_role(NEW.updated_by, NEW.organization_id, NEW.updater_role)
     OR NEW.updater_role NOT IN ('owner', 'admin', 'verifier') THEN
    RAISE EXCEPTION 'project status transition requires a verified human with an exact active organization role' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.updated_at <> date_trunc('milliseconds', NEW.updated_at) OR NEW.updated_at <= current_state.updated_at THEN
    RAISE EXCEPTION 'project status transition timestamp must advance at UTC millisecond precision' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.previous_status <> current_state.status
     OR NEW.previous_project_root <> current_state.project_root
     OR NOT projects.status_transition_allowed(NEW.previous_status, NEW.status) THEN
    RAISE EXCEPTION 'project status transition does not extend current authority' USING ERRCODE = 'check_violation';
  END IF;
  IF projects.contains_unsafe_claim(ARRAY[NEW.rationale, COALESCE(NEW.governance_approval_id, '')]) THEN
    RAISE EXCEPTION 'project status transition contains an unsupported public claim or secret material' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IN ('active', 'monitored') THEN
    IF NOT projects.governance_approval_valid(
      NEW.project_id,
      registration.governance_policy_id,
      NEW.governance_approval_id,
      registration.created_by,
      NEW.updated_by,
      NEW.updated_at
    ) THEN
      RAISE EXCEPTION 'project active or monitored transition requires an independent valid governance approval' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.governance_approval_id IS DISTINCT FROM current_state.governance_approval_id THEN
    RAISE EXCEPTION 'project governance approval can only be introduced by an active or monitored transition' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.transition_hash IS DISTINCT FROM projects.transition_hash(NEW)
     OR NEW.id IS DISTINCT FROM 'cp_project_transition_' || left(NEW.transition_hash, 24)
     OR NEW.transition_root IS DISTINCT FROM projects.transition_root(NEW) THEN
    RAISE EXCEPTION 'project status transition hash lineage is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION projects.validate_monitoring_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  current_state record;
  registration projects.projects%ROWTYPE;
  expected_project_status text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.observed_by THEN
    RAISE EXCEPTION 'project monitoring insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('domain-event:' || NEW.project_id, 0));
  SELECT * INTO STRICT registration FROM projects.projects WHERE id = NEW.project_id;
  SELECT * INTO STRICT current_state FROM projects.current_authority(NEW.project_id);
  IF NEW.organization_id <> registration.organization_id
     OR NOT projects.actor_has_project_role(NEW.observed_by, NEW.organization_id, NEW.observer_role) THEN
    RAISE EXCEPTION 'project monitoring requires a verified human with an exact active organization role' USING ERRCODE = 'check_violation';
  END IF;
  IF current_state.status = 'archived' THEN
    RAISE EXCEPTION 'archived project cannot accept monitoring events' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.observed_at <> date_trunc('milliseconds', NEW.observed_at) OR NEW.observed_at <= current_state.updated_at THEN
    RAISE EXCEPTION 'project monitoring timestamp must advance at UTC millisecond precision' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.previous_status <> current_state.status OR NEW.previous_project_root <> current_state.project_root THEN
    RAISE EXCEPTION 'project monitoring event does not extend current authority' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.state = 'accepted' AND current_state.status NOT IN ('active', 'monitored') THEN
    RAISE EXCEPTION 'accepted project monitoring requires active or monitored authority' USING ERRCODE = 'check_violation';
  END IF;
  expected_project_status := CASE
    WHEN NEW.state = 'challenged' THEN 'challenged'
    WHEN NEW.state = 'accepted' AND current_state.status = 'active' THEN 'monitored'
    ELSE current_state.status
  END;
  IF NEW.project_status <> expected_project_status THEN
    RAISE EXCEPTION 'project monitoring projected status is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT audit.is_sorted_unique_text_array(NEW.evidence_ids)
     OR NOT audit.is_sorted_unique_text_array(NEW.terra_scene_ids)
     OR NOT audit.is_sorted_unique_text_array(NEW.biodiversity_indicators)
     OR NOT audit.is_sorted_unique_text_array(NEW.water_indicators)
     OR NOT audit.is_sorted_unique_text_array(NEW.climate_risk_indicators)
     OR NOT audit.is_bounded_text_array(NEW.evidence_ids, 1, 240, 256)
     OR NOT audit.is_bounded_text_array(NEW.terra_scene_ids, 1, 240, 256)
     OR NOT audit.is_bounded_text_array(NEW.biodiversity_indicators, 1, 240, 128)
     OR NOT audit.is_bounded_text_array(NEW.water_indicators, 1, 240, 128)
     OR NOT audit.is_bounded_text_array(NEW.climate_risk_indicators, 1, 240, 128) THEN
    RAISE EXCEPTION 'project monitoring references and indicators must be bounded sorted sets' USING ERRCODE = 'check_violation';
  END IF;
  IF jsonb_typeof(NEW.metrics) <> 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(NEW.metrics)) > 128
     OR EXISTS (
       SELECT 1 FROM jsonb_each(NEW.metrics) metric(key_name, metric_value)
       WHERE length(btrim(key_name)) NOT BETWEEN 1 AND 120 OR jsonb_typeof(metric_value) <> 'number'
     ) THEN
    RAISE EXCEPTION 'project monitoring metrics must be a bounded numeric object' USING ERRCODE = 'check_violation';
  END IF;
  IF projects.contains_unsafe_claim(
    ARRAY[NEW.event_type, NEW.rationale]
    || NEW.evidence_ids
    || NEW.terra_scene_ids
    || NEW.biodiversity_indicators
    || NEW.water_indicators
    || NEW.climate_risk_indicators
    || ARRAY(SELECT key_name FROM jsonb_object_keys(NEW.metrics) key_name ORDER BY key_name)
  ) THEN
    RAISE EXCEPTION 'project monitoring contains an unsupported public claim or secret material' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM unnest(NEW.evidence_ids) evidence_id
    LEFT JOIN evidence.evidence_objects evidence_record ON evidence_record.id = evidence_id
    WHERE evidence_record.id IS NULL
       OR evidence_record.project_id <> NEW.project_id
       OR evidence_record.observed_at > NEW.observed_at
  ) THEN
    RAISE EXCEPTION 'project monitoring evidence reference is missing, foreign, or future-dated' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM unnest(NEW.terra_scene_ids) scene_id
    LEFT JOIN satellite.observations observation ON observation.id = scene_id
    WHERE observation.id IS NULL
       OR observation.project_id <> NEW.project_id
       OR observation.acquired_at > NEW.observed_at
  ) THEN
    RAISE EXCEPTION 'project monitoring Terra reference is missing, foreign, or future-dated' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.event_hash IS DISTINCT FROM projects.monitoring_hash(NEW)
     OR NEW.id IS DISTINCT FROM 'cp_project_monitoring_' || left(NEW.event_hash, 24)
     OR NEW.monitoring_root IS DISTINCT FROM projects.monitoring_root(NEW) THEN
    RAISE EXCEPTION 'project monitoring hash lineage is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION projects.validate_semantic_event_binding()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  event_record audit.domain_events%ROWTYPE;
  current_state record;
  expected_action text;
  expected_actor text;
  expected_entity_type text;
  expected_entity_id text;
  expected_stream_id text;
  expected_created_at timestamptz;
  expected_rationale text;
  expected_payload_hash text;
  expected_previous_root text;
  expected_sequence bigint;
  expected_audit_history jsonb;
BEGIN
  IF TG_TABLE_NAME = 'projects' THEN
    expected_action := 'ASSERT';
    expected_actor := NEW.created_by;
    expected_entity_type := 'project';
    expected_entity_id := NEW.id;
    expected_stream_id := NEW.id;
    expected_created_at := NEW.created_at;
    expected_rationale := 'CanopyProof project registered as a bounded environmental accountability record.';
    expected_payload_hash := projects.registration_payload_hash(NEW);
    expected_sequence := 1;
  ELSIF TG_TABLE_NAME = 'project_status_transitions' THEN
    SELECT * INTO STRICT current_state FROM projects.current_authority(NEW.project_id);
    expected_action := CASE WHEN NEW.status = 'challenged' THEN 'CHALLENGE' ELSE 'FULFILL' END;
    expected_actor := NEW.updated_by;
    expected_entity_type := 'project_status_transition';
    expected_entity_id := NEW.id;
    expected_stream_id := NEW.project_id;
    expected_created_at := NEW.updated_at;
    expected_rationale := NEW.rationale;
    expected_payload_hash := projects.transition_payload_hash(NEW);
    expected_previous_root := current_state.audit_event_root;
    expected_sequence := current_state.sequence_no + 1;
  ELSIF TG_TABLE_NAME = 'monitoring_events' THEN
    SELECT * INTO STRICT current_state FROM projects.current_authority(NEW.project_id);
    expected_action := CASE WHEN NEW.state = 'challenged' THEN 'CHALLENGE' ELSE 'ASSERT' END;
    expected_actor := NEW.observed_by;
    expected_entity_type := 'project_monitoring_event';
    expected_entity_id := NEW.id;
    expected_stream_id := NEW.project_id;
    expected_created_at := NEW.observed_at;
    expected_rationale := NEW.rationale;
    expected_payload_hash := projects.monitoring_payload_hash(NEW);
    expected_previous_root := current_state.audit_event_root;
    expected_sequence := current_state.sequence_no + 1;
  ELSE
    RAISE EXCEPTION 'unsupported project semantic event source table' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT event_record
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root;

  IF event_record.stream_id <> expected_stream_id
     OR event_record.sequence_no <> expected_sequence
     OR event_record.action <> expected_action
     OR event_record.actor_id <> expected_actor
     OR event_record.entity_type <> expected_entity_type
     OR event_record.entity_id <> expected_entity_id
     OR event_record.created_at <> expected_created_at
     OR event_record.rationale <> expected_rationale
     OR event_record.payload_hash <> expected_payload_hash
     OR (expected_previous_root IS NOT NULL AND event_record.previous_root <> expected_previous_root) THEN
    RAISE EXCEPTION 'project source row requires an exact semantic event binding' USING ERRCODE = 'check_violation';
  END IF;

  IF TG_TABLE_NAME = 'projects' THEN
    expected_audit_history := jsonb_build_array(jsonb_build_object(
      'id', event_record.id,
      'action', event_record.action,
      'actor', event_record.actor_id,
      'entityType', event_record.entity_type,
      'entityId', event_record.entity_id,
      'previousRoot', event_record.previous_root,
      'payloadHash', event_record.payload_hash,
      'eventRoot', event_record.event_root,
      'createdAt', audit.iso8601_millis(event_record.created_at),
      'rationale', event_record.rationale
    ));
    IF NEW.audit_history IS DISTINCT FROM expected_audit_history THEN
      RAISE EXCEPTION 'project registration audit history is not the singular bound semantic event' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
EXCEPTION
  WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
    RAISE EXCEPTION 'project source row requires an exact semantic event binding' USING ERRCODE = 'check_violation';
END;
$$;

DROP TRIGGER IF EXISTS project_registration_event_binding ON projects.projects;
CREATE TRIGGER project_registration_event_binding
BEFORE INSERT ON projects.projects
FOR EACH ROW EXECUTE FUNCTION projects.validate_semantic_event_binding();

DROP TRIGGER IF EXISTS project_registration_validate ON projects.projects;
CREATE TRIGGER project_registration_validate
BEFORE INSERT ON projects.projects
FOR EACH ROW EXECUTE FUNCTION projects.validate_registration_insert();

DROP TRIGGER IF EXISTS project_transition_event_binding ON projects.project_status_transitions;
CREATE TRIGGER project_transition_event_binding
BEFORE INSERT ON projects.project_status_transitions
FOR EACH ROW EXECUTE FUNCTION projects.validate_semantic_event_binding();

DROP TRIGGER IF EXISTS project_transition_validate ON projects.project_status_transitions;
CREATE TRIGGER project_transition_validate
BEFORE INSERT ON projects.project_status_transitions
FOR EACH ROW EXECUTE FUNCTION projects.validate_transition_insert();

DROP TRIGGER IF EXISTS project_monitoring_event_binding ON projects.monitoring_events;
CREATE TRIGGER project_monitoring_event_binding
BEFORE INSERT ON projects.monitoring_events
FOR EACH ROW EXECUTE FUNCTION projects.validate_semantic_event_binding();

DROP TRIGGER IF EXISTS project_monitoring_validate ON projects.monitoring_events;
CREATE TRIGGER project_monitoring_validate
BEFORE INSERT ON projects.monitoring_events
FOR EACH ROW EXECUTE FUNCTION projects.validate_monitoring_insert();

CREATE OR REPLACE FUNCTION evidence.registration_claim_boundary()
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT jsonb_build_object(
    'structuralValidationOnly', true,
    'pendingAiAndHumanReview', true,
    'notFinalVerification', true,
    'notCertificate', true,
    'notCertifiedCarbonCredit', true,
    'notCarbonTaxOffset', true,
    'notFinancialAsset', true,
    'notGuaranteedYield', true,
    'noMainnetFunds', true,
    'notAutomaticCanopyDistribution', true,
    'disclosure', 'This evidence registration passed or failed structural ingestion checks only. It is pending AI assistance and accountable human review; it is not final verification, a certificate, certified carbon credit, carbon-tax offset, financial asset, guaranteed yield, mainnet-fund movement, or automatic CANOPY distribution.'
  );
$$;

CREATE OR REPLACE FUNCTION evidence.actor_has_registration_role(
  actor_identifier text,
  organization_identifier text,
  actor_role text
)
RETURNS boolean
LANGUAGE sql
STABLE
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM identity.participants participant
    JOIN organizations.memberships membership
      ON membership.actor_id = participant.id
     AND membership.organization_id = organization_identifier
     AND membership.role = actor_role
     AND membership.status = 'active'
    JOIN organizations.organizations organization
      ON organization.id = membership.organization_id
     AND organization.verification_status = 'verified'
    WHERE participant.id = actor_identifier
      AND participant.participant_type = 'human'
      AND participant.verification_status = 'verified'
      AND actor_role = ANY(participant.roles)
      AND actor_role IN ('owner', 'admin', 'verifier', 'researcher', 'community')
  );
$$;

CREATE OR REPLACE FUNCTION evidence.registration_validation_issues(
  evidence_location jsonb,
  project_region_identifier text
)
RETURNS text[]
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT array_remove(ARRAY[
    CASE
      WHEN evidence_location ? 'accuracyMeters'
       AND (evidence_location ->> 'accuracyMeters')::double precision > 100
      THEN 'gps_accuracy_too_weak'
    END,
    CASE
      WHEN evidence_location ? 'regionId'
       AND evidence_location ->> 'regionId' <> project_region_identifier
      THEN 'project_region_mismatch'
    END
  ]::text[], NULL);
$$;

CREATE OR REPLACE FUNCTION evidence.registration_hash(evidence_record evidence.evidence_objects)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-evidence-registration-v1',
    'id', evidence_record.id,
    'projectId', evidence_record.project_id,
    'organizationId', evidence_record.organization_id,
    'projectRootAtSubmission', evidence_record.project_root_at_submission,
    'projectStatusAtSubmission', evidence_record.project_status_at_submission,
    'projectRegionIdAtSubmission', evidence_record.project_region_id_at_submission,
    'projectAuthorityUpdatedAtAtSubmission', audit.iso8601_millis(evidence_record.project_authority_updated_at_at_submission),
    'evidenceType', evidence_record.evidence_type,
    'location', evidence_record.location,
    'timestamp', audit.iso8601_millis(evidence_record.observed_at),
    'createdAt', audit.iso8601_millis(evidence_record.created_at),
    'contributor', evidence_record.contributor_id,
    'contributorRole', evidence_record.contributor_role,
    'media_hash', evidence_record.media_hash,
    'gps_hash', evidence_record.gps_hash,
    'verification_status', evidence_record.verification_status,
    'confidence_score', evidence_record.confidence_score,
    'reviewers', to_jsonb(evidence_record.reviewers),
    'validationIssues', to_jsonb(evidence_record.validation_issues),
    'offline_sync_id', evidence_record.offline_sync_id,
    'device_fingerprint_hash', evidence_record.device_fingerprint_hash,
    'exif_hash', evidence_record.exif_hash,
    'claimBoundary', evidence_record.claim_boundary
  ));
$$;

CREATE OR REPLACE FUNCTION evidence.registration_root(evidence_record evidence.evidence_objects)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-evidence-root-v1',
    'projectRoot', evidence_record.project_root_at_submission,
    'evidenceHash', evidence_record.evidence_hash,
    'mediaHash', evidence_record.media_hash,
    'gpsHash', evidence_record.gps_hash
  ));
$$;

CREATE OR REPLACE FUNCTION evidence.registration_payload_hash(evidence_record evidence.evidence_objects)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'id', evidence_record.id,
    'projectId', evidence_record.project_id,
    'organizationId', evidence_record.organization_id,
    'projectRootAtSubmission', evidence_record.project_root_at_submission,
    'projectStatusAtSubmission', evidence_record.project_status_at_submission,
    'projectRegionIdAtSubmission', evidence_record.project_region_id_at_submission,
    'projectAuthorityUpdatedAtAtSubmission', audit.iso8601_millis(evidence_record.project_authority_updated_at_at_submission),
    'evidenceType', evidence_record.evidence_type,
    'location', evidence_record.location,
    'timestamp', audit.iso8601_millis(evidence_record.observed_at),
    'createdAt', audit.iso8601_millis(evidence_record.created_at),
    'contributor', evidence_record.contributor_id,
    'contributorRole', evidence_record.contributor_role,
    'media_hash', evidence_record.media_hash,
    'gps_hash', evidence_record.gps_hash,
    'verification_status', evidence_record.verification_status,
    'confidence_score', evidence_record.confidence_score,
    'reviewers', to_jsonb(evidence_record.reviewers),
    'validationIssues', to_jsonb(evidence_record.validation_issues),
    'offline_sync_id', evidence_record.offline_sync_id,
    'device_fingerprint_hash', evidence_record.device_fingerprint_hash,
    'exif_hash', evidence_record.exif_hash,
    'evidenceHash', evidence_record.evidence_hash,
    'evidenceRoot', evidence_record.evidence_root,
    'claimBoundary', evidence_record.claim_boundary
  ));
$$;

CREATE OR REPLACE FUNCTION evidence.validate_registration_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  project_registration projects.projects%ROWTYPE;
  project_authority record;
  expected_issues text[];
  expected_status text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.contributor_id THEN
    RAISE EXCEPTION 'evidence registration requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM pg_advisory_xact_lock_shared(hashtextextended('domain-event:' || NEW.project_id, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-media:' || NEW.media_hash, 0));
  SELECT * INTO STRICT project_registration FROM projects.projects WHERE id = NEW.project_id;
  SELECT * INTO STRICT project_authority FROM projects.current_authority(NEW.project_id);

  IF project_authority.status = 'archived' THEN
    RAISE EXCEPTION 'archived project cannot accept evidence registration' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.organization_id IS NULL
     OR NEW.project_root_at_submission IS NULL
     OR NEW.project_status_at_submission IS NULL
     OR NEW.project_region_id_at_submission IS NULL
     OR NEW.project_authority_updated_at_at_submission IS NULL
     OR NEW.contributor_role IS NULL
     OR NEW.evidence_hash IS NULL
     OR NEW.evidence_root IS NULL
     OR NEW.audit_event_root IS NULL
     OR NEW.audit_history IS NULL
     OR NEW.claim_boundary IS NULL THEN
    RAISE EXCEPTION 'evidence registration authority fields are required' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.organization_id <> project_registration.organization_id
     OR NEW.project_region_id_at_submission <> project_registration.region_id
     OR NEW.project_status_at_submission <> project_authority.status
     OR NEW.project_root_at_submission <> project_authority.project_root
     OR NEW.project_authority_updated_at_at_submission <> project_authority.updated_at THEN
    RAISE EXCEPTION 'evidence registration does not bind current project authority' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT evidence.actor_has_registration_role(NEW.contributor_id, NEW.organization_id, NEW.contributor_role) THEN
    RAISE EXCEPTION 'evidence registration requires a verified human with an exact active project organization role' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.observed_at <> date_trunc('milliseconds', NEW.observed_at)
     OR NEW.created_at <> date_trunc('milliseconds', NEW.created_at)
     OR NEW.project_authority_updated_at_at_submission <> date_trunc('milliseconds', NEW.project_authority_updated_at_at_submission)
     OR NEW.observed_at > NEW.created_at
     OR NEW.created_at < NEW.project_authority_updated_at_at_submission THEN
    RAISE EXCEPTION 'evidence registration timestamps must be ordered at UTC millisecond precision' USING ERRCODE = 'check_violation';
  END IF;
  IF length(btrim(NEW.id)) NOT BETWEEN 1 AND 240
     OR length(btrim(NEW.project_region_id_at_submission)) NOT BETWEEN 1 AND 160
     OR (NEW.offline_sync_id IS NOT NULL AND length(btrim(NEW.offline_sync_id)) NOT BETWEEN 1 AND 240) THEN
    RAISE EXCEPTION 'evidence registration text fields are outside bounded limits' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.media_hash !~ '^[0-9a-f]{64}$'
     OR NEW.gps_hash !~ '^[0-9a-f]{64}$'
     OR (NEW.device_fingerprint_hash IS NOT NULL AND NEW.device_fingerprint_hash !~ '^[0-9a-f]{64}$')
     OR (NEW.exif_hash IS NOT NULL AND NEW.exif_hash !~ '^[0-9a-f]{64}$') THEN
    RAISE EXCEPTION 'evidence registration commitments are not canonical SHA-256 values' USING ERRCODE = 'check_violation';
  END IF;
  IF jsonb_typeof(NEW.location) <> 'object'
     OR jsonb_typeof(NEW.location -> 'latitude') <> 'number'
     OR jsonb_typeof(NEW.location -> 'longitude') <> 'number'
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(NEW.location) key_name
       WHERE key_name <> ALL(ARRAY['latitude', 'longitude', 'accuracyMeters', 'regionId']::text[])
     )
     OR (NEW.location ->> 'latitude')::double precision NOT BETWEEN -90 AND 90
     OR (NEW.location ->> 'longitude')::double precision NOT BETWEEN -180 AND 180
     OR (
       NEW.location ? 'accuracyMeters'
       AND (
         jsonb_typeof(NEW.location -> 'accuracyMeters') <> 'number'
         OR (NEW.location ->> 'accuracyMeters')::double precision NOT BETWEEN 0 AND 100000
       )
     )
     OR (
       NEW.location ? 'regionId'
       AND (
         jsonb_typeof(NEW.location -> 'regionId') <> 'string'
         OR length(btrim(NEW.location ->> 'regionId')) NOT BETWEEN 1 AND 160
       )
     ) THEN
    RAISE EXCEPTION 'evidence registration location is not canonical' USING ERRCODE = 'check_violation';
  END IF;

  expected_issues := evidence.registration_validation_issues(NEW.location, project_registration.region_id);
  expected_status := CASE WHEN cardinality(expected_issues) = 0 THEN 'validated' ELSE 'challenged' END;
  IF NEW.validation_issues IS DISTINCT FROM expected_issues
     OR NEW.verification_status <> expected_status
     OR cardinality(NEW.reviewers) <> 0
     OR (expected_status = 'challenged' AND NEW.confidence_score > 25) THEN
    RAISE EXCEPTION 'evidence registration structural validation projection is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  IF projects.contains_unsafe_claim(ARRAY[
    NEW.id,
    NEW.project_id,
    NEW.organization_id,
    NEW.project_region_id_at_submission,
    NEW.contributor_id,
    COALESCE(NEW.offline_sync_id, ''),
    COALESCE(NEW.location ->> 'regionId', '')
  ]) THEN
    RAISE EXCEPTION 'evidence registration contains an unsupported public claim or secret material' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.claim_boundary IS DISTINCT FROM evidence.registration_claim_boundary() THEN
    RAISE EXCEPTION 'evidence registration claim boundary is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.evidence_hash IS DISTINCT FROM evidence.registration_hash(NEW)
     OR NEW.evidence_root IS DISTINCT FROM evidence.registration_root(NEW) THEN
    RAISE EXCEPTION 'evidence registration hash lineage is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM evidence.evidence_objects existing
    WHERE existing.media_hash = NEW.media_hash AND existing.id <> NEW.id
  ) THEN
    RAISE EXCEPTION 'evidence registration media commitment is already registered' USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
EXCEPTION
  WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
    RAISE EXCEPTION 'evidence registration requires one current project authority' USING ERRCODE = 'check_violation';
END;
$$;

CREATE OR REPLACE FUNCTION evidence.validate_registration_event_binding()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  event_record audit.domain_events%ROWTYPE;
  expected_action text;
  expected_rationale text;
  expected_audit_history jsonb;
BEGIN
  expected_action := CASE WHEN NEW.verification_status = 'challenged' THEN 'CHALLENGE' ELSE 'ASSERT' END;
  expected_rationale := CASE
    WHEN NEW.verification_status = 'challenged'
      THEN 'Evidence envelope retained in challenged state after deterministic structural validation.'
    ELSE 'Evidence envelope accepted as structurally valid and remains pending AI and accountable human review.'
  END;

  SELECT * INTO STRICT event_record
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root;

  IF event_record.stream_id <> NEW.id
     OR event_record.sequence_no <> 1
     OR event_record.action <> expected_action
     OR event_record.actor_id <> NEW.contributor_id
     OR event_record.entity_type <> 'evidence'
     OR event_record.entity_id <> NEW.id
     OR event_record.created_at <> NEW.created_at
     OR event_record.rationale <> expected_rationale
     OR event_record.payload_hash <> evidence.registration_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence registration requires an exact semantic event binding' USING ERRCODE = 'check_violation';
  END IF;

  expected_audit_history := jsonb_build_array(jsonb_build_object(
    'id', event_record.id,
    'action', event_record.action,
    'actor', event_record.actor_id,
    'entityType', event_record.entity_type,
    'entityId', event_record.entity_id,
    'previousRoot', event_record.previous_root,
    'payloadHash', event_record.payload_hash,
    'eventRoot', event_record.event_root,
    'createdAt', audit.iso8601_millis(event_record.created_at),
    'rationale', event_record.rationale
  ));
  IF NEW.audit_history IS DISTINCT FROM expected_audit_history THEN
    RAISE EXCEPTION 'evidence registration audit history is not the singular bound semantic event' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
EXCEPTION
  WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
    RAISE EXCEPTION 'evidence registration requires an exact semantic event binding' USING ERRCODE = 'check_violation';
END;
$$;

DROP TRIGGER IF EXISTS evidence_registration_event_binding ON evidence.evidence_objects;
CREATE TRIGGER evidence_registration_event_binding
BEFORE INSERT ON evidence.evidence_objects
FOR EACH ROW EXECUTE FUNCTION evidence.validate_registration_event_binding();

DROP TRIGGER IF EXISTS evidence_registration_validate ON evidence.evidence_objects;
CREATE TRIGGER evidence_registration_validate
BEFORE INSERT ON evidence.evidence_objects
FOR EACH ROW EXECUTE FUNCTION evidence.validate_registration_insert();

CREATE OR REPLACE FUNCTION organizations.validate_data_sharing_semantic_event_binding()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  row_document jsonb;
  expected_actor_id text;
  expected_entity_type text;
  expected_created_at timestamptz;
BEGIN
  row_document := to_jsonb(NEW);
  IF TG_TABLE_NAME = 'data_sharing_agreements' THEN
    expected_actor_id := row_document ->> 'created_by';
    expected_entity_type := 'data_sharing_agreement';
    expected_created_at := (row_document ->> 'created_at')::timestamptz;
  ELSIF TG_TABLE_NAME = 'data_sharing_agreement_revocations' THEN
    expected_actor_id := row_document ->> 'revoked_by';
    expected_entity_type := 'data_sharing_agreement_revocation';
    expected_created_at := (row_document ->> 'revoked_at')::timestamptz;
  ELSIF TG_TABLE_NAME = 'data_sharing_agreement_supersessions' THEN
    expected_actor_id := row_document ->> 'superseded_by';
    expected_entity_type := 'data_sharing_agreement_supersession';
    expected_created_at := (row_document ->> 'superseded_at')::timestamptz;
  ELSE
    RAISE EXCEPTION 'unsupported data-sharing semantic event source table' USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM audit.domain_events event
    WHERE event.event_root = NEW.audit_event_root
      AND event.stream_id = NEW.organization_id
      AND event.actor_id = expected_actor_id
      AND event.entity_type = expected_entity_type
      AND event.entity_id = NEW.id
      AND event.created_at = expected_created_at
  ) THEN
    RAISE EXCEPTION 'data-sharing source row requires an exact semantic event binding' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

