CREATE OR REPLACE FUNCTION organizations.validate_data_access_semantic_event_binding()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  row_document jsonb;
  expected_actor_id text;
  expected_entity_type text;
  expected_entity_id text;
  expected_created_at timestamptz;
  expected_action text;
BEGIN
  row_document := to_jsonb(NEW);
  IF TG_TABLE_NAME = 'data_access_requests' THEN
    expected_actor_id := row_document ->> 'requested_by';
    expected_entity_type := 'data_access_request';
    expected_entity_id := row_document ->> 'id';
    expected_created_at := (row_document ->> 'requested_at')::timestamptz;
  ELSIF TG_TABLE_NAME = 'data_access_request_decisions' THEN
    expected_actor_id := row_document ->> 'decision_by';
    expected_entity_type := 'data_access_request_decision';
    expected_entity_id := row_document ->> 'id';
    expected_created_at := (row_document ->> 'decided_at')::timestamptz;
  ELSIF TG_TABLE_NAME = 'data_access_delivery_receipts' THEN
    expected_actor_id := row_document ->> 'delivered_by';
    expected_entity_type := 'data_access_delivery_receipt';
    expected_entity_id := row_document ->> 'id';
    expected_created_at := (row_document ->> 'delivered_at')::timestamptz;
  ELSIF TG_TABLE_NAME = 'data_use_attestations' THEN
    expected_actor_id := row_document ->> 'attested_by';
    expected_entity_type := 'data_use_attestation';
    expected_entity_id := row_document ->> 'id';
    expected_created_at := (row_document ->> 'attested_at')::timestamptz;
    expected_action := CASE row_document ->> 'usage_state'
      WHEN 'within_scope' THEN 'ASSERT'
      WHEN 'no_use' THEN 'ASSERT'
      ELSE 'CHALLENGE'
    END;
  ELSIF TG_TABLE_NAME = 'data_use_enforcement_cases' THEN
    expected_actor_id := row_document ->> 'reviewer_id';
    expected_entity_type := 'data_use_enforcement_case';
    expected_entity_id := row_document ->> 'id';
    expected_created_at := (row_document ->> 'reviewed_at')::timestamptz;
    expected_action := CASE
      WHEN row_document ->> 'case_state' IN ('resolved', 'rejected') THEN 'FULFILL'
      ELSE 'CHALLENGE'
    END;
  ELSIF TG_TABLE_NAME = 'data_access_restrictions' THEN
    expected_actor_id := row_document ->> 'decided_by';
    expected_entity_type := 'data_access_restriction';
    expected_entity_id := row_document ->> 'id';
    expected_created_at := (row_document ->> 'decided_at')::timestamptz;
    expected_action := CASE
      WHEN row_document ->> 'restriction_state' = 'restored' THEN 'FULFILL'
      ELSE 'CHALLENGE'
    END;
  ELSIF TG_TABLE_NAME = 'data_access_accountability_packets' THEN
    expected_actor_id := row_document ->> 'generated_by';
    expected_entity_type := 'data_access_accountability_packet';
    expected_entity_id := row_document ->> 'id';
    expected_created_at := (row_document ->> 'generated_at')::timestamptz;
    expected_action := 'ASSERT';
  ELSIF TG_TABLE_NAME = 'data_access_accountability_verifications' THEN
    expected_actor_id := row_document ->> 'verified_by';
    expected_entity_type := 'data_access_accountability_verification';
    expected_entity_id := row_document ->> 'id';
    expected_created_at := (row_document ->> 'verified_at')::timestamptz;
    expected_action := CASE WHEN (row_document ->> 'valid')::boolean THEN 'ASSERT' ELSE 'CHALLENGE' END;
  ELSIF TG_TABLE_NAME = 'data_access_accountability_disclosures' THEN
    expected_actor_id := row_document ->> 'published_by';
    expected_entity_type := 'data_access_accountability_disclosure';
    expected_entity_id := row_document ->> 'id';
    expected_created_at := (row_document ->> 'published_at')::timestamptz;
    expected_action := 'FULFILL';
  ELSIF TG_TABLE_NAME = 'data_access_accountability_disclosure_challenges' THEN
    expected_actor_id := row_document ->> 'challenged_by';
    expected_entity_type := 'data_access_accountability_disclosure_challenge';
    expected_entity_id := row_document ->> 'id';
    expected_created_at := (row_document ->> 'challenged_at')::timestamptz;
    expected_action := 'CHALLENGE';
  ELSIF TG_TABLE_NAME = 'data_access_accountability_disclosure_resolutions' THEN
    expected_actor_id := row_document ->> 'reviewed_by';
    expected_entity_type := 'data_access_accountability_disclosure_resolution';
    expected_entity_id := row_document ->> 'id';
    expected_created_at := (row_document ->> 'reviewed_at')::timestamptz;
    expected_action := CASE row_document ->> 'decision'
      WHEN 'dismissed' THEN 'ASSERT'
      WHEN 'upheld' THEN 'FULFILL'
      ELSE 'REASON'
    END;
  ELSIF TG_TABLE_NAME = 'data_access_accountability_disclosure_notices' THEN
    expected_actor_id := row_document ->> 'published_by';
    expected_entity_type := 'data_access_accountability_disclosure_notice';
    expected_entity_id := row_document ->> 'id';
    expected_created_at := (row_document ->> 'published_at')::timestamptz;
    expected_action := 'FULFILL';
  ELSE
    RAISE EXCEPTION 'unsupported data access semantic event source table' USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM audit.domain_events event
    WHERE event.event_root = NEW.audit_event_root
      AND event.stream_id = NEW.organization_id
      AND event.actor_id = expected_actor_id
      AND event.entity_type = expected_entity_type
      AND event.entity_id = expected_entity_id
      AND event.created_at = expected_created_at
      AND (expected_action IS NULL OR event.action = expected_action)
  ) THEN
    RAISE EXCEPTION 'data access source row requires an exact semantic event binding' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_access_request_decision_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  request_record organizations.data_access_requests%ROWTYPE;
  agreement_record organizations.data_sharing_agreements%ROWTYPE;
  organization_record organizations.organizations%ROWTYPE;
  current_status text := 'pending';
  prior_decided_at timestamptz;
  effective_expiry timestamptz;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.decision_by THEN
    RAISE EXCEPTION 'data access decision insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO request_record
  FROM organizations.data_access_requests
  WHERE id = NEW.request_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data access decision request does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF request_record.status <> 'pending' OR request_record.decision_by IS NOT NULL OR request_record.decided_at IS NOT NULL THEN
    RAISE EXCEPTION 'data access decision requires an immutable pending request source row' USING ERRCODE = 'check_violation';
  END IF;
  IF request_record.organization_id <> NEW.organization_id OR request_record.agreement_id <> NEW.agreement_id THEN
    RAISE EXCEPTION 'data access decision request authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF request_record.requested_by = NEW.decision_by THEN
    RAISE EXCEPTION 'data access decision actor must be independent from the requester' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.decided_at < request_record.requested_at THEN
    RAISE EXCEPTION 'data access decision cannot predate its request' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO organization_record
  FROM organizations.organizations
  WHERE id = NEW.organization_id
  FOR UPDATE;
  IF NOT FOUND OR organization_record.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'data access decision requires a verified organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.organization_id
      AND membership.actor_id = NEW.decision_by
      AND membership.status = 'active'
      AND membership.role IN ('owner', 'admin', 'verifier')
  ) THEN
    RAISE EXCEPTION 'data access decision actor lacks an active decision membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT decision.status, decision.decided_at
  INTO current_status, prior_decided_at
  FROM organizations.data_access_request_decisions decision
  JOIN audit.domain_events event ON event.event_root = decision.audit_event_root
  WHERE decision.request_id = NEW.request_id
  ORDER BY event.sequence_no DESC
  LIMIT 1;
  current_status := COALESCE(current_status, 'pending');
  IF NEW.previous_status <> current_status THEN
    RAISE EXCEPTION 'data access decision predecessor does not match current state' USING ERRCODE = 'check_violation';
  END IF;
  IF prior_decided_at IS NOT NULL AND NEW.decided_at < prior_decided_at THEN
    RAISE EXCEPTION 'data access decision timestamp cannot move backwards' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO agreement_record
  FROM organizations.data_sharing_agreements
  WHERE id = NEW.agreement_id
  FOR UPDATE;
  IF NOT FOUND OR agreement_record.organization_id <> NEW.organization_id THEN
    RAISE EXCEPTION 'data access decision agreement authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'approved' THEN
    IF agreement_record.revoked OR EXISTS (
      SELECT 1 FROM organizations.data_sharing_agreement_revocations revocation
      WHERE revocation.agreement_id = NEW.agreement_id
    ) OR EXISTS (
      SELECT 1 FROM organizations.data_sharing_agreement_supersessions supersession
      WHERE supersession.predecessor_agreement_id = NEW.agreement_id
    ) THEN
      RAISE EXCEPTION 'data access approval requires an active agreement' USING ERRCODE = 'check_violation';
    END IF;
    IF agreement_record.expires_at IS NOT NULL AND NEW.decided_at >= agreement_record.expires_at THEN
      RAISE EXCEPTION 'data access approval cannot use an expired agreement' USING ERRCODE = 'check_violation';
    END IF;
    IF request_record.expires_at IS NOT NULL AND NEW.decided_at >= request_record.expires_at THEN
      RAISE EXCEPTION 'data access approval cannot approve an expired request' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.status = 'expired' THEN
    effective_expiry := CASE
      WHEN request_record.expires_at IS NULL THEN agreement_record.expires_at
      WHEN agreement_record.expires_at IS NULL THEN request_record.expires_at
      ELSE LEAST(request_record.expires_at, agreement_record.expires_at)
    END;
    IF effective_expiry IS NULL OR NEW.decided_at < effective_expiry THEN
      RAISE EXCEPTION 'data access expiration requires a reached validity boundary' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

