CREATE TABLE IF NOT EXISTS audit.event_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  event_version text NOT NULL DEFAULT 'canopyproof_db_audit_v2' CHECK (event_version = 'canopyproof_db_audit_v2'),
  stream_key text NOT NULL,
  schema_name text NOT NULL,
  table_name text NOT NULL,
  row_pk_hash text NOT NULL,
  sequence_no bigint NOT NULL CHECK (sequence_no > 0),
  action text NOT NULL CHECK (action IN ('INSERT', 'UPDATE', 'DELETE')),
  actor_id text NOT NULL CHECK (length(btrim(actor_id)) > 0),
  recorded_at_unix_micros bigint NOT NULL CHECK (recorded_at_unix_micros > 0),
  previous_event_hash text NOT NULL,
  before_state_hash text NOT NULL,
  after_state_hash text NOT NULL,
  event_hash text NOT NULL,
  created_at timestamptz NOT NULL,
  UNIQUE (stream_key, sequence_no),
  UNIQUE (stream_key, event_hash),
  CHECK (stream_key = schema_name || '.' || table_name || ':' || row_pk_hash),
  CHECK (row_pk_hash ~ '^[0-9a-f]{64}$'),
  CHECK (previous_event_hash ~ '^[0-9a-f]{64}$'),
  CHECK (before_state_hash ~ '^[0-9a-f]{64}$'),
  CHECK (after_state_hash ~ '^[0-9a-f]{64}$'),
  CHECK (event_hash ~ '^[0-9a-f]{64}$'),
  CHECK (floor(extract(epoch FROM created_at) * 1000000)::bigint = recorded_at_unix_micros),
  CHECK (
    event_hash = audit.compute_event_log_hash(
      event_version,
      stream_key,
      schema_name,
      table_name,
      row_pk_hash,
      sequence_no,
      action,
      actor_id,
      recorded_at_unix_micros,
      previous_event_hash,
      before_state_hash,
      after_state_hash
    )
  )
);

CREATE INDEX IF NOT EXISTS audit_event_log_stream_page
ON audit.event_log (stream_key, sequence_no DESC);

CREATE INDEX IF NOT EXISTS audit_event_log_actor_time
ON audit.event_log (actor_id, recorded_at_unix_micros DESC);

CREATE OR REPLACE FUNCTION audit.validate_event_log_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  prior_hash text;
  prior_recorded_at_unix_micros bigint;
  genesis_hash text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.actor_id THEN
    RAISE EXCEPTION 'audit event insert requires matching app.actor_id transaction context' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.stream_key, 0));
  genesis_hash := encode(digest('canopyproof-db-audit-genesis-v2', 'sha256'), 'hex');

  IF NEW.sequence_no = 1 THEN
    IF NEW.previous_event_hash <> genesis_hash THEN
      RAISE EXCEPTION 'audit event sequence one must link to v2 genesis' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    SELECT event_hash, recorded_at_unix_micros
    INTO prior_hash, prior_recorded_at_unix_micros
    FROM audit.event_log
    WHERE stream_key = NEW.stream_key AND sequence_no = NEW.sequence_no - 1
    FOR UPDATE;

    IF prior_hash IS NULL OR NEW.previous_event_hash <> prior_hash THEN
      RAISE EXCEPTION 'audit event predecessor is missing or mismatched' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.recorded_at_unix_micros <= prior_recorded_at_unix_micros THEN
      RAISE EXCEPTION 'audit event timestamp must increase with sequence' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS audit_event_log_validate_insert ON audit.event_log;
CREATE TRIGGER audit_event_log_validate_insert
BEFORE INSERT ON audit.event_log
FOR EACH ROW EXECUTE FUNCTION audit.validate_event_log_insert();

CREATE TABLE IF NOT EXISTS audit.event_log_checkpoints (
  id text PRIMARY KEY,
  checkpoint_version text NOT NULL DEFAULT 'canopyproof_db_audit_checkpoint_v1'
    CHECK (checkpoint_version = 'canopyproof_db_audit_checkpoint_v1'),
  stream_key text NOT NULL,
  first_sequence_no bigint NOT NULL DEFAULT 1 CHECK (first_sequence_no = 1),
  last_sequence_no bigint NOT NULL CHECK (last_sequence_no >= first_sequence_no),
  event_count integer NOT NULL CHECK (event_count > 0),
  first_event_hash text NOT NULL,
  terminal_event_hash text NOT NULL,
  event_root text NOT NULL,
  created_by text NOT NULL CHECK (length(btrim(created_by)) > 0),
  created_at_unix_micros bigint NOT NULL CHECK (created_at_unix_micros > 0),
  checkpoint_hash text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL,
  UNIQUE (stream_key, last_sequence_no),
  CHECK (event_count = last_sequence_no),
  CHECK (first_event_hash ~ '^[0-9a-f]{64}$'),
  CHECK (terminal_event_hash ~ '^[0-9a-f]{64}$'),
  CHECK (event_root ~ '^[0-9a-f]{64}$'),
  CHECK (checkpoint_hash ~ '^[0-9a-f]{64}$'),
  CHECK (floor(extract(epoch FROM created_at) * 1000000)::bigint = created_at_unix_micros)
);

CREATE INDEX IF NOT EXISTS audit_event_log_checkpoints_stream_page
ON audit.event_log_checkpoints (stream_key, last_sequence_no DESC);

CREATE OR REPLACE FUNCTION audit.compute_event_log_checkpoint_hash(
  checkpoint_version text,
  stream_key text,
  first_sequence_no bigint,
  last_sequence_no bigint,
  event_count integer,
  first_event_hash text,
  terminal_event_hash text,
  event_root text,
  created_by text,
  created_at_unix_micros bigint
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      audit.length_prefix(checkpoint_version) ||
      audit.length_prefix(stream_key) ||
      audit.length_prefix(first_sequence_no::text) ||
      audit.length_prefix(last_sequence_no::text) ||
      audit.length_prefix(event_count::text) ||
      audit.length_prefix(first_event_hash) ||
      audit.length_prefix(terminal_event_hash) ||
      audit.length_prefix(event_root) ||
      audit.length_prefix(created_by) ||
      audit.length_prefix(created_at_unix_micros::text),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION audit.validate_event_log_checkpoint_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  first_sequence bigint;
  last_sequence bigint;
  total_events bigint;
  first_hash text;
  terminal_hash text;
  aggregate_root text;
  expected_checkpoint_hash text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.created_by THEN
    RAISE EXCEPTION 'audit checkpoint insert requires matching app.actor_id transaction context' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.stream_key, 0));
  SELECT
    min(sequence_no),
    max(sequence_no),
    count(*),
    encode(digest(string_agg(event_hash, '' ORDER BY sequence_no), 'sha256'), 'hex')
  INTO first_sequence, last_sequence, total_events, aggregate_root
  FROM audit.event_log
  WHERE stream_key = NEW.stream_key AND sequence_no <= NEW.last_sequence_no;

  SELECT event_hash INTO first_hash
  FROM audit.event_log
  WHERE stream_key = NEW.stream_key AND sequence_no = 1;

  SELECT event_hash INTO terminal_hash
  FROM audit.event_log
  WHERE stream_key = NEW.stream_key AND sequence_no = NEW.last_sequence_no
  FOR UPDATE;

  IF
    total_events = 0 OR
    first_sequence <> 1 OR
    last_sequence <> NEW.last_sequence_no OR
    total_events <> NEW.event_count OR
    first_hash <> NEW.first_event_hash OR
    terminal_hash <> NEW.terminal_event_hash OR
    aggregate_root <> NEW.event_root
  THEN
    RAISE EXCEPTION 'audit checkpoint does not cover a complete contiguous stream' USING ERRCODE = 'check_violation';
  END IF;

  expected_checkpoint_hash := audit.compute_event_log_checkpoint_hash(
    NEW.checkpoint_version,
    NEW.stream_key,
    NEW.first_sequence_no,
    NEW.last_sequence_no,
    NEW.event_count,
    NEW.first_event_hash,
    NEW.terminal_event_hash,
    NEW.event_root,
    NEW.created_by,
    NEW.created_at_unix_micros
  );
  IF NEW.checkpoint_hash <> expected_checkpoint_hash THEN
    RAISE EXCEPTION 'audit checkpoint hash mismatch' USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS audit_event_log_checkpoints_validate_insert ON audit.event_log_checkpoints;
CREATE TRIGGER audit_event_log_checkpoints_validate_insert
BEFORE INSERT ON audit.event_log_checkpoints
FOR EACH ROW EXECUTE FUNCTION audit.validate_event_log_checkpoint_insert();

CREATE OR REPLACE FUNCTION audit.create_event_log_checkpoint(target_stream_key text, checkpoint_actor_id text)
RETURNS audit.event_log_checkpoints
LANGUAGE plpgsql
AS $$
DECLARE
  checkpoint audit.event_log_checkpoints%ROWTYPE;
  first_sequence bigint;
  last_sequence bigint;
  total_events bigint;
  first_hash text;
  terminal_hash text;
  aggregate_root text;
  checkpoint_micros bigint;
  computed_checkpoint_hash text;
  checkpoint_id text;
BEGIN
  IF length(btrim(target_stream_key)) = 0 OR length(btrim(checkpoint_actor_id)) = 0 THEN
    RAISE EXCEPTION 'audit checkpoint requires stream key and accountable actor' USING ERRCODE = 'check_violation';
  END IF;
  IF NULLIF(btrim(current_setting('app.actor_id', true)), '') IS DISTINCT FROM checkpoint_actor_id THEN
    RAISE EXCEPTION 'audit checkpoint actor must match app.actor_id transaction context' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(target_stream_key, 0));

  SELECT
    min(sequence_no),
    max(sequence_no),
    count(*),
    encode(digest(string_agg(event_hash, '' ORDER BY sequence_no), 'sha256'), 'hex')
  INTO first_sequence, last_sequence, total_events, aggregate_root
  FROM audit.event_log
  WHERE stream_key = target_stream_key;

  IF total_events = 0 OR first_sequence <> 1 OR total_events <> last_sequence THEN
    RAISE EXCEPTION 'audit checkpoint requires a non-empty contiguous stream from sequence one' USING ERRCODE = 'check_violation';
  END IF;

  SELECT event_hash INTO STRICT first_hash
  FROM audit.event_log
  WHERE stream_key = target_stream_key AND sequence_no = first_sequence;

  SELECT event_hash INTO STRICT terminal_hash
  FROM audit.event_log
  WHERE stream_key = target_stream_key AND sequence_no = last_sequence
  FOR UPDATE;

  checkpoint_micros := floor(extract(epoch FROM clock_timestamp()) * 1000000)::bigint;
  computed_checkpoint_hash := audit.compute_event_log_checkpoint_hash(
    'canopyproof_db_audit_checkpoint_v1',
    target_stream_key,
    first_sequence,
    last_sequence,
    total_events::integer,
    first_hash,
    terminal_hash,
    aggregate_root,
    checkpoint_actor_id,
    checkpoint_micros
  );
  checkpoint_id := 'cp_db_audit_checkpoint_' || substr(computed_checkpoint_hash, 1, 24);

  INSERT INTO audit.event_log_checkpoints (
    id,
    checkpoint_version,
    stream_key,
    first_sequence_no,
    last_sequence_no,
    event_count,
    first_event_hash,
    terminal_event_hash,
    event_root,
    created_by,
    created_at_unix_micros,
    checkpoint_hash,
    created_at
  )
  VALUES (
    checkpoint_id,
    'canopyproof_db_audit_checkpoint_v1',
    target_stream_key,
    first_sequence,
    last_sequence,
    total_events::integer,
    first_hash,
    terminal_hash,
    aggregate_root,
    checkpoint_actor_id,
    checkpoint_micros,
    computed_checkpoint_hash,
    to_timestamp(checkpoint_micros::numeric / 1000000)
  )
  ON CONFLICT (stream_key, last_sequence_no) DO NOTHING
  RETURNING * INTO checkpoint;

  IF checkpoint.id IS NULL THEN
    SELECT * INTO STRICT checkpoint
    FROM audit.event_log_checkpoints
    WHERE stream_key = target_stream_key AND last_sequence_no = last_sequence;
  END IF;

  RETURN checkpoint;
END;
$$;

CREATE TABLE IF NOT EXISTS audit.agent_events (
  id text PRIMARY KEY,
  agent_id text NOT NULL REFERENCES identity.agent_profiles(id),
  actor_id text NOT NULL REFERENCES identity.participants(id),
  action text NOT NULL CHECK (action IN ('ASSERT', 'REASON', 'DELEGATE', 'FULFILL', 'CHALLENGE')),
  subject_type text NOT NULL,
  subject_id text NOT NULL,
  payload_hash text NOT NULL,
  source_root text NOT NULL,
  confidence_score integer NOT NULL CHECK (confidence_score >= 0 AND confidence_score <= 100),
  human_review_required boolean NOT NULL,
  final_authority boolean NOT NULL DEFAULT false CHECK (final_authority IS false),
  event_root text NOT NULL,
  created_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS audit.memory_records (
  id text PRIMARY KEY,
  subject_type text NOT NULL CHECK (
    subject_type IN (
      'project',
      'evidence',
      'ai_analysis',
      'human_review',
      'proof_record',
      'certificate',
      'terra_scene',
      'esg_report',
      'organization',
      'funding_allocation',
      'funding_milestone',
      'risk_alert',
      'agent_event',
      'governance_approval',
      'system'
    )
  ),
  subject_id text NOT NULL,
  project_id text REFERENCES projects.projects(id),
  organization_id text REFERENCES organizations.organizations(id),
  scope text NOT NULL CHECK (scope IN ('public', 'institutional', 'restricted')),
  retention_class text NOT NULL CHECK (retention_class IN ('operational', 'institutional', 'research', 'legal_hold')),
  summary text NOT NULL,
  tags text[] NOT NULL DEFAULT ARRAY[]::text[],
  source_ids text[] NOT NULL,
  related_record_ids text[] NOT NULL DEFAULT ARRAY[]::text[],
  payload_hash text NOT NULL,
  source_root text NOT NULL,
  memory_hash text NOT NULL UNIQUE,
  created_by text NOT NULL REFERENCES identity.participants(id),
  created_at timestamptz NOT NULL,
  final_authority boolean NOT NULL DEFAULT false CHECK (final_authority IS false),
  event_root text NOT NULL UNIQUE,
  CHECK (array_length(source_ids, 1) > 0)
);

CREATE TABLE IF NOT EXISTS audit.abuse_signals (
  id text PRIMARY KEY,
  actor_id text NOT NULL,
  route text NOT NULL,
  method text NOT NULL CHECK (method IN ('GET', 'HEAD', 'POST', 'PATCH', 'PUT', 'DELETE', 'OPTIONS')),
  reason text NOT NULL CHECK (reason IN ('rate_limit_exceeded', 'anonymous_mutation', 'unsafe_claim')),
  severity text NOT NULL CHECK (severity IN ('medium', 'high', 'critical')),
  payload_hash text NOT NULL,
  event_root text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS audit.resilience_drills (
  id text PRIMARY KEY,
  dependency text NOT NULL CHECK (dependency IN ('postgresql', 'api_origin', 'object_storage', 'cloudflare_worker')),
  scenario text NOT NULL CHECK (scenario IN ('database_connection_drop', 'audit_append_failed', 'domain_mutation_failed', 'api_origin_unavailable', 'object_storage_unavailable')),
  route text NOT NULL,
  actor_id text NOT NULL,
  idempotency_key text,
  simulation jsonb NOT NULL,
  safety_assertions jsonb NOT NULL,
  decision text NOT NULL CHECK (decision IN ('pass', 'needs_recovery', 'fail_closed_violation')),
  recommended_actions text[] NOT NULL,
  drill_hash text NOT NULL UNIQUE,
  event_root text NOT NULL UNIQUE,
  started_at timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS audit.audit_verifications (
  id text PRIMARY KEY,
  actor_id text NOT NULL REFERENCES identity.participants(id),
  scope text NOT NULL CHECK (scope IN ('evidence', 'proof_record', 'organization', 'funding', 'governance', 'reporting', 'system')),
  subject_id text NOT NULL,
  event_count integer NOT NULL CHECK (event_count > 0),
  first_root text NOT NULL,
  terminal_root text NOT NULL,
  chain_root text NOT NULL UNIQUE,
  valid boolean NOT NULL,
  issue_codes text[] NOT NULL DEFAULT ARRAY[]::text[],
  submitted_event_roots text[] NOT NULL,
  payload_bundle_hash text,
  verifier_version text NOT NULL,
  verified_at timestamptz NOT NULL,
  event_root text NOT NULL UNIQUE,
  CHECK (array_length(submitted_event_roots, 1) = event_count),
  CHECK ((valid IS true AND array_length(issue_codes, 1) IS NULL) OR valid IS false)
);

CREATE TABLE IF NOT EXISTS audit.attestations (
  id text PRIMARY KEY,
  scope text NOT NULL CHECK (scope IN ('evidence', 'proof_record', 'organization', 'funding', 'governance', 'reporting', 'system')),
  subject_id text NOT NULL,
  auditor_organization_id text NOT NULL REFERENCES organizations.organizations(id),
  auditor_name text NOT NULL,
  methods text[] NOT NULL,
  standards text[] NOT NULL,
  source_event_roots text[] NOT NULL,
  source_event_root text NOT NULL,
  audit_verification_root text NOT NULL,
  finding_root text NOT NULL,
  findings jsonb NOT NULL DEFAULT '[]'::jsonb,
  decision text NOT NULL CHECK (decision IN ('attest', 'qualified', 'reject')),
  independence_statement text NOT NULL,
  limitations text[] NOT NULL,
  public_summary text NOT NULL,
  claim_boundary jsonb NOT NULL,
  attestation_hash text NOT NULL UNIQUE,
  event_root text NOT NULL UNIQUE,
  issued_at timestamptz NOT NULL,
  CHECK (array_length(methods, 1) > 0),
  CHECK (array_length(standards, 1) > 0),
  CHECK (array_length(source_event_roots, 1) > 0),
  CHECK (jsonb_typeof(findings) = 'array'),
  CHECK (jsonb_array_length(findings) > 0 OR decision <> 'reject')
);

CREATE OR REPLACE FUNCTION audit.is_valid_export_manifest_entries(entries_to_check jsonb)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT
    jsonb_typeof(entries_to_check) = 'array' AND
    jsonb_array_length(entries_to_check) > 0 AND
    NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(entries_to_check) AS entry
      WHERE
        jsonb_typeof(entry) <> 'object' OR
        EXISTS (
          SELECT 1
          FROM jsonb_object_keys(entry) AS entry_key
          WHERE entry_key NOT IN (
            'id', 'resourceType', 'resourceId', 'contentHash', 'eventRoot',
            'classification', 'redactionPolicy', 'included', 'reason'
          )
        ) OR
        COALESCE(length(btrim(entry ->> 'id')), 0) = 0 OR
        COALESCE(length(btrim(entry ->> 'resourceId')), 0) = 0 OR
        COALESCE(length(btrim(entry ->> 'reason')), 0) < 8 OR
        entry ->> 'resourceType' NOT IN (
          'evidence', 'proof_record', 'public_record', 'audit_attestation',
          'governance_approval', 'terra_scene', 'funding_ledger', 'esg_report',
          'risk_alert', 'memory_record', 'audit_event'
        ) OR
        COALESCE(entry ->> 'contentHash', '') !~ '^[0-9a-f]{64}$' OR
        (entry ? 'eventRoot' AND COALESCE(entry ->> 'eventRoot', '') !~ '^[0-9a-f]{64}$') OR
        entry ->> 'classification' NOT IN ('public', 'internal', 'restricted', 'confidential') OR
        entry ->> 'redactionPolicy' NOT IN (
          'public_safe', 'precise_location_redacted', 'personal_data_redacted', 'confidential_hash_only'
        ) OR
        jsonb_typeof(entry -> 'included') <> 'boolean'
    ) AND
    (
      SELECT count(*) = count(DISTINCT entry ->> 'id')
      FROM jsonb_array_elements(entries_to_check) AS entry
    );
$$;

CREATE TABLE IF NOT EXISTS audit.export_manifests (
  id text PRIMARY KEY,
  manifest_version text NOT NULL DEFAULT 'canopyproof_audit_export_manifest_v1' CHECK (manifest_version = 'canopyproof_audit_export_manifest_v1'),
  manifest_kind text NOT NULL CHECK (manifest_kind IN ('institutional_audit_packet', 'public_transparency_packet', 'regulator_review_packet', 'esg_report_packet')),
  scope text NOT NULL CHECK (scope IN ('evidence', 'proof_record', 'organization', 'funding', 'governance', 'reporting', 'system')),
  subject_id text NOT NULL CONSTRAINT audit_export_manifests_subject_nonempty CHECK (length(btrim(subject_id)) > 0),
  requester_organization_id text NOT NULL REFERENCES organizations.organizations(id),
  requested_by text NOT NULL REFERENCES identity.participants(id),
  purpose text NOT NULL CONSTRAINT audit_export_manifests_purpose_length CHECK (length(btrim(purpose)) >= 12),
  classification text NOT NULL CHECK (classification IN ('public', 'internal', 'restricted', 'confidential')),
  entries jsonb NOT NULL CONSTRAINT audit_export_manifests_entries_shape CHECK (audit.is_valid_export_manifest_entries(entries)),
  entry_root text NOT NULL CONSTRAINT audit_export_manifests_entry_root_shape CHECK (entry_root ~ '^[0-9a-f]{64}$'),
  redaction_root text NOT NULL CONSTRAINT audit_export_manifests_redaction_root_shape CHECK (redaction_root ~ '^[0-9a-f]{64}$'),
  source_event_root text NOT NULL CONSTRAINT audit_export_manifests_source_root_shape CHECK (source_event_root ~ '^[0-9a-f]{64}$'),
  export_hash text NOT NULL UNIQUE CONSTRAINT audit_export_manifests_hash_shape CHECK (export_hash ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CONSTRAINT audit_export_manifests_safety_boundary CHECK (
    safety @> '{
      "hashOnlyManifest": true,
      "rawEvidenceExcluded": true,
      "personalDataRedacted": true,
      "preciseLocationRedactedUnlessAuthorized": true,
      "noFinancialOrCarbonCreditAuthority": true
    }'::jsonb
  ),
  expires_at timestamptz,
  created_at timestamptz NOT NULL,
  event_root text NOT NULL UNIQUE CONSTRAINT audit_export_manifests_event_root_shape CHECK (event_root ~ '^[0-9a-f]{64}$'),
  CONSTRAINT audit_export_manifests_expiry_after_creation CHECK (expires_at IS NULL OR expires_at > created_at)
);

CREATE INDEX IF NOT EXISTS audit_export_manifests_organization_time
  ON audit.export_manifests (requester_organization_id, created_at DESC, id DESC);

CREATE INDEX IF NOT EXISTS audit_export_manifests_subject_time
  ON audit.export_manifests (scope, subject_id, created_at DESC, id DESC);

CREATE INDEX IF NOT EXISTS audit_export_manifests_classification_time
  ON audit.export_manifests (classification, created_at DESC, id DESC);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'audit_export_manifests_subject_nonempty'
      AND conrelid = 'audit.export_manifests'::regclass
  ) THEN
    ALTER TABLE audit.export_manifests
      ADD CONSTRAINT audit_export_manifests_subject_nonempty
      CHECK (length(btrim(subject_id)) > 0) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'audit_export_manifests_purpose_length'
      AND conrelid = 'audit.export_manifests'::regclass
  ) THEN
    ALTER TABLE audit.export_manifests
      ADD CONSTRAINT audit_export_manifests_purpose_length
      CHECK (length(btrim(purpose)) >= 12) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'audit_export_manifests_entries_shape'
      AND conrelid = 'audit.export_manifests'::regclass
  ) THEN
    ALTER TABLE audit.export_manifests
      ADD CONSTRAINT audit_export_manifests_entries_shape
      CHECK (audit.is_valid_export_manifest_entries(entries)) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'audit_export_manifests_entry_root_shape'
      AND conrelid = 'audit.export_manifests'::regclass
  ) THEN
    ALTER TABLE audit.export_manifests
      ADD CONSTRAINT audit_export_manifests_entry_root_shape
      CHECK (entry_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'audit_export_manifests_redaction_root_shape'
      AND conrelid = 'audit.export_manifests'::regclass
  ) THEN
    ALTER TABLE audit.export_manifests
      ADD CONSTRAINT audit_export_manifests_redaction_root_shape
      CHECK (redaction_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'audit_export_manifests_source_root_shape'
      AND conrelid = 'audit.export_manifests'::regclass
  ) THEN
    ALTER TABLE audit.export_manifests
      ADD CONSTRAINT audit_export_manifests_source_root_shape
      CHECK (source_event_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'audit_export_manifests_hash_shape'
      AND conrelid = 'audit.export_manifests'::regclass
  ) THEN
    ALTER TABLE audit.export_manifests
      ADD CONSTRAINT audit_export_manifests_hash_shape
      CHECK (export_hash ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'audit_export_manifests_safety_boundary'
      AND conrelid = 'audit.export_manifests'::regclass
  ) THEN
    ALTER TABLE audit.export_manifests
      ADD CONSTRAINT audit_export_manifests_safety_boundary
      CHECK (
        safety @> '{
          "hashOnlyManifest": true,
          "rawEvidenceExcluded": true,
          "personalDataRedacted": true,
          "preciseLocationRedactedUnlessAuthorized": true,
          "noFinancialOrCarbonCreditAuthority": true
        }'::jsonb
      ) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'audit_export_manifests_event_root_shape'
      AND conrelid = 'audit.export_manifests'::regclass
  ) THEN
    ALTER TABLE audit.export_manifests
      ADD CONSTRAINT audit_export_manifests_event_root_shape
      CHECK (event_root ~ '^[0-9a-f]{64}$') NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'audit_export_manifests_expiry_after_creation'
      AND conrelid = 'audit.export_manifests'::regclass
  ) THEN
    ALTER TABLE audit.export_manifests
      ADD CONSTRAINT audit_export_manifests_expiry_after_creation
      CHECK (expires_at IS NULL OR expires_at > created_at) NOT VALID;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION audit.validate_export_manifest_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  organization_record organizations.organizations%ROWTYPE;
  manifest_classification_rank integer;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.requested_by THEN
    RAISE EXCEPTION 'audit export manifest insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.expires_at IS NOT NULL AND NEW.expires_at <= NEW.created_at THEN
    RAISE EXCEPTION 'audit export manifest expiry must follow creation' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.subject_id ~* '(BEGIN|END)[[:space:]]+(RSA |EC |OPENSSH |PRIVATE )?PRIVATE KEY' OR
    NEW.purpose ~* '(private[_ -]?key|api[_ -]?secret|access[_ -]?secret|password)' OR
    NEW.entries::text ~* '(BEGIN|END)[[:space:]]+(RSA |EC |OPENSSH |PRIVATE )?PRIVATE KEY' OR
    NEW.entries::text ~* '[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}'
  THEN
    RAISE EXCEPTION 'audit export manifest cannot embed private key or secret material' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO organization_record
  FROM organizations.organizations
  WHERE id = NEW.requester_organization_id
  FOR UPDATE;
  IF NOT FOUND OR organization_record.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'audit export manifest requires a verified requester organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.requester_organization_id
      AND membership.actor_id = NEW.requested_by
      AND membership.status = 'active'
      AND membership.role IN ('owner', 'admin', 'verifier', 'researcher')
  ) THEN
    RAISE EXCEPTION 'audit export manifest requester lacks an active organization membership' USING ERRCODE = 'check_violation';
  END IF;

  manifest_classification_rank := CASE NEW.classification
    WHEN 'public' THEN 0 WHEN 'internal' THEN 1 WHEN 'restricted' THEN 2 WHEN 'confidential' THEN 3 ELSE -1
  END;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(NEW.entries) AS entry
    WHERE CASE entry ->> 'classification'
      WHEN 'public' THEN 0 WHEN 'internal' THEN 1 WHEN 'restricted' THEN 2 WHEN 'confidential' THEN 3 ELSE 99
    END > manifest_classification_rank
  ) THEN
    RAISE EXCEPTION 'audit export manifest classification is lower than an entry classification' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(NEW.entries) AS entry
    WHERE entry ->> 'classification' IN ('restricted', 'confidential')
      AND entry ->> 'redactionPolicy' = 'public_safe'
  ) THEN
    RAISE EXCEPTION 'restricted audit export entries require explicit redaction' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.classification = 'public' AND EXISTS (
    SELECT 1
    FROM jsonb_array_elements(NEW.entries) AS entry
    WHERE (entry ->> 'included')::boolean
      AND entry ->> 'redactionPolicy' <> 'public_safe'
  ) THEN
    RAISE EXCEPTION 'public audit export manifests require public-safe included entries' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM audit.domain_events event
    WHERE event.event_root = NEW.event_root
      AND event.stream_id = NEW.requester_organization_id
      AND event.actor_id = NEW.requested_by
      AND event.entity_type = 'audit_export_manifest'
      AND event.entity_id = NEW.id
      AND event.created_at = NEW.created_at
  ) THEN
    RAISE EXCEPTION 'audit export manifest requires an exact semantic event binding' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS audit_export_manifests_validate_insert ON audit.export_manifests;
CREATE TRIGGER audit_export_manifests_validate_insert
BEFORE INSERT ON audit.export_manifests
FOR EACH ROW EXECUTE FUNCTION audit.validate_export_manifest_insert();

CREATE OR REPLACE FUNCTION organizations.data_access_delivery_safety_canonical()
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT '{"agreementBound":true,"approvedRequestBound":true,"humanDecisionRequired":true,"manifestHashOnly":true,"noPrivateContactData":true,"notCarbonCredit":true,"notFinalProofAuthority":true,"notFinancialAsset":true,"notGuaranteedYield":true,"notTaxOffset":true,"rawDataNotEmbedded":true,"redactionPolicyEnforced":true}';
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_delivery_receipt_hash(
  delivery_organization_id text,
  delivery_request_id text,
  delivery_agreement_id text,
  delivery_manifest_id text,
  delivery_manifest_requester_organization_id text,
  delivery_manifest_hash text,
  delivery_manifest_entry_root text,
  delivery_manifest_classification text,
  delivery_channel text,
  delivery_recipient_actor_id text,
  delivery_actor_id text,
  delivery_created_at timestamptz,
  delivery_purpose text,
  delivery_access_root text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"accessRoot":' || to_json(delivery_access_root)::text ||
        ',"agreementId":' || to_json(delivery_agreement_id)::text ||
        ',"channel":' || to_json(delivery_channel)::text ||
        ',"deliveredAt":' || to_json(to_char(delivery_created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"deliveredBy":' || to_json(delivery_actor_id)::text ||
        ',"kind":"canopyproof-data-access-delivery-receipt-v1"' ||
        ',"manifestClassification":' || to_json(delivery_manifest_classification)::text ||
        ',"manifestEntryRoot":' || to_json(delivery_manifest_entry_root)::text ||
        ',"manifestHash":' || to_json(delivery_manifest_hash)::text ||
        ',"manifestId":' || to_json(delivery_manifest_id)::text ||
        ',"manifestRequesterOrganizationId":' || to_json(delivery_manifest_requester_organization_id)::text ||
        ',"organizationId":' || to_json(delivery_organization_id)::text ||
        ',"purpose":' || to_json(delivery_purpose)::text ||
        ',"recipientActorId":' || to_json(delivery_recipient_actor_id)::text ||
        ',"requestId":' || to_json(delivery_request_id)::text ||
        ',"safety":' || organizations.data_access_delivery_safety_canonical() ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_delivery_root(
  delivery_access_root text,
  delivery_manifest_entry_root text,
  delivery_manifest_hash text,
  delivery_receipt_hash text,
  delivery_request_hash text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"accessRoot":' || to_json(delivery_access_root)::text ||
        ',"kind":"canopyproof-data-access-delivery-root-v1"' ||
        ',"manifestEntryRoot":' || to_json(delivery_manifest_entry_root)::text ||
        ',"manifestHash":' || to_json(delivery_manifest_hash)::text ||
        ',"receiptHash":' || to_json(delivery_receipt_hash)::text ||
        ',"requestHash":' || to_json(delivery_request_hash)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_delivery_payload_hash(
  delivery_organization_id text,
  delivery_request_id text,
  delivery_agreement_id text,
  delivery_manifest_id text,
  delivery_manifest_requester_organization_id text,
  delivery_manifest_hash text,
  delivery_manifest_entry_root text,
  delivery_manifest_classification text,
  delivery_channel text,
  delivery_recipient_actor_id text,
  delivery_actor_id text,
  delivery_created_at timestamptz,
  delivery_purpose text,
  delivery_access_root text,
  delivery_receipt_hash text,
  delivery_root_hash text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"accessRoot":' || to_json(delivery_access_root)::text ||
        ',"agreementId":' || to_json(delivery_agreement_id)::text ||
        ',"channel":' || to_json(delivery_channel)::text ||
        ',"deliveredAt":' || to_json(to_char(delivery_created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"deliveredBy":' || to_json(delivery_actor_id)::text ||
        ',"deliveryRoot":' || to_json(delivery_root_hash)::text ||
        ',"manifestClassification":' || to_json(delivery_manifest_classification)::text ||
        ',"manifestEntryRoot":' || to_json(delivery_manifest_entry_root)::text ||
        ',"manifestHash":' || to_json(delivery_manifest_hash)::text ||
        ',"manifestId":' || to_json(delivery_manifest_id)::text ||
        ',"manifestRequesterOrganizationId":' || to_json(delivery_manifest_requester_organization_id)::text ||
        ',"organizationId":' || to_json(delivery_organization_id)::text ||
        ',"purpose":' || to_json(delivery_purpose)::text ||
        ',"receiptHash":' || to_json(delivery_receipt_hash)::text ||
        ',"recipientActorId":' || to_json(delivery_recipient_actor_id)::text ||
        ',"requestId":' || to_json(delivery_request_id)::text ||
        ',"safety":' || organizations.data_access_delivery_safety_canonical() ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_access_delivery_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  organization_record organizations.organizations%ROWTYPE;
  request_record organizations.data_access_requests%ROWTYPE;
  agreement_record organizations.data_sharing_agreements%ROWTYPE;
  manifest_record audit.export_manifests%ROWTYPE;
  recipient_record identity.participants%ROWTYPE;
  current_request_status text := 'pending';
  approval_decided_at timestamptz;
  manifest_classification_rank integer;
  request_privacy_rank integer;
  expected_receipt_hash text;
  expected_delivery_root text;
  expected_payload_hash text;
  bound_payload_hash text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.delivered_by THEN
    RAISE EXCEPTION 'data access delivery insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.delivered_by = NEW.recipient_actor_id THEN
    RAISE EXCEPTION 'data access delivery actor must differ from the recipient' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.purpose ~* '(BEGIN|END)[[:space:]]+(RSA |EC |OPENSSH |PRIVATE )?PRIVATE KEY' OR
    NEW.purpose ~* '(private[_ -]?key|api[_ -]?secret|access[_ -]?secret|password)'
  THEN
    RAISE EXCEPTION 'data access delivery receipt cannot embed private key or secret material' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO organization_record
  FROM organizations.organizations
  WHERE id = NEW.organization_id
  FOR UPDATE;
  IF NOT FOUND OR organization_record.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'data access delivery requires a verified organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.organization_id
      AND membership.actor_id = NEW.delivered_by
      AND membership.status = 'active'
      AND membership.role IN ('owner', 'admin', 'verifier')
  ) THEN
    RAISE EXCEPTION 'data access delivery actor lacks an active delivery membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO recipient_record
  FROM identity.participants
  WHERE id = NEW.recipient_actor_id
  FOR UPDATE;
  IF NOT FOUND OR recipient_record.organization_id IS DISTINCT FROM NEW.organization_id OR recipient_record.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'data access delivery recipient must be a verified participant in the request organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.organization_id
      AND membership.actor_id = NEW.recipient_actor_id
      AND membership.status = 'active'
      AND (
        (NEW.manifest_classification IN ('public', 'internal', 'restricted') AND membership.role IN ('owner', 'admin', 'verifier', 'researcher')) OR
        (NEW.manifest_classification = 'confidential' AND membership.role IN ('owner', 'admin', 'verifier'))
      )
  ) THEN
    RAISE EXCEPTION 'data access delivery recipient lacks an active classification-appropriate membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO request_record
  FROM organizations.data_access_requests
  WHERE id = NEW.request_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data access delivery request does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF
    request_record.organization_id <> NEW.organization_id OR
    request_record.agreement_id <> NEW.agreement_id OR
    request_record.access_root <> NEW.access_root
  THEN
    RAISE EXCEPTION 'data access delivery request authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF request_record.status <> 'pending' OR request_record.decision_by IS NOT NULL OR request_record.decided_at IS NOT NULL THEN
    RAISE EXCEPTION 'data access delivery requires an immutable pending request source row' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.delivered_at < request_record.requested_at THEN
    RAISE EXCEPTION 'data access delivery cannot predate its request' USING ERRCODE = 'check_violation';
  END IF;
  IF request_record.expires_at IS NOT NULL AND NEW.delivered_at >= request_record.expires_at THEN
    RAISE EXCEPTION 'data access delivery cannot use an expired request' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM organizations.data_access_request_decisions decision
    LEFT JOIN audit.domain_events event
      ON event.event_root = decision.audit_event_root
     AND event.stream_id = decision.organization_id
     AND event.actor_id = decision.decision_by
     AND event.entity_type = 'data_access_request_decision'
     AND event.entity_id = decision.id
     AND event.created_at = decision.decided_at
    WHERE decision.request_id = NEW.request_id
      AND event.event_root IS NULL
  ) THEN
    RAISE EXCEPTION 'data access delivery request decision lineage is not fully event-bound' USING ERRCODE = 'check_violation';
  END IF;
  SELECT decision.status, decision.decided_at
  INTO current_request_status, approval_decided_at
  FROM organizations.data_access_request_decisions decision
  JOIN audit.domain_events event ON event.event_root = decision.audit_event_root
  WHERE decision.request_id = NEW.request_id
  ORDER BY event.sequence_no DESC
  LIMIT 1;
  current_request_status := COALESCE(current_request_status, 'pending');
  IF current_request_status <> 'approved' OR approval_decided_at IS NULL THEN
    RAISE EXCEPTION 'data access delivery requires a currently approved request' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.delivered_at < approval_decided_at THEN
    RAISE EXCEPTION 'data access delivery cannot predate request approval' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO agreement_record
  FROM organizations.data_sharing_agreements
  WHERE id = NEW.agreement_id
  FOR UPDATE;
  IF NOT FOUND OR agreement_record.organization_id <> NEW.organization_id THEN
    RAISE EXCEPTION 'data access delivery agreement authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF agreement_record.revoked OR EXISTS (
    SELECT 1 FROM organizations.data_sharing_agreement_revocations revocation
    WHERE revocation.agreement_id = NEW.agreement_id
  ) OR EXISTS (
    SELECT 1 FROM organizations.data_sharing_agreement_supersessions supersession
    WHERE supersession.predecessor_agreement_id = NEW.agreement_id
  ) THEN
    RAISE EXCEPTION 'data access delivery requires an active agreement' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.delivered_at < agreement_record.created_at THEN
    RAISE EXCEPTION 'data access delivery cannot predate its agreement' USING ERRCODE = 'check_violation';
  END IF;
  IF agreement_record.expires_at IS NOT NULL AND NEW.delivered_at >= agreement_record.expires_at THEN
    RAISE EXCEPTION 'data access delivery cannot use an expired agreement' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO manifest_record
  FROM audit.export_manifests
  WHERE id = NEW.manifest_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data access delivery manifest does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF
    manifest_record.requester_organization_id <> NEW.organization_id OR
    NEW.manifest_requester_organization_id <> NEW.organization_id OR
    manifest_record.export_hash <> NEW.manifest_hash OR
    manifest_record.entry_root <> NEW.manifest_entry_root OR
    manifest_record.classification <> NEW.manifest_classification
  THEN
    RAISE EXCEPTION 'data access delivery manifest authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.delivered_at < manifest_record.created_at THEN
    RAISE EXCEPTION 'data access delivery cannot predate its manifest' USING ERRCODE = 'check_violation';
  END IF;
  IF manifest_record.expires_at IS NOT NULL AND NEW.delivered_at >= manifest_record.expires_at THEN
    RAISE EXCEPTION 'data access delivery cannot use an expired manifest' USING ERRCODE = 'check_violation';
  END IF;

  manifest_classification_rank := CASE NEW.manifest_classification
    WHEN 'public' THEN 1 WHEN 'internal' THEN 2 WHEN 'restricted' THEN 2 WHEN 'confidential' THEN 3 ELSE 99
  END;
  request_privacy_rank := CASE request_record.privacy_tier
    WHEN 'public' THEN 1 WHEN 'restricted' THEN 2 WHEN 'confidential' THEN 3 ELSE 0
  END;
  IF manifest_classification_rank > request_privacy_rank THEN
    RAISE EXCEPTION 'data access delivery manifest classification exceeds the approved request privacy tier' USING ERRCODE = 'check_violation';
  END IF;

  expected_receipt_hash := organizations.compute_data_access_delivery_receipt_hash(
    NEW.organization_id,
    NEW.request_id,
    NEW.agreement_id,
    NEW.manifest_id,
    NEW.manifest_requester_organization_id,
    NEW.manifest_hash,
    NEW.manifest_entry_root,
    NEW.manifest_classification,
    NEW.channel,
    NEW.recipient_actor_id,
    NEW.delivered_by,
    NEW.delivered_at,
    NEW.purpose,
    NEW.access_root
  );
  IF NEW.receipt_hash <> expected_receipt_hash OR NEW.id <> 'cp_data_delivery_' || left(expected_receipt_hash, 24) THEN
    RAISE EXCEPTION 'data access delivery receipt hash or identifier is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_delivery_root := organizations.compute_data_access_delivery_root(
    NEW.access_root,
    NEW.manifest_entry_root,
    NEW.manifest_hash,
    NEW.receipt_hash,
    request_record.request_hash
  );
  IF NEW.delivery_root <> expected_delivery_root THEN
    RAISE EXCEPTION 'data access delivery root is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_payload_hash := organizations.compute_data_access_delivery_payload_hash(
    NEW.organization_id,
    NEW.request_id,
    NEW.agreement_id,
    NEW.manifest_id,
    NEW.manifest_requester_organization_id,
    NEW.manifest_hash,
    NEW.manifest_entry_root,
    NEW.manifest_classification,
    NEW.channel,
    NEW.recipient_actor_id,
    NEW.delivered_by,
    NEW.delivered_at,
    NEW.purpose,
    NEW.access_root,
    NEW.receipt_hash,
    NEW.delivery_root
  );
  SELECT event.payload_hash INTO bound_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root;
  IF bound_payload_hash IS DISTINCT FROM expected_payload_hash THEN
    RAISE EXCEPTION 'data access delivery semantic event payload does not match the canonical receipt' USING ERRCODE = 'check_violation';
  END IF;

  IF organizations.data_access_request_is_restricted(NEW.request_id) THEN
    RAISE EXCEPTION 'data access delivery is blocked by the current durable restriction state' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_access_delivery_receipts_validate_insert ON organizations.data_access_delivery_receipts;
CREATE TRIGGER organizations_data_access_delivery_receipts_validate_insert
BEFORE INSERT ON organizations.data_access_delivery_receipts
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_access_delivery_insert();

CREATE OR REPLACE FUNCTION audit.canonical_text_array(values_to_encode text[])
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT array_to_json(values_to_encode)::text;
$$;

CREATE OR REPLACE FUNCTION organizations.data_use_attestation_safety_canonical()
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT '{"approvedRequestBound":true,"deliveryReceiptBound":true,"noPrivateContactData":true,"noRawDataEmbedded":true,"notCarbonCredit":true,"notFinalProofAuthority":true,"notFinancialAsset":true,"notGuaranteedYield":true,"notTaxOffset":true,"outputHashOnly":true,"purposeBound":true}';
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_use_attestation_hash(
  use_organization_id text,
  use_request_id text,
  use_delivery_id text,
  use_manifest_id text,
  use_state text,
  use_case_text text,
  use_output_hashes text[],
  use_evidence_event_roots text[],
  use_limitations text[],
  use_attested_by text,
  use_attested_at timestamptz,
  use_delivery_root text,
  use_access_root text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"accessRoot":' || to_json(use_access_root)::text ||
        ',"attestedAt":' || to_json(to_char(use_attested_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"attestedBy":' || to_json(use_attested_by)::text ||
        ',"deliveryId":' || to_json(use_delivery_id)::text ||
        ',"deliveryRoot":' || to_json(use_delivery_root)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(use_evidence_event_roots) ||
        ',"kind":"canopyproof-data-use-attestation-v1"' ||
        ',"limitations":' || audit.canonical_text_array(use_limitations) ||
        ',"manifestId":' || to_json(use_manifest_id)::text ||
        ',"organizationId":' || to_json(use_organization_id)::text ||
        ',"outputHashes":' || audit.canonical_text_array(use_output_hashes) ||
        ',"requestId":' || to_json(use_request_id)::text ||
        ',"safety":' || organizations.data_use_attestation_safety_canonical() ||
        ',"usageState":' || to_json(use_state)::text ||
        ',"useCase":' || to_json(use_case_text)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

