        ',"outputHashes":' || audit.canonical_text_array(use_output_hashes) ||
        ',"requestId":' || to_json(use_request_id)::text ||
        ',"safety":' || organizations.data_use_attestation_safety_canonical() ||
        ',"usageRoot":' || to_json(use_root)::text ||
        ',"usageState":' || to_json(use_state)::text ||
        ',"useCase":' || to_json(use_case_text)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
