  );
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_use_attestation_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  organization_record organizations.organizations%ROWTYPE;
  actor_record identity.participants%ROWTYPE;
  delivery_record organizations.data_access_delivery_receipts%ROWTYPE;
  request_record organizations.data_access_requests%ROWTYPE;
  agreement_record organizations.data_sharing_agreements%ROWTYPE;
  manifest_record audit.export_manifests%ROWTYPE;
  current_request_status text := 'pending';
  approval_decided_at timestamptz;
  expected_attestation_hash text;
  expected_usage_root text;
  expected_payload_hash text;
  bound_payload_hash text;
  expected_delivery_receipt_hash text;
  expected_delivery_root text;
  expected_delivery_payload_hash text;
  bound_delivery_payload_hash text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.attested_by THEN
    RAISE EXCEPTION 'data use attestation insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.use_case ~* '(BEGIN|END)[[:space:]]+(RSA |EC |OPENSSH |PRIVATE )?PRIVATE KEY' OR
    NEW.use_case ~* '(private[_ -]?key|api[_ -]?secret|access[_ -]?secret|password|[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})' OR
    array_to_string(NEW.limitations, ' ') ~* '(BEGIN|END)[[:space:]]+(RSA |EC |OPENSSH |PRIVATE )?PRIVATE KEY' OR
    array_to_string(NEW.limitations, ' ') ~* '(private[_ -]?key|api[_ -]?secret|access[_ -]?secret|password|[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})'
  THEN
    RAISE EXCEPTION 'data use attestation cannot embed private key, secret, or private contact material' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO organization_record
  FROM organizations.organizations
  WHERE id = NEW.organization_id
  FOR UPDATE;
  IF NOT FOUND OR organization_record.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'data use attestation requires a verified organization' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO actor_record
  FROM identity.participants
  WHERE id = NEW.attested_by
  FOR UPDATE;
  IF
    NOT FOUND OR
    actor_record.participant_type <> 'human' OR
    actor_record.verification_status <> 'verified' OR
    actor_record.organization_id IS DISTINCT FROM NEW.organization_id
  THEN
    RAISE EXCEPTION 'data use attestation requires a verified human participant in the delivery organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.organization_id
      AND membership.actor_id = NEW.attested_by
      AND membership.status = 'active'
      AND membership.role IN ('owner', 'admin', 'verifier', 'researcher')
  ) THEN
    RAISE EXCEPTION 'data use attestation actor lacks an active institutional membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO delivery_record
  FROM organizations.data_access_delivery_receipts
  WHERE id = NEW.delivery_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data use attestation delivery does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF
    delivery_record.organization_id <> NEW.organization_id OR
    delivery_record.request_id <> NEW.request_id OR
    delivery_record.manifest_id <> NEW.manifest_id
  THEN
    RAISE EXCEPTION 'data use attestation delivery authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.attested_at < delivery_record.delivered_at THEN
    RAISE EXCEPTION 'data use attestation cannot predate its delivery receipt' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.usage_state IN ('within_scope', 'no_use') AND NEW.attested_by <> delivery_record.recipient_actor_id THEN
    RAISE EXCEPTION 'positive and no-use attestations require the named delivery recipient' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM audit.domain_events event
    WHERE event.event_root = delivery_record.audit_event_root
      AND event.stream_id = delivery_record.organization_id
      AND event.actor_id = delivery_record.delivered_by
      AND event.entity_type = 'data_access_delivery_receipt'
      AND event.entity_id = delivery_record.id
      AND event.created_at = delivery_record.delivered_at
  ) THEN
    RAISE EXCEPTION 'data use attestation requires an event-bound delivery receipt' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO request_record
  FROM organizations.data_access_requests
  WHERE id = NEW.request_id
  FOR UPDATE;
  IF NOT FOUND OR request_record.organization_id <> NEW.organization_id OR request_record.access_root <> delivery_record.access_root THEN
    RAISE EXCEPTION 'data use attestation request authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO agreement_record
  FROM organizations.data_sharing_agreements
  WHERE id = request_record.agreement_id
  FOR UPDATE;
  IF NOT FOUND OR agreement_record.organization_id <> NEW.organization_id THEN
    RAISE EXCEPTION 'data use attestation agreement authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO manifest_record
  FROM audit.export_manifests
  WHERE id = NEW.manifest_id
  FOR UPDATE;
  IF
    NOT FOUND OR
    manifest_record.requester_organization_id <> NEW.organization_id OR
    manifest_record.export_hash <> delivery_record.manifest_hash OR
    manifest_record.entry_root <> delivery_record.manifest_entry_root OR
    manifest_record.classification <> delivery_record.manifest_classification
  THEN
    RAISE EXCEPTION 'data use attestation manifest authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;

  expected_delivery_receipt_hash := organizations.compute_data_access_delivery_receipt_hash(
    delivery_record.organization_id,
    delivery_record.request_id,
    delivery_record.agreement_id,
    delivery_record.manifest_id,
    delivery_record.manifest_requester_organization_id,
    delivery_record.manifest_hash,
    delivery_record.manifest_entry_root,
    delivery_record.manifest_classification,
    delivery_record.channel,
    delivery_record.recipient_actor_id,
    delivery_record.delivered_by,
    delivery_record.delivered_at,
    delivery_record.purpose,
    delivery_record.access_root
  );
  IF
    delivery_record.receipt_hash <> expected_delivery_receipt_hash OR
    delivery_record.id <> 'cp_data_delivery_' || left(expected_delivery_receipt_hash, 24)
  THEN
    RAISE EXCEPTION 'data use attestation delivery receipt hash lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  expected_delivery_root := organizations.compute_data_access_delivery_root(
    delivery_record.access_root,
    delivery_record.manifest_entry_root,
    delivery_record.manifest_hash,
    delivery_record.receipt_hash,
    request_record.request_hash
  );
  IF delivery_record.delivery_root <> expected_delivery_root THEN
    RAISE EXCEPTION 'data use attestation delivery root lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  expected_delivery_payload_hash := organizations.compute_data_access_delivery_payload_hash(
    delivery_record.organization_id,
    delivery_record.request_id,
    delivery_record.agreement_id,
    delivery_record.manifest_id,
    delivery_record.manifest_requester_organization_id,
    delivery_record.manifest_hash,
    delivery_record.manifest_entry_root,
    delivery_record.manifest_classification,
    delivery_record.channel,
    delivery_record.recipient_actor_id,
    delivery_record.delivered_by,
    delivery_record.delivered_at,
    delivery_record.purpose,
    delivery_record.access_root,
    delivery_record.receipt_hash,
    delivery_record.delivery_root
  );
  SELECT event.payload_hash INTO bound_delivery_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = delivery_record.audit_event_root;
  IF bound_delivery_payload_hash IS DISTINCT FROM expected_delivery_payload_hash THEN
    RAISE EXCEPTION 'data use attestation delivery event payload lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.usage_state = 'within_scope' THEN
    IF EXISTS (
      SELECT 1
      FROM organizations.data_access_request_decisions decision
      LEFT JOIN audit.domain_events event
        ON event.event_root = decision.audit_event_root
       AND event.stream_id = decision.organization_id
       AND event.actor_id = decision.decision_by
       AND event.entity_type = 'data_access_request_decision'
       AND event.entity_id = decision.id
       AND event.created_at = decision.decided_at
      WHERE decision.request_id = NEW.request_id
        AND event.event_root IS NULL
    ) THEN
      RAISE EXCEPTION 'within-scope data use request decision lineage is not fully event-bound' USING ERRCODE = 'check_violation';
    END IF;
    SELECT decision.status, decision.decided_at
    INTO current_request_status, approval_decided_at
    FROM organizations.data_access_request_decisions decision
    JOIN audit.domain_events event ON event.event_root = decision.audit_event_root
    WHERE decision.request_id = NEW.request_id
    ORDER BY event.sequence_no DESC
    LIMIT 1;
    current_request_status := COALESCE(current_request_status, 'pending');
    IF current_request_status <> 'approved' OR approval_decided_at IS NULL OR NEW.attested_at < approval_decided_at THEN
      RAISE EXCEPTION 'within-scope data use requires a currently approved request' USING ERRCODE = 'check_violation';
    END IF;
    IF request_record.expires_at IS NOT NULL AND NEW.attested_at >= request_record.expires_at THEN
      RAISE EXCEPTION 'within-scope data use cannot use an expired request' USING ERRCODE = 'check_violation';
    END IF;
    IF agreement_record.revoked OR EXISTS (
      SELECT 1 FROM organizations.data_sharing_agreement_revocations revocation
      WHERE revocation.agreement_id = agreement_record.id
    ) OR EXISTS (
      SELECT 1 FROM organizations.data_sharing_agreement_supersessions supersession
      WHERE supersession.predecessor_agreement_id = agreement_record.id
    ) THEN
      RAISE EXCEPTION 'within-scope data use requires an active agreement' USING ERRCODE = 'check_violation';
    END IF;
    IF agreement_record.expires_at IS NOT NULL AND NEW.attested_at >= agreement_record.expires_at THEN
      RAISE EXCEPTION 'within-scope data use cannot use an expired agreement' USING ERRCODE = 'check_violation';
    END IF;
    IF manifest_record.expires_at IS NOT NULL AND NEW.attested_at >= manifest_record.expires_at THEN
      RAISE EXCEPTION 'within-scope data use cannot use an expired manifest' USING ERRCODE = 'check_violation';
    END IF;
    IF organizations.data_access_request_is_restricted(NEW.request_id) THEN
      RAISE EXCEPTION 'within-scope data use is blocked by the current durable restriction state' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  expected_attestation_hash := organizations.compute_data_use_attestation_hash(
    NEW.organization_id,
    NEW.request_id,
    NEW.delivery_id,
    NEW.manifest_id,
    NEW.usage_state,
    NEW.use_case,
    NEW.output_hashes,
    NEW.evidence_event_roots,
    NEW.limitations,
    NEW.attested_by,
    NEW.attested_at,
    delivery_record.delivery_root,
    delivery_record.access_root
  );
  IF NEW.attestation_hash <> expected_attestation_hash OR NEW.id <> 'cp_data_use_' || left(expected_attestation_hash, 24) THEN
    RAISE EXCEPTION 'data use attestation hash or identifier is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_usage_root := organizations.compute_data_use_root(
    delivery_record.access_root,
    NEW.attestation_hash,
    delivery_record.delivery_root,
    NEW.evidence_event_roots,
    NEW.output_hashes
  );
  IF NEW.usage_root <> expected_usage_root THEN
    RAISE EXCEPTION 'data use root is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_payload_hash := organizations.compute_data_use_attestation_payload_hash(
    NEW.organization_id,
    NEW.request_id,
    NEW.delivery_id,
    NEW.manifest_id,
    NEW.usage_state,
    NEW.use_case,
    NEW.output_hashes,
    NEW.evidence_event_roots,
    NEW.limitations,
    NEW.attested_by,
    NEW.attested_at,
    delivery_record.delivery_root,
    delivery_record.access_root,
    NEW.attestation_hash,
    NEW.usage_root
  );
  SELECT event.payload_hash INTO bound_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root;
  IF bound_payload_hash IS DISTINCT FROM expected_payload_hash THEN
    RAISE EXCEPTION 'data use semantic event payload does not match the canonical attestation' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_use_attestations_validate_insert ON organizations.data_use_attestations;
CREATE TRIGGER organizations_data_use_attestations_validate_insert
BEFORE INSERT ON organizations.data_use_attestations
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_use_attestation_insert();

CREATE OR REPLACE FUNCTION organizations.data_use_enforcement_safety_canonical()
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT '{"accessMutationRequiresSeparateApproval":true,"appendOnly":true,"approvedRequestBound":true,"challengedAttestationBound":true,"deliveryReceiptBound":true,"humanDecisionRequired":true,"independentReviewerRequired":true,"noPrivateContactData":true,"noRawDataEmbedded":true,"notCarbonCredit":true,"notFinalProofAuthority":true,"notFinancialAsset":true,"notGuaranteedYield":true,"notTaxOffset":true}';
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_use_enforcement_hash(
  enforcement_organization_id text,
  enforcement_request_id text,
  enforcement_delivery_id text,
  enforcement_attestation_id text,
  enforcement_manifest_id text,
  enforcement_case_state text,
  enforcement_action_name text,
  enforcement_rationale text,
  enforcement_evidence_event_roots text[],
  enforcement_reviewer_id text,
  enforcement_reviewed_at timestamptz,
  enforcement_usage_root text,
  enforcement_delivery_root text,
  enforcement_access_root text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"accessRoot":' || to_json(enforcement_access_root)::text ||
        ',"attestationId":' || to_json(enforcement_attestation_id)::text ||
        ',"caseState":' || to_json(enforcement_case_state)::text ||
        ',"deliveryId":' || to_json(enforcement_delivery_id)::text ||
        ',"deliveryRoot":' || to_json(enforcement_delivery_root)::text ||
        ',"enforcementAction":' || to_json(enforcement_action_name)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(enforcement_evidence_event_roots) ||
        ',"kind":"canopyproof-data-use-enforcement-case-v1"' ||
        ',"manifestId":' || to_json(enforcement_manifest_id)::text ||
        ',"organizationId":' || to_json(enforcement_organization_id)::text ||
        ',"rationale":' || to_json(enforcement_rationale)::text ||
        ',"requestId":' || to_json(enforcement_request_id)::text ||
        ',"reviewedAt":' || to_json(to_char(enforcement_reviewed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"reviewerId":' || to_json(enforcement_reviewer_id)::text ||
        ',"safety":' || organizations.data_use_enforcement_safety_canonical() ||
        ',"usageRoot":' || to_json(enforcement_usage_root)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_use_enforcement_root(
  enforcement_access_root text,
  enforcement_delivery_root text,
  enforcement_hash_value text,
  enforcement_evidence_event_roots text[],
  enforcement_usage_root text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"accessRoot":' || to_json(enforcement_access_root)::text ||
        ',"deliveryRoot":' || to_json(enforcement_delivery_root)::text ||
        ',"enforcementHash":' || to_json(enforcement_hash_value)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(enforcement_evidence_event_roots) ||
        ',"kind":"canopyproof-data-use-enforcement-root-v1"' ||
        ',"usageRoot":' || to_json(enforcement_usage_root)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_use_enforcement_payload_hash(
  enforcement_organization_id text,
  enforcement_request_id text,
  enforcement_delivery_id text,
  enforcement_attestation_id text,
  enforcement_manifest_id text,
  enforcement_case_state text,
  enforcement_action_name text,
  enforcement_rationale text,
  enforcement_evidence_event_roots text[],
  enforcement_reviewer_id text,
  enforcement_reviewed_at timestamptz,
  enforcement_usage_root text,
  enforcement_delivery_root text,
  enforcement_access_root text,
  enforcement_hash_value text,
  enforcement_root_value text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"accessRoot":' || to_json(enforcement_access_root)::text ||
        ',"attestationId":' || to_json(enforcement_attestation_id)::text ||
        ',"caseState":' || to_json(enforcement_case_state)::text ||
        ',"deliveryId":' || to_json(enforcement_delivery_id)::text ||
        ',"deliveryRoot":' || to_json(enforcement_delivery_root)::text ||
        ',"enforcementAction":' || to_json(enforcement_action_name)::text ||
        ',"enforcementHash":' || to_json(enforcement_hash_value)::text ||
        ',"enforcementRoot":' || to_json(enforcement_root_value)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(enforcement_evidence_event_roots) ||
        ',"manifestId":' || to_json(enforcement_manifest_id)::text ||
        ',"organizationId":' || to_json(enforcement_organization_id)::text ||
        ',"rationale":' || to_json(enforcement_rationale)::text ||
        ',"requestId":' || to_json(enforcement_request_id)::text ||
        ',"reviewedAt":' || to_json(to_char(enforcement_reviewed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"reviewerId":' || to_json(enforcement_reviewer_id)::text ||
        ',"safety":' || organizations.data_use_enforcement_safety_canonical() ||
        ',"usageRoot":' || to_json(enforcement_usage_root)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_use_enforcement_case_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  organization_record organizations.organizations%ROWTYPE;
  reviewer_record identity.participants%ROWTYPE;
  attestation_record organizations.data_use_attestations%ROWTYPE;
  delivery_record organizations.data_access_delivery_receipts%ROWTYPE;
  request_record organizations.data_access_requests%ROWTYPE;
  agreement_record organizations.data_sharing_agreements%ROWTYPE;
  manifest_record audit.export_manifests%ROWTYPE;
  delivery_event_sequence bigint;
  historical_request_status text := 'pending';
  historical_approval_at timestamptz;
  expected_delivery_receipt_hash text;
  expected_delivery_root text;
  expected_delivery_payload_hash text;
  bound_delivery_payload_hash text;
  expected_attestation_hash text;
  expected_usage_root text;
  expected_attestation_payload_hash text;
  bound_attestation_payload_hash text;
  expected_enforcement_hash text;
  expected_enforcement_root text;
  expected_enforcement_payload_hash text;
  bound_enforcement_payload_hash text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.reviewer_id THEN
    RAISE EXCEPTION 'data use enforcement case insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.rationale ~* '(BEGIN|END)[[:space:]]+(RSA |EC |OPENSSH |PRIVATE )?PRIVATE KEY' OR
    NEW.rationale ~* '(private[_ -]?key|api[_ -]?secret|access[_ -]?secret|password|[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})'
  THEN
    RAISE EXCEPTION 'data use enforcement case cannot embed private key, secret, or private contact material' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO organization_record
  FROM organizations.organizations
  WHERE id = NEW.organization_id
  FOR UPDATE;
  IF NOT FOUND OR organization_record.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'data use enforcement case requires a verified organization' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO reviewer_record
  FROM identity.participants
  WHERE id = NEW.reviewer_id
  FOR UPDATE;
  IF
    NOT FOUND OR
    reviewer_record.participant_type <> 'human' OR
    reviewer_record.verification_status <> 'verified' OR
    reviewer_record.organization_id IS DISTINCT FROM NEW.organization_id
  THEN
    RAISE EXCEPTION 'data use enforcement case requires a verified human reviewer in the delivery organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.organization_id
      AND membership.actor_id = NEW.reviewer_id
      AND membership.status = 'active'
      AND membership.role IN ('owner', 'admin', 'verifier')
  ) THEN
    RAISE EXCEPTION 'data use enforcement reviewer lacks an active institutional review membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO attestation_record
  FROM organizations.data_use_attestations
  WHERE id = NEW.attestation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data use enforcement attestation does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF
    attestation_record.organization_id <> NEW.organization_id OR
    attestation_record.request_id <> NEW.request_id OR
    attestation_record.delivery_id <> NEW.delivery_id OR
    attestation_record.manifest_id <> NEW.manifest_id
  THEN
    RAISE EXCEPTION 'data use enforcement attestation authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF attestation_record.usage_state NOT IN ('misuse_challenged', 'revocation_requested') THEN
    RAISE EXCEPTION 'data use enforcement case requires a challenged or revocation-requested attestation' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reviewed_at < attestation_record.attested_at THEN
    RAISE EXCEPTION 'data use enforcement review cannot predate its challenged attestation' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM unnest(attestation_record.evidence_event_roots) AS challenged_root(root_value)
    WHERE NOT (challenged_root.root_value = ANY(NEW.evidence_event_roots))
  ) THEN
    RAISE EXCEPTION 'data use enforcement case must retain every challenged attestation evidence root' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO delivery_record
  FROM organizations.data_access_delivery_receipts
  WHERE id = NEW.delivery_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data use enforcement delivery does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF
    delivery_record.organization_id <> NEW.organization_id OR
    delivery_record.request_id <> NEW.request_id OR
    delivery_record.manifest_id <> NEW.manifest_id
  THEN
    RAISE EXCEPTION 'data use enforcement delivery authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reviewer_id IN (attestation_record.attested_by, delivery_record.recipient_actor_id, delivery_record.delivered_by) THEN
    RAISE EXCEPTION 'data use enforcement reviewer must be independent from attester, recipient, and delivery actor' USING ERRCODE = 'check_violation';
  END IF;

  SELECT event.sequence_no INTO delivery_event_sequence
  FROM audit.domain_events event
  WHERE event.event_root = delivery_record.audit_event_root
    AND event.stream_id = NEW.organization_id
    AND event.actor_id = delivery_record.delivered_by
    AND event.entity_type = 'data_access_delivery_receipt'
    AND event.entity_id = delivery_record.id
    AND event.created_at = delivery_record.delivered_at;
  IF delivery_event_sequence IS NULL THEN
    RAISE EXCEPTION 'data use enforcement requires an event-bound delivery receipt' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM audit.domain_events event
    WHERE event.event_root = attestation_record.audit_event_root
      AND event.stream_id = NEW.organization_id
      AND event.actor_id = attestation_record.attested_by
      AND event.entity_type = 'data_use_attestation'
      AND event.entity_id = attestation_record.id
      AND event.action = 'CHALLENGE'
      AND event.created_at = attestation_record.attested_at
      AND event.sequence_no > delivery_event_sequence
  ) THEN
    RAISE EXCEPTION 'data use enforcement requires an event-bound challenged attestation after delivery' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO request_record
  FROM organizations.data_access_requests
  WHERE id = NEW.request_id
  FOR UPDATE;
  IF NOT FOUND OR request_record.organization_id <> NEW.organization_id OR request_record.access_root <> delivery_record.access_root THEN
    RAISE EXCEPTION 'data use enforcement request authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM organizations.data_access_request_decisions decision
    LEFT JOIN audit.domain_events event
      ON event.event_root = decision.audit_event_root
     AND event.stream_id = decision.organization_id
     AND event.actor_id = decision.decision_by
     AND event.entity_type = 'data_access_request_decision'
     AND event.entity_id = decision.id
     AND event.created_at = decision.decided_at
    WHERE decision.request_id = NEW.request_id
      AND event.event_root IS NULL
  ) THEN
    RAISE EXCEPTION 'data use enforcement request decision lineage is not fully event-bound' USING ERRCODE = 'check_violation';
  END IF;
  SELECT decision.status, decision.decided_at
  INTO historical_request_status, historical_approval_at
  FROM organizations.data_access_request_decisions decision
  JOIN audit.domain_events event ON event.event_root = decision.audit_event_root
  WHERE decision.request_id = NEW.request_id
    AND event.sequence_no < delivery_event_sequence
  ORDER BY event.sequence_no DESC
  LIMIT 1;
  historical_request_status := COALESCE(historical_request_status, 'pending');
  IF historical_request_status <> 'approved' OR historical_approval_at IS NULL OR historical_approval_at > delivery_record.delivered_at THEN
    RAISE EXCEPTION 'data use enforcement delivery lacks historical request approval' USING ERRCODE = 'check_violation';
  END IF;
  IF request_record.expires_at IS NOT NULL AND delivery_record.delivered_at >= request_record.expires_at THEN
    RAISE EXCEPTION 'data use enforcement delivery used an expired request' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO agreement_record
  FROM organizations.data_sharing_agreements
  WHERE id = delivery_record.agreement_id
  FOR UPDATE;
  IF
    NOT FOUND OR
    agreement_record.organization_id <> NEW.organization_id OR
    request_record.agreement_id <> agreement_record.id
  THEN
    RAISE EXCEPTION 'data use enforcement agreement authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF delivery_record.delivered_at < agreement_record.created_at OR
     (agreement_record.expires_at IS NOT NULL AND delivery_record.delivered_at >= agreement_record.expires_at) THEN
    RAISE EXCEPTION 'data use enforcement delivery falls outside agreement validity' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM organizations.data_sharing_agreement_revocations revocation
    JOIN audit.domain_events event ON event.event_root = revocation.audit_event_root
    WHERE revocation.agreement_id = agreement_record.id
      AND event.sequence_no < delivery_event_sequence
  ) OR EXISTS (
    SELECT 1
    FROM organizations.data_sharing_agreement_supersessions supersession
    JOIN audit.domain_events event ON event.event_root = supersession.audit_event_root
    WHERE supersession.predecessor_agreement_id = agreement_record.id
      AND event.sequence_no < delivery_event_sequence
  ) THEN
    RAISE EXCEPTION 'data use enforcement delivery used withdrawn agreement authority' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO manifest_record
  FROM audit.export_manifests
  WHERE id = NEW.manifest_id
  FOR UPDATE;
  IF
    NOT FOUND OR
    manifest_record.requester_organization_id <> NEW.organization_id OR
    manifest_record.export_hash <> delivery_record.manifest_hash OR
    manifest_record.entry_root <> delivery_record.manifest_entry_root OR
    manifest_record.classification <> delivery_record.manifest_classification OR
    delivery_record.delivered_at < manifest_record.created_at OR
    (manifest_record.expires_at IS NOT NULL AND delivery_record.delivered_at >= manifest_record.expires_at)
  THEN
    RAISE EXCEPTION 'data use enforcement manifest authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;

  expected_delivery_receipt_hash := organizations.compute_data_access_delivery_receipt_hash(
    delivery_record.organization_id,
    delivery_record.request_id,
    delivery_record.agreement_id,
    delivery_record.manifest_id,
    delivery_record.manifest_requester_organization_id,
    delivery_record.manifest_hash,
    delivery_record.manifest_entry_root,
    delivery_record.manifest_classification,
    delivery_record.channel,
    delivery_record.recipient_actor_id,
    delivery_record.delivered_by,
    delivery_record.delivered_at,
    delivery_record.purpose,
    delivery_record.access_root
  );
  IF
    delivery_record.receipt_hash <> expected_delivery_receipt_hash OR
    delivery_record.id <> 'cp_data_delivery_' || left(expected_delivery_receipt_hash, 24)
  THEN
    RAISE EXCEPTION 'data use enforcement delivery receipt hash lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  expected_delivery_root := organizations.compute_data_access_delivery_root(
    delivery_record.access_root,
    delivery_record.manifest_entry_root,
    delivery_record.manifest_hash,
    delivery_record.receipt_hash,
    request_record.request_hash
  );
  IF delivery_record.delivery_root <> expected_delivery_root THEN
    RAISE EXCEPTION 'data use enforcement delivery root lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  expected_delivery_payload_hash := organizations.compute_data_access_delivery_payload_hash(
    delivery_record.organization_id,
    delivery_record.request_id,
    delivery_record.agreement_id,
    delivery_record.manifest_id,
    delivery_record.manifest_requester_organization_id,
    delivery_record.manifest_hash,
    delivery_record.manifest_entry_root,
    delivery_record.manifest_classification,
    delivery_record.channel,
    delivery_record.recipient_actor_id,
    delivery_record.delivered_by,
    delivery_record.delivered_at,
    delivery_record.purpose,
    delivery_record.access_root,
    delivery_record.receipt_hash,
    delivery_record.delivery_root
  );
  SELECT event.payload_hash INTO bound_delivery_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = delivery_record.audit_event_root;
  IF bound_delivery_payload_hash IS DISTINCT FROM expected_delivery_payload_hash THEN
    RAISE EXCEPTION 'data use enforcement delivery event payload lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;

  expected_attestation_hash := organizations.compute_data_use_attestation_hash(
    attestation_record.organization_id,
    attestation_record.request_id,
    attestation_record.delivery_id,
    attestation_record.manifest_id,
    attestation_record.usage_state,
    attestation_record.use_case,
    attestation_record.output_hashes,
    attestation_record.evidence_event_roots,
    attestation_record.limitations,
    attestation_record.attested_by,
    attestation_record.attested_at,
    delivery_record.delivery_root,
    delivery_record.access_root
  );
  IF
    attestation_record.attestation_hash <> expected_attestation_hash OR
    attestation_record.id <> 'cp_data_use_' || left(expected_attestation_hash, 24)
  THEN
    RAISE EXCEPTION 'data use enforcement attestation hash lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  expected_usage_root := organizations.compute_data_use_root(
    delivery_record.access_root,
    attestation_record.attestation_hash,
    delivery_record.delivery_root,
    attestation_record.evidence_event_roots,
    attestation_record.output_hashes
  );
  IF attestation_record.usage_root <> expected_usage_root THEN
    RAISE EXCEPTION 'data use enforcement usage root lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  expected_attestation_payload_hash := organizations.compute_data_use_attestation_payload_hash(
    attestation_record.organization_id,
    attestation_record.request_id,
    attestation_record.delivery_id,
    attestation_record.manifest_id,
    attestation_record.usage_state,
    attestation_record.use_case,
    attestation_record.output_hashes,
    attestation_record.evidence_event_roots,
    attestation_record.limitations,
    attestation_record.attested_by,
    attestation_record.attested_at,
    delivery_record.delivery_root,
    delivery_record.access_root,
    attestation_record.attestation_hash,
    attestation_record.usage_root
  );
  SELECT event.payload_hash INTO bound_attestation_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = attestation_record.audit_event_root;
  IF bound_attestation_payload_hash IS DISTINCT FROM expected_attestation_payload_hash THEN
    RAISE EXCEPTION 'data use enforcement attestation event payload lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;

  expected_enforcement_hash := organizations.compute_data_use_enforcement_hash(
    NEW.organization_id,
    NEW.request_id,
    NEW.delivery_id,
    NEW.attestation_id,
    NEW.manifest_id,
    NEW.case_state,
    NEW.enforcement_action,
    NEW.rationale,
    NEW.evidence_event_roots,
    NEW.reviewer_id,
    NEW.reviewed_at,
    attestation_record.usage_root,
    delivery_record.delivery_root,
    delivery_record.access_root
  );
  IF NEW.enforcement_hash <> expected_enforcement_hash OR NEW.id <> 'cp_data_use_enforcement_' || left(expected_enforcement_hash, 24) THEN
    RAISE EXCEPTION 'data use enforcement hash or identifier is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_enforcement_root := organizations.compute_data_use_enforcement_root(
    delivery_record.access_root,
    delivery_record.delivery_root,
    NEW.enforcement_hash,
    NEW.evidence_event_roots,
    attestation_record.usage_root
  );
  IF NEW.enforcement_root <> expected_enforcement_root THEN
    RAISE EXCEPTION 'data use enforcement root is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_enforcement_payload_hash := organizations.compute_data_use_enforcement_payload_hash(
    NEW.organization_id,
    NEW.request_id,
    NEW.delivery_id,
    NEW.attestation_id,
    NEW.manifest_id,
    NEW.case_state,
    NEW.enforcement_action,
    NEW.rationale,
    NEW.evidence_event_roots,
    NEW.reviewer_id,
    NEW.reviewed_at,
    attestation_record.usage_root,
    delivery_record.delivery_root,
    delivery_record.access_root,
    NEW.enforcement_hash,
    NEW.enforcement_root
  );
  SELECT event.payload_hash INTO bound_enforcement_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root;
  IF bound_enforcement_payload_hash IS DISTINCT FROM expected_enforcement_payload_hash THEN
    RAISE EXCEPTION 'data use enforcement semantic event payload does not match the canonical case' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_use_enforcement_cases_validate_insert ON organizations.data_use_enforcement_cases;
CREATE TRIGGER organizations_data_use_enforcement_cases_validate_insert
BEFORE INSERT ON organizations.data_use_enforcement_cases
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_use_enforcement_case_insert();

CREATE OR REPLACE FUNCTION organizations.data_access_restriction_safety_canonical()
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT '{"appendOnly":true,"approvedRequestBound":true,"deliveryBlockingEnforced":true,"enforcementCaseBound":true,"independentDecisionRequired":true,"noPrivateContactData":true,"noRawDataEmbedded":true,"notCarbonCredit":true,"notFinalProofAuthority":true,"notFinancialAsset":true,"notGuaranteedYield":true,"notTaxOffset":true,"reviewerSeparationRequired":true,"separateApprovalPath":true}';
$$;

CREATE OR REPLACE FUNCTION organizations.is_data_access_restriction_transition_allowed(
  previous_state text,
  next_state text
)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE
    WHEN previous_state IS NULL THEN next_state IN ('remediation_hold', 'suspended', 'revoked')
    WHEN previous_state = 'remediation_hold' THEN next_state IN ('suspended', 'revoked', 'restored')
    WHEN previous_state = 'suspended' THEN next_state IN ('revoked', 'restored')
    WHEN previous_state = 'revoked' THEN next_state = 'restored'
    WHEN previous_state = 'restored' THEN next_state IN ('remediation_hold', 'suspended', 'revoked')
    ELSE false
  END;
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_restriction_hash(
  restriction_organization_id text,
  restriction_request_id text,
  restriction_enforcement_case_id text,
  restriction_attestation_id text,
  restriction_delivery_id text,
  restriction_previous_id text,
  restriction_previous_root text,
  restriction_previous_state text,
  restriction_state_value text,
  restriction_rationale text,
  restriction_evidence_event_roots text[],
  restriction_decided_by text,
  restriction_decided_at timestamptz,
  restriction_expires_at timestamptz,
  restriction_enforcement_root text,
  restriction_usage_root text,
  restriction_delivery_root text,
  restriction_access_root text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"accessRoot":' || to_json(restriction_access_root)::text ||
        ',"attestationId":' || to_json(restriction_attestation_id)::text ||
        ',"decidedAt":' || to_json(to_char(restriction_decided_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"decidedBy":' || to_json(restriction_decided_by)::text ||
        ',"deliveryId":' || to_json(restriction_delivery_id)::text ||
        ',"deliveryRoot":' || to_json(restriction_delivery_root)::text ||
        ',"enforcementCaseId":' || to_json(restriction_enforcement_case_id)::text ||
        ',"enforcementRoot":' || to_json(restriction_enforcement_root)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(restriction_evidence_event_roots) ||
        ',"expiresAt":' || COALESCE(to_json(to_char(restriction_expires_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text, 'null') ||
        ',"kind":"canopyproof-data-access-restriction-v1"' ||
        ',"organizationId":' || to_json(restriction_organization_id)::text ||
        ',"previousRestrictionId":' || COALESCE(to_json(restriction_previous_id)::text, 'null') ||
        ',"previousRestrictionRoot":' || COALESCE(to_json(restriction_previous_root)::text, 'null') ||
        ',"previousRestrictionState":' || COALESCE(to_json(restriction_previous_state)::text, 'null') ||
        ',"rationale":' || to_json(restriction_rationale)::text ||
        ',"requestId":' || to_json(restriction_request_id)::text ||
        ',"restrictionState":' || to_json(restriction_state_value)::text ||
        ',"safety":' || organizations.data_access_restriction_safety_canonical() ||
        ',"usageRoot":' || to_json(restriction_usage_root)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_restriction_root(
  restriction_access_root text,
  restriction_delivery_root text,
  restriction_enforcement_root text,
  restriction_evidence_event_roots text[],
  restriction_previous_root text,
  restriction_hash_value text,
  restriction_usage_root text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"accessRoot":' || to_json(restriction_access_root)::text ||
        ',"deliveryRoot":' || to_json(restriction_delivery_root)::text ||
        ',"enforcementRoot":' || to_json(restriction_enforcement_root)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(restriction_evidence_event_roots) ||
        ',"kind":"canopyproof-data-access-restriction-root-v1"' ||
        ',"previousRestrictionRoot":' || COALESCE(to_json(restriction_previous_root)::text, 'null') ||
        ',"restrictionHash":' || to_json(restriction_hash_value)::text ||
        ',"usageRoot":' || to_json(restriction_usage_root)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_restriction_payload_hash(
  restriction_organization_id text,
  restriction_request_id text,
  restriction_enforcement_case_id text,
  restriction_attestation_id text,
  restriction_delivery_id text,
  restriction_previous_id text,
  restriction_previous_root text,
  restriction_previous_state text,
  restriction_state_value text,
  restriction_rationale text,
  restriction_evidence_event_roots text[],
  restriction_decided_by text,
  restriction_decided_at timestamptz,
  restriction_expires_at timestamptz,
  restriction_enforcement_root text,
  restriction_usage_root text,
  restriction_delivery_root text,
  restriction_access_root text,
  restriction_hash_value text,
  restriction_root_value text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"accessRoot":' || to_json(restriction_access_root)::text ||
        ',"attestationId":' || to_json(restriction_attestation_id)::text ||
        ',"decidedAt":' || to_json(to_char(restriction_decided_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"decidedBy":' || to_json(restriction_decided_by)::text ||
        ',"deliveryId":' || to_json(restriction_delivery_id)::text ||
        ',"deliveryRoot":' || to_json(restriction_delivery_root)::text ||
        ',"enforcementCaseId":' || to_json(restriction_enforcement_case_id)::text ||
        ',"enforcementRoot":' || to_json(restriction_enforcement_root)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(restriction_evidence_event_roots) ||
        ',"expiresAt":' || COALESCE(to_json(to_char(restriction_expires_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text, 'null') ||
        ',"organizationId":' || to_json(restriction_organization_id)::text ||
        ',"previousRestrictionId":' || COALESCE(to_json(restriction_previous_id)::text, 'null') ||
        ',"previousRestrictionRoot":' || COALESCE(to_json(restriction_previous_root)::text, 'null') ||
        ',"previousRestrictionState":' || COALESCE(to_json(restriction_previous_state)::text, 'null') ||
        ',"rationale":' || to_json(restriction_rationale)::text ||
        ',"requestId":' || to_json(restriction_request_id)::text ||
        ',"restrictionHash":' || to_json(restriction_hash_value)::text ||
        ',"restrictionRoot":' || to_json(restriction_root_value)::text ||
        ',"restrictionState":' || to_json(restriction_state_value)::text ||
        ',"safety":' || organizations.data_access_restriction_safety_canonical() ||
        ',"usageRoot":' || to_json(restriction_usage_root)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_access_restriction_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  organization_record organizations.organizations%ROWTYPE;
  decision_actor_record identity.participants%ROWTYPE;
  enforcement_record organizations.data_use_enforcement_cases%ROWTYPE;
  attestation_record organizations.data_use_attestations%ROWTYPE;
  delivery_record organizations.data_access_delivery_receipts%ROWTYPE;
  request_record organizations.data_access_requests%ROWTYPE;
  previous_record organizations.data_access_restrictions%ROWTYPE;
  previous_event_sequence bigint;
  enforcement_event_sequence bigint;
  new_event_sequence bigint;
  expected_enforcement_hash text;
  expected_enforcement_root text;
  expected_enforcement_payload_hash text;
  bound_enforcement_payload_hash text;
  expected_restriction_hash text;
  expected_restriction_root text;
  expected_restriction_payload_hash text;
  bound_restriction_payload_hash text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.decided_by THEN
    RAISE EXCEPTION 'data access restriction insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.rationale ~* '(BEGIN|END)[[:space:]]+(RSA |EC |OPENSSH |PRIVATE )?PRIVATE KEY' OR
    NEW.rationale ~* '(private[_ -]?key|api[_ -]?secret|access[_ -]?secret|password|[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})'
  THEN
    RAISE EXCEPTION 'data access restriction cannot embed private key, secret, or private contact material' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO organization_record
  FROM organizations.organizations
  WHERE id = NEW.organization_id
  FOR UPDATE;
  IF NOT FOUND OR organization_record.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'data access restriction requires a verified organization' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO decision_actor_record
  FROM identity.participants
  WHERE id = NEW.decided_by
  FOR UPDATE;
  IF
    NOT FOUND OR
    decision_actor_record.participant_type <> 'human' OR
    decision_actor_record.verification_status <> 'verified' OR
    decision_actor_record.organization_id IS DISTINCT FROM NEW.organization_id
  THEN
    RAISE EXCEPTION 'data access restriction requires a verified human decision actor in the governed organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.organization_id
      AND membership.actor_id = NEW.decided_by
      AND membership.status = 'active'
      AND membership.role IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'data access restriction actor lacks an active owner or admin membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO enforcement_record
  FROM organizations.data_use_enforcement_cases
  WHERE id = NEW.enforcement_case_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data access restriction enforcement case does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF
    enforcement_record.organization_id <> NEW.organization_id OR
    enforcement_record.request_id <> NEW.request_id OR
    enforcement_record.attestation_id <> NEW.attestation_id OR
    enforcement_record.delivery_id <> NEW.delivery_id
  THEN
    RAISE EXCEPTION 'data access restriction enforcement authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO attestation_record
  FROM organizations.data_use_attestations
  WHERE id = NEW.attestation_id
  FOR UPDATE;
  SELECT * INTO delivery_record
  FROM organizations.data_access_delivery_receipts
  WHERE id = NEW.delivery_id
  FOR UPDATE;
  SELECT * INTO request_record
  FROM organizations.data_access_requests
  WHERE id = NEW.request_id
  FOR UPDATE;
  IF
    attestation_record.id IS NULL OR
    delivery_record.id IS NULL OR
    request_record.id IS NULL OR
    attestation_record.organization_id <> NEW.organization_id OR
    attestation_record.request_id <> NEW.request_id OR
    attestation_record.delivery_id <> NEW.delivery_id OR
    delivery_record.organization_id <> NEW.organization_id OR
    delivery_record.request_id <> NEW.request_id OR
    request_record.organization_id <> NEW.organization_id OR
    delivery_record.access_root <> request_record.access_root
  THEN
    RAISE EXCEPTION 'data access restriction upstream authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.decided_by IN (
    enforcement_record.reviewer_id,
    attestation_record.attested_by,
    delivery_record.recipient_actor_id,
    delivery_record.delivered_by
  ) THEN
    RAISE EXCEPTION 'data access restriction actor must be independent from reviewer, attester, recipient, and delivery actor' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.decided_at < enforcement_record.reviewed_at THEN
    RAISE EXCEPTION 'data access restriction decision cannot predate its enforcement review' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM unnest(enforcement_record.evidence_event_roots) AS enforcement_root(root_value)
    WHERE NOT (enforcement_root.root_value = ANY(NEW.evidence_event_roots))
  ) THEN
    RAISE EXCEPTION 'data access restriction must retain every enforcement evidence root' USING ERRCODE = 'check_violation';
  END IF;

  SELECT event.sequence_no INTO enforcement_event_sequence
  FROM audit.domain_events event
  WHERE event.event_root = enforcement_record.audit_event_root
    AND event.stream_id = NEW.organization_id
    AND event.actor_id = enforcement_record.reviewer_id
    AND event.entity_type = 'data_use_enforcement_case'
    AND event.entity_id = enforcement_record.id
    AND event.created_at = enforcement_record.reviewed_at;
  SELECT event.sequence_no INTO new_event_sequence
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root
    AND event.stream_id = NEW.organization_id
    AND event.actor_id = NEW.decided_by
    AND event.entity_type = 'data_access_restriction'
    AND event.entity_id = NEW.id
    AND event.created_at = NEW.decided_at;
  IF enforcement_event_sequence IS NULL OR new_event_sequence IS NULL OR new_event_sequence <= enforcement_event_sequence THEN
    RAISE EXCEPTION 'data access restriction requires an event-bound prior enforcement review' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.restriction_state = 'remediation_hold' AND NOT (
    enforcement_record.case_state IN ('action_required', 'remediation_required') AND
    enforcement_record.enforcement_action = 'require_remediation'
  ) THEN
    RAISE EXCEPTION 'data access remediation hold requires a remediation enforcement disposition' USING ERRCODE = 'check_violation';
  ELSIF NEW.restriction_state = 'suspended' AND NOT (
    enforcement_record.case_state = 'access_suspended' AND
    enforcement_record.enforcement_action = 'suspend_data_access'
  ) THEN
    RAISE EXCEPTION 'data access suspension requires a suspension enforcement disposition' USING ERRCODE = 'check_violation';
  ELSIF NEW.restriction_state = 'revoked' AND NOT (
    enforcement_record.case_state = 'access_revoked' AND
    enforcement_record.enforcement_action = 'revoke_data_access'
  ) THEN
    RAISE EXCEPTION 'data access revocation requires a revocation enforcement disposition' USING ERRCODE = 'check_violation';
  ELSIF NEW.restriction_state = 'restored' AND enforcement_record.case_state <> 'resolved' THEN
    RAISE EXCEPTION 'data access restoration requires a resolved enforcement disposition' USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM organizations.data_access_restrictions restriction
    LEFT JOIN audit.domain_events event
      ON event.event_root = restriction.audit_event_root
     AND event.stream_id = restriction.organization_id
     AND event.actor_id = restriction.decided_by
     AND event.entity_type = 'data_access_restriction'
     AND event.entity_id = restriction.id
     AND event.created_at = restriction.decided_at
    WHERE restriction.request_id = NEW.request_id
      AND event.event_root IS NULL
  ) THEN
    RAISE EXCEPTION 'data access restriction predecessor stream is not fully event-bound' USING ERRCODE = 'check_violation';
  END IF;
  SELECT restriction.*
  INTO previous_record
  FROM organizations.data_access_restrictions restriction
  JOIN audit.domain_events event ON event.event_root = restriction.audit_event_root
  WHERE restriction.request_id = NEW.request_id
  ORDER BY event.sequence_no DESC
  LIMIT 1
  FOR UPDATE OF restriction;
  IF previous_record.id IS NOT NULL THEN
    SELECT event.sequence_no INTO previous_event_sequence
    FROM audit.domain_events event
    WHERE event.event_root = previous_record.audit_event_root;
  END IF;

  IF previous_record.id IS NULL THEN
    IF
      NEW.previous_restriction_id IS NOT NULL OR
      NEW.previous_restriction_root IS NOT NULL OR
      NEW.previous_restriction_state IS NOT NULL OR
      NOT organizations.is_data_access_restriction_transition_allowed(NULL, NEW.restriction_state)
    THEN
      RAISE EXCEPTION 'initial data access restriction has invalid predecessor or state' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF
      NEW.previous_restriction_id IS DISTINCT FROM previous_record.id OR
      NEW.previous_restriction_root IS DISTINCT FROM previous_record.restriction_root OR
      NEW.previous_restriction_state IS DISTINCT FROM previous_record.restriction_state
    THEN
      RAISE EXCEPTION 'data access restriction predecessor does not match current semantic state' USING ERRCODE = 'check_violation';
    END IF;
    IF new_event_sequence <= previous_event_sequence OR NEW.decided_at < previous_record.decided_at THEN
      RAISE EXCEPTION 'data access restriction decision cannot move behind its predecessor' USING ERRCODE = 'check_violation';
    END IF;
    IF enforcement_event_sequence <= previous_event_sequence OR enforcement_record.reviewed_at < previous_record.decided_at THEN
      RAISE EXCEPTION 'data access restriction successor requires a later enforcement review' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT organizations.is_data_access_restriction_transition_allowed(previous_record.restriction_state, NEW.restriction_state) THEN
      RAISE EXCEPTION 'data access restriction state transition is invalid' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.restriction_state = 'restored' AND NEW.decided_by = previous_record.decided_by THEN
      RAISE EXCEPTION 'data access restoration requires an actor independent from the prior restriction decision' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  expected_enforcement_hash := organizations.compute_data_use_enforcement_hash(
    enforcement_record.organization_id,
    enforcement_record.request_id,
    enforcement_record.delivery_id,
    enforcement_record.attestation_id,
    enforcement_record.manifest_id,
    enforcement_record.case_state,
    enforcement_record.enforcement_action,
    enforcement_record.rationale,
    enforcement_record.evidence_event_roots,
    enforcement_record.reviewer_id,
    enforcement_record.reviewed_at,
    attestation_record.usage_root,
    delivery_record.delivery_root,
    delivery_record.access_root
  );
  IF
    enforcement_record.enforcement_hash <> expected_enforcement_hash OR
    enforcement_record.id <> 'cp_data_use_enforcement_' || left(expected_enforcement_hash, 24)
  THEN
    RAISE EXCEPTION 'data access restriction enforcement hash lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  expected_enforcement_root := organizations.compute_data_use_enforcement_root(
    delivery_record.access_root,
    delivery_record.delivery_root,
    enforcement_record.enforcement_hash,
    enforcement_record.evidence_event_roots,
    attestation_record.usage_root
  );
  IF enforcement_record.enforcement_root <> expected_enforcement_root THEN
    RAISE EXCEPTION 'data access restriction enforcement root lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  expected_enforcement_payload_hash := organizations.compute_data_use_enforcement_payload_hash(
    enforcement_record.organization_id,
    enforcement_record.request_id,
    enforcement_record.delivery_id,
    enforcement_record.attestation_id,
    enforcement_record.manifest_id,
    enforcement_record.case_state,
    enforcement_record.enforcement_action,
    enforcement_record.rationale,
    enforcement_record.evidence_event_roots,
    enforcement_record.reviewer_id,
    enforcement_record.reviewed_at,
    attestation_record.usage_root,
    delivery_record.delivery_root,
    delivery_record.access_root,
    enforcement_record.enforcement_hash,
    enforcement_record.enforcement_root
  );
  SELECT event.payload_hash INTO bound_enforcement_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = enforcement_record.audit_event_root;
  IF bound_enforcement_payload_hash IS DISTINCT FROM expected_enforcement_payload_hash THEN
    RAISE EXCEPTION 'data access restriction enforcement event payload lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;

  expected_restriction_hash := organizations.compute_data_access_restriction_hash(
    NEW.organization_id,
    NEW.request_id,
    NEW.enforcement_case_id,
    NEW.attestation_id,
    NEW.delivery_id,
    NEW.previous_restriction_id,
    NEW.previous_restriction_root,
    NEW.previous_restriction_state,
    NEW.restriction_state,
    NEW.rationale,
    NEW.evidence_event_roots,
    NEW.decided_by,
    NEW.decided_at,
    NEW.expires_at,
    enforcement_record.enforcement_root,
    attestation_record.usage_root,
    delivery_record.delivery_root,
    delivery_record.access_root
  );
  IF NEW.restriction_hash <> expected_restriction_hash OR NEW.id <> 'cp_data_access_restriction_' || left(expected_restriction_hash, 24) THEN
    RAISE EXCEPTION 'data access restriction hash or identifier is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_restriction_root := organizations.compute_data_access_restriction_root(
    delivery_record.access_root,
    delivery_record.delivery_root,
    enforcement_record.enforcement_root,
    NEW.evidence_event_roots,
    NEW.previous_restriction_root,
    NEW.restriction_hash,
    attestation_record.usage_root
  );
  IF NEW.restriction_root <> expected_restriction_root THEN
    RAISE EXCEPTION 'data access restriction root is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_restriction_payload_hash := organizations.compute_data_access_restriction_payload_hash(
    NEW.organization_id,
    NEW.request_id,
    NEW.enforcement_case_id,
    NEW.attestation_id,
    NEW.delivery_id,
    NEW.previous_restriction_id,
    NEW.previous_restriction_root,
    NEW.previous_restriction_state,
    NEW.restriction_state,
    NEW.rationale,
    NEW.evidence_event_roots,
    NEW.decided_by,
    NEW.decided_at,
    NEW.expires_at,
    enforcement_record.enforcement_root,
    attestation_record.usage_root,
    delivery_record.delivery_root,
    delivery_record.access_root,
    NEW.restriction_hash,
    NEW.restriction_root
  );
  SELECT event.payload_hash INTO bound_restriction_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root;
  IF bound_restriction_payload_hash IS DISTINCT FROM expected_restriction_payload_hash THEN
    RAISE EXCEPTION 'data access restriction semantic event payload does not match the canonical decision' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_access_restrictions_validate_insert ON organizations.data_access_restrictions;
CREATE TRIGGER organizations_data_access_restrictions_validate_insert
BEFORE INSERT ON organizations.data_access_restrictions
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_access_restriction_insert();

CREATE OR REPLACE FUNCTION organizations.data_access_request_is_restricted(restriction_request_id text)
RETURNS boolean
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  restriction_record record;
  current_id text;
  current_root text;
  current_state text;
  expected_hash text;
  expected_root text;
  expected_payload_hash text;
  enforcement_root_value text;
  usage_root_value text;
  delivery_root_value text;
  access_root_value text;
BEGIN
  FOR restriction_record IN
    SELECT restriction.*, event.sequence_no, event.payload_hash AS bound_payload_hash
    FROM organizations.data_access_restrictions restriction
    LEFT JOIN audit.domain_events event
      ON event.event_root = restriction.audit_event_root
     AND event.stream_id = restriction.organization_id
     AND event.actor_id = restriction.decided_by
     AND event.entity_type = 'data_access_restriction'
     AND event.entity_id = restriction.id
     AND event.created_at = restriction.decided_at
     AND event.action = CASE WHEN restriction.restriction_state = 'restored' THEN 'FULFILL' ELSE 'CHALLENGE' END
    WHERE restriction.request_id = restriction_request_id
    ORDER BY event.sequence_no ASC NULLS LAST
  LOOP
    IF restriction_record.sequence_no IS NULL THEN
      RAISE EXCEPTION 'data access restriction stream contains an unbound semantic event' USING ERRCODE = 'check_violation';
    END IF;
    IF
      restriction_record.previous_restriction_id IS DISTINCT FROM current_id OR
      restriction_record.previous_restriction_root IS DISTINCT FROM current_root OR
      restriction_record.previous_restriction_state IS DISTINCT FROM current_state OR
      NOT organizations.is_data_access_restriction_transition_allowed(current_state, restriction_record.restriction_state)
    THEN
      RAISE EXCEPTION 'data access restriction stream predecessor or transition is invalid' USING ERRCODE = 'check_violation';
    END IF;
    SELECT
      enforcement_case.enforcement_root,
      attestation.usage_root,
      delivery.delivery_root,
      request.access_root
    INTO enforcement_root_value, usage_root_value, delivery_root_value, access_root_value
    FROM organizations.data_use_enforcement_cases enforcement_case
    JOIN organizations.data_use_attestations attestation ON attestation.id = restriction_record.attestation_id
    JOIN organizations.data_access_delivery_receipts delivery ON delivery.id = restriction_record.delivery_id
    JOIN organizations.data_access_requests request ON request.id = restriction_record.request_id
    WHERE enforcement_case.id = restriction_record.enforcement_case_id
      AND enforcement_case.organization_id = restriction_record.organization_id
      AND enforcement_case.request_id = restriction_record.request_id
      AND enforcement_case.attestation_id = restriction_record.attestation_id
      AND enforcement_case.delivery_id = restriction_record.delivery_id;
    IF enforcement_root_value IS NULL OR usage_root_value IS NULL OR delivery_root_value IS NULL OR access_root_value IS NULL THEN
      RAISE EXCEPTION 'data access restriction stream authority lineage is incomplete' USING ERRCODE = 'check_violation';
    END IF;
    expected_hash := organizations.compute_data_access_restriction_hash(
      restriction_record.organization_id,
      restriction_record.request_id,
      restriction_record.enforcement_case_id,
      restriction_record.attestation_id,
      restriction_record.delivery_id,
      restriction_record.previous_restriction_id,
      restriction_record.previous_restriction_root,
      restriction_record.previous_restriction_state,
      restriction_record.restriction_state,
      restriction_record.rationale,
      restriction_record.evidence_event_roots,
      restriction_record.decided_by,
      restriction_record.decided_at,
      restriction_record.expires_at,
      enforcement_root_value,
      usage_root_value,
      delivery_root_value,
      access_root_value
    );
    expected_root := organizations.compute_data_access_restriction_root(
      access_root_value,
      delivery_root_value,
      enforcement_root_value,
      restriction_record.evidence_event_roots,
      restriction_record.previous_restriction_root,
      expected_hash,
      usage_root_value
    );
    expected_payload_hash := organizations.compute_data_access_restriction_payload_hash(
      restriction_record.organization_id,
      restriction_record.request_id,
      restriction_record.enforcement_case_id,
      restriction_record.attestation_id,
      restriction_record.delivery_id,
      restriction_record.previous_restriction_id,
      restriction_record.previous_restriction_root,
      restriction_record.previous_restriction_state,
      restriction_record.restriction_state,
      restriction_record.rationale,
      restriction_record.evidence_event_roots,
      restriction_record.decided_by,
      restriction_record.decided_at,
      restriction_record.expires_at,
      enforcement_root_value,
      usage_root_value,
      delivery_root_value,
      access_root_value,
      expected_hash,
      expected_root
    );
    IF
      restriction_record.safety <> organizations.data_access_restriction_safety_canonical()::jsonb OR
      restriction_record.id <> 'cp_data_access_restriction_' || left(expected_hash, 24) OR
      restriction_record.restriction_hash <> expected_hash OR
      restriction_record.restriction_root <> expected_root OR
      restriction_record.bound_payload_hash IS DISTINCT FROM expected_payload_hash
    THEN
      RAISE EXCEPTION 'data access restriction stream contains non-canonical authority' USING ERRCODE = 'check_violation';
    END IF;
    current_id := restriction_record.id;
    current_root := restriction_record.restriction_root;
    current_state := restriction_record.restriction_state;
  END LOOP;
  RETURN current_state IS NOT NULL AND current_state <> 'restored';
END;
$$;

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_packet_safety_canonical()
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT '{"appendOnlyLedgerDerived":true,"hashOnlyLineage":true,"noPrivateContactData":true,"noRawDataEmbedded":true,"notCarbonCredit":true,"notFinalProofAuthority":true,"notFinancialAsset":true,"notGuaranteedYield":true,"notTaxOffset":true,"observerReadable":true,"requestBound":true}';
$$;

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_counts_canonical(packet_counts jsonb)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT
    '{"activeRestrictionCount":' || (packet_counts ->> 'activeRestrictionCount') ||
    ',"agreementRevocationCount":' || (packet_counts ->> 'agreementRevocationCount') ||
    ',"agreementSupersessionCount":' || (packet_counts ->> 'agreementSupersessionCount') ||
    ',"dataUseAttestationCount":' || (packet_counts ->> 'dataUseAttestationCount') ||
    ',"deliveryReceiptCount":' || (packet_counts ->> 'deliveryReceiptCount') ||
    ',"enforcementCaseCount":' || (packet_counts ->> 'enforcementCaseCount') ||
    ',"totalRestrictionCount":' || (packet_counts ->> 'totalRestrictionCount') ||
    '}';
$$;

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_lineage_canonical(packet_lineage jsonb)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT
    '{"accessRoot":' || to_json(packet_lineage ->> 'accessRoot')::text ||
    ',"agreementRevocationRoots":' || audit.canonical_text_array(ARRAY(
      SELECT item.value
      FROM jsonb_array_elements_text(packet_lineage -> 'agreementRevocationRoots') WITH ORDINALITY AS item(value, ordinality)
      ORDER BY item.ordinality
    )) ||
    ',"agreementSupersessionRoots":' || audit.canonical_text_array(ARRAY(
      SELECT item.value
      FROM jsonb_array_elements_text(packet_lineage -> 'agreementSupersessionRoots') WITH ORDINALITY AS item(value, ordinality)
      ORDER BY item.ordinality
    )) ||
    ',"deliveryRoots":' || audit.canonical_text_array(ARRAY(
      SELECT item.value
      FROM jsonb_array_elements_text(packet_lineage -> 'deliveryRoots') WITH ORDINALITY AS item(value, ordinality)
      ORDER BY item.ordinality
    )) ||
    ',"enforcementRoots":' || audit.canonical_text_array(ARRAY(
      SELECT item.value
      FROM jsonb_array_elements_text(packet_lineage -> 'enforcementRoots') WITH ORDINALITY AS item(value, ordinality)
      ORDER BY item.ordinality
    )) ||
    ',"restrictionRoots":' || audit.canonical_text_array(ARRAY(
      SELECT item.value
      FROM jsonb_array_elements_text(packet_lineage -> 'restrictionRoots') WITH ORDINALITY AS item(value, ordinality)
      ORDER BY item.ordinality
    )) ||
    ',"usageRoots":' || audit.canonical_text_array(ARRAY(
      SELECT item.value
      FROM jsonb_array_elements_text(packet_lineage -> 'usageRoots') WITH ORDINALITY AS item(value, ordinality)
      ORDER BY item.ordinality
    )) ||
    '}';
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_packet_hash(
  packet_organization_id text,
  packet_request_id text,
  packet_agreement_id text,
  packet_generated_by text,
  packet_generated_at timestamptz,
  packet_intended_audience text,
  packet_request_status text,
  packet_request_hash text,
  packet_counts jsonb,
  packet_lineage jsonb
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"agreementId":' || to_json(packet_agreement_id)::text ||
        ',"counts":' || organizations.data_access_accountability_counts_canonical(packet_counts) ||
        ',"generatedAt":' || to_json(to_char(packet_generated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"generatedBy":' || to_json(packet_generated_by)::text ||
        ',"intendedAudience":' || to_json(packet_intended_audience)::text ||
        ',"kind":"canopyproof-data-access-accountability-packet-v1"' ||
        ',"lineageRoots":' || organizations.data_access_accountability_lineage_canonical(packet_lineage) ||
        ',"organizationId":' || to_json(packet_organization_id)::text ||
        ',"requestHash":' || to_json(packet_request_hash)::text ||
        ',"requestId":' || to_json(packet_request_id)::text ||
        ',"requestStatus":' || to_json(packet_request_status)::text ||
        ',"safety":' || organizations.data_access_accountability_packet_safety_canonical() ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_packet_root(
  packet_access_root text,
  packet_counts jsonb,
  packet_lineage jsonb,
  packet_hash_value text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"accessRoot":' || to_json(packet_access_root)::text ||
        ',"counts":' || organizations.data_access_accountability_counts_canonical(packet_counts) ||
        ',"kind":"canopyproof-data-access-accountability-root-v1"' ||
        ',"lineageRoots":' || organizations.data_access_accountability_lineage_canonical(packet_lineage) ||
        ',"packetHash":' || to_json(packet_hash_value)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_packet_payload_hash(
  packet_organization_id text,
  packet_request_id text,
  packet_agreement_id text,
  packet_generated_by text,
  packet_generated_at timestamptz,
  packet_intended_audience text,
  packet_request_status text,
  packet_request_hash text,
  packet_counts jsonb,
  packet_lineage jsonb,
  packet_hash_value text,
  packet_root_value text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"agreementId":' || to_json(packet_agreement_id)::text ||
        ',"counts":' || organizations.data_access_accountability_counts_canonical(packet_counts) ||
        ',"generatedAt":' || to_json(to_char(packet_generated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"generatedBy":' || to_json(packet_generated_by)::text ||
        ',"intendedAudience":' || to_json(packet_intended_audience)::text ||
        ',"lineageRoots":' || organizations.data_access_accountability_lineage_canonical(packet_lineage) ||
        ',"organizationId":' || to_json(packet_organization_id)::text ||
        ',"packetHash":' || to_json(packet_hash_value)::text ||
        ',"packetRoot":' || to_json(packet_root_value)::text ||
        ',"requestHash":' || to_json(packet_request_hash)::text ||
        ',"requestId":' || to_json(packet_request_id)::text ||
        ',"requestStatus":' || to_json(packet_request_status)::text ||
        ',"safety":' || organizations.data_access_accountability_packet_safety_canonical() ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_snapshot(
  snapshot_request_id text,
  packet_event_sequence bigint
)
RETURNS TABLE(request_status text, counts jsonb, lineage_roots jsonb)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  request_record organizations.data_access_requests%ROWTYPE;
  current_request_status text := 'pending';
  latest_restriction_state text;
  agreement_revocation_roots text[];
  agreement_supersession_roots text[];
  delivery_roots text[];
  usage_roots text[];
  enforcement_roots text[];
  restriction_roots text[];
BEGIN
  SELECT * INTO request_record
  FROM organizations.data_access_requests
  WHERE id = snapshot_request_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accountability packet request does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM audit.domain_events event
    WHERE event.event_root = request_record.audit_event_root
      AND event.stream_id = request_record.organization_id
      AND event.actor_id = request_record.requested_by
      AND event.entity_type = 'data_access_request'
      AND event.entity_id = request_record.id
      AND event.created_at = request_record.requested_at
      AND event.sequence_no < packet_event_sequence
  ) THEN
    RAISE EXCEPTION 'accountability packet request lacks prior exact semantic authority' USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM (
      SELECT decision.audit_event_root, decision.organization_id, decision.decision_by AS actor_id,
        'data_access_request_decision'::text AS entity_type, decision.id AS entity_id,
        decision.decided_at AS created_at,
        CASE WHEN decision.status = 'approved' THEN 'FULFILL' ELSE 'CHALLENGE' END AS event_action
      FROM organizations.data_access_request_decisions decision
      WHERE decision.request_id = request_record.id
      UNION ALL
      SELECT revocation.audit_event_root, revocation.organization_id, revocation.revoked_by,
        'data_sharing_agreement_revocation', revocation.id, revocation.revoked_at, 'CHALLENGE'
      FROM organizations.data_sharing_agreement_revocations revocation
      WHERE revocation.agreement_id = request_record.agreement_id
      UNION ALL
      SELECT supersession.audit_event_root, supersession.organization_id, supersession.superseded_by,
        'data_sharing_agreement_supersession', supersession.id, supersession.superseded_at, 'FULFILL'
      FROM organizations.data_sharing_agreement_supersessions supersession
      WHERE supersession.predecessor_agreement_id = request_record.agreement_id
         OR supersession.successor_agreement_id = request_record.agreement_id
      UNION ALL
      SELECT delivery.audit_event_root, delivery.organization_id, delivery.delivered_by,
        'data_access_delivery_receipt', delivery.id, delivery.delivered_at, 'FULFILL'
      FROM organizations.data_access_delivery_receipts delivery
      WHERE delivery.request_id = request_record.id
      UNION ALL
      SELECT attestation.audit_event_root, attestation.organization_id, attestation.attested_by,
        'data_use_attestation', attestation.id, attestation.attested_at,
        CASE WHEN attestation.usage_state IN ('within_scope', 'no_use') THEN 'ASSERT' ELSE 'CHALLENGE' END
      FROM organizations.data_use_attestations attestation
      WHERE attestation.request_id = request_record.id
      UNION ALL
      SELECT enforcement.audit_event_root, enforcement.organization_id, enforcement.reviewer_id,
        'data_use_enforcement_case', enforcement.id, enforcement.reviewed_at,
        CASE WHEN enforcement.case_state IN ('resolved', 'rejected') THEN 'FULFILL' ELSE 'CHALLENGE' END
      FROM organizations.data_use_enforcement_cases enforcement
      WHERE enforcement.request_id = request_record.id
      UNION ALL
      SELECT restriction.audit_event_root, restriction.organization_id, restriction.decided_by,
        'data_access_restriction', restriction.id, restriction.decided_at,
        CASE WHEN restriction.restriction_state = 'restored' THEN 'FULFILL' ELSE 'CHALLENGE' END
      FROM organizations.data_access_restrictions restriction
      WHERE restriction.request_id = request_record.id
    ) AS source
    LEFT JOIN audit.domain_events event
      ON event.event_root = source.audit_event_root
     AND event.stream_id = source.organization_id
     AND event.actor_id = source.actor_id
     AND event.entity_type = source.entity_type
     AND event.entity_id = source.entity_id
     AND event.created_at = source.created_at
     AND event.action = source.event_action
    WHERE source.organization_id <> request_record.organization_id OR event.event_root IS NULL
  ) THEN
    RAISE EXCEPTION 'accountability packet source lineage is not fully event-bound' USING ERRCODE = 'check_violation';
  END IF;

  SELECT decision.status INTO current_request_status
  FROM organizations.data_access_request_decisions decision
  JOIN audit.domain_events event ON event.event_root = decision.audit_event_root
  WHERE decision.request_id = request_record.id
    AND event.sequence_no < packet_event_sequence
  ORDER BY event.sequence_no DESC
  LIMIT 1;
  current_request_status := COALESCE(current_request_status, 'pending');

  agreement_revocation_roots := ARRAY(
    SELECT revocation.revocation_root
    FROM organizations.data_sharing_agreement_revocations revocation
    JOIN audit.domain_events event ON event.event_root = revocation.audit_event_root
    WHERE revocation.agreement_id = request_record.agreement_id
      AND event.sequence_no < packet_event_sequence
    ORDER BY revocation.revocation_root
  );
  agreement_supersession_roots := ARRAY(
    SELECT supersession.supersession_root
    FROM organizations.data_sharing_agreement_supersessions supersession
    JOIN audit.domain_events event ON event.event_root = supersession.audit_event_root
    WHERE (
      supersession.predecessor_agreement_id = request_record.agreement_id OR
      supersession.successor_agreement_id = request_record.agreement_id
    ) AND event.sequence_no < packet_event_sequence
    ORDER BY supersession.supersession_root
  );
  delivery_roots := ARRAY(
    SELECT delivery.delivery_root
    FROM organizations.data_access_delivery_receipts delivery
    JOIN audit.domain_events event ON event.event_root = delivery.audit_event_root
    WHERE delivery.request_id = request_record.id
      AND event.sequence_no < packet_event_sequence
    ORDER BY delivery.delivery_root
  );
  usage_roots := ARRAY(
    SELECT attestation.usage_root
    FROM organizations.data_use_attestations attestation
    JOIN audit.domain_events event ON event.event_root = attestation.audit_event_root
    WHERE attestation.request_id = request_record.id
      AND event.sequence_no < packet_event_sequence
    ORDER BY attestation.usage_root
  );
  enforcement_roots := ARRAY(
    SELECT enforcement.enforcement_root
    FROM organizations.data_use_enforcement_cases enforcement
    JOIN audit.domain_events event ON event.event_root = enforcement.audit_event_root
    WHERE enforcement.request_id = request_record.id
      AND event.sequence_no < packet_event_sequence
    ORDER BY enforcement.enforcement_root
  );
  restriction_roots := ARRAY(
    SELECT restriction.restriction_root
    FROM organizations.data_access_restrictions restriction
    JOIN audit.domain_events event ON event.event_root = restriction.audit_event_root
    WHERE restriction.request_id = request_record.id
      AND event.sequence_no < packet_event_sequence
    ORDER BY restriction.restriction_root
  );
  SELECT restriction.restriction_state INTO latest_restriction_state
  FROM organizations.data_access_restrictions restriction
  JOIN audit.domain_events event ON event.event_root = restriction.audit_event_root
  WHERE restriction.request_id = request_record.id
    AND event.sequence_no < packet_event_sequence
  ORDER BY event.sequence_no DESC
  LIMIT 1;

  RETURN QUERY SELECT
    current_request_status,
    jsonb_build_object(
      'agreementRevocationCount', cardinality(agreement_revocation_roots),
      'agreementSupersessionCount', cardinality(agreement_supersession_roots),
      'deliveryReceiptCount', cardinality(delivery_roots),
      'dataUseAttestationCount', cardinality(usage_roots),
      'enforcementCaseCount', cardinality(enforcement_roots),
      'activeRestrictionCount', CASE WHEN latest_restriction_state IS NOT NULL AND latest_restriction_state <> 'restored' THEN 1 ELSE 0 END,
      'totalRestrictionCount', cardinality(restriction_roots)
    ),
    jsonb_build_object(
      'accessRoot', request_record.access_root,
      'agreementRevocationRoots', to_jsonb(agreement_revocation_roots),
      'agreementSupersessionRoots', to_jsonb(agreement_supersession_roots),
      'deliveryRoots', to_jsonb(delivery_roots),
      'usageRoots', to_jsonb(usage_roots),
      'enforcementRoots', to_jsonb(enforcement_roots),
      'restrictionRoots', to_jsonb(restriction_roots)
    );
END;
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_access_accountability_packet_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  organization_record organizations.organizations%ROWTYPE;
  generator_record identity.participants%ROWTYPE;
  request_record organizations.data_access_requests%ROWTYPE;
  packet_event_sequence bigint;
  expected_snapshot record;
  expected_packet_hash text;
  expected_packet_root text;
  expected_payload_hash text;
  bound_payload_hash text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.generated_by THEN
    RAISE EXCEPTION 'accountability packet insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.intended_audience ~* '(BEGIN|END)[[:space:]]+(RSA |EC |OPENSSH |PRIVATE )?PRIVATE KEY' OR
    NEW.intended_audience ~* '(private[_ -]?key|api[_ -]?secret|access[_ -]?secret|password|[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})'
  THEN
    RAISE EXCEPTION 'accountability packet cannot embed private key, secret, or private contact material' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO organization_record
  FROM organizations.organizations
  WHERE id = NEW.organization_id
  FOR UPDATE;
  IF NOT FOUND OR organization_record.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'accountability packet requires a verified organization' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO generator_record
  FROM identity.participants
  WHERE id = NEW.generated_by
  FOR UPDATE;
  IF
    NOT FOUND OR
    generator_record.participant_type <> 'human' OR
    generator_record.verification_status <> 'verified' OR
    generator_record.organization_id IS DISTINCT FROM NEW.organization_id
  THEN
    RAISE EXCEPTION 'accountability packet requires a verified human generator in the governed organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.organization_id
      AND membership.actor_id = NEW.generated_by
      AND membership.status = 'active'
      AND membership.role IN ('owner', 'admin', 'verifier', 'researcher')
  ) THEN
    RAISE EXCEPTION 'accountability packet generator lacks an active institutional membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO request_record
  FROM organizations.data_access_requests
  WHERE id = NEW.request_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accountability packet request does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF request_record.organization_id <> NEW.organization_id OR request_record.agreement_id <> NEW.agreement_id THEN
    RAISE EXCEPTION 'accountability packet request and agreement lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.generated_at < request_record.requested_at THEN
    RAISE EXCEPTION 'accountability packet cannot predate its request' USING ERRCODE = 'check_violation';
  END IF;

  SELECT event.sequence_no, event.payload_hash
  INTO packet_event_sequence, bound_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root
    AND event.stream_id = NEW.organization_id
    AND event.actor_id = NEW.generated_by
    AND event.entity_type = 'data_access_accountability_packet'
    AND event.entity_id = NEW.id
    AND event.created_at = NEW.generated_at
    AND event.action = 'ASSERT';
  IF packet_event_sequence IS NULL THEN
    RAISE EXCEPTION 'accountability packet requires an exact prior semantic event' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO expected_snapshot
  FROM organizations.data_access_accountability_snapshot(NEW.request_id, packet_event_sequence);
  IF
    NEW.request_status IS DISTINCT FROM expected_snapshot.request_status OR
    NEW.counts IS DISTINCT FROM expected_snapshot.counts OR
    NEW.lineage_roots IS DISTINCT FROM expected_snapshot.lineage_roots
  THEN
    RAISE EXCEPTION 'accountability packet snapshot does not match the complete event-bound ledger prefix' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NOT organizations.data_access_accountability_counts_are_valid(NEW.counts) OR
    NOT organizations.data_access_accountability_lineage_roots_are_valid(NEW.lineage_roots) OR
    NEW.safety <> organizations.data_access_accountability_packet_safety_canonical()::jsonb
  THEN
    RAISE EXCEPTION 'accountability packet count, lineage, or safety boundary is invalid' USING ERRCODE = 'check_violation';
  END IF;

  expected_packet_hash := organizations.compute_data_access_accountability_packet_hash(
    NEW.organization_id,
    NEW.request_id,
    NEW.agreement_id,
    NEW.generated_by,
    NEW.generated_at,
    NEW.intended_audience,
    NEW.request_status,
    request_record.request_hash,
    NEW.counts,
    NEW.lineage_roots
  );
  IF NEW.packet_hash <> expected_packet_hash OR NEW.id <> 'cp_data_access_packet_' || left(expected_packet_hash, 24) THEN
    RAISE EXCEPTION 'accountability packet hash or identifier is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_packet_root := organizations.compute_data_access_accountability_packet_root(
    request_record.access_root,
    NEW.counts,
    NEW.lineage_roots,
    NEW.packet_hash
  );
  IF NEW.packet_root <> expected_packet_root THEN
    RAISE EXCEPTION 'accountability packet root is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_payload_hash := organizations.compute_data_access_accountability_packet_payload_hash(
    NEW.organization_id,
    NEW.request_id,
    NEW.agreement_id,
    NEW.generated_by,
    NEW.generated_at,
    NEW.intended_audience,
    NEW.request_status,
    request_record.request_hash,
    NEW.counts,
    NEW.lineage_roots,
    NEW.packet_hash,
    NEW.packet_root
  );
  IF bound_payload_hash IS DISTINCT FROM expected_payload_hash THEN
    RAISE EXCEPTION 'accountability packet semantic event payload does not match the canonical snapshot' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_access_accountability_packets_validate_insert ON organizations.data_access_accountability_packets;
CREATE TRIGGER organizations_data_access_accountability_packets_validate_insert
BEFORE INSERT ON organizations.data_access_accountability_packets
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_access_accountability_packet_insert();

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_verification_safety_canonical()
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT '{"hashOnlyLineage":true,"noPrivateContactData":true,"noRawDataEmbedded":true,"notCarbonCredit":true,"notFinalProofAuthority":true,"notFinancialAsset":true,"notGuaranteedYield":true,"notTaxOffset":true,"replayVerification":true}';
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_verification_root(
  verification_organization_id text,
  verification_packet_id text,
  verification_request_id text,
  verification_valid boolean,
  verification_issues text[],
  verification_expected_packet_root text,
  verification_packet_hash text,
  verification_recomputed_packet_hash text,
  verification_packet_root text,
  verification_recomputed_packet_root text,
  verification_verified_by text,
  verification_verified_at timestamptz
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"expectedPacketRoot":' || COALESCE(to_json(verification_expected_packet_root)::text, 'null') ||
        ',"issues":' || audit.canonical_text_array(verification_issues) ||
        ',"kind":"canopyproof-data-access-accountability-verification-v1"' ||
        ',"organizationId":' || to_json(verification_organization_id)::text ||
        ',"packetHash":' || to_json(verification_packet_hash)::text ||
        ',"packetId":' || to_json(verification_packet_id)::text ||
        ',"packetRoot":' || to_json(verification_packet_root)::text ||
        ',"recomputedPacketHash":' || to_json(verification_recomputed_packet_hash)::text ||
        ',"recomputedPacketRoot":' || to_json(verification_recomputed_packet_root)::text ||
        ',"requestId":' || to_json(verification_request_id)::text ||
        ',"safety":' || organizations.data_access_accountability_verification_safety_canonical() ||
        ',"valid":' || CASE WHEN verification_valid THEN 'true' ELSE 'false' END ||
        ',"verifiedAt":' || to_json(to_char(verification_verified_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"verifiedBy":' || to_json(verification_verified_by)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_verification_payload_hash(
  verification_organization_id text,
  verification_packet_id text,
  verification_request_id text,
  verification_valid boolean,
  verification_issues text[],
  verification_expected_packet_root text,
  verification_packet_hash text,
  verification_recomputed_packet_hash text,
  verification_packet_root text,
  verification_recomputed_packet_root text,
  verification_verified_by text,
  verification_verified_at timestamptz,
  verification_root_value text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"expectedPacketRoot":' || COALESCE(to_json(verification_expected_packet_root)::text, 'null') ||
        ',"issues":' || audit.canonical_text_array(verification_issues) ||
        ',"organizationId":' || to_json(verification_organization_id)::text ||
        ',"packetHash":' || to_json(verification_packet_hash)::text ||
        ',"packetId":' || to_json(verification_packet_id)::text ||
        ',"packetRoot":' || to_json(verification_packet_root)::text ||
        ',"recomputedPacketHash":' || to_json(verification_recomputed_packet_hash)::text ||
        ',"recomputedPacketRoot":' || to_json(verification_recomputed_packet_root)::text ||
        ',"requestId":' || to_json(verification_request_id)::text ||
        ',"safety":' || organizations.data_access_accountability_verification_safety_canonical() ||
        ',"valid":' || CASE WHEN verification_valid THEN 'true' ELSE 'false' END ||
        ',"verificationRoot":' || to_json(verification_root_value)::text ||
        ',"verifiedAt":' || to_json(to_char(verification_verified_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"verifiedBy":' || to_json(verification_verified_by)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_access_accountability_verification_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  organization_record organizations.organizations%ROWTYPE;
  verifier_record identity.participants%ROWTYPE;
  packet_record organizations.data_access_accountability_packets%ROWTYPE;
  request_record organizations.data_access_requests%ROWTYPE;
  packet_event_sequence bigint;
  verification_event_sequence bigint;
  packet_bound_payload_hash text;
  verification_bound_payload_hash text;
  packet_snapshot record;
  current_snapshot record;
  canonical_packet_hash text;
  canonical_packet_root text;
  canonical_packet_payload_hash text;
  current_packet_hash text;
  current_packet_root text;
  expected_issues text[] := ARRAY[]::text[];
  expected_valid boolean;
  expected_verification_root text;
  expected_verification_payload_hash text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.verified_by THEN
    RAISE EXCEPTION 'accountability verification insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO organization_record
  FROM organizations.organizations
  WHERE id = NEW.organization_id
  FOR UPDATE;
  IF NOT FOUND OR organization_record.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'accountability verification requires a verified organization' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO verifier_record
  FROM identity.participants
  WHERE id = NEW.verified_by
  FOR UPDATE;
  IF
    NOT FOUND OR
    verifier_record.participant_type <> 'human' OR
    verifier_record.verification_status <> 'verified' OR
    verifier_record.organization_id IS DISTINCT FROM NEW.organization_id
  THEN
    RAISE EXCEPTION 'accountability verification requires a verified human in the governed organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.organization_id
      AND membership.actor_id = NEW.verified_by
      AND membership.status = 'active'
      AND membership.role IN ('owner', 'admin', 'verifier', 'researcher', 'observer')
  ) THEN
    RAISE EXCEPTION 'accountability verifier lacks an active institutional membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO packet_record
  FROM organizations.data_access_accountability_packets
  WHERE id = NEW.packet_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accountability verification packet does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  SELECT * INTO request_record
  FROM organizations.data_access_requests
  WHERE id = packet_record.request_id
  FOR UPDATE;
  IF
    request_record.id IS NULL OR
    packet_record.organization_id <> NEW.organization_id OR
    packet_record.request_id <> NEW.request_id OR
    request_record.organization_id <> NEW.organization_id OR
    request_record.agreement_id <> packet_record.agreement_id
  THEN
    RAISE EXCEPTION 'accountability verification packet authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.verified_by = packet_record.generated_by THEN
    RAISE EXCEPTION 'accountability verification requires an actor independent from the packet generator' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.verified_at < packet_record.generated_at THEN
    RAISE EXCEPTION 'accountability verification cannot predate the packet' USING ERRCODE = 'check_violation';
  END IF;

  SELECT event.sequence_no, event.payload_hash
  INTO packet_event_sequence, packet_bound_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = packet_record.audit_event_root
    AND event.stream_id = packet_record.organization_id
    AND event.actor_id = packet_record.generated_by
    AND event.entity_type = 'data_access_accountability_packet'
    AND event.entity_id = packet_record.id
    AND event.created_at = packet_record.generated_at
    AND event.action = 'ASSERT';
  SELECT event.sequence_no, event.payload_hash
  INTO verification_event_sequence, verification_bound_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root
    AND event.stream_id = NEW.organization_id
    AND event.actor_id = NEW.verified_by
    AND event.entity_type = 'data_access_accountability_verification'
    AND event.entity_id = NEW.id
    AND event.created_at = NEW.verified_at
    AND event.action = CASE WHEN NEW.valid THEN 'ASSERT' ELSE 'CHALLENGE' END;
  IF
    packet_event_sequence IS NULL OR
    verification_event_sequence IS NULL OR
    verification_event_sequence <= packet_event_sequence
  THEN
    RAISE EXCEPTION 'accountability verification requires ordered exact semantic events' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO packet_snapshot
  FROM organizations.data_access_accountability_snapshot(packet_record.request_id, packet_event_sequence);
  canonical_packet_hash := organizations.compute_data_access_accountability_packet_hash(
    packet_record.organization_id,
    packet_record.request_id,
    packet_record.agreement_id,
    packet_record.generated_by,
    packet_record.generated_at,
    packet_record.intended_audience,
    packet_record.request_status,
    request_record.request_hash,
    packet_record.counts,
    packet_record.lineage_roots
  );
  canonical_packet_root := organizations.compute_data_access_accountability_packet_root(
    request_record.access_root,
    packet_record.counts,
    packet_record.lineage_roots,
    canonical_packet_hash
  );
  canonical_packet_payload_hash := organizations.compute_data_access_accountability_packet_payload_hash(
    packet_record.organization_id,
    packet_record.request_id,
    packet_record.agreement_id,
    packet_record.generated_by,
    packet_record.generated_at,
    packet_record.intended_audience,
    packet_record.request_status,
    request_record.request_hash,
    packet_record.counts,
    packet_record.lineage_roots,
    canonical_packet_hash,
    canonical_packet_root
  );
  IF
    packet_record.id <> 'cp_data_access_packet_' || left(canonical_packet_hash, 24) OR
    packet_record.packet_hash <> canonical_packet_hash OR
    packet_record.request_status IS DISTINCT FROM packet_snapshot.request_status OR
    packet_record.counts IS DISTINCT FROM packet_snapshot.counts OR
    packet_record.lineage_roots IS DISTINCT FROM packet_snapshot.lineage_roots OR
    packet_bound_payload_hash IS DISTINCT FROM canonical_packet_payload_hash
  THEN
    expected_issues := array_append(expected_issues, 'packet_hash_mismatch');
  END IF;
  IF packet_record.packet_root <> canonical_packet_root THEN
    expected_issues := array_append(expected_issues, 'packet_root_mismatch');
  END IF;

  SELECT * INTO current_snapshot
  FROM organizations.data_access_accountability_snapshot(packet_record.request_id, verification_event_sequence);
  current_packet_hash := organizations.compute_data_access_accountability_packet_hash(
    packet_record.organization_id,
    packet_record.request_id,
    packet_record.agreement_id,
    packet_record.generated_by,
    packet_record.generated_at,
    packet_record.intended_audience,
    current_snapshot.request_status,
    request_record.request_hash,
    current_snapshot.counts,
    current_snapshot.lineage_roots
  );
  current_packet_root := organizations.compute_data_access_accountability_packet_root(
    request_record.access_root,
    current_snapshot.counts,
    current_snapshot.lineage_roots,
    current_packet_hash
  );
  IF packet_record.packet_hash <> current_packet_hash OR packet_record.packet_root <> current_packet_root THEN
    expected_issues := array_append(expected_issues, 'lineage_stale');
  END IF;
  IF NEW.expected_packet_root IS NOT NULL AND NEW.expected_packet_root <> packet_record.packet_root THEN
    expected_issues := array_append(expected_issues, 'expected_root_mismatch');
  END IF;
  IF packet_record.safety <> organizations.data_access_accountability_packet_safety_canonical()::jsonb THEN
    expected_issues := array_append(expected_issues, 'safety_boundary_violation');
  END IF;
  expected_issues := ARRAY(SELECT DISTINCT issue FROM unnest(expected_issues) AS issue ORDER BY issue);
  expected_valid := cardinality(expected_issues) = 0;

  IF
    NEW.valid IS DISTINCT FROM expected_valid OR
    NEW.issues IS DISTINCT FROM expected_issues OR
    NEW.packet_hash <> packet_record.packet_hash OR
    NEW.recomputed_packet_hash <> current_packet_hash OR
    NEW.packet_root <> packet_record.packet_root OR
    NEW.recomputed_packet_root <> current_packet_root OR
    NEW.safety <> organizations.data_access_accountability_verification_safety_canonical()::jsonb
  THEN
    RAISE EXCEPTION 'accountability verification fields do not match database-derived replay' USING ERRCODE = 'check_violation';
  END IF;

  expected_verification_root := organizations.compute_data_access_accountability_verification_root(
    NEW.organization_id,
    NEW.packet_id,
    NEW.request_id,
    NEW.valid,
    NEW.issues,
    NEW.expected_packet_root,
    NEW.packet_hash,
    NEW.recomputed_packet_hash,
    NEW.packet_root,
    NEW.recomputed_packet_root,
    NEW.verified_by,
    NEW.verified_at
  );
  IF
    NEW.verification_root <> expected_verification_root OR
    NEW.id <> 'cp_data_access_packet_verification_' || left(expected_verification_root, 24)
  THEN
    RAISE EXCEPTION 'accountability verification root or identifier is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_verification_payload_hash := organizations.compute_data_access_accountability_verification_payload_hash(
    NEW.organization_id,
    NEW.packet_id,
    NEW.request_id,
    NEW.valid,
    NEW.issues,
    NEW.expected_packet_root,
    NEW.packet_hash,
    NEW.recomputed_packet_hash,
    NEW.packet_root,
    NEW.recomputed_packet_root,
    NEW.verified_by,
    NEW.verified_at,
    NEW.verification_root
  );
  IF verification_bound_payload_hash IS DISTINCT FROM expected_verification_payload_hash THEN
    RAISE EXCEPTION 'accountability verification semantic event payload does not match database replay' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_access_accountability_verifications_validate_insert ON organizations.data_access_accountability_verifications;
CREATE TRIGGER organizations_data_access_accountability_verifications_validate_insert
BEFORE INSERT ON organizations.data_access_accountability_verifications
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_access_accountability_verification_insert();

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_disclosure_safety_canonical()
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT '{"appendOnly":true,"hashOnly":true,"independentPublicationRequired":true,"noPrivateContactData":true,"noRawDataEmbedded":true,"notCarbonCredit":true,"notFinalProofAuthority":true,"notFinancialAsset":true,"notGuaranteedYield":true,"notTaxOffset":true,"observerDiscoverable":true,"packetBound":true,"validReplayRequired":true}'::text;
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_disclosure_hash(
  disclosure_organization_id text,
  disclosure_packet_id text,
  disclosure_packet_hash text,
  disclosure_packet_root text,
  disclosure_verification_id text,
  disclosure_verification_root text,
  disclosure_policy_id text,
  disclosure_published_by text,
  disclosure_published_at timestamptz
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"kind":"canopyproof-data-access-accountability-disclosure-v1"' ||
        ',"organizationId":' || to_json(disclosure_organization_id)::text ||
        ',"packetHash":' || to_json(disclosure_packet_hash)::text ||
        ',"packetId":' || to_json(disclosure_packet_id)::text ||
        ',"packetRoot":' || to_json(disclosure_packet_root)::text ||
        ',"policyId":' || to_json(disclosure_policy_id)::text ||
        ',"publishedAt":' || to_json(to_char(disclosure_published_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"publishedBy":' || to_json(disclosure_published_by)::text ||
        ',"safety":' || organizations.data_access_accountability_disclosure_safety_canonical() ||
        ',"verificationId":' || to_json(disclosure_verification_id)::text ||
        ',"verificationRoot":' || to_json(disclosure_verification_root)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_disclosure_root(
  disclosure_hash_value text,
  disclosure_packet_root text,
  disclosure_verification_root text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"disclosureHash":' || to_json(disclosure_hash_value)::text ||
        ',"kind":"canopyproof-data-access-accountability-disclosure-root-v1"' ||
        ',"packetRoot":' || to_json(disclosure_packet_root)::text ||
        ',"verificationRoot":' || to_json(disclosure_verification_root)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_disclosure_payload_hash(
  disclosure_organization_id text,
  disclosure_packet_id text,
  disclosure_packet_hash text,
  disclosure_packet_root text,
  disclosure_verification_id text,
  disclosure_verification_root text,
  disclosure_policy_id text,
  disclosure_published_by text,
  disclosure_published_at timestamptz,
  disclosure_hash_value text,
  disclosure_root_value text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"disclosureHash":' || to_json(disclosure_hash_value)::text ||
        ',"disclosureRoot":' || to_json(disclosure_root_value)::text ||
        ',"organizationId":' || to_json(disclosure_organization_id)::text ||
        ',"packetHash":' || to_json(disclosure_packet_hash)::text ||
        ',"packetId":' || to_json(disclosure_packet_id)::text ||
        ',"packetRoot":' || to_json(disclosure_packet_root)::text ||
        ',"policyId":' || to_json(disclosure_policy_id)::text ||
        ',"publishedAt":' || to_json(to_char(disclosure_published_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"publishedBy":' || to_json(disclosure_published_by)::text ||
        ',"safety":' || organizations.data_access_accountability_disclosure_safety_canonical() ||
        ',"verificationId":' || to_json(disclosure_verification_id)::text ||
        ',"verificationRoot":' || to_json(disclosure_verification_root)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_access_accountability_disclosure()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  organization_record organizations.organizations%ROWTYPE;
  publisher_record identity.participants%ROWTYPE;
  packet_record organizations.data_access_accountability_packets%ROWTYPE;
  verification_record organizations.data_access_accountability_verifications%ROWTYPE;
  request_record organizations.data_access_requests%ROWTYPE;
  packet_event_sequence bigint;
  verification_event_sequence bigint;
  disclosure_event_sequence bigint;
  packet_bound_payload_hash text;
  verification_bound_payload_hash text;
  disclosure_bound_payload_hash text;
  packet_snapshot record;
  verification_snapshot record;
  disclosure_snapshot record;
  canonical_packet_hash text;
  canonical_packet_root text;
  canonical_packet_payload_hash text;
  verification_packet_hash text;
  verification_packet_root text;
  canonical_verification_root text;
  canonical_verification_payload_hash text;
  disclosure_packet_hash text;
  disclosure_packet_root text;
  expected_disclosure_hash text;
  expected_disclosure_root text;
  expected_disclosure_payload_hash text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.published_by THEN
    RAISE EXCEPTION 'accountability disclosure insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO organization_record
  FROM organizations.organizations
  WHERE id = NEW.organization_id
  FOR UPDATE;
  IF NOT FOUND OR organization_record.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'accountability disclosure requires a verified organization' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO publisher_record
  FROM identity.participants
  WHERE id = NEW.published_by
  FOR UPDATE;
  IF
    NOT FOUND OR
    publisher_record.participant_type <> 'human' OR
    publisher_record.verification_status <> 'verified' OR
    publisher_record.organization_id IS DISTINCT FROM NEW.organization_id
  THEN
    RAISE EXCEPTION 'accountability disclosure requires a verified human in the governed organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.organization_id
      AND membership.actor_id = NEW.published_by
      AND membership.status = 'active'
      AND membership.role IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'accountability disclosure publisher lacks active owner or admin membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO packet_record
  FROM organizations.data_access_accountability_packets
  WHERE id = NEW.packet_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accountability disclosure packet does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  SELECT * INTO verification_record
  FROM organizations.data_access_accountability_verifications
  WHERE id = NEW.verification_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accountability disclosure verification does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  SELECT * INTO request_record
  FROM organizations.data_access_requests
  WHERE id = packet_record.request_id
  FOR UPDATE;
  IF
    request_record.id IS NULL OR
    packet_record.organization_id <> NEW.organization_id OR
    request_record.organization_id <> NEW.organization_id OR
    request_record.agreement_id <> packet_record.agreement_id OR
    verification_record.organization_id <> NEW.organization_id OR
    verification_record.packet_id <> packet_record.id OR
    verification_record.request_id <> request_record.id
  THEN
    RAISE EXCEPTION 'accountability disclosure source authority lineage mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF
    packet_record.generated_by = verification_record.verified_by OR
    packet_record.generated_by = NEW.published_by OR
    verification_record.verified_by = NEW.published_by
  THEN
    RAISE EXCEPTION 'accountability disclosure requires three separate human actors' USING ERRCODE = 'check_violation';
  END IF;
  IF verification_record.verified_at < packet_record.generated_at OR NEW.published_at < verification_record.verified_at THEN
    RAISE EXCEPTION 'accountability disclosure chronology is invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT event.sequence_no, event.payload_hash
  INTO packet_event_sequence, packet_bound_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = packet_record.audit_event_root
    AND event.stream_id = packet_record.organization_id
    AND event.actor_id = packet_record.generated_by
    AND event.entity_type = 'data_access_accountability_packet'
    AND event.entity_id = packet_record.id
    AND event.created_at = packet_record.generated_at
    AND event.action = 'ASSERT';
  SELECT event.sequence_no, event.payload_hash
  INTO verification_event_sequence, verification_bound_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = verification_record.audit_event_root
    AND event.stream_id = verification_record.organization_id
    AND event.actor_id = verification_record.verified_by
    AND event.entity_type = 'data_access_accountability_verification'
    AND event.entity_id = verification_record.id
    AND event.created_at = verification_record.verified_at
    AND event.action = 'ASSERT';
  SELECT event.sequence_no, event.payload_hash
  INTO disclosure_event_sequence, disclosure_bound_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root
    AND event.stream_id = NEW.organization_id
    AND event.actor_id = NEW.published_by
    AND event.entity_type = 'data_access_accountability_disclosure'
    AND event.entity_id = NEW.id
    AND event.created_at = NEW.published_at
    AND event.action = 'FULFILL';
  IF
    packet_event_sequence IS NULL OR
    verification_event_sequence IS NULL OR
    disclosure_event_sequence IS NULL OR
    verification_event_sequence <= packet_event_sequence OR
    disclosure_event_sequence <= verification_event_sequence
  THEN
    RAISE EXCEPTION 'accountability disclosure requires strictly ordered exact semantic events' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO packet_snapshot
  FROM organizations.data_access_accountability_snapshot(packet_record.request_id, packet_event_sequence);
  canonical_packet_hash := organizations.compute_data_access_accountability_packet_hash(
    packet_record.organization_id,
    packet_record.request_id,
    packet_record.agreement_id,
    packet_record.generated_by,
    packet_record.generated_at,
    packet_record.intended_audience,
    packet_record.request_status,
    request_record.request_hash,
    packet_record.counts,
    packet_record.lineage_roots
  );
  canonical_packet_root := organizations.compute_data_access_accountability_packet_root(
    request_record.access_root,
    packet_record.counts,
    packet_record.lineage_roots,
    canonical_packet_hash
  );
  canonical_packet_payload_hash := organizations.compute_data_access_accountability_packet_payload_hash(
    packet_record.organization_id,
    packet_record.request_id,
    packet_record.agreement_id,
    packet_record.generated_by,
    packet_record.generated_at,
    packet_record.intended_audience,
    packet_record.request_status,
    request_record.request_hash,
    packet_record.counts,
    packet_record.lineage_roots,
    canonical_packet_hash,
    canonical_packet_root
  );
  IF
    packet_record.id <> 'cp_data_access_packet_' || left(canonical_packet_hash, 24) OR
    packet_record.packet_hash <> canonical_packet_hash OR
    packet_record.packet_root <> canonical_packet_root OR
    packet_record.request_status IS DISTINCT FROM packet_snapshot.request_status OR
    packet_record.counts IS DISTINCT FROM packet_snapshot.counts OR
    packet_record.lineage_roots IS DISTINCT FROM packet_snapshot.lineage_roots OR
    packet_record.safety <> organizations.data_access_accountability_packet_safety_canonical()::jsonb OR
    packet_bound_payload_hash IS DISTINCT FROM canonical_packet_payload_hash
  THEN
    RAISE EXCEPTION 'accountability disclosure packet is not canonical at creation' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO verification_snapshot
  FROM organizations.data_access_accountability_snapshot(packet_record.request_id, verification_event_sequence);
  verification_packet_hash := organizations.compute_data_access_accountability_packet_hash(
    packet_record.organization_id,
    packet_record.request_id,
    packet_record.agreement_id,
    packet_record.generated_by,
    packet_record.generated_at,
    packet_record.intended_audience,
    verification_snapshot.request_status,
    request_record.request_hash,
    verification_snapshot.counts,
    verification_snapshot.lineage_roots
  );
  verification_packet_root := organizations.compute_data_access_accountability_packet_root(
    request_record.access_root,
    verification_snapshot.counts,
    verification_snapshot.lineage_roots,
    verification_packet_hash
  );
  canonical_verification_root := organizations.compute_data_access_accountability_verification_root(
    verification_record.organization_id,
    verification_record.packet_id,
    verification_record.request_id,
    verification_record.valid,
    verification_record.issues,
    verification_record.expected_packet_root,
    verification_record.packet_hash,
    verification_record.recomputed_packet_hash,
    verification_record.packet_root,
    verification_record.recomputed_packet_root,
    verification_record.verified_by,
    verification_record.verified_at
  );
  canonical_verification_payload_hash := organizations.compute_data_access_accountability_verification_payload_hash(
    verification_record.organization_id,
    verification_record.packet_id,
    verification_record.request_id,
    verification_record.valid,
    verification_record.issues,
    verification_record.expected_packet_root,
    verification_record.packet_hash,
    verification_record.recomputed_packet_hash,
    verification_record.packet_root,
    verification_record.recomputed_packet_root,
    verification_record.verified_by,
    verification_record.verified_at,
    canonical_verification_root
  );
  IF
    verification_record.valid IS DISTINCT FROM true OR
    verification_record.issues IS DISTINCT FROM ARRAY[]::text[] OR
    (verification_record.expected_packet_root IS NOT NULL AND verification_record.expected_packet_root <> packet_record.packet_root) OR
    verification_record.packet_hash <> packet_record.packet_hash OR
    verification_record.recomputed_packet_hash <> packet_record.packet_hash OR
    verification_record.packet_root <> packet_record.packet_root OR
    verification_record.recomputed_packet_root <> packet_record.packet_root OR
    verification_packet_hash <> packet_record.packet_hash OR
    verification_packet_root <> packet_record.packet_root OR
    verification_record.safety <> organizations.data_access_accountability_verification_safety_canonical()::jsonb OR
    verification_record.verification_root <> canonical_verification_root OR
    verification_record.id <> 'cp_data_access_packet_verification_' || left(canonical_verification_root, 24) OR
    verification_bound_payload_hash IS DISTINCT FROM canonical_verification_payload_hash
  THEN
    RAISE EXCEPTION 'accountability disclosure requires a canonical current replay verification' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO disclosure_snapshot
  FROM organizations.data_access_accountability_snapshot(packet_record.request_id, disclosure_event_sequence);
  disclosure_packet_hash := organizations.compute_data_access_accountability_packet_hash(
    packet_record.organization_id,
    packet_record.request_id,
    packet_record.agreement_id,
    packet_record.generated_by,
    packet_record.generated_at,
    packet_record.intended_audience,
    disclosure_snapshot.request_status,
    request_record.request_hash,
    disclosure_snapshot.counts,
    disclosure_snapshot.lineage_roots
  );
  disclosure_packet_root := organizations.compute_data_access_accountability_packet_root(
    request_record.access_root,
    disclosure_snapshot.counts,
    disclosure_snapshot.lineage_roots,
    disclosure_packet_hash
  );
  IF disclosure_packet_hash <> packet_record.packet_hash OR disclosure_packet_root <> packet_record.packet_root THEN
    RAISE EXCEPTION 'accountability disclosure packet lineage is stale at publication' USING ERRCODE = 'check_violation';
  END IF;

  IF
    NEW.packet_hash <> packet_record.packet_hash OR
    NEW.packet_root <> packet_record.packet_root OR
    NEW.verification_root <> verification_record.verification_root OR
    NEW.policy_id <> 'canopyproof_policy_partner_accountability_disclosure_v1' OR
    NEW.safety <> organizations.data_access_accountability_disclosure_safety_canonical()::jsonb
  THEN
    RAISE EXCEPTION 'accountability disclosure fields do not match database-derived authority' USING ERRCODE = 'check_violation';
  END IF;
  expected_disclosure_hash := organizations.compute_data_access_accountability_disclosure_hash(
    NEW.organization_id,
    NEW.packet_id,
    NEW.packet_hash,
    NEW.packet_root,
    NEW.verification_id,
    NEW.verification_root,
    NEW.policy_id,
    NEW.published_by,
    NEW.published_at
  );
  expected_disclosure_root := organizations.compute_data_access_accountability_disclosure_root(
    expected_disclosure_hash,
    NEW.packet_root,
    NEW.verification_root
  );
  IF
    NEW.disclosure_hash <> expected_disclosure_hash OR
    NEW.disclosure_root <> expected_disclosure_root OR
    NEW.id <> 'cp_data_access_disclosure_' || left(expected_disclosure_hash, 24)
  THEN
    RAISE EXCEPTION 'accountability disclosure hash, root, or identifier is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_disclosure_payload_hash := organizations.compute_data_access_accountability_disclosure_payload_hash(
    NEW.organization_id,
    NEW.packet_id,
    NEW.packet_hash,
    NEW.packet_root,
    NEW.verification_id,
    NEW.verification_root,
    NEW.policy_id,
    NEW.published_by,
    NEW.published_at,
    NEW.disclosure_hash,
    NEW.disclosure_root
  );
  IF disclosure_bound_payload_hash IS DISTINCT FROM expected_disclosure_payload_hash THEN
    RAISE EXCEPTION 'accountability disclosure semantic event payload does not match database replay' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS organizations_data_access_accountability_disclosures_validate ON organizations.data_access_accountability_disclosures;
CREATE TRIGGER organizations_data_access_accountability_disclosures_validate
BEFORE INSERT ON organizations.data_access_accountability_disclosures
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_access_accountability_disclosure();

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_disclosure_challenge_safety_canonical()
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT '{"appendOnly":true,"disclosureBound":true,"humanResolutionRequired":true,"noPrivateContactData":true,"noRawDataEmbedded":true,"notCarbonCredit":true,"notFinalProofAuthority":true,"notFinancialAsset":true,"notGuaranteedYield":true,"notTaxOffset":true,"publicStatement":true}'::text;
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_disclosure_challenge_hash(
  challenge_organization_id text,
  challenge_disclosure_id text,
  challenge_disclosure_root text,
  challenge_reason text,
  challenge_statement text,
  challenge_evidence_event_roots text[],
  challenge_challenged_by text,
  challenge_challenger_role text,
  challenge_challenged_at timestamptz
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"challengedAt":' || to_json(to_char(challenge_challenged_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"challengedBy":' || to_json(challenge_challenged_by)::text ||
        ',"challengerRole":' || to_json(challenge_challenger_role)::text ||
        ',"disclosureId":' || to_json(challenge_disclosure_id)::text ||
        ',"disclosureRoot":' || to_json(challenge_disclosure_root)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(challenge_evidence_event_roots) ||
        ',"kind":"canopyproof-data-access-accountability-disclosure-challenge-v1"' ||
        ',"organizationId":' || to_json(challenge_organization_id)::text ||
        ',"reason":' || to_json(challenge_reason)::text ||
        ',"safety":' || organizations.data_access_accountability_disclosure_challenge_safety_canonical() ||
        ',"statement":' || to_json(challenge_statement)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_disclosure_challenge_root(
  challenge_hash_value text,
  challenge_disclosure_root text,
  challenge_evidence_event_roots text[]
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"challengeHash":' || to_json(challenge_hash_value)::text ||
        ',"disclosureRoot":' || to_json(challenge_disclosure_root)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(challenge_evidence_event_roots) ||
        ',"kind":"canopyproof-data-access-accountability-disclosure-challenge-root-v1"' ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_disclosure_challenge_payload_hash(
  challenge_organization_id text,
  challenge_disclosure_id text,
  challenge_disclosure_root text,
  challenge_reason text,
  challenge_statement text,
  challenge_evidence_event_roots text[],
  challenge_challenged_by text,
  challenge_challenger_role text,
  challenge_challenged_at timestamptz,
  challenge_hash_value text,
  challenge_root_value text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"challengeHash":' || to_json(challenge_hash_value)::text ||
        ',"challengeRoot":' || to_json(challenge_root_value)::text ||
        ',"challengedAt":' || to_json(to_char(challenge_challenged_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"challengedBy":' || to_json(challenge_challenged_by)::text ||
        ',"challengerRole":' || to_json(challenge_challenger_role)::text ||
        ',"disclosureId":' || to_json(challenge_disclosure_id)::text ||
        ',"disclosureRoot":' || to_json(challenge_disclosure_root)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(challenge_evidence_event_roots) ||
        ',"organizationId":' || to_json(challenge_organization_id)::text ||
        ',"reason":' || to_json(challenge_reason)::text ||
        ',"safety":' || organizations.data_access_accountability_disclosure_challenge_safety_canonical() ||
        ',"statement":' || to_json(challenge_statement)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_access_accountability_disclosure_challenge()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  disclosure_record organizations.data_access_accountability_disclosures%ROWTYPE;
  challenger_record identity.participants%ROWTYPE;
  challenger_organization organizations.organizations%ROWTYPE;
  disclosure_event_sequence bigint;
  challenge_event_sequence bigint;
  challenge_bound_payload_hash text;
  expected_challenge_hash text;
  expected_challenge_root text;
  expected_challenge_payload_hash text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.challenged_by THEN
    RAISE EXCEPTION 'accountability disclosure challenge insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO challenger_record
  FROM identity.participants
  WHERE id = NEW.challenged_by
  FOR UPDATE;
  IF
    NOT FOUND OR
    challenger_record.participant_type <> 'human' OR
    challenger_record.verification_status <> 'verified' OR
    challenger_record.organization_id IS NULL OR
    NOT (NEW.challenger_role = ANY(challenger_record.roles))
  THEN
    RAISE EXCEPTION 'accountability disclosure challenge requires a verified human with the claimed durable role' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO challenger_organization
  FROM organizations.organizations
  WHERE id = challenger_record.organization_id
  FOR UPDATE;
  IF NOT FOUND OR challenger_organization.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'accountability disclosure challenger organization must be verified' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = challenger_record.organization_id
      AND membership.actor_id = NEW.challenged_by
      AND membership.status = 'active'
      AND membership.role = NEW.challenger_role
  ) THEN
    RAISE EXCEPTION 'accountability disclosure challenger lacks an active role membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO disclosure_record
  FROM organizations.data_access_accountability_disclosures
  WHERE id = NEW.disclosure_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accountability disclosure challenge target does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF
    disclosure_record.organization_id <> NEW.organization_id OR
    disclosure_record.disclosure_root <> NEW.disclosure_root OR
    NEW.challenged_at < disclosure_record.published_at
  THEN
    RAISE EXCEPTION 'accountability disclosure challenge publication binding is invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT event.sequence_no
  INTO disclosure_event_sequence
  FROM audit.domain_events event
  WHERE event.event_root = disclosure_record.audit_event_root
    AND event.stream_id = disclosure_record.organization_id
    AND event.actor_id = disclosure_record.published_by
    AND event.entity_type = 'data_access_accountability_disclosure'
    AND event.entity_id = disclosure_record.id
    AND event.created_at = disclosure_record.published_at
    AND event.action = 'FULFILL';
  SELECT event.sequence_no, event.payload_hash
  INTO challenge_event_sequence, challenge_bound_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root
    AND event.stream_id = NEW.organization_id
    AND event.actor_id = NEW.challenged_by
    AND event.entity_type = 'data_access_accountability_disclosure_challenge'
    AND event.entity_id = NEW.id
    AND event.created_at = NEW.challenged_at
    AND event.action = 'CHALLENGE';
  IF
    disclosure_event_sequence IS NULL OR
    challenge_event_sequence IS NULL OR
    challenge_event_sequence <= disclosure_event_sequence
  THEN
    RAISE EXCEPTION 'accountability disclosure challenge requires ordered exact semantic events' USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(NEW.evidence_event_roots) AS evidence_root
    LEFT JOIN audit.domain_events evidence_event ON evidence_event.event_root = evidence_root
    WHERE
      evidence_event.event_root IS NULL OR
      evidence_event.event_root = NEW.audit_event_root OR
      evidence_event.created_at > NEW.challenged_at OR
      (
        evidence_event.stream_id = NEW.organization_id AND
        evidence_event.sequence_no >= challenge_event_sequence
      )
  ) THEN
    RAISE EXCEPTION 'accountability disclosure challenge evidence roots must bind prior semantic events' USING ERRCODE = 'check_violation';
  END IF;

  IF
    NEW.statement ~* '(private[_ -]?key|api[_ -]?secret|access[_ -]?secret|client[_ -]?secret|password|[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}|\+?[0-9][0-9 ().-]{7,}[0-9])'
  THEN
    RAISE EXCEPTION 'accountability disclosure challenge cannot embed private key, secret, or private contact material' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.statement ~* '(certified[[:space:]]+carbon[[:space:]]+credit|carbon[-[:space:]]?tax[[:space:]]+offset|guaranteed[[:space:]]+(rwa[[:space:]]+)?yield|automatic[[:space:]]+\$?canopy[[:space:]]+distribution)' AND
    NEW.statement !~* '(^|[^[:alnum:]_])not([^[:alnum:]_]|$)'
  THEN
    RAISE EXCEPTION 'accountability disclosure challenge contains an unsupported public claim' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.safety <> organizations.data_access_accountability_disclosure_challenge_safety_canonical()::jsonb THEN
    RAISE EXCEPTION 'accountability disclosure challenge safety boundary is not canonical' USING ERRCODE = 'check_violation';
  END IF;

  expected_challenge_hash := organizations.compute_data_access_accountability_disclosure_challenge_hash(
    NEW.organization_id,
    NEW.disclosure_id,
    NEW.disclosure_root,
    NEW.reason,
    NEW.statement,
    NEW.evidence_event_roots,
    NEW.challenged_by,
    NEW.challenger_role,
    NEW.challenged_at
  );
  expected_challenge_root := organizations.compute_data_access_accountability_disclosure_challenge_root(
    expected_challenge_hash,
    NEW.disclosure_root,
    NEW.evidence_event_roots
  );
  IF
    NEW.challenge_hash <> expected_challenge_hash OR
    NEW.challenge_root <> expected_challenge_root OR
    NEW.id <> 'cp_data_access_disclosure_challenge_' || left(expected_challenge_hash, 24)
  THEN
    RAISE EXCEPTION 'accountability disclosure challenge hash, root, or identifier is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_challenge_payload_hash := organizations.compute_data_access_accountability_disclosure_challenge_payload_hash(
    NEW.organization_id,
    NEW.disclosure_id,
    NEW.disclosure_root,
    NEW.reason,
    NEW.statement,
    NEW.evidence_event_roots,
    NEW.challenged_by,
    NEW.challenger_role,
    NEW.challenged_at,
    NEW.challenge_hash,
    NEW.challenge_root
  );
  IF challenge_bound_payload_hash IS DISTINCT FROM expected_challenge_payload_hash THEN
    RAISE EXCEPTION 'accountability disclosure challenge semantic event payload does not match canonical fields' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS org_data_access_disclosure_challenge_validate ON organizations.data_access_accountability_disclosure_challenges;
CREATE TRIGGER org_data_access_disclosure_challenge_validate
BEFORE INSERT ON organizations.data_access_accountability_disclosure_challenges
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_access_accountability_disclosure_challenge();

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_disclosure_resolution_safety_canonical()
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT '{"appendOnly":true,"challengeBound":true,"historyPreserved":true,"independentHumanReviewRequired":true,"noAutomatedFinalAuthority":true,"noPrivateContactData":true,"noRawDataEmbedded":true,"notCarbonCredit":true,"notFinalProofAuthority":true,"notFinancialAsset":true,"notGuaranteedYield":true,"notTaxOffset":true}'::text;
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_disclosure_resolution_hash(
  resolution_organization_id text,
  resolution_disclosure_id text,
  resolution_challenge_id text,
  resolution_decision text,
  resolution_remedial_action text,
  resolution_rationale text,
  resolution_evidence_event_roots text[],
  resolution_previous_id text,
  resolution_previous_root text,
  resolution_reviewed_by text,
  resolution_reviewer_role text,
  resolution_reviewed_at timestamptz
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"challengeId":' || to_json(resolution_challenge_id)::text ||
        ',"decision":' || to_json(resolution_decision)::text ||
        ',"disclosureId":' || to_json(resolution_disclosure_id)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(resolution_evidence_event_roots) ||
        ',"kind":"canopyproof-data-access-accountability-disclosure-resolution-v1"' ||
        ',"organizationId":' || to_json(resolution_organization_id)::text ||
        CASE WHEN resolution_previous_id IS NULL
          THEN ''
          ELSE ',"previousResolutionId":' || to_json(resolution_previous_id)::text
        END ||
        ',"previousResolutionRoot":' || COALESCE(to_json(resolution_previous_root)::text, 'null') ||
        ',"rationale":' || to_json(resolution_rationale)::text ||
        ',"remedialAction":' || to_json(resolution_remedial_action)::text ||
        ',"reviewedAt":' || to_json(to_char(resolution_reviewed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"reviewedBy":' || to_json(resolution_reviewed_by)::text ||
        ',"reviewerRole":' || to_json(resolution_reviewer_role)::text ||
        ',"safety":' || organizations.data_access_accountability_disclosure_resolution_safety_canonical() ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_disclosure_resolution_root(
  resolution_challenge_root text,
  resolution_evidence_event_roots text[],
  resolution_previous_root text,
  resolution_hash_value text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"challengeRoot":' || to_json(resolution_challenge_root)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(resolution_evidence_event_roots) ||
        ',"kind":"canopyproof-data-access-accountability-disclosure-resolution-root-v1"' ||
        ',"previousResolutionRoot":' || COALESCE(to_json(resolution_previous_root)::text, 'null') ||
        ',"resolutionHash":' || to_json(resolution_hash_value)::text ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_disclosure_resolution_payload_hash(
  resolution_organization_id text,
  resolution_disclosure_id text,
  resolution_challenge_id text,
  resolution_decision text,
  resolution_remedial_action text,
  resolution_rationale text,
  resolution_evidence_event_roots text[],
  resolution_previous_id text,
  resolution_previous_root text,
  resolution_reviewed_by text,
  resolution_reviewer_role text,
  resolution_reviewed_at timestamptz,
  resolution_hash_value text,
