)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"challengeId":' || to_json(resolution_challenge_id)::text ||
        ',"decision":' || to_json(resolution_decision)::text ||
        ',"disclosureId":' || to_json(resolution_disclosure_id)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(resolution_evidence_event_roots) ||
        ',"organizationId":' || to_json(resolution_organization_id)::text ||
        CASE WHEN resolution_previous_id IS NULL
          THEN ''
          ELSE ',"previousResolutionId":' || to_json(resolution_previous_id)::text
        END ||
        ',"previousResolutionRoot":' || COALESCE(to_json(resolution_previous_root)::text, 'null') ||
        ',"rationale":' || to_json(resolution_rationale)::text ||
        ',"remedialAction":' || to_json(resolution_remedial_action)::text ||
        ',"resolutionHash":' || to_json(resolution_hash_value)::text ||
        ',"resolutionRoot":' || to_json(resolution_root_value)::text ||
        ',"reviewedAt":' || to_json(to_char(resolution_reviewed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"reviewedBy":' || to_json(resolution_reviewed_by)::text ||
        ',"reviewerRole":' || to_json(resolution_reviewer_role)::text ||
        ',"safety":' || organizations.data_access_accountability_disclosure_resolution_safety_canonical() ||
        '}',
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_access_accountability_disclosure_resolution()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  organization_record organizations.organizations%ROWTYPE;
  reviewer_record identity.participants%ROWTYPE;
  challenge_record organizations.data_access_accountability_disclosure_challenges%ROWTYPE;
  disclosure_record organizations.data_access_accountability_disclosures%ROWTYPE;
  previous_record organizations.data_access_accountability_disclosure_resolutions%ROWTYPE;
  challenge_event_sequence bigint;
  previous_event_sequence bigint;
  resolution_event_sequence bigint;
  bound_resolution_payload_hash text;
  expected_resolution_hash text;
  expected_resolution_root text;
  expected_resolution_payload_hash text;
  expected_action text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.reviewed_by THEN
    RAISE EXCEPTION 'accountability disclosure resolution insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO reviewer_record
  FROM identity.participants
  WHERE id = NEW.reviewed_by
  FOR UPDATE;
  IF
    NOT FOUND OR
    reviewer_record.participant_type <> 'human' OR
    reviewer_record.verification_status <> 'verified' OR
    reviewer_record.organization_id <> NEW.organization_id OR
    NOT (NEW.reviewer_role = ANY(reviewer_record.roles))
  THEN
    RAISE EXCEPTION 'accountability disclosure resolution requires a verified human in the target organization with the claimed role' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO organization_record
  FROM organizations.organizations
  WHERE id = NEW.organization_id
  FOR UPDATE;
  IF NOT FOUND OR organization_record.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'accountability disclosure resolution organization must be verified' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.organization_id
      AND membership.actor_id = NEW.reviewed_by
      AND membership.status = 'active'
      AND membership.role = NEW.reviewer_role
      AND membership.role IN ('owner', 'admin', 'verifier')
  ) THEN
    RAISE EXCEPTION 'accountability disclosure resolution reviewer lacks an active target-organization review membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO challenge_record
  FROM organizations.data_access_accountability_disclosure_challenges
  WHERE id = NEW.challenge_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accountability disclosure resolution challenge does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  SELECT * INTO disclosure_record
  FROM organizations.data_access_accountability_disclosures
  WHERE id = NEW.disclosure_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accountability disclosure resolution disclosure does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF
    challenge_record.organization_id <> NEW.organization_id OR
    challenge_record.disclosure_id <> NEW.disclosure_id OR
    disclosure_record.organization_id <> NEW.organization_id OR
    NEW.reviewed_at < challenge_record.challenged_at
  THEN
    RAISE EXCEPTION 'accountability disclosure resolution challenge lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reviewed_by IN (challenge_record.challenged_by, disclosure_record.published_by) THEN
    RAISE EXCEPTION 'accountability disclosure resolution requires an independent human reviewer' USING ERRCODE = 'check_violation';
  END IF;
  IF
    (NEW.decision = 'upheld' AND NEW.remedial_action NOT IN ('publish_correction', 'publish_withdrawal_notice')) OR
    (NEW.decision <> 'upheld' AND NEW.remedial_action <> 'none')
  THEN
    RAISE EXCEPTION 'accountability disclosure resolution decision and remedial action are inconsistent' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM organizations.data_access_accountability_disclosure_resolutions existing
    WHERE existing.challenge_id = NEW.challenge_id
      AND existing.decision <> 'needs_more_evidence'
  ) THEN
    RAISE EXCEPTION 'accountability disclosure challenge already has final resolution' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.previous_resolution_id IS NULL THEN
    IF NEW.previous_resolution_root IS NOT NULL OR EXISTS (
      SELECT 1
      FROM organizations.data_access_accountability_disclosure_resolutions existing
      WHERE existing.challenge_id = NEW.challenge_id
    ) THEN
      RAISE EXCEPTION 'accountability disclosure root resolution requires an empty predecessor chain' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    SELECT * INTO previous_record
    FROM organizations.data_access_accountability_disclosure_resolutions
    WHERE id = NEW.previous_resolution_id
    FOR UPDATE;
    IF
      NOT FOUND OR
      previous_record.challenge_id <> NEW.challenge_id OR
      previous_record.disclosure_id <> NEW.disclosure_id OR
      previous_record.organization_id <> NEW.organization_id OR
      previous_record.resolution_root <> NEW.previous_resolution_root OR
      previous_record.decision <> 'needs_more_evidence' OR
      NEW.reviewed_at <= previous_record.reviewed_at OR
      EXISTS (
        SELECT 1
        FROM organizations.data_access_accountability_disclosure_resolutions successor
        WHERE successor.previous_resolution_id = previous_record.id
      )
    THEN
      RAISE EXCEPTION 'accountability disclosure previous resolution lineage is invalid' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  SELECT event.sequence_no
  INTO challenge_event_sequence
  FROM audit.domain_events event
  WHERE event.event_root = challenge_record.audit_event_root
    AND event.stream_id = NEW.organization_id
    AND event.entity_type = 'data_access_accountability_disclosure_challenge'
    AND event.entity_id = challenge_record.id
    AND event.actor_id = challenge_record.challenged_by
    AND event.created_at = challenge_record.challenged_at
    AND event.action = 'CHALLENGE';
  expected_action := CASE NEW.decision
    WHEN 'dismissed' THEN 'ASSERT'
    WHEN 'upheld' THEN 'FULFILL'
    ELSE 'REASON'
  END;
  SELECT event.sequence_no, event.payload_hash
  INTO resolution_event_sequence, bound_resolution_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root
    AND event.stream_id = NEW.organization_id
    AND event.entity_type = 'data_access_accountability_disclosure_resolution'
    AND event.entity_id = NEW.id
    AND event.actor_id = NEW.reviewed_by
    AND event.created_at = NEW.reviewed_at
    AND event.action = expected_action;
  IF
    challenge_event_sequence IS NULL OR
    resolution_event_sequence IS NULL OR
    resolution_event_sequence <= challenge_event_sequence
  THEN
    RAISE EXCEPTION 'accountability disclosure resolution requires ordered exact semantic events' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.previous_resolution_id IS NOT NULL THEN
    SELECT event.sequence_no
    INTO previous_event_sequence
    FROM audit.domain_events event
    WHERE event.event_root = previous_record.audit_event_root
      AND event.stream_id = NEW.organization_id
      AND event.entity_type = 'data_access_accountability_disclosure_resolution'
      AND event.entity_id = previous_record.id;
    IF previous_event_sequence IS NULL OR previous_event_sequence >= resolution_event_sequence THEN
      RAISE EXCEPTION 'accountability disclosure resolution predecessor event order is invalid' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(NEW.evidence_event_roots) AS evidence_root
    LEFT JOIN audit.domain_events evidence_event ON evidence_event.event_root = evidence_root
    WHERE
      evidence_event.event_root IS NULL OR
      evidence_event.event_root = NEW.audit_event_root OR
      evidence_event.created_at > NEW.reviewed_at OR
      (
        evidence_event.stream_id = NEW.organization_id AND
        evidence_event.sequence_no >= resolution_event_sequence
      )
  ) THEN
    RAISE EXCEPTION 'accountability disclosure resolution evidence roots must bind prior semantic events' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.rationale ~* '(BEGIN|END)[[:space:]]+(RSA |EC |OPENSSH |PRIVATE )?PRIVATE KEY' OR
    NEW.rationale ~* '(private[_ -]?key|api[_ -]?secret|access[_ -]?secret|client[_ -]?secret|password|[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}|\+?[0-9][0-9 ().-]{7,}[0-9])'
  THEN
    RAISE EXCEPTION 'accountability disclosure resolution cannot embed private key, secret, or private contact material' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.rationale ~* '(certified[[:space:]]+carbon[[:space:]]+credit|carbon[-[:space:]]?tax[[:space:]]+offset|guaranteed[[:space:]]+(rwa[[:space:]]+)?yield|automatic[[:space:]]+\$?canopy[[:space:]]+distribution)' AND
    NEW.rationale !~* '(^|[^[:alnum:]_])not([^[:alnum:]_]|$)'
  THEN
    RAISE EXCEPTION 'accountability disclosure resolution contains an unsupported public claim' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.safety <> organizations.data_access_accountability_disclosure_resolution_safety_canonical()::jsonb THEN
    RAISE EXCEPTION 'accountability disclosure resolution safety boundary is not canonical' USING ERRCODE = 'check_violation';
  END IF;

  expected_resolution_hash := organizations.compute_data_access_accountability_disclosure_resolution_hash(
    NEW.organization_id,
    NEW.disclosure_id,
    NEW.challenge_id,
    NEW.decision,
    NEW.remedial_action,
    NEW.rationale,
    NEW.evidence_event_roots,
    NEW.previous_resolution_id,
    NEW.previous_resolution_root,
    NEW.reviewed_by,
    NEW.reviewer_role,
    NEW.reviewed_at
  );
  expected_resolution_root := organizations.compute_data_access_accountability_disclosure_resolution_root(
    challenge_record.challenge_root,
    NEW.evidence_event_roots,
    NEW.previous_resolution_root,
    expected_resolution_hash
  );
  IF
    NEW.resolution_hash <> expected_resolution_hash OR
    NEW.resolution_root <> expected_resolution_root OR
    NEW.id <> 'cp_data_access_disclosure_resolution_' || left(expected_resolution_hash, 24)
  THEN
    RAISE EXCEPTION 'accountability disclosure resolution hash, root, or identifier is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_resolution_payload_hash := organizations.compute_data_access_accountability_disclosure_resolution_payload_hash(
    NEW.organization_id,
    NEW.disclosure_id,
    NEW.challenge_id,
    NEW.decision,
    NEW.remedial_action,
    NEW.rationale,
    NEW.evidence_event_roots,
    NEW.previous_resolution_id,
    NEW.previous_resolution_root,
    NEW.reviewed_by,
    NEW.reviewer_role,
    NEW.reviewed_at,
    NEW.resolution_hash,
    NEW.resolution_root
  );
  IF bound_resolution_payload_hash IS DISTINCT FROM expected_resolution_payload_hash THEN
    RAISE EXCEPTION 'accountability disclosure resolution semantic event payload does not match canonical fields' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS org_data_access_disclosure_resolution_validate ON organizations.data_access_accountability_disclosure_resolutions;
CREATE TRIGGER org_data_access_disclosure_resolution_validate
BEFORE INSERT ON organizations.data_access_accountability_disclosure_resolutions
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_access_accountability_disclosure_resolution();

