RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT '{"appendOnly":true,"noPrivateContactData":true,"noRawDataEmbedded":true,"notCarbonCredit":true,"notFinalProofAuthority":true,"notFinancialAsset":true,"notGuaranteedYield":true,"notTaxOffset":true,"originalDisclosurePreserved":true,"publicStatement":true,"resolutionBound":true}'::text;
$$;

CREATE OR REPLACE FUNCTION organizations.compute_data_access_accountability_disclosure_notice_hash(
  notice_organization_id text,
  notice_disclosure_id text,
  notice_challenge_id text,
  notice_resolution_id text,
  notice_resolution_root text,
  notice_type_value text,
  notice_replacement_disclosure_id text,
