  notice_published_by text,
  notice_publisher_role text,
  notice_published_at timestamptz
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT encode(
    digest(
      convert_to(
        '{"challengeId":' || to_json(notice_challenge_id)::text ||
        ',"disclosureId":' || to_json(notice_disclosure_id)::text ||
        ',"evidenceEventRoots":' || audit.canonical_text_array(notice_evidence_event_roots) ||
        ',"kind":"canopyproof-data-access-accountability-disclosure-notice-v1"' ||
        ',"noticeType":' || to_json(notice_type_value)::text ||
        ',"organizationId":' || to_json(notice_organization_id)::text ||
        ',"publishedAt":' || to_json(to_char(notice_published_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text ||
        ',"publishedBy":' || to_json(notice_published_by)::text ||
        ',"publisherRole":' || to_json(notice_publisher_role)::text ||
        ',"replacementDisclosureId":' || COALESCE(to_json(notice_replacement_disclosure_id)::text, 'null') ||
        ',"replacementDisclosureRoot":' || COALESCE(to_json(notice_replacement_disclosure_root)::text, 'null') ||
        ',"resolutionId":' || to_json(notice_resolution_id)::text ||
