      ),
      'sha256'
    ),
    'hex'
  );
$$;

CREATE OR REPLACE FUNCTION organizations.validate_data_access_accountability_disclosure_notice()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  organization_record organizations.organizations%ROWTYPE;
  publisher_record identity.participants%ROWTYPE;
  resolution_record organizations.data_access_accountability_disclosure_resolutions%ROWTYPE;
  challenge_record organizations.data_access_accountability_disclosure_challenges%ROWTYPE;
  disclosure_record organizations.data_access_accountability_disclosures%ROWTYPE;
  replacement_record organizations.data_access_accountability_disclosures%ROWTYPE;
  resolution_event_sequence bigint;
  notice_event_sequence bigint;
  replacement_event_sequence bigint;
  bound_notice_payload_hash text;
  replacement_root text;
  expected_notice_hash text;
  expected_notice_root text;
  expected_notice_payload_hash text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.published_by THEN
    RAISE EXCEPTION 'accountability disclosure notice insert requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO publisher_record
  FROM identity.participants
  WHERE id = NEW.published_by
  FOR UPDATE;
  IF
    NOT FOUND OR
    publisher_record.participant_type <> 'human' OR
    publisher_record.verification_status <> 'verified' OR
    publisher_record.organization_id <> NEW.organization_id OR
    NOT (NEW.publisher_role = ANY(publisher_record.roles))
  THEN
    RAISE EXCEPTION 'accountability disclosure notice requires a verified human in the target organization with the claimed role' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO organization_record
  FROM organizations.organizations
  WHERE id = NEW.organization_id
  FOR UPDATE;
  IF NOT FOUND OR organization_record.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'accountability disclosure notice organization must be verified' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organizations.memberships membership
    WHERE membership.organization_id = NEW.organization_id
      AND membership.actor_id = NEW.published_by
      AND membership.status = 'active'
      AND membership.role = NEW.publisher_role
      AND membership.role IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'accountability disclosure notice publisher lacks an active target-organization publication membership' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO resolution_record
  FROM organizations.data_access_accountability_disclosure_resolutions
  WHERE id = NEW.resolution_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accountability disclosure notice resolution does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  SELECT * INTO challenge_record
  FROM organizations.data_access_accountability_disclosure_challenges
  WHERE id = NEW.challenge_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accountability disclosure notice challenge does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  SELECT * INTO disclosure_record
  FROM organizations.data_access_accountability_disclosures
  WHERE id = NEW.disclosure_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accountability disclosure notice disclosure does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF
    resolution_record.organization_id <> NEW.organization_id OR
    resolution_record.challenge_id <> challenge_record.id OR
    resolution_record.disclosure_id <> disclosure_record.id OR
    challenge_record.organization_id <> NEW.organization_id OR
    challenge_record.disclosure_id <> disclosure_record.id OR
    disclosure_record.organization_id <> NEW.organization_id OR
    resolution_record.decision <> 'upheld' OR
    NEW.published_at < resolution_record.reviewed_at
  THEN
    RAISE EXCEPTION 'accountability disclosure notice resolution lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF
    (resolution_record.remedial_action = 'publish_correction' AND NEW.notice_type <> 'correction') OR
    (resolution_record.remedial_action = 'publish_withdrawal_notice' AND NEW.notice_type <> 'withdrawal') OR
    resolution_record.remedial_action = 'none'
  THEN
    RAISE EXCEPTION 'accountability disclosure notice type does not match the upheld remedy' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.published_by IN (
    disclosure_record.published_by,
    challenge_record.challenged_by,
    resolution_record.reviewed_by
  ) THEN
    RAISE EXCEPTION 'accountability disclosure notice requires an independent human publisher' USING ERRCODE = 'check_violation';
  END IF;

  SELECT event.sequence_no
  INTO resolution_event_sequence
  FROM audit.domain_events event
  WHERE event.event_root = resolution_record.audit_event_root
    AND event.stream_id = NEW.organization_id
    AND event.entity_type = 'data_access_accountability_disclosure_resolution'
    AND event.entity_id = resolution_record.id
    AND event.actor_id = resolution_record.reviewed_by
    AND event.created_at = resolution_record.reviewed_at
    AND event.action = 'FULFILL';
  SELECT event.sequence_no, event.payload_hash
  INTO notice_event_sequence, bound_notice_payload_hash
  FROM audit.domain_events event
  WHERE event.event_root = NEW.audit_event_root
    AND event.stream_id = NEW.organization_id
    AND event.entity_type = 'data_access_accountability_disclosure_notice'
    AND event.entity_id = NEW.id
    AND event.actor_id = NEW.published_by
    AND event.created_at = NEW.published_at
    AND event.action = 'FULFILL';
  IF
    resolution_event_sequence IS NULL OR
    notice_event_sequence IS NULL OR
    notice_event_sequence <= resolution_event_sequence OR
    EXISTS (
      SELECT 1
      FROM organizations.data_access_accountability_disclosure_resolutions later
      JOIN audit.domain_events later_event ON later_event.event_root = later.audit_event_root
      WHERE later.challenge_id = NEW.challenge_id
        AND later_event.sequence_no > resolution_event_sequence
        AND later_event.sequence_no < notice_event_sequence
    )
  THEN
    RAISE EXCEPTION 'accountability disclosure notice requires the latest ordered resolution and notice events' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.notice_type = 'correction' THEN
    IF NEW.replacement_disclosure_id IS NULL THEN
      RAISE EXCEPTION 'accountability correction notice requires a replacement disclosure' USING ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO replacement_record
    FROM organizations.data_access_accountability_disclosures
    WHERE id = NEW.replacement_disclosure_id
    FOR UPDATE;
    IF
      NOT FOUND OR
      replacement_record.id = disclosure_record.id OR
      replacement_record.organization_id <> NEW.organization_id
    THEN
      RAISE EXCEPTION 'accountability correction replacement disclosure is invalid' USING ERRCODE = 'check_violation';
    END IF;
    SELECT event.sequence_no
    INTO replacement_event_sequence
    FROM audit.domain_events event
    WHERE event.event_root = replacement_record.audit_event_root
      AND event.stream_id = NEW.organization_id
      AND event.entity_type = 'data_access_accountability_disclosure'
      AND event.entity_id = replacement_record.id
      AND event.actor_id = replacement_record.published_by
      AND event.created_at = replacement_record.published_at
      AND event.action = 'FULFILL';
    IF
      replacement_event_sequence IS NULL OR
      replacement_event_sequence >= notice_event_sequence OR
      NOT organizations.data_access_accountability_packet_is_current(
        replacement_record.packet_id,
        notice_event_sequence
      ) OR
      organizations.data_access_accountability_disclosure_governance_state_at(
        replacement_record.id,
        notice_event_sequence
      ) NOT IN ('unchallenged', 'challenge_dismissed')
    THEN
      RAISE EXCEPTION 'accountability correction replacement must be current and uncontested at notice publication' USING ERRCODE = 'check_violation';
    END IF;
    replacement_root := replacement_record.disclosure_root;
  ELSE
    IF NEW.replacement_disclosure_id IS NOT NULL THEN
      RAISE EXCEPTION 'accountability withdrawal notice cannot reference a replacement disclosure' USING ERRCODE = 'check_violation';
    END IF;
    replacement_root := NULL;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(NEW.evidence_event_roots) AS evidence_root
    LEFT JOIN audit.domain_events evidence_event ON evidence_event.event_root = evidence_root
    WHERE
      evidence_event.event_root IS NULL OR
      evidence_event.event_root = NEW.audit_event_root OR
      evidence_event.created_at > NEW.published_at OR
      (
        evidence_event.stream_id = NEW.organization_id AND
        evidence_event.sequence_no >= notice_event_sequence
      )
  ) THEN
    RAISE EXCEPTION 'accountability disclosure notice evidence roots must bind prior semantic events' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.statement ~* '(BEGIN|END)[[:space:]]+(RSA |EC |OPENSSH |PRIVATE )?PRIVATE KEY' OR
    NEW.statement ~* '(private[_ -]?key|api[_ -]?secret|access[_ -]?secret|client[_ -]?secret|password|[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}|\+?[0-9][0-9 ().-]{7,}[0-9])'
  THEN
    RAISE EXCEPTION 'accountability disclosure notice cannot embed private key, secret, or private contact material' USING ERRCODE = 'check_violation';
  END IF;
  IF
    NEW.statement ~* '(certified[[:space:]]+carbon[[:space:]]+credit|carbon[-[:space:]]?tax[[:space:]]+offset|guaranteed[[:space:]]+(rwa[[:space:]]+)?yield|automatic[[:space:]]+\$?canopy[[:space:]]+distribution)' AND
    NEW.statement !~* '(^|[^[:alnum:]_])not([^[:alnum:]_]|$)'
  THEN
    RAISE EXCEPTION 'accountability disclosure notice contains an unsupported public claim' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.safety <> organizations.data_access_accountability_disclosure_notice_safety_canonical()::jsonb THEN
    RAISE EXCEPTION 'accountability disclosure notice safety boundary is not canonical' USING ERRCODE = 'check_violation';
  END IF;

  expected_notice_hash := organizations.compute_data_access_accountability_disclosure_notice_hash(
    NEW.organization_id,
    NEW.disclosure_id,
    NEW.challenge_id,
    NEW.resolution_id,
    resolution_record.resolution_root,
    NEW.notice_type,
    NEW.replacement_disclosure_id,
    replacement_root,
    NEW.statement,
    NEW.evidence_event_roots,
    NEW.published_by,
    NEW.publisher_role,
    NEW.published_at
  );
  expected_notice_root := organizations.compute_data_access_accountability_disclosure_notice_root(
    disclosure_record.disclosure_root,
    NEW.evidence_event_roots,
    expected_notice_hash,
    replacement_root,
    resolution_record.resolution_root
  );
  IF
    NEW.notice_hash <> expected_notice_hash OR
    NEW.notice_root <> expected_notice_root OR
    NEW.id <> 'cp_data_access_disclosure_notice_' || left(expected_notice_hash, 24)
  THEN
    RAISE EXCEPTION 'accountability disclosure notice hash, root, or identifier is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  expected_notice_payload_hash := organizations.compute_data_access_accountability_disclosure_notice_payload_hash(
    NEW.organization_id,
    NEW.disclosure_id,
    NEW.challenge_id,
    NEW.resolution_id,
    resolution_record.resolution_root,
    NEW.notice_type,
    NEW.replacement_disclosure_id,
    replacement_root,
    NEW.statement,
    NEW.evidence_event_roots,
    NEW.published_by,
    NEW.publisher_role,
    NEW.published_at,
    NEW.notice_hash,
    NEW.notice_root
  );
  IF bound_notice_payload_hash IS DISTINCT FROM expected_notice_payload_hash THEN
    RAISE EXCEPTION 'accountability disclosure notice semantic event payload does not match canonical fields' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS org_data_access_disclosure_notice_validate ON organizations.data_access_accountability_disclosure_notices;
CREATE TRIGGER org_data_access_disclosure_notice_validate
BEFORE INSERT ON organizations.data_access_accountability_disclosure_notices
FOR EACH ROW EXECUTE FUNCTION organizations.validate_data_access_accountability_disclosure_notice();

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_disclosure_governance_state_at(
  target_disclosure_id text,
  event_boundary bigint
)
RETURNS text
LANGUAGE sql
STABLE
AS $$
  WITH bounded_challenges AS (
    SELECT challenge.id
    FROM organizations.data_access_accountability_disclosure_challenges challenge
    JOIN audit.domain_events challenge_event
      ON challenge_event.event_root = challenge.audit_event_root
    WHERE challenge.disclosure_id = target_disclosure_id
      AND challenge_event.sequence_no < event_boundary
  ),
  bounded_resolutions AS (
    SELECT
      resolution.id,
      resolution.challenge_id,
      resolution.decision,
      resolution.remedial_action,
      resolution_event.sequence_no
    FROM organizations.data_access_accountability_disclosure_resolutions resolution
    JOIN audit.domain_events resolution_event
      ON resolution_event.event_root = resolution.audit_event_root
    WHERE resolution_event.sequence_no < event_boundary
  ),
  latest AS (
    SELECT DISTINCT ON (challenge.id)
      challenge.id,
      resolution.id AS resolution_id,
      resolution.decision,
      resolution.remedial_action
    FROM bounded_challenges challenge
    LEFT JOIN bounded_resolutions resolution
      ON resolution.challenge_id = challenge.id
    ORDER BY challenge.id, resolution.sequence_no DESC NULLS LAST
  ),
  bounded_notices AS (
    SELECT notice.resolution_id, notice.notice_type
    FROM organizations.data_access_accountability_disclosure_notices notice
    JOIN audit.domain_events notice_event
      ON notice_event.event_root = notice.audit_event_root
    WHERE notice.disclosure_id = target_disclosure_id
      AND notice_event.sequence_no < event_boundary
  )
  SELECT CASE
    WHEN NOT EXISTS (SELECT 1 FROM latest) THEN 'unchallenged'
    WHEN EXISTS (SELECT 1 FROM bounded_notices WHERE notice_type = 'withdrawal') THEN 'withdrawn'
    WHEN EXISTS (SELECT 1 FROM latest WHERE decision IS NULL) THEN 'challenged'
    WHEN EXISTS (SELECT 1 FROM latest WHERE decision = 'needs_more_evidence') THEN 'needs_more_evidence'
    WHEN EXISTS (
      SELECT 1
      FROM latest
      WHERE decision = 'upheld'
        AND remedial_action = 'publish_withdrawal_notice'
        AND NOT EXISTS (
          SELECT 1 FROM bounded_notices notice
          WHERE notice.resolution_id = latest.resolution_id
        )
    ) THEN 'withdrawal_required'
    WHEN EXISTS (
      SELECT 1
      FROM latest
      WHERE decision = 'upheld'
        AND remedial_action = 'publish_correction'
        AND NOT EXISTS (
          SELECT 1 FROM bounded_notices notice
          WHERE notice.resolution_id = latest.resolution_id
        )
    ) THEN 'correction_required'
    WHEN EXISTS (SELECT 1 FROM bounded_notices WHERE notice_type = 'correction') THEN 'corrected'
    ELSE 'challenge_dismissed'
  END;
$$;

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_disclosure_governance_state(
  target_disclosure_id text
)
RETURNS text
LANGUAGE sql
STABLE
AS $$
  SELECT organizations.data_access_accountability_disclosure_governance_state_at(
    target_disclosure_id,
    COALESCE(
      (
        SELECT MAX(event.sequence_no) + 1
        FROM organizations.data_access_accountability_disclosures disclosure
        JOIN audit.domain_events event ON event.stream_id = disclosure.organization_id
        WHERE disclosure.id = target_disclosure_id
      ),
      1
    )
  );
$$;

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_disclosure_open_challenge_count(
  target_disclosure_id text
)
RETURNS integer
LANGUAGE sql
STABLE
AS $$
  WITH latest AS (
    SELECT DISTINCT ON (challenge.id)
      challenge.id,
      resolution.decision
    FROM organizations.data_access_accountability_disclosure_challenges challenge
    LEFT JOIN organizations.data_access_accountability_disclosure_resolutions resolution
      ON resolution.challenge_id = challenge.id
    LEFT JOIN audit.domain_events resolution_event
      ON resolution_event.event_root = resolution.audit_event_root
    WHERE challenge.disclosure_id = target_disclosure_id
    ORDER BY challenge.id, resolution_event.sequence_no DESC NULLS LAST
  )
  SELECT COUNT(*)::integer
  FROM latest
  WHERE decision IS NULL OR decision = 'needs_more_evidence';
$$;

CREATE OR REPLACE FUNCTION audit.merkle_root(ordered_leaves text[])
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  level_values text[];
  next_level text[];
  index_value integer;
  right_value text;
BEGIN
  IF COALESCE(cardinality(ordered_leaves), 0) = 0 THEN
    RETURN encode(digest(convert_to('dropin-empty-merkle-root', 'UTF8'), 'sha256'), 'hex');
  END IF;
  level_values := ARRAY(
    SELECT encode(digest(convert_to(leaf, 'UTF8'), 'sha256'), 'hex')
    FROM unnest(ordered_leaves) WITH ORDINALITY AS item(leaf, position)
    ORDER BY position
  );
  WHILE cardinality(level_values) > 1 LOOP
    next_level := ARRAY[]::text[];
    index_value := 1;
    WHILE index_value <= cardinality(level_values) LOOP
      right_value := COALESCE(level_values[index_value + 1], level_values[index_value]);
      next_level := array_append(
        next_level,
        encode(
          digest(convert_to(level_values[index_value] || right_value, 'UTF8'), 'sha256'),
          'hex'
        )
      );
      index_value := index_value + 2;
    END LOOP;
    level_values := next_level;
  END LOOP;
  RETURN level_values[1];
END;
$$;

CREATE OR REPLACE FUNCTION organizations.data_access_accountability_packet_is_current(
  current_packet_id text,
  current_event_boundary bigint
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  packet_record organizations.data_access_accountability_packets%ROWTYPE;
  request_record organizations.data_access_requests%ROWTYPE;
  current_snapshot record;
  current_packet_hash text;
  current_packet_root text;
BEGIN
  SELECT * INTO packet_record
  FROM organizations.data_access_accountability_packets
  WHERE id = current_packet_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  SELECT * INTO request_record
  FROM organizations.data_access_requests
  WHERE id = packet_record.request_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  SELECT * INTO current_snapshot
  FROM organizations.data_access_accountability_snapshot(packet_record.request_id, current_event_boundary);
  current_packet_hash := organizations.compute_data_access_accountability_packet_hash(
    packet_record.organization_id,
    packet_record.request_id,
    packet_record.agreement_id,
    packet_record.generated_by,
    packet_record.generated_at,
    packet_record.intended_audience,
    current_snapshot.request_status,
    request_record.request_hash,
    current_snapshot.counts,
    current_snapshot.lineage_roots
  );
  current_packet_root := organizations.compute_data_access_accountability_packet_root(
    request_record.access_root,
    current_snapshot.counts,
    current_snapshot.lineage_roots,
    current_packet_hash
  );
  RETURN
    packet_record.packet_hash = current_packet_hash AND
    packet_record.packet_root = current_packet_root AND
    packet_record.safety = organizations.data_access_accountability_packet_safety_canonical()::jsonb;
END;
$$;

CREATE OR REPLACE FUNCTION audit.prevent_event_log_update_or_delete()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'audit records are append-only';
END;
$$;

