CREATE OR REPLACE FUNCTION audit.capture_row_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  target_pk text;
  target_pk_hash text;
  target_stream_key text;
  prior_hash text;
  prior_sequence bigint;
  prior_recorded_at_unix_micros bigint;
  next_sequence bigint;
  event_recorded_at_unix_micros bigint;
  event_actor_id text;
  before_hash text;
  after_hash text;
  computed_event_hash text;
  before_doc jsonb;
  after_doc jsonb;
BEGIN
  before_doc := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END;
  after_doc := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END;
  target_pk := COALESCE(after_doc->>'id', before_doc->>'id');
  IF target_pk IS NULL OR length(btrim(target_pk)) = 0 THEN
    RAISE EXCEPTION 'audited mutation requires a non-empty id primary key' USING ERRCODE = 'check_violation';
  END IF;
  target_pk_hash := encode(digest(target_pk, 'sha256'), 'hex');
  target_stream_key := TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME || ':' || target_pk_hash;
  event_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF event_actor_id IS NULL THEN
    RAISE EXCEPTION 'audited mutation requires app.actor_id transaction context' USING ERRCODE = 'check_violation';
  END IF;
  before_hash := encode(
    digest(COALESCE(before_doc::text, 'canopyproof-db-audit-null-state-v2'), 'sha256'),
    'hex'
  );
  after_hash := encode(
    digest(COALESCE(after_doc::text, 'canopyproof-db-audit-null-state-v2'), 'sha256'),
    'hex'
  );

  PERFORM pg_advisory_xact_lock(hashtextextended(target_stream_key, 0));

  SELECT event_hash, sequence_no, recorded_at_unix_micros
    INTO prior_hash, prior_sequence, prior_recorded_at_unix_micros
    FROM audit.event_log
   WHERE stream_key = target_stream_key
   ORDER BY sequence_no DESC
   LIMIT 1
   FOR UPDATE;

  prior_hash := COALESCE(prior_hash, encode(digest('canopyproof-db-audit-genesis-v2', 'sha256'), 'hex'));
  prior_sequence := COALESCE(prior_sequence, 0);
  prior_recorded_at_unix_micros := COALESCE(prior_recorded_at_unix_micros, 0);
  next_sequence := prior_sequence + 1;
  event_recorded_at_unix_micros := greatest(
    floor(extract(epoch FROM clock_timestamp()) * 1000000)::bigint,
    prior_recorded_at_unix_micros + 1
  );
  computed_event_hash := audit.compute_event_log_hash(
    'canopyproof_db_audit_v2',
    target_stream_key,
    TG_TABLE_SCHEMA,
    TG_TABLE_NAME,
    target_pk_hash,
    next_sequence,
    TG_OP,
    event_actor_id,
    event_recorded_at_unix_micros,
    prior_hash,
    before_hash,
    after_hash
  );

  INSERT INTO audit.event_log (
    event_version,
    stream_key,
    schema_name,
    table_name,
    row_pk_hash,
    sequence_no,
    action,
    actor_id,
    recorded_at_unix_micros,
    previous_event_hash,
    before_state_hash,
    after_state_hash,
    event_hash,
    created_at
  )
  VALUES (
    'canopyproof_db_audit_v2',
    target_stream_key,
    TG_TABLE_SCHEMA,
    TG_TABLE_NAME,
    target_pk_hash,
    next_sequence,
    TG_OP,
    event_actor_id,
    event_recorded_at_unix_micros,
    prior_hash,
    before_hash,
    after_hash,
    computed_event_hash,
    to_timestamp(event_recorded_at_unix_micros::numeric / 1000000)
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

