-- Durable evidence verification authority. These append-only facts supersede
-- the preliminary mutable verification.ai_analyses and human_reviews tables.
CREATE TABLE IF NOT EXISTS verification.evidence_validation_runs (
  id text PRIMARY KEY,
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  evidence_root text NOT NULL CHECK (evidence_root ~ '^[0-9a-f]{64}$'),
  ruleset_id text NOT NULL CHECK (ruleset_id = 'canopyproof-evidence-validation-core'),
  ruleset_version text NOT NULL CHECK (ruleset_version = '1.0.0'),
  ruleset_hash text NOT NULL CHECK (ruleset_hash ~ '^[0-9a-f]{64}$'),
  checks jsonb NOT NULL CHECK (jsonb_typeof(checks) = 'array'),
  issues text[] NOT NULL,
  outcome text NOT NULL CHECK (outcome IN ('pass', 'needs_review', 'blocked')),
  confidence_score integer NOT NULL CHECK (confidence_score BETWEEN 0 AND 100),
  executor_id text NOT NULL REFERENCES identity.participants(id),
  executor_snapshot jsonb NOT NULL CHECK (jsonb_typeof(executor_snapshot) = 'object'),
  executed_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 1),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  validation_hash text NOT NULL UNIQUE CHECK (validation_hash ~ '^[0-9a-f]{64}$'),
  validation_root text NOT NULL UNIQUE CHECK (validation_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence)
);

CREATE TABLE IF NOT EXISTS verification.evidence_ai_analyses (
  id text PRIMARY KEY,
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  evidence_root text NOT NULL CHECK (evidence_root ~ '^[0-9a-f]{64}$'),
  validation_run_id text NOT NULL REFERENCES verification.evidence_validation_runs(id),
  validation_root text NOT NULL CHECK (validation_root ~ '^[0-9a-f]{64}$'),
  agent_id text NOT NULL REFERENCES identity.participants(id),
  agent_snapshot jsonb NOT NULL CHECK (jsonb_typeof(agent_snapshot) = 'object'),
  model_provider text NOT NULL CHECK (length(btrim(model_provider)) BETWEEN 1 AND 160),
  model_name text NOT NULL CHECK (length(btrim(model_name)) BETWEEN 1 AND 160),
  model_version text NOT NULL CHECK (length(btrim(model_version)) BETWEEN 1 AND 160),
  model_artifact_hash text NOT NULL CHECK (model_artifact_hash ~ '^[0-9a-f]{64}$'),
  prompt_hash text NOT NULL CHECK (prompt_hash ~ '^[0-9a-f]{64}$'),
  dataset_snapshot_roots text[] NOT NULL CHECK (cardinality(dataset_snapshot_roots) BETWEEN 1 AND 64),
  source_event_roots text[] NOT NULL CHECK (cardinality(source_event_roots) BETWEEN 2 AND 64),
  execution_environment text NOT NULL CHECK (length(btrim(execution_environment)) BETWEEN 1 AND 240),
  capabilities text[] NOT NULL,
  findings jsonb NOT NULL CHECK (jsonb_typeof(findings) = 'array' AND jsonb_array_length(findings) <= 64),
  recommendation text NOT NULL CHECK (recommendation IN ('needs_human_review', 'rejected')),
  claimed_confidence_score integer NOT NULL CHECK (claimed_confidence_score BETWEEN 0 AND 100),
  confidence_score integer NOT NULL CHECK (confidence_score BETWEEN 0 AND 100),
  advisory_only boolean NOT NULL DEFAULT true CHECK (advisory_only IS TRUE),
  analyzed_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 2),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  analysis_hash text NOT NULL UNIQUE CHECK (analysis_hash ~ '^[0-9a-f]{64}$'),
  analysis_root text NOT NULL UNIQUE CHECK (analysis_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence)
);

CREATE TABLE IF NOT EXISTS verification.evidence_human_reviews (
  id text PRIMARY KEY,
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  evidence_root text NOT NULL CHECK (evidence_root ~ '^[0-9a-f]{64}$'),
  validation_run_id text NOT NULL REFERENCES verification.evidence_validation_runs(id),
  validation_root text NOT NULL CHECK (validation_root ~ '^[0-9a-f]{64}$'),
  ai_analysis_ids text[] NOT NULL CHECK (cardinality(ai_analysis_ids) BETWEEN 1 AND 64),
  ai_analysis_roots text[] NOT NULL CHECK (cardinality(ai_analysis_roots) BETWEEN 1 AND 64),
  reviewer_id text NOT NULL REFERENCES identity.participants(id),
  reviewer_snapshot jsonb NOT NULL CHECK (jsonb_typeof(reviewer_snapshot) = 'object'),
  decision text NOT NULL CHECK (decision IN ('approve', 'reject', 'challenge', 'request_changes')),
  finding_dispositions jsonb NOT NULL CHECK (jsonb_typeof(finding_dispositions) = 'array' AND jsonb_array_length(finding_dispositions) <= 256),
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 12 AND 4000),
  limitations text[] NOT NULL CHECK (cardinality(limitations) <= 32),
  reviewed_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 3),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  review_hash text NOT NULL UNIQUE CHECK (review_hash ~ '^[0-9a-f]{64}$'),
  review_root text NOT NULL UNIQUE CHECK (review_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence)
);

CREATE INDEX IF NOT EXISTS evidence_validation_runs_evidence_time
  ON verification.evidence_validation_runs (evidence_id, evidence_sequence DESC, id);
CREATE INDEX IF NOT EXISTS evidence_validation_runs_organization_time
  ON verification.evidence_validation_runs (organization_id, executed_at DESC, id);
CREATE INDEX IF NOT EXISTS evidence_ai_analyses_evidence_validation
  ON verification.evidence_ai_analyses (evidence_id, validation_run_id, evidence_sequence, id);
CREATE INDEX IF NOT EXISTS evidence_ai_analyses_agent_time
  ON verification.evidence_ai_analyses (agent_id, analyzed_at DESC, id);
CREATE INDEX IF NOT EXISTS evidence_human_reviews_evidence_validation
  ON verification.evidence_human_reviews (evidence_id, validation_run_id, evidence_sequence, id);
CREATE INDEX IF NOT EXISTS evidence_human_reviews_reviewer_time
  ON verification.evidence_human_reviews (reviewer_id, reviewed_at DESC, id);

CREATE OR REPLACE FUNCTION verification.evidence_verification_safety_canonical()
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT jsonb_build_object(
    'evidenceRegistrationImmutable', true,
    'aiAdvisoryOnly', true,
    'independentHumanApprovalRequired', true,
    'notFinalVerification', true,
    'notCertificate', true,
    'notCertifiedCarbonCredit', true,
    'notCarbonTaxOffset', true,
    'notFinancialAsset', true,
    'notGuaranteedYield', true,
    'noMainnetFunds', true,
    'notAutomaticCanopyDistribution', true
  );
$$;

CREATE OR REPLACE FUNCTION verification.evidence_validation_ruleset_hash()
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-evidence-validation-ruleset-v1',
    'id', 'canopyproof-evidence-validation-core',
    'version', '1.0.0',
    'checks', jsonb_build_array(
      'registration_integrity', 'project_status_eligible', 'structural_registration',
      'location_accuracy', 'project_region_binding', 'minimum_confidence'
    ),
    'blockedProjectStatuses', jsonb_build_array('suspended', 'archived'),
    'reviewProjectStatuses', jsonb_build_array('submitted', 'under_review', 'challenged'),
    'maximumGpsAccuracyMeters', 100,
    'minimumReviewConfidence', 10,
    'passConfidence', 50
  ));
$$;

CREATE OR REPLACE FUNCTION verification.actor_snapshot_authority_root(actor_snapshot jsonb)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-verification-actor-authority-v1') ||
    (actor_snapshot - 'authorityRoot')
  );
$$;

CREATE OR REPLACE FUNCTION verification.actor_snapshot_is_valid(
  actor_snapshot jsonb,
  expected_actor_id text,
  expected_organization_id text,
  required_participant_type text,
  allowed_roles text[]
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  participant identity.participants%ROWTYPE;
  organization organizations.organizations%ROWTYPE;
  membership organizations.memberships%ROWTYPE;
  accreditation organizations.accreditations%ROWTYPE;
  latest_accreditation_id text;
  scope_values text[];
BEGIN
  IF jsonb_typeof(actor_snapshot) <> 'object'
     OR actor_snapshot->>'id' <> expected_actor_id
     OR actor_snapshot->>'organizationId' <> expected_organization_id
     OR actor_snapshot->>'participantType' <> required_participant_type
     OR NOT (actor_snapshot->>'role' = ANY(allowed_roles))
     OR actor_snapshot->>'verificationStatus' <> 'verified'
     OR actor_snapshot->>'organizationVerificationStatus' <> 'verified'
     OR actor_snapshot->>'participantRoot' !~ '^[0-9a-f]{64}$'
     OR actor_snapshot->>'organizationRoot' !~ '^[0-9a-f]{64}$'
     OR actor_snapshot->>'authorityRoot' <> verification.actor_snapshot_authority_root(actor_snapshot)
     OR jsonb_typeof(actor_snapshot->'accreditationScope') <> 'array' THEN
    RETURN false;
  END IF;
  scope_values := ARRAY(SELECT jsonb_array_elements_text(actor_snapshot->'accreditationScope'));
  IF cardinality(scope_values) > 32 OR NOT audit.is_sorted_unique_text_array(scope_values) THEN
    RETURN false;
  END IF;
  SELECT * INTO participant FROM identity.participants WHERE id = expected_actor_id;
  SELECT * INTO organization FROM organizations.organizations WHERE id = expected_organization_id;
  IF NOT FOUND OR participant.id IS NULL OR organization.id IS NULL
     OR participant.participant_type <> required_participant_type
     OR participant.verification_status <> 'verified'
     OR participant.subject_hash IS NULL
     OR participant.subject_hash <> actor_snapshot->>'participantRoot'
     OR NOT (actor_snapshot->>'role' = ANY(participant.roles))
     OR organization.verification_status <> 'verified'
     OR organization.profile_hash IS NULL
     OR organization.profile_hash <> actor_snapshot->>'organizationRoot' THEN
    RETURN false;
  END IF;
  IF required_participant_type = 'agent' THEN
    RETURN participant.organization_id = expected_organization_id
       AND actor_snapshot->>'role' = 'agent'
       AND NOT (actor_snapshot ? 'membershipId')
       AND NOT (actor_snapshot ? 'accreditationId')
       AND cardinality(scope_values) = 0;
  END IF;
  SELECT * INTO membership
  FROM organizations.memberships
  WHERE id = actor_snapshot->>'membershipId';
  IF membership.id IS NULL
     OR membership.organization_id <> expected_organization_id
     OR membership.actor_id <> expected_actor_id
     OR membership.role <> actor_snapshot->>'role'
     OR membership.status <> 'active'
     OR actor_snapshot->>'membershipStatus' <> 'active'
     OR membership.audit_event_root <> actor_snapshot->>'membershipRoot' THEN
    RETURN false;
  END IF;
  IF actor_snapshot ? 'accreditationId' THEN
    IF NOT (actor_snapshot ? 'accreditationStatus') OR NOT (actor_snapshot ? 'accreditationRoot') THEN
      RETURN false;
    END IF;
    SELECT * INTO accreditation
    FROM organizations.accreditations
    WHERE id = actor_snapshot->>'accreditationId';
    SELECT id INTO latest_accreditation_id
    FROM organizations.accreditations
    WHERE organization_id = expected_organization_id
    ORDER BY decided_at DESC, id DESC
    LIMIT 1;
    RETURN accreditation.id IS NOT NULL
       AND accreditation.id = latest_accreditation_id
       AND accreditation.organization_id = expected_organization_id
       AND accreditation.status = actor_snapshot->>'accreditationStatus'
       AND accreditation.audit_event_root = actor_snapshot->>'accreditationRoot'
       AND to_jsonb(ARRAY(SELECT value FROM unnest(accreditation.scope) value ORDER BY value))
          = actor_snapshot->'accreditationScope';
  END IF;
  RETURN cardinality(scope_values) = 0
     AND NOT (actor_snapshot ? 'accreditationStatus')
     AND NOT (actor_snapshot ? 'accreditationRoot')
     AND membership.id IS NOT NULL
     AND membership.organization_id = expected_organization_id
     AND membership.actor_id = expected_actor_id
     AND membership.role = actor_snapshot->>'role'
     AND membership.status = 'active'
     AND actor_snapshot->>'membershipStatus' = 'active'
     AND membership.audit_event_root = actor_snapshot->>'membershipRoot';
END;
$$;

CREATE OR REPLACE FUNCTION verification.validation_checks(registration evidence.evidence_objects)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT jsonb_build_array(
    jsonb_build_object(
      'code', 'registration_integrity', 'state', 'pass',
      'detail', 'Evidence registration hash lineage was replayed before validation.'
    ),
    jsonb_build_object(
      'code', 'project_status_eligible',
      'state', to_jsonb((CASE
        WHEN registration.project_status_at_submission IN ('suspended', 'archived') THEN 'blocked'
        WHEN registration.project_status_at_submission IN ('submitted', 'under_review', 'challenged') THEN 'needs_review'
        ELSE 'pass' END)::text),
      'detail', to_jsonb(('Project status at evidence submission was ' || registration.project_status_at_submission || '.')::text)
    ),
    jsonb_build_object(
      'code', 'structural_registration',
      'state', to_jsonb((CASE WHEN registration.verification_status = 'validated' THEN 'pass' ELSE 'needs_review' END)::text),
      'detail', to_jsonb(('Immutable registration structural status is ' || registration.verification_status || '.')::text)
    ),
    jsonb_build_object(
      'code', 'location_accuracy',
      'state', to_jsonb((CASE
        WHEN jsonb_extract_path_text(registration.location, 'accuracyMeters') IS NULL
          OR jsonb_extract_path_text(registration.location, 'accuracyMeters')::double precision > 100 THEN 'needs_review'
        ELSE 'pass' END)::text),
      'detail', to_jsonb((CASE
        WHEN jsonb_extract_path_text(registration.location, 'accuracyMeters') IS NULL THEN 'GPS accuracy was not committed.'::text
        ELSE ('GPS accuracy is ' || jsonb_extract_path_text(registration.location, 'accuracyMeters') || ' meters.')::text END)::text)
    ),
    jsonb_build_object(
      'code', 'project_region_binding',
      'state', to_jsonb((CASE
        WHEN jsonb_extract_path_text(registration.location, 'regionId') IS NULL THEN 'needs_review'
        WHEN jsonb_extract_path_text(registration.location, 'regionId') = registration.project_region_id_at_submission THEN 'pass'
        ELSE 'needs_review' END)::text),
      'detail', to_jsonb((CASE
        WHEN jsonb_extract_path_text(registration.location, 'regionId') IS NULL THEN 'Evidence location did not commit a project region identifier.'::text
        ELSE 'Evidence location region was compared with the immutable project boundary.'::text END)::text)
    ),
    jsonb_build_object(
      'code', 'minimum_confidence',
      'state', to_jsonb((CASE
        WHEN registration.confidence_score < 10 THEN 'blocked'
        WHEN registration.confidence_score < 50 THEN 'needs_review'
        ELSE 'pass' END)::text),
      'detail', to_jsonb(('Registration confidence is ' || registration.confidence_score::text || '.')::text)
    )
  );
$$;

CREATE OR REPLACE FUNCTION verification.validation_issues(validation_checks jsonb)
RETURNS text[]
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT COALESCE(array_agg(item->>'code' ORDER BY position), ARRAY[]::text[])
  FROM jsonb_array_elements(validation_checks) WITH ORDINALITY AS entry(item, position)
  WHERE item->>'state' <> 'pass';
$$;

CREATE OR REPLACE FUNCTION verification.validation_outcome(validation_checks jsonb)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(validation_checks) item WHERE item->>'state' = 'blocked') THEN 'blocked'
    WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(validation_checks) item WHERE item->>'state' = 'needs_review') THEN 'needs_review'
    ELSE 'pass' END;
$$;

CREATE OR REPLACE FUNCTION verification.validation_command_hash(run verification.evidence_validation_runs)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
