  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-evidence-validation-command-v1',
    'evidenceId', run.evidence_id,
    'evidenceRoot', run.evidence_root,
    'rulesetId', run.ruleset_id,
    'rulesetVersion', run.ruleset_version,
    'rulesetHash', run.ruleset_hash,
    'executor', run.executor_snapshot,
    'executedAt', audit.iso8601_millis(run.executed_at)
  ));
$$;

