IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'factType', 'validation_run',
    'id', run.id,
    'evidenceId', run.evidence_id,
    'projectId', run.project_id,
    'organizationId', run.organization_id,
    'evidenceRoot', run.evidence_root,
    'rulesetId', run.ruleset_id,
    'rulesetVersion', run.ruleset_version,
    'rulesetHash', run.ruleset_hash,
    'checks', run.checks,
    'issues', to_jsonb(run.issues),
    'outcome', run.outcome,
    'confidenceScore', run.confidence_score,
    'executor', run.executor_snapshot,
    'executedAt', audit.iso8601_millis(run.executed_at),
    'commandHash', run.command_hash,
    'evidenceSequence', run.evidence_sequence,
    'previousEventRoot', run.previous_event_root,
    'validationHash', run.validation_hash,
    'validationRoot', run.validation_root,
    'safety', run.safety
  ));
$$;

CREATE OR REPLACE FUNCTION verification.validate_evidence_validation_run_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  registration evidence.evidence_objects%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  expected_checks jsonb;
  expected_issues text[];
  expected_outcome text;
  expected_confidence integer;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.executor_id THEN
    RAISE EXCEPTION 'evidence validation requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT registration FROM evidence.evidence_objects WHERE id = NEW.evidence_id FOR SHARE;
  IF NEW.project_id <> registration.project_id
     OR NEW.organization_id <> registration.organization_id
     OR NEW.evidence_root <> registration.evidence_root THEN
    RAISE EXCEPTION 'evidence validation registration boundary mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT (
    (NEW.executor_snapshot->>'participantType' = 'agent' AND verification.actor_snapshot_is_valid(
      NEW.executor_snapshot, NEW.executor_id, NEW.organization_id, 'agent', ARRAY['agent']::text[]
    )) OR
    (NEW.executor_snapshot->>'participantType' = 'human' AND verification.actor_snapshot_is_valid(
      NEW.executor_snapshot, NEW.executor_id, NEW.organization_id, 'human', ARRAY['owner','admin','verifier','researcher']::text[]
    ))
  ) THEN
    RAISE EXCEPTION 'evidence validation executor authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  expected_checks := verification.validation_checks(registration);
  expected_issues := verification.validation_issues(expected_checks);
  expected_outcome := verification.validation_outcome(expected_checks);
  expected_confidence := CASE expected_outcome
    WHEN 'pass' THEN registration.confidence_score
    WHEN 'needs_review' THEN least(registration.confidence_score, 50)
    ELSE least(registration.confidence_score, 10) END;
  IF NEW.ruleset_hash <> verification.evidence_validation_ruleset_hash()
     OR NEW.checks <> expected_checks
     OR NEW.issues <> expected_issues
     OR NEW.outcome <> expected_outcome
     OR NEW.confidence_score <> expected_confidence
     OR NEW.safety <> verification.evidence_verification_safety_canonical() THEN
    RAISE EXCEPTION 'evidence validation deterministic output is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence FROM audit.domain_events WHERE stream_id = NEW.evidence_id;
  IF semantic_event.stream_id <> NEW.evidence_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.executor_id
     OR semantic_event.entity_type <> 'validation_run'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> (CASE WHEN NEW.outcome = 'blocked' THEN 'CHALLENGE' ELSE 'REASON' END)
     OR semantic_event.rationale <> (CASE
       WHEN NEW.outcome = 'pass' THEN 'Deterministic evidence validation completed without granting final authority.'
       ELSE 'Deterministic evidence validation retained review or blocking issues for accountable follow-up.'
     END)
     OR semantic_event.created_at <> NEW.executed_at THEN
    RAISE EXCEPTION 'evidence validation semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.command_hash <> verification.validation_command_hash(NEW)
     OR NEW.id <> 'cp_validation_' || left(NEW.command_hash, 24)
     OR NEW.validation_hash <> verification.validation_hash(NEW)
     OR NEW.validation_root <> verification.validation_root(NEW)
     OR semantic_event.payload_hash <> verification.validation_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence validation hash lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS verification_evidence_validation_runs_validate ON verification.evidence_validation_runs;
CREATE TRIGGER verification_evidence_validation_runs_validate
BEFORE INSERT ON verification.evidence_validation_runs
