CREATE OR REPLACE FUNCTION verification.validate_evidence_ai_analysis_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  registration evidence.evidence_objects%ROWTYPE;
  validation verification.evidence_validation_runs%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  finding jsonb;
  finding_roots text[];
  finding_ids text[] := ARRAY[]::text[];
  expected_capabilities text[];
  expected_recommendation text;
  severity_penalty integer := 0;
  expected_confidence integer;
  latest_validation_id text;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.agent_id THEN
    RAISE EXCEPTION 'evidence AI analysis requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT registration FROM evidence.evidence_objects WHERE id = NEW.evidence_id FOR SHARE;
  SELECT * INTO STRICT validation FROM verification.evidence_validation_runs WHERE id = NEW.validation_run_id FOR SHARE;
  SELECT id INTO latest_validation_id
  FROM verification.evidence_validation_runs
  WHERE evidence_id = NEW.evidence_id
  ORDER BY evidence_sequence DESC LIMIT 1;
  IF latest_validation_id <> NEW.validation_run_id
     OR validation.evidence_id <> NEW.evidence_id
     OR validation.validation_root <> NEW.validation_root
     OR NEW.project_id <> registration.project_id
     OR NEW.organization_id <> registration.organization_id
     OR NEW.evidence_root <> registration.evidence_root THEN
    RAISE EXCEPTION 'evidence AI analysis validation or registration boundary mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.actor_snapshot_is_valid(
    NEW.agent_snapshot, NEW.agent_id, NEW.organization_id, 'agent', ARRAY['agent']::text[]
  ) THEN
    RAISE EXCEPTION 'evidence AI analysis agent authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF projects.contains_unsafe_claim(ARRAY[
    NEW.id, NEW.model_provider, NEW.model_name, NEW.model_version, NEW.execution_environment
  ] || ARRAY(
    SELECT jsonb_extract_path_text(finding_item::jsonb, 'code')
    FROM jsonb_array_elements(NEW.findings) AS finding_entry(finding_item)
    UNION ALL
    SELECT jsonb_extract_path_text(finding_item::jsonb, 'message')
    FROM jsonb_array_elements(NEW.findings) AS finding_entry(finding_item)
  )) THEN
    RAISE EXCEPTION 'evidence AI analysis contains an unsupported public claim or secret material' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT audit.is_sha256_hash_array(NEW.dataset_snapshot_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.dataset_snapshot_roots)
     OR NOT audit.is_sha256_hash_array(NEW.source_event_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.source_event_roots)
     OR NOT (registration.audit_event_root = ANY(NEW.source_event_roots))
     OR NOT (validation.audit_event_root = ANY(NEW.source_event_roots)) THEN
    RAISE EXCEPTION 'evidence AI analysis source roots are not canonical' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(NEW.source_event_roots) root
    LEFT JOIN audit.domain_events event
      ON event.event_root = root AND event.stream_id = NEW.evidence_id AND event.sequence_no < NEW.evidence_sequence
    WHERE event.id IS NULL
  ) THEN
    RAISE EXCEPTION 'evidence AI analysis references a missing or future semantic event' USING ERRCODE = 'check_violation';
  END IF;
  FOR finding IN SELECT value FROM jsonb_array_elements(NEW.findings) LOOP
    IF jsonb_typeof(finding) <> 'object'
       OR finding->>'capability' NOT IN (
         'satellite comparison', 'anomaly detection', 'duplicate detection',
         'fraud detection', 'ecological reasoning', 'survival estimation'
       )
       OR finding->>'severity' NOT IN ('low', 'medium', 'high', 'critical')
       OR finding->>'code' !~ '^[a-z][a-z0-9_]{2,79}$'
       OR length(btrim(finding->>'message')) NOT BETWEEN 1 AND 2000
       OR finding->>'recommendedAction' NOT IN ('REASON', 'DELEGATE', 'CHALLENGE')
       OR jsonb_typeof(finding->'sourceEventRoots') <> 'array' THEN
      RAISE EXCEPTION 'evidence AI finding shape is invalid' USING ERRCODE = 'check_violation';
    END IF;
    finding_roots := ARRAY(SELECT jsonb_array_elements_text(finding->'sourceEventRoots'));
    IF cardinality(finding_roots) NOT BETWEEN 1 AND 32
       OR NOT audit.is_sha256_hash_array(finding_roots)
       OR NOT audit.is_sorted_unique_text_array(finding_roots)
       OR EXISTS (SELECT 1 FROM unnest(finding_roots) root WHERE NOT (root = ANY(NEW.source_event_roots)))
       OR finding->>'findingHash' <> verification.ai_finding_hash(finding)
       OR finding->>'id' <> 'cp_ai_finding_' || left(finding->>'findingHash', 24) THEN
      RAISE EXCEPTION 'evidence AI finding provenance or hash is invalid' USING ERRCODE = 'check_violation';
    END IF;
    finding_ids := array_append(finding_ids, finding->>'id');
    severity_penalty := severity_penalty + CASE finding->>'severity'
      WHEN 'low' THEN 1 WHEN 'medium' THEN 4 WHEN 'high' THEN 10 ELSE 20 END;
  END LOOP;
  IF NOT audit.is_sorted_unique_text_array(finding_ids) THEN
    RAISE EXCEPTION 'evidence AI findings must be sorted and unique' USING ERRCODE = 'check_violation';
  END IF;
  SELECT COALESCE(
    array_agg(DISTINCT finding_item->>'capability' ORDER BY finding_item->>'capability'),
    ARRAY[]::text[]
  )
  INTO expected_capabilities
  FROM jsonb_array_elements(NEW.findings) AS finding_entry(finding_item);
  expected_recommendation := CASE WHEN EXISTS (
    SELECT 1 FROM jsonb_array_elements(NEW.findings) item WHERE item->>'severity' = 'critical'
  ) THEN 'rejected' ELSE 'needs_human_review' END;
  expected_confidence := greatest(
    0,
    least(NEW.claimed_confidence_score, validation.confidence_score) - least(severity_penalty, 60)
  );
  IF NEW.capabilities <> expected_capabilities
     OR NOT audit.is_sorted_unique_text_array(NEW.capabilities)
     OR NEW.recommendation <> expected_recommendation
     OR NEW.confidence_score <> expected_confidence
     OR NEW.safety <> verification.evidence_verification_safety_canonical()
     OR NEW.analyzed_at < validation.executed_at THEN
    RAISE EXCEPTION 'evidence AI analysis derived output is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence FROM audit.domain_events WHERE stream_id = NEW.evidence_id;
  IF semantic_event.stream_id <> NEW.evidence_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.agent_id
     OR semantic_event.entity_type <> 'ai_analysis'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> (CASE WHEN NEW.recommendation = 'rejected' THEN 'CHALLENGE' ELSE 'REASON' END)
     OR semantic_event.rationale <> 'Verified AI agent recorded a provenance-bound advisory analysis; human authority remains required.'
     OR semantic_event.created_at <> NEW.analyzed_at THEN
    RAISE EXCEPTION 'evidence AI analysis semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.command_hash <> verification.ai_analysis_command_hash(NEW)
     OR NEW.id <> 'cp_ai_analysis_' || left(NEW.command_hash, 24)
     OR NEW.analysis_hash <> verification.ai_analysis_hash(NEW)
     OR NEW.analysis_root <> verification.ai_analysis_root(NEW)
     OR semantic_event.payload_hash <> verification.ai_analysis_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence AI analysis hash lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

