CREATE OR REPLACE FUNCTION verification.human_review_source_root(review verification.evidence_human_reviews)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.merkle_root(ARRAY(
    SELECT leaf FROM (
      SELECT review.evidence_root AS leaf
      UNION ALL SELECT review.validation_root
      UNION ALL SELECT unnest(review.ai_analysis_roots)
      UNION ALL SELECT value->>'dispositionHash' FROM jsonb_array_elements(review.finding_dispositions) value
    ) source_leaves
    ORDER BY leaf
  ));
$$;

