CREATE OR REPLACE FUNCTION verification.validate_evidence_human_review_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  registration evidence.evidence_objects%ROWTYPE;
  validation verification.evidence_validation_runs%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  accreditation organizations.accreditations%ROWTYPE;
  expected_analysis_ids text[];
  expected_analysis_roots text[];
  disposition jsonb;
  disposition_key text;
  disposition_keys text[] := ARRAY[]::text[];
  disposition_roots text[];
  latest_validation_id text;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.reviewer_id THEN
    RAISE EXCEPTION 'evidence human review requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT registration FROM evidence.evidence_objects WHERE id = NEW.evidence_id FOR SHARE;
  SELECT * INTO STRICT validation FROM verification.evidence_validation_runs WHERE id = NEW.validation_run_id FOR SHARE;
  SELECT id INTO latest_validation_id
  FROM verification.evidence_validation_runs
  WHERE evidence_id = NEW.evidence_id
  ORDER BY evidence_sequence DESC LIMIT 1;
  IF latest_validation_id <> NEW.validation_run_id
     OR validation.evidence_id <> NEW.evidence_id
     OR validation.validation_root <> NEW.validation_root
     OR NEW.project_id <> registration.project_id
     OR NEW.organization_id <> registration.organization_id
     OR NEW.evidence_root <> registration.evidence_root THEN
    RAISE EXCEPTION 'evidence human review validation or registration boundary mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.actor_snapshot_is_valid(
    NEW.reviewer_snapshot, NEW.reviewer_id, NEW.organization_id, 'human', ARRAY['verifier','researcher']::text[]
  ) THEN
    RAISE EXCEPTION 'evidence human reviewer authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF projects.contains_unsafe_claim(
    ARRAY[NEW.id, NEW.rationale] || NEW.limitations || ARRAY(
      SELECT jsonb_extract_path_text(disposition_item::jsonb, 'rationale')
      FROM jsonb_array_elements(NEW.finding_dispositions) AS disposition_entry(disposition_item)
    )
  ) THEN
    RAISE EXCEPTION 'evidence human review contains an unsupported public claim or secret material' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reviewer_id = registration.contributor_id OR EXISTS (
    SELECT 1 FROM verification.evidence_ai_analyses analysis
    WHERE analysis.validation_run_id = NEW.validation_run_id AND analysis.agent_id = NEW.reviewer_id
  ) THEN
    RAISE EXCEPTION 'evidence human review requires independence from contributor and AI agents' USING ERRCODE = 'check_violation';
  END IF;
  SELECT
    COALESCE(array_agg(id ORDER BY id), ARRAY[]::text[]),
    COALESCE(array_agg(analysis_root ORDER BY analysis_root), ARRAY[]::text[])
  INTO expected_analysis_ids, expected_analysis_roots
  FROM verification.evidence_ai_analyses
  WHERE evidence_id = NEW.evidence_id AND validation_run_id = NEW.validation_run_id;
  IF cardinality(expected_analysis_ids) = 0
     OR NEW.ai_analysis_ids <> expected_analysis_ids
     OR NEW.ai_analysis_roots <> expected_analysis_roots
     OR NOT audit.is_sorted_unique_text_array(NEW.ai_analysis_ids)
     OR NOT audit.is_sorted_unique_text_array(NEW.ai_analysis_roots)
     OR NOT audit.is_bounded_text_array(NEW.limitations, 1, 1000, 32)
     OR NOT audit.is_sorted_unique_text_array(NEW.limitations)
     OR NEW.safety <> verification.evidence_verification_safety_canonical()
     OR EXISTS (
       SELECT 1 FROM verification.evidence_ai_analyses analysis
       WHERE analysis.validation_run_id = NEW.validation_run_id AND NEW.reviewed_at < analysis.analyzed_at
     ) THEN
    RAISE EXCEPTION 'evidence human review source set or derived boundary is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  FOR disposition IN SELECT value FROM jsonb_array_elements(NEW.finding_dispositions) LOOP
    disposition_key := disposition->>'analysisId' || ':' || disposition->>'findingId';
    IF jsonb_typeof(disposition) <> 'object'
       OR disposition->>'disposition' NOT IN ('accepted', 'overruled', 'escalated')
       OR length(btrim(disposition->>'rationale')) NOT BETWEEN 12 AND 2000
       OR jsonb_typeof(disposition->'evidenceEventRoots') <> 'array'
       OR NOT EXISTS (
         SELECT 1 FROM verification.evidence_ai_analyses analysis,
              jsonb_array_elements(analysis.findings) AS finding_entry(finding_item)
         WHERE analysis.id = disposition->>'analysisId'
           AND analysis.validation_run_id = NEW.validation_run_id
           AND finding_item->>'id' = disposition->>'findingId'
       ) THEN
      RAISE EXCEPTION 'evidence human finding disposition shape or reference is invalid' USING ERRCODE = 'check_violation';
    END IF;
    disposition_roots := ARRAY(SELECT jsonb_array_elements_text(disposition->'evidenceEventRoots'));
    IF cardinality(disposition_roots) > 32
       OR (cardinality(disposition_roots) > 0 AND NOT audit.is_sha256_hash_array(disposition_roots))
       OR NOT audit.is_sorted_unique_text_array(disposition_roots)
       OR (disposition->>'disposition' IN ('accepted', 'overruled') AND cardinality(disposition_roots) = 0)
       OR EXISTS (
         SELECT 1 FROM unnest(disposition_roots) root
         LEFT JOIN audit.domain_events event
           ON event.event_root = root AND event.stream_id = NEW.evidence_id AND event.sequence_no < NEW.evidence_sequence
         WHERE event.id IS NULL
       )
       OR disposition->>'dispositionHash' <> verification.human_disposition_hash(disposition) THEN
      RAISE EXCEPTION 'evidence human finding disposition provenance or hash is invalid' USING ERRCODE = 'check_violation';
    END IF;
    disposition_keys := array_append(disposition_keys, disposition_key);
  END LOOP;
  IF NOT audit.is_sorted_unique_text_array(disposition_keys) THEN
    RAISE EXCEPTION 'evidence human finding dispositions must be sorted and unique' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.decision = 'approve' THEN
    IF NEW.reviewer_snapshot->>'role' <> 'verifier'
       OR NEW.reviewer_snapshot->>'accreditationStatus' <> 'approved'
       OR validation.outcome <> 'pass' THEN
      RAISE EXCEPTION 'evidence approval requires passing validation and accredited verifier role' USING ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO accreditation
    FROM organizations.accreditations
    WHERE id = NEW.reviewer_snapshot->>'accreditationId';
    IF NOT FOUND
       OR accreditation.organization_id <> NEW.organization_id
       OR accreditation.status <> 'approved'
       OR accreditation.decided_at > NEW.reviewed_at
       OR accreditation.audit_event_root <> NEW.reviewer_snapshot->>'accreditationRoot'
       OR to_jsonb(ARRAY(SELECT value FROM unnest(accreditation.scope) value ORDER BY value))
          <> NEW.reviewer_snapshot->'accreditationScope'
       OR NOT EXISTS (
         SELECT 1 FROM organizations.organizations organization
         WHERE organization.id = NEW.organization_id
           AND organization.accreditation_status = 'approved'
       ) THEN
      RAISE EXCEPTION 'evidence approval accreditation snapshot is invalid' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM verification.evidence_ai_analyses analysis,
           jsonb_array_elements(analysis.findings) AS finding_entry(finding_item)
      WHERE analysis.validation_run_id = NEW.validation_run_id
        AND jsonb_extract_path_text(finding_item::jsonb, 'severity') IN ('high', 'critical')
        AND NOT ((analysis.id || ':' || jsonb_extract_path_text(finding_item::jsonb, 'id')) = ANY(disposition_keys))
    ) OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(NEW.finding_dispositions) AS disposition_entry(disposition_item)
      WHERE jsonb_extract_path_text(disposition_item::jsonb, 'disposition') = 'escalated'
        AND EXISTS (
          SELECT 1 FROM verification.evidence_ai_analyses analysis,
               jsonb_array_elements(analysis.findings) AS finding_entry(finding_item)
          WHERE analysis.id = jsonb_extract_path_text(disposition_item::jsonb, 'analysisId')
            AND jsonb_extract_path_text(finding_item::jsonb, 'id') = jsonb_extract_path_text(disposition_item::jsonb, 'findingId')
            AND jsonb_extract_path_text(finding_item::jsonb, 'severity') IN ('high', 'critical')
        )
    ) THEN
      RAISE EXCEPTION 'evidence approval has unresolved or escalated material AI findings' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence FROM audit.domain_events WHERE stream_id = NEW.evidence_id;
  IF semantic_event.stream_id <> NEW.evidence_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.reviewer_id
     OR semantic_event.entity_type <> 'human_review'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> (CASE WHEN NEW.decision = 'approve' THEN 'FULFILL' ELSE 'CHALLENGE' END)
     OR semantic_event.rationale <> NEW.rationale
     OR semantic_event.created_at <> NEW.reviewed_at THEN
    RAISE EXCEPTION 'evidence human review semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.source_root <> verification.human_review_source_root(NEW)
     OR NEW.command_hash <> verification.human_review_command_hash(NEW)
     OR NEW.id <> 'cp_human_review_' || left(NEW.command_hash, 24)
     OR NEW.review_hash <> verification.human_review_hash(NEW)
     OR NEW.review_root <> verification.human_review_root(NEW)
     OR semantic_event.payload_hash <> verification.human_review_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence human review hash lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS verification_evidence_human_reviews_validate ON verification.evidence_human_reviews;
CREATE TRIGGER verification_evidence_human_reviews_validate
BEFORE INSERT ON verification.evidence_human_reviews
FOR EACH ROW EXECUTE FUNCTION verification.validate_evidence_human_review_insert();

DROP TRIGGER IF EXISTS verification_evidence_validation_runs_no_update ON verification.evidence_validation_runs;
CREATE TRIGGER verification_evidence_validation_runs_no_update
BEFORE UPDATE ON verification.evidence_validation_runs
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
DROP TRIGGER IF EXISTS verification_evidence_validation_runs_no_delete ON verification.evidence_validation_runs;
CREATE TRIGGER verification_evidence_validation_runs_no_delete
BEFORE DELETE ON verification.evidence_validation_runs
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();

DROP TRIGGER IF EXISTS verification_evidence_ai_analyses_no_update ON verification.evidence_ai_analyses;
CREATE TRIGGER verification_evidence_ai_analyses_no_update
BEFORE UPDATE ON verification.evidence_ai_analyses
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
DROP TRIGGER IF EXISTS verification_evidence_ai_analyses_no_delete ON verification.evidence_ai_analyses;
CREATE TRIGGER verification_evidence_ai_analyses_no_delete
BEFORE DELETE ON verification.evidence_ai_analyses
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();

DROP TRIGGER IF EXISTS verification_evidence_human_reviews_no_update ON verification.evidence_human_reviews;
CREATE TRIGGER verification_evidence_human_reviews_no_update
BEFORE UPDATE ON verification.evidence_human_reviews
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
DROP TRIGGER IF EXISTS verification_evidence_human_reviews_no_delete ON verification.evidence_human_reviews;
CREATE TRIGGER verification_evidence_human_reviews_no_delete
BEFORE DELETE ON verification.evidence_human_reviews
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();

DROP TRIGGER IF EXISTS verification_evidence_validation_runs_audit ON verification.evidence_validation_runs;
CREATE TRIGGER verification_evidence_validation_runs_audit
AFTER INSERT OR UPDATE OR DELETE ON verification.evidence_validation_runs
FOR EACH ROW EXECUTE FUNCTION audit.capture_row_mutation();
DROP TRIGGER IF EXISTS verification_evidence_ai_analyses_audit ON verification.evidence_ai_analyses;
CREATE TRIGGER verification_evidence_ai_analyses_audit
AFTER INSERT OR UPDATE OR DELETE ON verification.evidence_ai_analyses
FOR EACH ROW EXECUTE FUNCTION audit.capture_row_mutation();
