CREATE TRIGGER verification_evidence_human_reviews_audit
AFTER INSERT OR UPDATE OR DELETE ON verification.evidence_human_reviews
FOR EACH ROW EXECUTE FUNCTION audit.capture_row_mutation();

-- Durable evidence challenge, independent resolution, and correction authority.
CREATE TABLE IF NOT EXISTS verification.evidence_challenges (
  id text PRIMARY KEY,
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  evidence_root text NOT NULL CHECK (evidence_root ~ '^[0-9a-f]{64}$'),
  challenged_reliance_state text NOT NULL CHECK (challenged_reliance_state IN (
    'registered', 'validation_passed', 'needs_review', 'blocked', 'ai_advised',
    'approved', 'rejected', 'challenged', 'changes_requested', 'correction_required'
  )),
  challenged_reliance_root text NOT NULL CHECK (challenged_reliance_root ~ '^[0-9a-f]{64}$'),
  challenged_terminal_event_root text NOT NULL CHECK (challenged_terminal_event_root ~ '^[0-9a-f]{64}$'),
  challenged_validation_run_id text REFERENCES verification.evidence_validation_runs(id),
  challenged_validation_root text CHECK (challenged_validation_root IS NULL OR challenged_validation_root ~ '^[0-9a-f]{64}$'),
  challenged_ai_analysis_ids text[] NOT NULL,
  challenged_ai_analysis_roots text[] NOT NULL,
  challenged_human_review_id text REFERENCES verification.evidence_human_reviews(id),
  challenged_human_review_root text CHECK (challenged_human_review_root IS NULL OR challenged_human_review_root ~ '^[0-9a-f]{64}$'),
  reason text NOT NULL CHECK (reason IN (
    'fake_evidence', 'duplicate_evidence', 'gps_spoofing', 'satellite_contradiction',
    'device_attestation_failure', 'methodology_gap', 'provenance_gap',
    'privacy_risk', 'unsafe_claim', 'other'
  )),
  severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 24 AND 4000),
  supporting_artifact_hashes text[] NOT NULL CHECK (cardinality(supporting_artifact_hashes) BETWEEN 1 AND 128),
  evidence_event_roots text[] NOT NULL CHECK (cardinality(evidence_event_roots) BETWEEN 1 AND 128),
  challenger_id text NOT NULL REFERENCES identity.participants(id),
  challenger_organization_id text NOT NULL REFERENCES organizations.organizations(id),
  challenger_snapshot jsonb NOT NULL CHECK (jsonb_typeof(challenger_snapshot) = 'object'),
  challenged_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 1),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  challenge_hash text NOT NULL UNIQUE CHECK (challenge_hash ~ '^[0-9a-f]{64}$'),
  challenge_root text NOT NULL UNIQUE CHECK (challenge_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence),
  UNIQUE (evidence_id, challenged_reliance_root, challenger_id, reason),
  CHECK ((challenged_validation_run_id IS NULL) = (challenged_validation_root IS NULL)),
  CHECK ((challenged_human_review_id IS NULL) = (challenged_human_review_root IS NULL)),
  CHECK (cardinality(challenged_ai_analysis_ids) = cardinality(challenged_ai_analysis_roots))
);

CREATE TABLE IF NOT EXISTS verification.evidence_challenge_resolutions (
  id text PRIMARY KEY,
  challenge_id text NOT NULL REFERENCES verification.evidence_challenges(id),
  challenge_root text NOT NULL CHECK (challenge_root ~ '^[0-9a-f]{64}$'),
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  evidence_root text NOT NULL CHECK (evidence_root ~ '^[0-9a-f]{64}$'),
  previous_resolution_id text REFERENCES verification.evidence_challenge_resolutions(id),
  previous_resolution_root text CHECK (previous_resolution_root IS NULL OR previous_resolution_root ~ '^[0-9a-f]{64}$'),
  decision text NOT NULL CHECK (decision IN ('upheld', 'dismissed', 'needs_more_evidence')),
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 24 AND 4000),
  limitations text[] NOT NULL CHECK (cardinality(limitations) <= 32),
  evidence_event_roots text[] NOT NULL CHECK (cardinality(evidence_event_roots) BETWEEN 1 AND 128),
  reviewer_id text NOT NULL REFERENCES identity.participants(id),
  reviewer_snapshot jsonb NOT NULL CHECK (jsonb_typeof(reviewer_snapshot) = 'object'),
  reviewed_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 2),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  resolution_hash text NOT NULL UNIQUE CHECK (resolution_hash ~ '^[0-9a-f]{64}$'),
  resolution_root text NOT NULL UNIQUE CHECK (resolution_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence),
  UNIQUE (challenge_id, evidence_sequence),
  CHECK ((previous_resolution_id IS NULL) = (previous_resolution_root IS NULL))
);

CREATE TABLE IF NOT EXISTS verification.evidence_corrections (
  id text PRIMARY KEY,
  challenge_id text NOT NULL REFERENCES verification.evidence_challenges(id),
  challenge_root text NOT NULL CHECK (challenge_root ~ '^[0-9a-f]{64}$'),
  resolution_id text NOT NULL UNIQUE REFERENCES verification.evidence_challenge_resolutions(id),
  resolution_root text NOT NULL CHECK (resolution_root ~ '^[0-9a-f]{64}$'),
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  evidence_root text NOT NULL CHECK (evidence_root ~ '^[0-9a-f]{64}$'),
  action text NOT NULL CHECK (action IN ('withdraw', 'supersede')),
  replacement_evidence_id text REFERENCES evidence.evidence_objects(id),
  replacement_evidence_root text CHECK (replacement_evidence_root IS NULL OR replacement_evidence_root ~ '^[0-9a-f]{64}$'),
  replacement_reliance_root text CHECK (replacement_reliance_root IS NULL OR replacement_reliance_root ~ '^[0-9a-f]{64}$'),
  replacement_terminal_event_root text CHECK (replacement_terminal_event_root IS NULL OR replacement_terminal_event_root ~ '^[0-9a-f]{64}$'),
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 24 AND 4000),
  evidence_event_roots text[] NOT NULL CHECK (cardinality(evidence_event_roots) BETWEEN 1 AND 128),
  publisher_id text NOT NULL REFERENCES identity.participants(id),
  publisher_snapshot jsonb NOT NULL CHECK (jsonb_typeof(publisher_snapshot) = 'object'),
  corrected_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 3),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  correction_hash text NOT NULL UNIQUE CHECK (correction_hash ~ '^[0-9a-f]{64}$'),
  correction_root text NOT NULL UNIQUE CHECK (correction_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence),
  UNIQUE (challenge_id),
  CHECK (
    (action = 'withdraw' AND replacement_evidence_id IS NULL AND replacement_evidence_root IS NULL
      AND replacement_reliance_root IS NULL AND replacement_terminal_event_root IS NULL)
    OR
    (action = 'supersede' AND replacement_evidence_id IS NOT NULL AND replacement_evidence_root IS NOT NULL
      AND replacement_reliance_root IS NOT NULL AND replacement_terminal_event_root IS NOT NULL)
  )
);

CREATE INDEX IF NOT EXISTS evidence_challenges_evidence_time
  ON verification.evidence_challenges (evidence_id, evidence_sequence, id);
CREATE INDEX IF NOT EXISTS evidence_challenges_challenger_time
  ON verification.evidence_challenges (challenger_id, challenged_at DESC, id);
CREATE INDEX IF NOT EXISTS evidence_challenge_resolutions_challenge_time
  ON verification.evidence_challenge_resolutions (challenge_id, evidence_sequence, id);
CREATE INDEX IF NOT EXISTS evidence_challenge_resolutions_reviewer_time
  ON verification.evidence_challenge_resolutions (reviewer_id, reviewed_at DESC, id);
CREATE INDEX IF NOT EXISTS evidence_corrections_evidence_time
  ON verification.evidence_corrections (evidence_id, evidence_sequence, id);
CREATE INDEX IF NOT EXISTS evidence_corrections_replacement
  ON verification.evidence_corrections (replacement_evidence_id) WHERE replacement_evidence_id IS NOT NULL;

CREATE OR REPLACE FUNCTION verification.evidence_challenge_safety_canonical()
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT verification.evidence_verification_safety_canonical() || jsonb_build_object(
    'factsAppendOnly', true,
    'originalEvidencePreserved', true,
    'challengeSuspendsReliance', true,
    'independentHumanResolutionRequired', true,
    'upheldChallengeRequiresCorrection', true,
    'replacementRequiresIndependentApproval', true,
    'crossOrganizationChallengeGrantsNoAccess', true
  );
$$;

CREATE OR REPLACE FUNCTION verification.evidence_reliance_seed_at(
  target_evidence_id text,
  maximum_sequence bigint
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  registration evidence.evidence_objects%ROWTYPE;
  validation verification.evidence_validation_runs%ROWTYPE;
  review verification.evidence_human_reviews%ROWTYPE;
  correction verification.evidence_corrections%ROWTYPE;
  terminal_event audit.domain_events%ROWTYPE;
  analysis_ids text[] := ARRAY[]::text[];
  maximum_analysis_sequence bigint := 0;
  open_challenge_ids text[] := ARRAY[]::text[];
  upheld_challenge_ids text[] := ARRAY[]::text[];
  dismissed_challenge_ids text[] := ARRAY[]::text[];
  corrected_challenge_ids text[] := ARRAY[]::text[];
  reliance_state text;
BEGIN
  SELECT * INTO STRICT registration
  FROM evidence.evidence_objects
  WHERE id = target_evidence_id;

  SELECT * INTO STRICT terminal_event
  FROM audit.domain_events
  WHERE stream_id = target_evidence_id AND sequence_no <= maximum_sequence
  ORDER BY sequence_no DESC
  LIMIT 1;

  SELECT * INTO validation
  FROM verification.evidence_validation_runs
  WHERE evidence_id = target_evidence_id AND evidence_sequence <= maximum_sequence
  ORDER BY evidence_sequence DESC
  LIMIT 1;

  IF validation.id IS NOT NULL THEN
    SELECT
      COALESCE(array_agg(id ORDER BY id), ARRAY[]::text[]),
      COALESCE(max(evidence_sequence), 0)
    INTO analysis_ids, maximum_analysis_sequence
    FROM verification.evidence_ai_analyses
    WHERE evidence_id = target_evidence_id
      AND validation_run_id = validation.id
      AND evidence_sequence <= maximum_sequence;

    SELECT * INTO review
    FROM verification.evidence_human_reviews
    WHERE evidence_id = target_evidence_id
      AND validation_run_id = validation.id
      AND evidence_sequence <= maximum_sequence
    ORDER BY evidence_sequence DESC
    LIMIT 1;
    IF review.id IS NOT NULL AND review.evidence_sequence <= maximum_analysis_sequence THEN
      review := NULL;
    END IF;
  END IF;

  SELECT
    COALESCE(array_agg(challenge_id ORDER BY challenge_id) FILTER (
      WHERE correction_id IS NULL AND (resolution_id IS NULL OR decision = 'needs_more_evidence')
    ), ARRAY[]::text[]),
    COALESCE(array_agg(challenge_id ORDER BY challenge_id) FILTER (
      WHERE correction_id IS NULL AND decision = 'upheld'
    ), ARRAY[]::text[]),
    COALESCE(array_agg(challenge_id ORDER BY challenge_id) FILTER (
      WHERE correction_id IS NULL AND decision = 'dismissed'
    ), ARRAY[]::text[]),
    COALESCE(array_agg(challenge_id ORDER BY challenge_id) FILTER (
      WHERE correction_id IS NOT NULL
    ), ARRAY[]::text[])
  INTO open_challenge_ids, upheld_challenge_ids, dismissed_challenge_ids, corrected_challenge_ids
  FROM (
    SELECT challenge.id AS challenge_id,
      latest_resolution.id AS resolution_id,
      latest_resolution.decision,
      remedy.id AS correction_id
    FROM verification.evidence_challenges challenge
    LEFT JOIN LATERAL (
      SELECT resolution.id, resolution.decision
      FROM verification.evidence_challenge_resolutions resolution
      WHERE resolution.challenge_id = challenge.id
        AND resolution.evidence_sequence <= maximum_sequence
      ORDER BY resolution.evidence_sequence DESC
      LIMIT 1
    ) latest_resolution ON true
    LEFT JOIN verification.evidence_corrections remedy
      ON remedy.challenge_id = challenge.id AND remedy.evidence_sequence <= maximum_sequence
    WHERE challenge.evidence_id = target_evidence_id
      AND challenge.evidence_sequence <= maximum_sequence
  ) challenge_projection;

  SELECT * INTO correction
  FROM verification.evidence_corrections
  WHERE evidence_id = target_evidence_id AND evidence_sequence <= maximum_sequence
  ORDER BY evidence_sequence DESC
  LIMIT 1;

  reliance_state := CASE
    WHEN validation.id IS NULL THEN 'registered'
    WHEN validation.outcome = 'blocked' THEN 'blocked'
    WHEN validation.outcome = 'needs_review' AND cardinality(analysis_ids) = 0 THEN 'needs_review'
    WHEN review.id IS NULL AND cardinality(analysis_ids) > 0 THEN 'ai_advised'
    WHEN review.id IS NULL AND validation.outcome = 'pass' THEN 'validation_passed'
    WHEN review.id IS NULL THEN 'needs_review'
    WHEN review.decision = 'approve' THEN 'approved'
    WHEN review.decision = 'reject' THEN 'rejected'
    WHEN review.decision = 'challenge' THEN 'challenged'
    ELSE 'changes_requested'
  END;
  IF cardinality(open_challenge_ids) > 0 THEN
    reliance_state := 'challenged';
  ELSIF cardinality(upheld_challenge_ids) > 0 THEN
    reliance_state := 'correction_required';
  ELSIF correction.id IS NOT NULL THEN
    reliance_state := CASE correction.action WHEN 'withdraw' THEN 'withdrawn' ELSE 'superseded' END;
  END IF;

  RETURN jsonb_build_object(
    'evidenceId', target_evidence_id,
    'evidenceRoot', registration.evidence_root,
    'state', reliance_state,
    'latestValidationRunId', validation.id,
    'latestValidationRoot', validation.validation_root,
    'currentAiAnalysisIds', to_jsonb(analysis_ids),
    'latestHumanReviewId', review.id,
    'latestHumanReviewRoot', review.review_root,
    'openChallengeIds', to_jsonb(open_challenge_ids),
    'upheldChallengeIds', to_jsonb(upheld_challenge_ids),
    'dismissedChallengeIds', to_jsonb(dismissed_challenge_ids),
    'correctedChallengeIds', to_jsonb(corrected_challenge_ids),
    'latestCorrectionId', correction.id,
    'latestCorrectionRoot', correction.correction_root,
    'replacementEvidenceId', correction.replacement_evidence_id,
    'terminalEventRoot', terminal_event.event_root,
    'evidenceSequence', terminal_event.sequence_no
  );
END;
$$;

CREATE OR REPLACE FUNCTION verification.evidence_reliance_root_at(
  target_evidence_id text,
  maximum_sequence bigint
)
RETURNS text
LANGUAGE sql
STABLE
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-evidence-reliance-v1') ||
    verification.evidence_reliance_seed_at(target_evidence_id, maximum_sequence)
  );
$$;

CREATE OR REPLACE FUNCTION verification.evidence_challenge_command_hash(
  challenge verification.evidence_challenges
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-evidence-challenge-command-v1',
    'evidenceId', challenge.evidence_id,
    'projectId', challenge.project_id,
    'organizationId', challenge.organization_id,
    'evidenceRoot', challenge.evidence_root,
    'challengedRelianceState', challenge.challenged_reliance_state,
    'challengedRelianceRoot', challenge.challenged_reliance_root,
    'challengedTerminalEventRoot', challenge.challenged_terminal_event_root,
    'challengedValidationRunId', challenge.challenged_validation_run_id,
    'challengedValidationRoot', challenge.challenged_validation_root,
    'challengedAiAnalysisIds', to_jsonb(challenge.challenged_ai_analysis_ids),
    'challengedAiAnalysisRoots', to_jsonb(challenge.challenged_ai_analysis_roots),
    'challengedHumanReviewId', challenge.challenged_human_review_id,
    'challengedHumanReviewRoot', challenge.challenged_human_review_root,
    'reason', challenge.reason,
    'severity', challenge.severity,
    'rationale', challenge.rationale,
    'supportingArtifactHashes', to_jsonb(challenge.supporting_artifact_hashes),
    'evidenceEventRoots', to_jsonb(challenge.evidence_event_roots),
    'challenger', challenge.challenger_snapshot,
    'challengedAt', audit.iso8601_millis(challenge.challenged_at)
  ));
$$;

