CREATE OR REPLACE FUNCTION verification.validate_evidence_challenge_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  registration evidence.evidence_objects%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  challenged_seed jsonb;
  expected_analysis_ids text[] := ARRAY[]::text[];
  expected_analysis_roots text[] := ARRAY[]::text[];
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.challenger_id THEN
    RAISE EXCEPTION 'evidence challenge requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT registration
  FROM evidence.evidence_objects WHERE id = NEW.evidence_id FOR SHARE;
  IF NEW.project_id <> registration.project_id
     OR NEW.organization_id <> registration.organization_id
     OR NEW.evidence_root <> registration.evidence_root
     OR NEW.challenger_snapshot->>'organizationId' <> NEW.challenger_organization_id THEN
    RAISE EXCEPTION 'evidence challenge registration or challenger boundary mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.actor_snapshot_is_valid(
    NEW.challenger_snapshot, NEW.challenger_id, NEW.challenger_organization_id,
    'human', ARRAY['owner','admin','verifier','researcher']::text[]
  ) THEN
    RAISE EXCEPTION 'evidence challenger authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF projects.contains_unsafe_claim(ARRAY[NEW.id, NEW.rationale])
     OR NOT audit.is_sha256_hash_array(NEW.supporting_artifact_hashes)
     OR NOT audit.is_sorted_unique_text_array(NEW.supporting_artifact_hashes)
     OR NOT audit.is_sha256_hash_array(NEW.evidence_event_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.evidence_event_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.challenged_ai_analysis_ids)
     OR NOT audit.is_sha256_hash_array(NEW.challenged_ai_analysis_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.challenged_ai_analysis_roots)
     OR NEW.safety <> verification.evidence_challenge_safety_canonical() THEN
    RAISE EXCEPTION 'evidence challenge input or safety boundary is not canonical' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(NEW.evidence_event_roots) root
    LEFT JOIN audit.domain_events event
      ON event.event_root = root
      AND event.stream_id = NEW.evidence_id
      AND event.sequence_no < NEW.evidence_sequence
    WHERE event.id IS NULL
  ) THEN
    RAISE EXCEPTION 'evidence challenge references a missing or future semantic event' USING ERRCODE = 'check_violation';
  END IF;

  challenged_seed := verification.evidence_reliance_seed_at(NEW.evidence_id, NEW.evidence_sequence - 1);
  IF challenged_seed->>'state' IN ('withdrawn', 'superseded')
     OR NEW.challenged_reliance_state <> challenged_seed->>'state'
     OR NEW.challenged_reliance_root <> verification.evidence_reliance_root_at(NEW.evidence_id, NEW.evidence_sequence - 1)
     OR NEW.challenged_terminal_event_root <> challenged_seed->>'terminalEventRoot'
     OR NEW.challenged_validation_run_id IS DISTINCT FROM NULLIF(challenged_seed->>'latestValidationRunId', '')
     OR NEW.challenged_validation_root IS DISTINCT FROM NULLIF(challenged_seed->>'latestValidationRoot', '')
     OR NEW.challenged_human_review_id IS DISTINCT FROM NULLIF(challenged_seed->>'latestHumanReviewId', '')
     OR NEW.challenged_human_review_root IS DISTINCT FROM NULLIF(challenged_seed->>'latestHumanReviewRoot', '')
     OR NOT (registration.audit_event_root = ANY(NEW.evidence_event_roots))
     OR NOT (NEW.challenged_terminal_event_root = ANY(NEW.evidence_event_roots)) THEN
    RAISE EXCEPTION 'evidence challenge does not bind the exact prior reliance projection' USING ERRCODE = 'check_violation';
  END IF;
  expected_analysis_ids := ARRAY(SELECT jsonb_array_elements_text(challenged_seed->'currentAiAnalysisIds'));
  SELECT COALESCE(array_agg(analysis_root ORDER BY analysis_root), ARRAY[]::text[])
  INTO expected_analysis_roots
  FROM verification.evidence_ai_analyses
  WHERE id = ANY(expected_analysis_ids);
  IF NEW.challenged_ai_analysis_ids <> expected_analysis_ids
     OR NEW.challenged_ai_analysis_roots <> expected_analysis_roots THEN
    RAISE EXCEPTION 'evidence challenge AI source projection mismatch' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence FROM audit.domain_events WHERE stream_id = NEW.evidence_id;
  IF semantic_event.stream_id <> NEW.evidence_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.challenger_id
     OR semantic_event.entity_type <> 'evidence_challenge'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> 'CHALLENGE'
     OR semantic_event.rationale <> 'A verified human opened an evidence-rooted challenge; current reliance is suspended pending independent review.'
     OR semantic_event.created_at <> NEW.challenged_at THEN
    RAISE EXCEPTION 'evidence challenge semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.command_hash <> verification.evidence_challenge_command_hash(NEW)
     OR NEW.id <> 'cp_evidence_challenge_' || left(NEW.command_hash, 24)
     OR NEW.challenge_hash <> verification.evidence_challenge_hash(NEW)
     OR NEW.challenge_root <> verification.evidence_challenge_root(NEW)
     OR semantic_event.payload_hash <> verification.evidence_challenge_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence challenge hash lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS verification_evidence_challenges_validate ON verification.evidence_challenges;
CREATE TRIGGER verification_evidence_challenges_validate
BEFORE INSERT ON verification.evidence_challenges
FOR EACH ROW EXECUTE FUNCTION verification.validate_evidence_challenge_insert();

CREATE OR REPLACE FUNCTION verification.validate_evidence_challenge_resolution_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  challenge verification.evidence_challenges%ROWTYPE;
  registration evidence.evidence_objects%ROWTYPE;
  previous_resolution verification.evidence_challenge_resolutions%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  accreditation organizations.accreditations%ROWTYPE;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.reviewer_id THEN
    RAISE EXCEPTION 'evidence challenge resolution requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT challenge
  FROM verification.evidence_challenges WHERE id = NEW.challenge_id FOR SHARE;
  SELECT * INTO STRICT registration
  FROM evidence.evidence_objects WHERE id = NEW.evidence_id FOR SHARE;
  IF NEW.challenge_root <> challenge.challenge_root
     OR NEW.evidence_id <> challenge.evidence_id
     OR NEW.project_id <> challenge.project_id
     OR NEW.organization_id <> challenge.organization_id
     OR NEW.evidence_root <> challenge.evidence_root
     OR registration.evidence_root <> NEW.evidence_root THEN
    RAISE EXCEPTION 'evidence challenge resolution lineage boundary mismatch' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.actor_snapshot_is_valid(
    NEW.reviewer_snapshot, NEW.reviewer_id, NEW.organization_id,
    'human', ARRAY['verifier','researcher']::text[]
  ) THEN
    RAISE EXCEPTION 'evidence challenge reviewer authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reviewer_id IN (registration.contributor_id, challenge.challenger_id)
     OR (challenge.challenged_human_review_id IS NOT NULL AND EXISTS (
       SELECT 1 FROM verification.evidence_human_reviews review
       WHERE review.id = challenge.challenged_human_review_id AND review.reviewer_id = NEW.reviewer_id
     ))
     OR EXISTS (
       SELECT 1 FROM verification.evidence_ai_analyses analysis
       WHERE analysis.id = ANY(challenge.challenged_ai_analysis_ids) AND analysis.agent_id = NEW.reviewer_id
     )
     OR EXISTS (
       SELECT 1 FROM verification.evidence_challenge_resolutions prior
       WHERE prior.challenge_id = NEW.challenge_id AND prior.reviewer_id = NEW.reviewer_id
     ) THEN
    RAISE EXCEPTION 'evidence challenge resolution requires an independent human reviewer' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO previous_resolution
  FROM verification.evidence_challenge_resolutions
  WHERE challenge_id = NEW.challenge_id
  ORDER BY evidence_sequence DESC LIMIT 1;
  IF previous_resolution.id IS NULL THEN
    IF NEW.previous_resolution_id IS NOT NULL OR NEW.previous_resolution_root IS NOT NULL THEN
      RAISE EXCEPTION 'first evidence challenge resolution cannot claim a predecessor' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF previous_resolution.decision <> 'needs_more_evidence'
     OR NEW.previous_resolution_id IS DISTINCT FROM previous_resolution.id
     OR NEW.previous_resolution_root IS DISTINCT FROM previous_resolution.resolution_root THEN
    RAISE EXCEPTION 'evidence challenge resolution predecessor is not the latest open review step' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.decision <> 'needs_more_evidence' THEN
    IF NEW.reviewer_snapshot->>'role' <> 'verifier'
       OR NEW.reviewer_snapshot->>'accreditationStatus' <> 'approved' THEN
      RAISE EXCEPTION 'terminal evidence challenge resolution requires accredited verifier authority' USING ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO accreditation
    FROM organizations.accreditations
    WHERE id = NEW.reviewer_snapshot->>'accreditationId';
    IF NOT FOUND
       OR accreditation.organization_id <> NEW.organization_id
       OR accreditation.status <> 'approved'
       OR accreditation.decided_at > NEW.reviewed_at
       OR accreditation.audit_event_root <> NEW.reviewer_snapshot->>'accreditationRoot'
       OR NOT EXISTS (
         SELECT 1 FROM organizations.organizations organization
         WHERE organization.id = NEW.organization_id AND organization.accreditation_status = 'approved'
       ) THEN
      RAISE EXCEPTION 'terminal evidence challenge resolution accreditation is invalid' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.reviewed_at < challenge.challenged_at
     OR projects.contains_unsafe_claim(ARRAY[NEW.id, NEW.rationale] || NEW.limitations)
     OR NOT audit.is_bounded_text_array(NEW.limitations, 1, 1000, 32)
     OR NOT audit.is_sorted_unique_text_array(NEW.limitations)
     OR NOT audit.is_sha256_hash_array(NEW.evidence_event_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.evidence_event_roots)
     OR NOT (challenge.audit_event_root = ANY(NEW.evidence_event_roots))
     OR (previous_resolution.id IS NOT NULL AND NOT (previous_resolution.audit_event_root = ANY(NEW.evidence_event_roots)))
     OR NEW.safety <> verification.evidence_challenge_safety_canonical()
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.evidence_event_roots) root
       LEFT JOIN audit.domain_events event
         ON event.event_root = root
         AND event.stream_id = NEW.evidence_id
         AND event.sequence_no < NEW.evidence_sequence
       WHERE event.id IS NULL
     ) THEN
    RAISE EXCEPTION 'evidence challenge resolution sources or safety boundary are invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence FROM audit.domain_events WHERE stream_id = NEW.evidence_id;
  IF semantic_event.stream_id <> NEW.evidence_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.reviewer_id
     OR semantic_event.entity_type <> 'evidence_challenge_resolution'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> (CASE NEW.decision
       WHEN 'dismissed' THEN 'FULFILL' WHEN 'upheld' THEN 'CHALLENGE' ELSE 'REASON' END)
     OR semantic_event.rationale <> NEW.rationale
     OR semantic_event.created_at <> NEW.reviewed_at THEN
    RAISE EXCEPTION 'evidence challenge resolution semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.source_root <> verification.evidence_challenge_resolution_source_root(NEW)
     OR NEW.command_hash <> verification.evidence_challenge_resolution_command_hash(NEW)
     OR NEW.id <> 'cp_evidence_challenge_resolution_' || left(NEW.command_hash, 24)
     OR NEW.resolution_hash <> verification.evidence_challenge_resolution_hash(NEW)
     OR NEW.resolution_root <> verification.evidence_challenge_resolution_root(NEW)
     OR semantic_event.payload_hash <> verification.evidence_challenge_resolution_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence challenge resolution hash lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS verification_evidence_challenge_resolutions_validate ON verification.evidence_challenge_resolutions;
CREATE TRIGGER verification_evidence_challenge_resolutions_validate
BEFORE INSERT ON verification.evidence_challenge_resolutions
FOR EACH ROW EXECUTE FUNCTION verification.validate_evidence_challenge_resolution_insert();

CREATE OR REPLACE FUNCTION verification.validate_evidence_correction_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  challenge verification.evidence_challenges%ROWTYPE;
  resolution verification.evidence_challenge_resolutions%ROWTYPE;
  registration evidence.evidence_objects%ROWTYPE;
  challenged_review verification.evidence_human_reviews%ROWTYPE;
  replacement evidence.evidence_objects%ROWTYPE;
  replacement_seed jsonb;
  replacement_terminal_event audit.domain_events%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  latest_resolution_id text;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.publisher_id THEN
    RAISE EXCEPTION 'evidence correction requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT challenge
  FROM verification.evidence_challenges WHERE id = NEW.challenge_id FOR SHARE;
  SELECT * INTO STRICT resolution
  FROM verification.evidence_challenge_resolutions WHERE id = NEW.resolution_id FOR SHARE;
  SELECT * INTO STRICT registration
  FROM evidence.evidence_objects WHERE id = NEW.evidence_id FOR SHARE;
  SELECT id INTO latest_resolution_id
  FROM verification.evidence_challenge_resolutions
  WHERE challenge_id = NEW.challenge_id
  ORDER BY evidence_sequence DESC LIMIT 1;
  IF resolution.id <> latest_resolution_id
     OR resolution.decision <> 'upheld'
     OR resolution.challenge_id <> challenge.id
     OR NEW.challenge_root <> challenge.challenge_root
     OR NEW.resolution_root <> resolution.resolution_root
     OR NEW.evidence_id <> challenge.evidence_id
     OR NEW.project_id <> challenge.project_id
     OR NEW.organization_id <> challenge.organization_id
     OR NEW.evidence_root <> challenge.evidence_root
     OR registration.evidence_root <> NEW.evidence_root THEN
    RAISE EXCEPTION 'evidence correction requires the exact latest upheld challenge lineage' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.actor_snapshot_is_valid(
    NEW.publisher_snapshot, NEW.publisher_id, NEW.organization_id,
    'human', ARRAY['owner','admin','verifier']::text[]
  ) THEN
    RAISE EXCEPTION 'evidence correction publisher authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.publisher_snapshot->>'role' = 'verifier'
     AND NEW.publisher_snapshot->>'accreditationStatus' <> 'approved' THEN
    RAISE EXCEPTION 'evidence correction verifier requires current approved accreditation' USING ERRCODE = 'check_violation';
  END IF;
  IF challenge.challenged_human_review_id IS NOT NULL THEN
    SELECT * INTO challenged_review
    FROM verification.evidence_human_reviews WHERE id = challenge.challenged_human_review_id;
  END IF;
  IF NEW.publisher_id IN (registration.contributor_id, challenge.challenger_id, resolution.reviewer_id)
     OR (challenged_review.id IS NOT NULL AND NEW.publisher_id = challenged_review.reviewer_id) THEN
    RAISE EXCEPTION 'evidence correction requires an independent human publisher' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.corrected_at < resolution.reviewed_at
     OR projects.contains_unsafe_claim(ARRAY[NEW.id, NEW.rationale, COALESCE(NEW.replacement_evidence_id, '')])
     OR NOT audit.is_sha256_hash_array(NEW.evidence_event_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.evidence_event_roots)
     OR NOT (resolution.audit_event_root = ANY(NEW.evidence_event_roots))
     OR NEW.safety <> verification.evidence_challenge_safety_canonical()
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.evidence_event_roots) root
       LEFT JOIN audit.domain_events event
         ON event.event_root = root
         AND event.stream_id = NEW.evidence_id
         AND event.sequence_no < NEW.evidence_sequence
       WHERE event.id IS NULL
     ) THEN
    RAISE EXCEPTION 'evidence correction sources or safety boundary are invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.action = 'supersede' THEN
    IF NEW.replacement_evidence_id = NEW.evidence_id THEN
      RAISE EXCEPTION 'evidence correction replacement must be distinct' USING ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO STRICT replacement
    FROM evidence.evidence_objects WHERE id = NEW.replacement_evidence_id FOR SHARE;
    IF replacement.organization_id <> NEW.organization_id OR replacement.project_id <> NEW.project_id THEN
      RAISE EXCEPTION 'evidence correction replacement organization or project mismatch' USING ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO STRICT replacement_terminal_event
    FROM audit.domain_events
    WHERE stream_id = replacement.id
    ORDER BY sequence_no DESC LIMIT 1;
    replacement_seed := verification.evidence_reliance_seed_at(replacement.id, replacement_terminal_event.sequence_no);
    IF replacement_seed->>'state' <> 'approved'
       OR NEW.replacement_evidence_root <> replacement.evidence_root
       OR NEW.replacement_reliance_root <> verification.evidence_reliance_root_at(replacement.id, replacement_terminal_event.sequence_no)
       OR NEW.replacement_terminal_event_root <> replacement_terminal_event.event_root
       OR replacement_terminal_event.created_at >= NEW.corrected_at THEN
      RAISE EXCEPTION 'evidence correction replacement is not independently approved and prior' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence FROM audit.domain_events WHERE stream_id = NEW.evidence_id;
  IF semantic_event.stream_id <> NEW.evidence_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.publisher_id
     OR semantic_event.entity_type <> 'evidence_correction'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> 'FULFILL'
     OR semantic_event.rationale <> NEW.rationale
     OR semantic_event.created_at <> NEW.corrected_at THEN
    RAISE EXCEPTION 'evidence correction semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.source_root <> verification.evidence_correction_source_root(NEW)
     OR NEW.command_hash <> verification.evidence_correction_command_hash(NEW)
     OR NEW.id <> 'cp_evidence_correction_' || left(NEW.command_hash, 24)
     OR NEW.correction_hash <> verification.evidence_correction_hash(NEW)
     OR NEW.correction_root <> verification.evidence_correction_root(NEW)
     OR semantic_event.payload_hash <> verification.evidence_correction_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence correction hash lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

