-- Durable second-human final evidence verification authority. This is an
-- internal evidence decision only; it does not issue a certificate or credit.
CREATE TABLE IF NOT EXISTS verification.evidence_final_decisions (
  id text PRIMARY KEY,
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  evidence_root text NOT NULL CHECK (evidence_root ~ '^[0-9a-f]{64}$'),
  pre_decision_reliance_state text NOT NULL CHECK (pre_decision_reliance_state IN (
    'registered', 'validation_passed', 'needs_review', 'blocked', 'ai_advised',
    'approved', 'rejected', 'challenged', 'changes_requested', 'correction_required',
    'withdrawn', 'superseded'
  )),
  pre_decision_reliance_root text NOT NULL CHECK (pre_decision_reliance_root ~ '^[0-9a-f]{64}$'),
  pre_decision_terminal_event_root text NOT NULL CHECK (pre_decision_terminal_event_root ~ '^[0-9a-f]{64}$'),
  validation_run_id text NOT NULL REFERENCES verification.evidence_validation_runs(id),
  validation_root text NOT NULL CHECK (validation_root ~ '^[0-9a-f]{64}$'),
  ai_analysis_ids text[] NOT NULL CHECK (cardinality(ai_analysis_ids) BETWEEN 1 AND 64),
  ai_analysis_roots text[] NOT NULL CHECK (cardinality(ai_analysis_roots) BETWEEN 1 AND 64),
  human_review_id text NOT NULL REFERENCES verification.evidence_human_reviews(id),
  human_review_root text NOT NULL CHECK (human_review_root ~ '^[0-9a-f]{64}$'),
  prior_final_decision_id text REFERENCES verification.evidence_final_decisions(id),
  prior_final_decision_root text CHECK (prior_final_decision_root IS NULL OR prior_final_decision_root ~ '^[0-9a-f]{64}$'),
  decision text NOT NULL CHECK (decision IN ('verify', 'reject', 'request_changes')),
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 24 AND 4000),
  limitations text[] NOT NULL CHECK (cardinality(limitations) <= 32),
  source_event_roots text[] NOT NULL CHECK (cardinality(source_event_roots) BETWEEN 1 AND 256),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  verifier_id text NOT NULL REFERENCES identity.participants(id),
  verifier_snapshot jsonb NOT NULL CHECK (jsonb_typeof(verifier_snapshot) = 'object'),
  decided_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 4),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  decision_hash text NOT NULL UNIQUE CHECK (decision_hash ~ '^[0-9a-f]{64}$'),
  decision_root text NOT NULL UNIQUE CHECK (decision_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence),
  CHECK (cardinality(ai_analysis_ids) = cardinality(ai_analysis_roots)),
  CHECK ((prior_final_decision_id IS NULL) = (prior_final_decision_root IS NULL))
);

CREATE INDEX IF NOT EXISTS evidence_final_decisions_evidence_sequence
  ON verification.evidence_final_decisions (evidence_id, evidence_sequence, id);
CREATE INDEX IF NOT EXISTS evidence_final_decisions_decision_time
  ON verification.evidence_final_decisions (decision, decided_at DESC, id);
CREATE INDEX IF NOT EXISTS evidence_final_decisions_verifier_time
  ON verification.evidence_final_decisions (verifier_id, decided_at DESC, id);
CREATE INDEX IF NOT EXISTS evidence_final_decisions_reliance_root
  ON verification.evidence_final_decisions (pre_decision_reliance_root);
CREATE INDEX IF NOT EXISTS evidence_final_decisions_prior
  ON verification.evidence_final_decisions (prior_final_decision_id)
  WHERE prior_final_decision_id IS NOT NULL;

CREATE OR REPLACE FUNCTION verification.evidence_final_decision_safety_canonical()
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT jsonb_build_object(
    'evidenceRegistrationImmutable', true,
    'aiAdvisoryOnly', true,
    'makerCheckerRequired', true,
    'currentAccreditedVerifierRequired', true,
    'challengeAwareRelianceBound', true,
    'laterFactsInvalidateDecision', true,
    'notEnvironmentalProofRecord', true,
    'notCertificate', true,
    'notCertifiedCarbonCredit', true,
    'notCarbonTaxOffset', true,
    'notFinancialAsset', true,
    'notGuaranteedYield', true,
    'noMainnetFunds', true,
    'notAutomaticCanopyDistribution', true
  );
$$;

CREATE OR REPLACE FUNCTION verification.evidence_final_decision_command_hash(
  final_decision verification.evidence_final_decisions
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-evidence-final-decision-command-v1',
    'evidenceId', final_decision.evidence_id,
    'projectId', final_decision.project_id,
    'organizationId', final_decision.organization_id,
    'evidenceRoot', final_decision.evidence_root,
    'preDecisionRelianceState', final_decision.pre_decision_reliance_state,
    'preDecisionRelianceRoot', final_decision.pre_decision_reliance_root,
    'preDecisionTerminalEventRoot', final_decision.pre_decision_terminal_event_root,
    'validationRunId', final_decision.validation_run_id,
    'validationRoot', final_decision.validation_root,
    'aiAnalysisIds', to_jsonb(final_decision.ai_analysis_ids),
    'aiAnalysisRoots', to_jsonb(final_decision.ai_analysis_roots),
    'humanReviewId', final_decision.human_review_id,
    'humanReviewRoot', final_decision.human_review_root,
    'priorFinalDecisionId', final_decision.prior_final_decision_id,
    'priorFinalDecisionRoot', final_decision.prior_final_decision_root,
    'decision', final_decision.decision,
    'rationale', final_decision.rationale,
    'limitations', to_jsonb(final_decision.limitations),
    'sourceEventRoots', to_jsonb(final_decision.source_event_roots),
    'verifier', final_decision.verifier_snapshot,
    'decidedAt', audit.iso8601_millis(final_decision.decided_at)
  ));
$$;

CREATE OR REPLACE FUNCTION verification.evidence_final_decision_source_root(
  final_decision verification.evidence_final_decisions
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.merkle_root(ARRAY(
    SELECT leaf FROM (
      SELECT final_decision.evidence_root AS leaf
      UNION ALL SELECT final_decision.pre_decision_reliance_root
      UNION ALL SELECT final_decision.validation_root
      UNION ALL SELECT unnest(final_decision.ai_analysis_roots)
      UNION ALL SELECT final_decision.human_review_root
      UNION ALL SELECT unnest(final_decision.source_event_roots)
      UNION ALL SELECT final_decision.prior_final_decision_root
        WHERE final_decision.prior_final_decision_root IS NOT NULL
    ) leaves ORDER BY leaf
  ));
$$;

CREATE OR REPLACE FUNCTION verification.evidence_final_decision_hash(
  final_decision verification.evidence_final_decisions
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-evidence-final-decision-v1') ||
    jsonb_strip_nulls(jsonb_build_object(
      'evidenceId', final_decision.evidence_id,
      'projectId', final_decision.project_id,
      'organizationId', final_decision.organization_id,
      'evidenceRoot', final_decision.evidence_root,
      'preDecisionRelianceState', final_decision.pre_decision_reliance_state,
      'preDecisionRelianceRoot', final_decision.pre_decision_reliance_root,
      'preDecisionTerminalEventRoot', final_decision.pre_decision_terminal_event_root,
      'validationRunId', final_decision.validation_run_id,
      'validationRoot', final_decision.validation_root,
      'aiAnalysisIds', to_jsonb(final_decision.ai_analysis_ids),
      'aiAnalysisRoots', to_jsonb(final_decision.ai_analysis_roots),
      'humanReviewId', final_decision.human_review_id,
      'humanReviewRoot', final_decision.human_review_root,
      'priorFinalDecisionId', final_decision.prior_final_decision_id,
      'priorFinalDecisionRoot', final_decision.prior_final_decision_root,
      'decision', final_decision.decision,
      'rationale', final_decision.rationale,
      'limitations', to_jsonb(final_decision.limitations),
      'sourceEventRoots', to_jsonb(final_decision.source_event_roots),
      'sourceRoot', final_decision.source_root,
      'verifier', final_decision.verifier_snapshot,
      'decidedAt', audit.iso8601_millis(final_decision.decided_at),
      'commandHash', final_decision.command_hash,
      'evidenceSequence', final_decision.evidence_sequence,
      'previousEventRoot', final_decision.previous_event_root
    ))
  );
$$;

CREATE OR REPLACE FUNCTION verification.evidence_final_decision_root(
  final_decision verification.evidence_final_decisions
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-evidence-final-decision-root-v1',
    'evidenceRoot', final_decision.evidence_root,
    'preDecisionRelianceRoot', final_decision.pre_decision_reliance_root,
