  final_decision verification.evidence_final_decisions
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('factType', 'evidence_final_decision', 'id', final_decision.id) ||
    jsonb_strip_nulls(jsonb_build_object(
      'evidenceId', final_decision.evidence_id,
      'projectId', final_decision.project_id,
      'organizationId', final_decision.organization_id,
      'evidenceRoot', final_decision.evidence_root,
      'preDecisionRelianceState', final_decision.pre_decision_reliance_state,
      'preDecisionRelianceRoot', final_decision.pre_decision_reliance_root,
      'preDecisionTerminalEventRoot', final_decision.pre_decision_terminal_event_root,
      'validationRunId', final_decision.validation_run_id,
      'validationRoot', final_decision.validation_root,
      'aiAnalysisIds', to_jsonb(final_decision.ai_analysis_ids),
      'aiAnalysisRoots', to_jsonb(final_decision.ai_analysis_roots),
      'humanReviewId', final_decision.human_review_id,
      'humanReviewRoot', final_decision.human_review_root,
      'priorFinalDecisionId', final_decision.prior_final_decision_id,
      'priorFinalDecisionRoot', final_decision.prior_final_decision_root,
      'decision', final_decision.decision,
      'rationale', final_decision.rationale,
      'limitations', to_jsonb(final_decision.limitations),
      'sourceEventRoots', to_jsonb(final_decision.source_event_roots),
      'sourceRoot', final_decision.source_root,
      'verifier', final_decision.verifier_snapshot,
      'decidedAt', audit.iso8601_millis(final_decision.decided_at),
      'commandHash', final_decision.command_hash,
      'evidenceSequence', final_decision.evidence_sequence,
      'previousEventRoot', final_decision.previous_event_root,
      'decisionHash', final_decision.decision_hash,
      'decisionRoot', final_decision.decision_root,
      'safety', final_decision.safety
    ))
  );
$$;

CREATE OR REPLACE FUNCTION verification.evidence_final_verification_seed_at(
  target_evidence_id text,
  maximum_sequence bigint
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  registration evidence.evidence_objects%ROWTYPE;
  terminal_event audit.domain_events%ROWTYPE;
  latest_decision verification.evidence_final_decisions%ROWTYPE;
  current_decision_id text;
  current_decision_root text;
  projection_state text;
BEGIN
  SELECT * INTO STRICT registration
  FROM evidence.evidence_objects WHERE id = target_evidence_id;
  SELECT * INTO STRICT terminal_event
  FROM audit.domain_events
  WHERE stream_id = target_evidence_id AND sequence_no <= maximum_sequence
  ORDER BY sequence_no DESC LIMIT 1;
  SELECT * INTO latest_decision
  FROM verification.evidence_final_decisions
  WHERE evidence_id = target_evidence_id AND evidence_sequence <= maximum_sequence
  ORDER BY evidence_sequence DESC LIMIT 1;

  IF latest_decision.id IS NULL THEN
    projection_state := 'not_decided';
  ELSIF latest_decision.audit_event_root <> terminal_event.event_root THEN
    projection_state := 'stale';
  ELSE
    projection_state := CASE latest_decision.decision
      WHEN 'verify' THEN 'verified'
      WHEN 'reject' THEN 'rejected'
      ELSE 'changes_requested'
    END;
    current_decision_id := latest_decision.id;
    current_decision_root := latest_decision.decision_root;
  END IF;

  RETURN jsonb_build_object(
    'evidenceId', target_evidence_id,
    'evidenceRoot', registration.evidence_root,
    'state', projection_state,
    'latestDecisionId', latest_decision.id,
    'latestDecisionRoot', latest_decision.decision_root,
    'currentDecisionId', current_decision_id,
    'currentDecisionRoot', current_decision_root,
    'terminalEventRoot', terminal_event.event_root,
    'evidenceSequence', terminal_event.sequence_no
  );
END;
$$;

CREATE OR REPLACE FUNCTION verification.evidence_final_verification_root_at(
  target_evidence_id text,
  maximum_sequence bigint
)
RETURNS text
LANGUAGE sql
STABLE
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-evidence-final-verification-v1') ||
    verification.evidence_final_verification_seed_at(target_evidence_id, maximum_sequence)
  );
$$;

CREATE OR REPLACE FUNCTION verification.validate_evidence_final_decision_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  registration evidence.evidence_objects%ROWTYPE;
  validation verification.evidence_validation_runs%ROWTYPE;
  human_review verification.evidence_human_reviews%ROWTYPE;
  accreditation organizations.accreditations%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  latest_prior verification.evidence_final_decisions%ROWTYPE;
  reliance_seed jsonb;
  expected_analysis_ids text[] := ARRAY[]::text[];
  expected_analysis_roots text[] := ARRAY[]::text[];
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.verifier_id THEN
    RAISE EXCEPTION 'evidence final decision requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT registration
  FROM evidence.evidence_objects WHERE id = NEW.evidence_id FOR SHARE;
  SELECT * INTO STRICT validation
  FROM verification.evidence_validation_runs WHERE id = NEW.validation_run_id FOR SHARE;
  SELECT * INTO STRICT human_review
  FROM verification.evidence_human_reviews WHERE id = NEW.human_review_id FOR SHARE;

  reliance_seed := verification.evidence_reliance_seed_at(NEW.evidence_id, NEW.evidence_sequence - 1);
  expected_analysis_ids := ARRAY(SELECT jsonb_array_elements_text(reliance_seed->'currentAiAnalysisIds'));
  SELECT COALESCE(array_agg(analysis_root ORDER BY analysis_root), ARRAY[]::text[])
  INTO expected_analysis_roots
  FROM verification.evidence_ai_analyses WHERE id = ANY(expected_analysis_ids);

  IF NEW.project_id <> registration.project_id
     OR NEW.organization_id <> registration.organization_id
     OR NEW.evidence_root <> registration.evidence_root
     OR NEW.validation_run_id IS DISTINCT FROM NULLIF(reliance_seed->>'latestValidationRunId', '')
     OR NEW.validation_root IS DISTINCT FROM NULLIF(reliance_seed->>'latestValidationRoot', '')
     OR NEW.human_review_id IS DISTINCT FROM NULLIF(reliance_seed->>'latestHumanReviewId', '')
     OR NEW.human_review_root IS DISTINCT FROM NULLIF(reliance_seed->>'latestHumanReviewRoot', '')
     OR validation.evidence_id <> NEW.evidence_id
     OR validation.validation_root <> NEW.validation_root
     OR human_review.evidence_id <> NEW.evidence_id
     OR human_review.review_root <> NEW.human_review_root
     OR NEW.ai_analysis_ids <> expected_analysis_ids
     OR NEW.ai_analysis_roots <> expected_analysis_roots THEN
    RAISE EXCEPTION 'evidence final decision does not bind the current verification authority set' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.pre_decision_reliance_state <> reliance_seed->>'state'
     OR NEW.pre_decision_reliance_root <> verification.evidence_reliance_root_at(NEW.evidence_id, NEW.evidence_sequence - 1)
     OR NEW.pre_decision_terminal_event_root <> reliance_seed->>'terminalEventRoot'
     OR NEW.previous_event_root <> NEW.pre_decision_terminal_event_root
     OR NEW.pre_decision_reliance_state IN (
       'registered', 'validation_passed', 'ai_advised', 'challenged',
       'correction_required', 'withdrawn', 'superseded'
     ) THEN
    RAISE EXCEPTION 'evidence final decision reliance projection is ineligible or non-canonical' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.decision = 'verify'
     AND (NEW.pre_decision_reliance_state <> 'approved' OR human_review.decision <> 'approve') THEN
    RAISE EXCEPTION 'evidence verify decision requires current approved human-reviewed reliance' USING ERRCODE = 'check_violation';
  END IF;

  IF NOT verification.actor_snapshot_is_valid(
    NEW.verifier_snapshot, NEW.verifier_id, NEW.organization_id,
    'human', ARRAY['verifier']::text[]
  ) OR NEW.verifier_snapshot->>'role' <> 'verifier'
     OR NEW.verifier_snapshot->>'accreditationStatus' <> 'approved' THEN
    RAISE EXCEPTION 'evidence final decision verifier authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO accreditation
  FROM organizations.accreditations
  WHERE id = NEW.verifier_snapshot->>'accreditationId';
  IF NOT FOUND
     OR accreditation.organization_id <> NEW.organization_id
     OR accreditation.status <> 'approved'
     OR accreditation.decided_at > NEW.decided_at
     OR accreditation.audit_event_root <> NEW.verifier_snapshot->>'accreditationRoot'
     OR to_jsonb(ARRAY(SELECT value FROM unnest(accreditation.scope) value ORDER BY value))
        <> NEW.verifier_snapshot->'accreditationScope'
     OR NOT EXISTS (
       SELECT 1 FROM organizations.organizations organization
       WHERE organization.id = NEW.organization_id
         AND organization.accreditation_status = 'approved'
     ) THEN
    RAISE EXCEPTION 'evidence final decision accreditation snapshot is invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO latest_prior
  FROM verification.evidence_final_decisions
  WHERE evidence_id = NEW.evidence_id
  ORDER BY evidence_sequence DESC LIMIT 1;
  IF latest_prior.id IS NULL THEN
    IF NEW.prior_final_decision_id IS NOT NULL OR NEW.prior_final_decision_root IS NOT NULL THEN
      RAISE EXCEPTION 'first evidence final decision cannot claim a prior final decision' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF latest_prior.audit_event_root = NEW.pre_decision_terminal_event_root
     OR NEW.prior_final_decision_id IS DISTINCT FROM latest_prior.id
     OR NEW.prior_final_decision_root IS DISTINCT FROM latest_prior.decision_root THEN
    RAISE EXCEPTION 'evidence final decision requires an intervening authority fact and exact prior lineage' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.verifier_id = registration.contributor_id
     OR NEW.verifier_id = human_review.reviewer_id
     OR (latest_prior.id IS NOT NULL AND NEW.verifier_id = latest_prior.verifier_id)
     OR EXISTS (
       SELECT 1 FROM verification.evidence_ai_analyses analysis
       WHERE analysis.id = ANY(expected_analysis_ids) AND analysis.agent_id = NEW.verifier_id
     )
     OR EXISTS (
       SELECT 1 FROM verification.evidence_challenges challenge
       WHERE challenge.evidence_id = NEW.evidence_id AND challenge.challenger_id = NEW.verifier_id
     )
     OR EXISTS (
       SELECT 1 FROM verification.evidence_challenge_resolutions resolution
       WHERE resolution.evidence_id = NEW.evidence_id AND resolution.reviewer_id = NEW.verifier_id
     )
     OR EXISTS (
       SELECT 1 FROM verification.evidence_corrections correction
       WHERE correction.evidence_id = NEW.evidence_id AND correction.publisher_id = NEW.verifier_id
     ) THEN
    RAISE EXCEPTION 'evidence final decision requires an independent accredited verifier' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.decided_at < human_review.reviewed_at
     OR projects.contains_unsafe_claim(ARRAY[NEW.id, NEW.rationale] || NEW.limitations)
     OR NOT audit.is_bounded_text_array(NEW.limitations, 1, 1000, 32)
     OR NOT audit.is_sorted_unique_text_array(NEW.limitations)
     OR NOT audit.is_sorted_unique_text_array(NEW.ai_analysis_ids)
     OR NOT audit.is_sha256_hash_array(NEW.ai_analysis_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.ai_analysis_roots)
     OR NOT audit.is_sha256_hash_array(NEW.source_event_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.source_event_roots)
     OR NEW.safety <> verification.evidence_final_decision_safety_canonical()
     OR NOT (registration.audit_event_root = ANY(NEW.source_event_roots))
     OR NOT (validation.audit_event_root = ANY(NEW.source_event_roots))
     OR NOT (human_review.audit_event_root = ANY(NEW.source_event_roots))
     OR NOT (NEW.pre_decision_terminal_event_root = ANY(NEW.source_event_roots))
     OR EXISTS (
       SELECT 1 FROM verification.evidence_ai_analyses analysis
       WHERE analysis.id = ANY(expected_analysis_ids)
         AND NOT (analysis.audit_event_root = ANY(NEW.source_event_roots))
     )
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.source_event_roots) root
       LEFT JOIN audit.domain_events event
         ON event.event_root = root
         AND event.stream_id = NEW.evidence_id
         AND event.sequence_no < NEW.evidence_sequence
       WHERE event.id IS NULL
     ) THEN
    RAISE EXCEPTION 'evidence final decision sources or safety boundary are invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT semantic_event
  FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence
  FROM audit.domain_events WHERE stream_id = NEW.evidence_id;
  IF semantic_event.stream_id <> NEW.evidence_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.verifier_id
     OR semantic_event.entity_type <> 'evidence_final_decision'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> (CASE NEW.decision
       WHEN 'verify' THEN 'FULFILL' WHEN 'reject' THEN 'CHALLENGE' ELSE 'REASON' END)
     OR semantic_event.rationale <> NEW.rationale
     OR semantic_event.created_at <> NEW.decided_at THEN
    RAISE EXCEPTION 'evidence final decision semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.source_root <> verification.evidence_final_decision_source_root(NEW)
     OR NEW.command_hash <> verification.evidence_final_decision_command_hash(NEW)
     OR NEW.id <> 'cp_evidence_final_decision_' || left(NEW.command_hash, 24)
     OR NEW.decision_hash <> verification.evidence_final_decision_hash(NEW)
     OR NEW.decision_root <> verification.evidence_final_decision_root(NEW)
     OR semantic_event.payload_hash <> verification.evidence_final_decision_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence final decision hash lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS verification_evidence_final_decisions_validate
  ON verification.evidence_final_decisions;
CREATE TRIGGER verification_evidence_final_decisions_validate
BEFORE INSERT ON verification.evidence_final_decisions
FOR EACH ROW EXECUTE FUNCTION verification.validate_evidence_final_decision_insert();

DROP TRIGGER IF EXISTS verification_evidence_final_decisions_no_update
  ON verification.evidence_final_decisions;
CREATE TRIGGER verification_evidence_final_decisions_no_update
BEFORE UPDATE ON verification.evidence_final_decisions
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
