  ON verification.evidence_final_decisions;
CREATE TRIGGER verification_evidence_final_decisions_no_delete
BEFORE DELETE ON verification.evidence_final_decisions
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();

DROP TRIGGER IF EXISTS verification_evidence_final_decisions_audit
  ON verification.evidence_final_decisions;
CREATE TRIGGER verification_evidence_final_decisions_audit
AFTER INSERT OR UPDATE OR DELETE ON verification.evidence_final_decisions
FOR EACH ROW EXECUTE FUNCTION audit.capture_row_mutation();

-- Canonical proof-policy authority. Preliminary governance.policies rows remain
-- compatibility configuration and are not consumed by durable proof issuance.
CREATE TABLE IF NOT EXISTS governance.proof_policy_versions (
  id text PRIMARY KEY,
  subject text NOT NULL CHECK (
    subject IN ('methodology_publication', 'environmental_proof_record', 'project_lifecycle')
  ),
  governance_organization_id text NOT NULL REFERENCES organizations.organizations(id),
  title text NOT NULL CHECK (length(btrim(title)) BETWEEN 16 AND 240),
  required_approvals integer NOT NULL CHECK (required_approvals BETWEEN 2 AND 32),
  allowed_reviewer_roles text[] NOT NULL CHECK (cardinality(allowed_reviewer_roles) BETWEEN 2 AND 4),
  supersedes_policy_id text UNIQUE REFERENCES governance.proof_policy_versions(id),
  supersedes_policy_root text CHECK (supersedes_policy_root IS NULL OR supersedes_policy_root ~ '^[0-9a-f]{64}$'),
  creator_id text NOT NULL REFERENCES identity.participants(id),
  creator_snapshot jsonb NOT NULL CHECK (jsonb_typeof(creator_snapshot) = 'object'),
  created_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  policy_hash text NOT NULL UNIQUE CHECK (policy_hash ~ '^[0-9a-f]{64}$'),
  policy_root text NOT NULL UNIQUE CHECK (policy_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  CHECK ((supersedes_policy_id IS NULL) = (supersedes_policy_root IS NULL))
);

CREATE INDEX IF NOT EXISTS proof_policy_versions_subject_time
  ON governance.proof_policy_versions (subject, created_at DESC, id);
CREATE INDEX IF NOT EXISTS proof_policy_versions_governance_organization
  ON governance.proof_policy_versions (governance_organization_id, subject, created_at DESC, id);

CREATE OR REPLACE FUNCTION audit.genesis_root()
RETURNS text
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
  SELECT 'f9eb6f91a48893e686f0b033bd12f0308b65918aa00c91d16d8146124600f6e4'::text;
$$;

CREATE OR REPLACE FUNCTION governance.methodology_governance_safety_canonical()
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT jsonb_build_object(
    'immutableAuthority', true,
    'exactHumanAuthority', true,
    'independentQuorumRequired', true,
    'aiIsNeverFinalAuthority', true,
    'environmentalAccountabilityOnly', true,
    'notCertifiedCarbonCredit', true,
    'notCarbonTaxOffset', true,
    'notFinancialAsset', true,
    'notGuaranteedYield', true,
    'noMainnetFunds', true,
    'notAutomaticCanopyDistribution', true
  );
$$;

CREATE OR REPLACE FUNCTION governance.proof_policy_command_hash(
  policy governance.proof_policy_versions
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-governed-policy-command-v1',
    'subject', policy.subject,
    'governanceOrganizationId', policy.governance_organization_id,
    'title', policy.title,
    'requiredApprovals', policy.required_approvals,
    'allowedReviewerRoles', to_jsonb(policy.allowed_reviewer_roles),
    'supersedesPolicyId', policy.supersedes_policy_id,
    'supersedesPolicyRoot', policy.supersedes_policy_root,
    'creator', policy.creator_snapshot,
    'createdAt', audit.iso8601_millis(policy.created_at)
  ));
$$;

CREATE OR REPLACE FUNCTION governance.proof_policy_hash(
  policy governance.proof_policy_versions
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-governed-policy-v1', 'id', policy.id) ||
    jsonb_strip_nulls(jsonb_build_object(
      'subject', policy.subject,
      'governanceOrganizationId', policy.governance_organization_id,
      'title', policy.title,
      'requiredApprovals', policy.required_approvals,
      'allowedReviewerRoles', to_jsonb(policy.allowed_reviewer_roles),
      'supersedesPolicyId', policy.supersedes_policy_id,
      'supersedesPolicyRoot', policy.supersedes_policy_root,
      'creator', policy.creator_snapshot,
      'createdAt', audit.iso8601_millis(policy.created_at),
      'commandHash', policy.command_hash
    ))
  );
$$;

CREATE OR REPLACE FUNCTION governance.proof_policy_root(
  policy governance.proof_policy_versions
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-governed-policy-root-v1',
    'policyHash', policy.policy_hash,
    'previousPolicyRoot', COALESCE(policy.supersedes_policy_root, audit.genesis_root())
  ));
$$;

CREATE OR REPLACE FUNCTION governance.proof_policy_payload_hash(
  policy governance.proof_policy_versions
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('factType', 'governed_policy_authority', 'id', policy.id) ||
    jsonb_strip_nulls(jsonb_build_object(
      'subject', policy.subject,
      'governanceOrganizationId', policy.governance_organization_id,
      'title', policy.title,
      'requiredApprovals', policy.required_approvals,
      'allowedReviewerRoles', to_jsonb(policy.allowed_reviewer_roles),
      'supersedesPolicyId', policy.supersedes_policy_id,
      'supersedesPolicyRoot', policy.supersedes_policy_root,
      'creator', policy.creator_snapshot,
      'createdAt', audit.iso8601_millis(policy.created_at),
      'commandHash', policy.command_hash,
      'policyHash', policy.policy_hash,
      'policyRoot', policy.policy_root,
      'safety', policy.safety
    ))
  );
$$;

CREATE OR REPLACE FUNCTION governance.validate_proof_policy_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  predecessor governance.proof_policy_versions%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  latest_sequence bigint;
  policy_stream_id text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.creator_id THEN
    RAISE EXCEPTION 'governed policy requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.actor_snapshot_is_valid(
    NEW.creator_snapshot, NEW.creator_id, NEW.governance_organization_id,
    'human', ARRAY['owner', 'admin']::text[]
  ) OR NEW.creator_snapshot->>'role' NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'governed policy creator authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT audit.is_sorted_unique_text_array(NEW.allowed_reviewer_roles)
     OR NOT (NEW.allowed_reviewer_roles <@ ARRAY['admin', 'owner', 'researcher', 'verifier']::text[])
     OR NOT ('verifier' = ANY(NEW.allowed_reviewer_roles))
     OR (
       NEW.subject = 'environmental_proof_record'
       AND NOT (NEW.allowed_reviewer_roles && ARRAY['admin', 'owner']::text[])
     )
     OR (
       NEW.subject IN ('methodology_publication', 'project_lifecycle')
       AND NOT (NEW.allowed_reviewer_roles && ARRAY['admin', 'owner', 'researcher']::text[])
     ) THEN
    RAISE EXCEPTION 'governed policy constitutional reviewer quorum is invalid' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.supersedes_policy_id IS NULL THEN
    IF EXISTS (SELECT 1 FROM governance.proof_policy_versions prior WHERE prior.subject = NEW.subject) THEN
      RAISE EXCEPTION 'governed policy subject already has authority and requires exact supersession' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    SELECT * INTO STRICT predecessor
    FROM governance.proof_policy_versions WHERE id = NEW.supersedes_policy_id FOR SHARE;
    IF predecessor.policy_root <> NEW.supersedes_policy_root
       OR predecessor.subject <> NEW.subject
       OR predecessor.governance_organization_id <> NEW.governance_organization_id
       OR NEW.created_at <= predecessor.created_at
       OR EXISTS (
         SELECT 1 FROM governance.proof_policy_versions successor
         WHERE successor.supersedes_policy_id = predecessor.id
       ) THEN
      RAISE EXCEPTION 'governed policy supersession authority is invalid or forked' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  policy_stream_id := 'governed_policy:' || NEW.subject;
  SELECT * INTO STRICT semantic_event
  FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence
  FROM audit.domain_events WHERE stream_id = policy_stream_id;
  IF semantic_event.stream_id <> policy_stream_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.previous_root <> COALESCE(predecessor.audit_event_root, audit.genesis_root())
     OR semantic_event.actor_id <> NEW.creator_id
     OR semantic_event.entity_type <> 'governed_policy_authority'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> 'ASSERT'
     OR semantic_event.created_at <> NEW.created_at
     OR semantic_event.rationale <> 'An immutable governed policy version was recorded under constitutional human-quorum invariants.' THEN
    RAISE EXCEPTION 'governed policy semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.safety <> governance.methodology_governance_safety_canonical()
     OR projects.contains_unsafe_claim(ARRAY[NEW.id, NEW.title])
     OR NEW.command_hash <> governance.proof_policy_command_hash(NEW)
     OR NEW.id <> 'cp_governed_policy_' || left(NEW.command_hash, 24)
     OR NEW.policy_hash <> governance.proof_policy_hash(NEW)
     OR NEW.policy_root <> governance.proof_policy_root(NEW)
     OR semantic_event.payload_hash <> governance.proof_policy_payload_hash(NEW) THEN
    RAISE EXCEPTION 'governed policy canonical hash or safety lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS governance_proof_policy_versions_validate
  ON governance.proof_policy_versions;
CREATE TRIGGER governance_proof_policy_versions_validate
BEFORE INSERT ON governance.proof_policy_versions
FOR EACH ROW EXECUTE FUNCTION governance.validate_proof_policy_insert();

DROP TRIGGER IF EXISTS governance_proof_policy_versions_no_update
  ON governance.proof_policy_versions;
CREATE TRIGGER governance_proof_policy_versions_no_update
BEFORE UPDATE ON governance.proof_policy_versions
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
DROP TRIGGER IF EXISTS governance_proof_policy_versions_no_delete
  ON governance.proof_policy_versions;
CREATE TRIGGER governance_proof_policy_versions_no_delete
BEFORE DELETE ON governance.proof_policy_versions
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();

DROP TRIGGER IF EXISTS governance_proof_policy_versions_audit
  ON governance.proof_policy_versions;
CREATE TRIGGER governance_proof_policy_versions_audit
AFTER INSERT OR UPDATE OR DELETE ON governance.proof_policy_versions
FOR EACH ROW EXECUTE FUNCTION audit.capture_row_mutation();

-- Technical methodology versions stay draft. A separate publication fact below
-- is the only durable publication authority; compatibility approval IDs are not.
CREATE OR REPLACE FUNCTION governance.methodology_claim_boundary_canonical()
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT jsonb_build_object(
    'environmentalAccountabilityOnly', true,
    'notCarbonCredit', true,
    'notFinancialAsset', true,
    'notTaxOffset', true,
    'notGuaranteedYield', true,
    'notAutomaticCanopyDistribution', true
  );
$$;

CREATE OR REPLACE FUNCTION governance.methodology_quality_gate_root(
  methodology governance.methodologies
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.merkle_root(ARRAY(
    SELECT audit.sha256_stable_json(jsonb_build_object(
      'qualityGate', quality_gate,
      'minimumGpsAccuracyMeters', methodology.minimum_gps_accuracy_meters::double precision,
      'monitoringCadenceDays', methodology.monitoring_cadence_days,
      'evidenceRetentionDays', methodology.evidence_retention_days
    ))
    FROM unnest(methodology.quality_gates) quality_gate
    ORDER BY 1
  ));
$$;

CREATE OR REPLACE FUNCTION governance.methodology_hash_canonical(
  methodology governance.methodologies
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-methodology-v1', 'methodology',
      jsonb_strip_nulls(jsonb_build_object(
        'slug', methodology.slug,
        'version', methodology.version,
        'title', methodology.title,
        'scope', methodology.scope,
        'status', methodology.status,
        'summary', methodology.summary,
        'requiredDataSources', to_jsonb(methodology.required_data_sources),
        'qualityGates', to_jsonb(methodology.quality_gates),
        'minimumGpsAccuracyMeters', methodology.minimum_gps_accuracy_meters::double precision,
        'monitoringCadenceDays', methodology.monitoring_cadence_days,
        'evidenceRetentionDays', methodology.evidence_retention_days,
        'governanceApprovalIds', to_jsonb(methodology.governance_approval_ids),
        'supersedes', methodology.supersedes,
        'limitations', to_jsonb(methodology.limitations),
        'claimBoundary', methodology.claim_boundary,
        'createdBy', methodology.created_by,
        'createdAt', audit.iso8601_millis(methodology.created_at),
        'publishedAt', CASE WHEN methodology.published_at IS NULL THEN NULL
          ELSE audit.iso8601_millis(methodology.published_at) END,
        'qualityGateRoot', methodology.quality_gate_root
      ))
    )
  );
$$;

CREATE OR REPLACE FUNCTION governance.methodology_payload_hash(
  methodology governance.methodologies
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_strip_nulls(jsonb_build_object(
      'slug', methodology.slug,
      'version', methodology.version,
      'title', methodology.title,
      'scope', methodology.scope,
      'status', methodology.status,
      'summary', methodology.summary,
      'requiredDataSources', to_jsonb(methodology.required_data_sources),
      'qualityGates', to_jsonb(methodology.quality_gates),
      'minimumGpsAccuracyMeters', methodology.minimum_gps_accuracy_meters::double precision,
      'monitoringCadenceDays', methodology.monitoring_cadence_days,
      'evidenceRetentionDays', methodology.evidence_retention_days,
      'governanceApprovalIds', to_jsonb(methodology.governance_approval_ids),
      'supersedes', methodology.supersedes,
      'limitations', to_jsonb(methodology.limitations),
      'claimBoundary', methodology.claim_boundary,
      'createdBy', methodology.created_by,
      'createdAt', audit.iso8601_millis(methodology.created_at),
      'publishedAt', CASE WHEN methodology.published_at IS NULL THEN NULL
        ELSE audit.iso8601_millis(methodology.published_at) END,
      'qualityGateRoot', methodology.quality_gate_root,
      'methodologyHash', methodology.methodology_hash
    ))
  );
$$;

CREATE OR REPLACE FUNCTION governance.validate_methodology_version_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  author identity.participants%ROWTYPE;
  predecessor governance.methodologies%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.created_by THEN
    RAISE EXCEPTION 'methodology version requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT author FROM identity.participants WHERE id = NEW.created_by FOR SHARE;
  IF author.participant_type <> 'human'
     OR author.verification_status <> 'verified'
     OR NOT (author.roles && ARRAY['admin', 'owner', 'researcher', 'verifier']::text[]) THEN
    RAISE EXCEPTION 'methodology technical author authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> 'draft'
     OR NEW.published_at IS NOT NULL
     OR cardinality(NEW.governance_approval_ids) <> 0
     OR NOT audit.is_sorted_unique_text_array(NEW.required_data_sources)
     OR NOT audit.is_sorted_unique_text_array(NEW.quality_gates)
     OR NOT audit.is_sorted_unique_text_array(NEW.limitations)
     OR NOT audit.is_bounded_text_array(NEW.limitations, 1, 1000, 128)
     OR NOT (NEW.required_data_sources <@ ARRAY[
       'field_photo', 'gps_trace', 'device_attestation', 'community_attestation',
       'satellite_scene', 'sensor_reading', 'governance_approval', 'audit_attestation'
     ]::text[])
     OR NOT (NEW.quality_gates <@ ARRAY[
       'media_hash_required', 'gps_hash_required', 'gps_accuracy_threshold',
       'device_attestation_required', 'satellite_cross_check_required',
       'duplicate_detection_required', 'human_review_required',
       'governance_approval_required', 'public_challenge_window_required',
       'monitoring_timeline_required'
     ]::text[])
     OR NOT (NEW.quality_gates @> ARRAY[
       'human_review_required', 'governance_approval_required',
       'public_challenge_window_required', 'monitoring_timeline_required'
     ]::text[])
     OR NEW.minimum_gps_accuracy_meters <= 0 OR NEW.minimum_gps_accuracy_meters > 10000
     OR NEW.monitoring_cadence_days <= 0 OR NEW.monitoring_cadence_days > 3650
     OR NEW.evidence_retention_days <= 0 OR NEW.evidence_retention_days > 36500
     OR NEW.claim_boundary <> governance.methodology_claim_boundary_canonical()
     OR projects.contains_unsafe_claim(ARRAY[
       NEW.id, NEW.slug, NEW.version, NEW.title, NEW.summary
     ] || NEW.limitations) THEN
    RAISE EXCEPTION 'methodology technical version boundary is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.supersedes IS NOT NULL THEN
    SELECT * INTO STRICT predecessor
    FROM governance.methodologies WHERE id = NEW.supersedes FOR SHARE;
    IF predecessor.slug <> NEW.slug
       OR predecessor.scope <> NEW.scope
       OR NEW.created_at <= predecessor.created_at
       OR EXISTS (SELECT 1 FROM governance.methodologies successor WHERE successor.supersedes = predecessor.id) THEN
      RAISE EXCEPTION 'methodology technical supersession is invalid or forked' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.event_root;
  SELECT max(sequence_no) INTO latest_sequence FROM audit.domain_events WHERE stream_id = NEW.id;
  IF semantic_event.stream_id <> NEW.id
     OR semantic_event.sequence_no <> 1
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.previous_root <> audit.genesis_root()
     OR semantic_event.actor_id <> NEW.created_by
     OR semantic_event.entity_type <> 'methodology'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> 'ASSERT'
     OR semantic_event.created_at <> NEW.created_at
     OR semantic_event.rationale <> 'CanopyProof methodology version recorded for institutional review without creating public proof authority.' THEN
    RAISE EXCEPTION 'methodology technical semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.quality_gate_root <> governance.methodology_quality_gate_root(NEW) THEN
    RAISE EXCEPTION 'methodology technical quality-gate root is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.methodology_hash <> governance.methodology_hash_canonical(NEW) THEN
    RAISE EXCEPTION 'methodology technical methodology hash is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF semantic_event.payload_hash <> governance.methodology_payload_hash(NEW) THEN
    RAISE EXCEPTION 'methodology technical semantic payload hash is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS governance_methodologies_validate ON governance.methodologies;
CREATE TRIGGER governance_methodologies_validate
BEFORE INSERT ON governance.methodologies
FOR EACH ROW EXECUTE FUNCTION governance.validate_methodology_version_insert();

CREATE TABLE IF NOT EXISTS governance.methodology_publication_approvals (
  id text PRIMARY KEY,
  methodology_id text NOT NULL REFERENCES governance.methodologies(id),
  methodology_hash text NOT NULL CHECK (methodology_hash ~ '^[0-9a-f]{64}$'),
  methodology_event_root text NOT NULL CHECK (methodology_event_root ~ '^[0-9a-f]{64}$'),
  policy_id text NOT NULL REFERENCES governance.proof_policy_versions(id),
  policy_root text NOT NULL CHECK (policy_root ~ '^[0-9a-f]{64}$'),
  governance_organization_id text NOT NULL REFERENCES organizations.organizations(id),
  prior_approval_id text REFERENCES governance.methodology_publication_approvals(id),
  prior_approval_root text CHECK (prior_approval_root IS NULL OR prior_approval_root ~ '^[0-9a-f]{64}$'),
  decision text NOT NULL CHECK (decision IN ('approve', 'reject', 'request_changes')),
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 24 AND 4000),
  conflict_disclosure text NOT NULL CHECK (length(btrim(conflict_disclosure)) BETWEEN 24 AND 2000),
  limitations text[] NOT NULL CHECK (cardinality(limitations) <= 32),
  source_event_roots text[] NOT NULL CHECK (cardinality(source_event_roots) BETWEEN 1 AND 128),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  approver_id text NOT NULL REFERENCES identity.participants(id),
  approver_snapshot jsonb NOT NULL CHECK (jsonb_typeof(approver_snapshot) = 'object'),
  decided_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  methodology_sequence bigint NOT NULL CHECK (methodology_sequence > 1),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  approval_hash text NOT NULL UNIQUE CHECK (approval_hash ~ '^[0-9a-f]{64}$'),
  approval_root text NOT NULL UNIQUE CHECK (approval_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (methodology_id, methodology_sequence),
  UNIQUE (methodology_id, approver_id),
  CHECK ((prior_approval_id IS NULL) = (prior_approval_root IS NULL))
);

CREATE INDEX IF NOT EXISTS methodology_publication_approvals_methodology_sequence
  ON governance.methodology_publication_approvals (methodology_id, methodology_sequence, id);
CREATE INDEX IF NOT EXISTS methodology_publication_approvals_policy_time
  ON governance.methodology_publication_approvals (policy_id, decided_at DESC, id);

CREATE TABLE IF NOT EXISTS governance.methodology_publications (
  id text PRIMARY KEY,
  methodology_id text NOT NULL UNIQUE REFERENCES governance.methodologies(id),
  methodology_hash text NOT NULL CHECK (methodology_hash ~ '^[0-9a-f]{64}$'),
  methodology_quality_gate_root text NOT NULL CHECK (methodology_quality_gate_root ~ '^[0-9a-f]{64}$'),
  methodology_event_root text NOT NULL CHECK (methodology_event_root ~ '^[0-9a-f]{64}$'),
  policy_id text NOT NULL REFERENCES governance.proof_policy_versions(id),
  policy_root text NOT NULL CHECK (policy_root ~ '^[0-9a-f]{64}$'),
  governance_organization_id text NOT NULL REFERENCES organizations.organizations(id),
  approval_ids text[] NOT NULL CHECK (cardinality(approval_ids) BETWEEN 2 AND 32),
  approval_roots text[] NOT NULL CHECK (cardinality(approval_roots) BETWEEN 2 AND 32),
  approval_quorum_root text NOT NULL CHECK (approval_quorum_root ~ '^[0-9a-f]{64}$'),
  publisher_id text NOT NULL REFERENCES identity.participants(id),
  publisher_snapshot jsonb NOT NULL CHECK (jsonb_typeof(publisher_snapshot) = 'object'),
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 24 AND 4000),
  limitations text[] NOT NULL CHECK (cardinality(limitations) <= 32),
  source_event_roots text[] NOT NULL CHECK (cardinality(source_event_roots) BETWEEN 1 AND 256),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  published_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  methodology_sequence bigint NOT NULL CHECK (methodology_sequence > 2),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  publication_hash text NOT NULL UNIQUE CHECK (publication_hash ~ '^[0-9a-f]{64}$'),
  publication_root text NOT NULL UNIQUE CHECK (publication_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  CHECK (cardinality(approval_ids) = cardinality(approval_roots))
);

CREATE INDEX IF NOT EXISTS methodology_publications_policy_time
  ON governance.methodology_publications (policy_id, published_at DESC, id);
CREATE INDEX IF NOT EXISTS methodology_publications_methodology_root
  ON governance.methodology_publications (methodology_id, publication_root);

CREATE OR REPLACE FUNCTION governance.methodology_publication_approval_command_hash(
  approval governance.methodology_publication_approvals
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-methodology-publication-approval-command-v1',
    'methodologyId', approval.methodology_id,
    'methodologyHash', approval.methodology_hash,
    'methodologyEventRoot', approval.methodology_event_root,
    'policyId', approval.policy_id,
    'policyRoot', approval.policy_root,
    'priorApprovalId', approval.prior_approval_id,
    'priorApprovalRoot', approval.prior_approval_root,
    'decision', approval.decision,
    'rationale', approval.rationale,
    'conflictDisclosure', approval.conflict_disclosure,
    'limitations', to_jsonb(approval.limitations),
    'sourceEventRoots', to_jsonb(approval.source_event_roots),
    'approver', approval.approver_snapshot,
    'decidedAt', audit.iso8601_millis(approval.decided_at)
  ));
$$;

CREATE OR REPLACE FUNCTION governance.methodology_publication_approval_source_root(
  approval governance.methodology_publication_approvals
)
RETURNS text
LANGUAGE sql
STABLE
STRICT
AS $$
  SELECT audit.merkle_root(ARRAY(
    SELECT leaf FROM (
      SELECT approval.methodology_hash AS leaf
      UNION ALL SELECT methodology.quality_gate_root
        FROM governance.methodologies methodology WHERE methodology.id = approval.methodology_id
      UNION ALL SELECT approval.policy_root
      UNION ALL SELECT unnest(approval.source_event_roots)
      UNION ALL SELECT approval.prior_approval_root WHERE approval.prior_approval_root IS NOT NULL
    ) leaves ORDER BY leaf
  ));
$$;

