  approval governance.methodology_publication_approvals
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-methodology-publication-approval-v1') ||
    jsonb_strip_nulls(jsonb_build_object(
      'methodologyId', approval.methodology_id,
      'methodologyHash', approval.methodology_hash,
      'methodologyEventRoot', approval.methodology_event_root,
      'policyId', approval.policy_id,
      'policyRoot', approval.policy_root,
      'governanceOrganizationId', approval.governance_organization_id,
      'priorApprovalId', approval.prior_approval_id,
      'priorApprovalRoot', approval.prior_approval_root,
      'decision', approval.decision,
      'rationale', approval.rationale,
      'conflictDisclosure', approval.conflict_disclosure,
      'limitations', to_jsonb(approval.limitations),
      'sourceEventRoots', to_jsonb(approval.source_event_roots),
      'sourceRoot', approval.source_root,
      'approver', approval.approver_snapshot,
      'decidedAt', audit.iso8601_millis(approval.decided_at),
      'commandHash', approval.command_hash,
      'methodologySequence', approval.methodology_sequence,
      'previousEventRoot', approval.previous_event_root
    ))
  );
$$;

