    jsonb_build_object('factType', 'methodology_publication_approval', 'id', approval.id) ||
    jsonb_strip_nulls(jsonb_build_object(
      'methodologyId', approval.methodology_id,
      'methodologyHash', approval.methodology_hash,
      'methodologyEventRoot', approval.methodology_event_root,
      'policyId', approval.policy_id,
      'policyRoot', approval.policy_root,
      'governanceOrganizationId', approval.governance_organization_id,
      'priorApprovalId', approval.prior_approval_id,
      'priorApprovalRoot', approval.prior_approval_root,
      'decision', approval.decision,
      'rationale', approval.rationale,
      'conflictDisclosure', approval.conflict_disclosure,
      'limitations', to_jsonb(approval.limitations),
      'sourceEventRoots', to_jsonb(approval.source_event_roots),
      'sourceRoot', approval.source_root,
      'approver', approval.approver_snapshot,
      'decidedAt', audit.iso8601_millis(approval.decided_at),
      'commandHash', approval.command_hash,
      'methodologySequence', approval.methodology_sequence,
      'previousEventRoot', approval.previous_event_root,
      'approvalHash', approval.approval_hash,
      'approvalRoot', approval.approval_root,
      'safety', approval.safety
    ))
  );
$$;

CREATE OR REPLACE FUNCTION governance.validate_methodology_publication_approval_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  methodology governance.methodologies%ROWTYPE;
  policy governance.proof_policy_versions%ROWTYPE;
  latest_prior governance.methodology_publication_approvals%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  accreditation organizations.accreditations%ROWTYPE;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.approver_id THEN
    RAISE EXCEPTION 'methodology publication approval requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT methodology FROM governance.methodologies WHERE id = NEW.methodology_id FOR SHARE;
  SELECT * INTO STRICT policy FROM governance.proof_policy_versions WHERE id = NEW.policy_id FOR SHARE;
  IF methodology.methodology_hash <> NEW.methodology_hash
     OR methodology.event_root <> NEW.methodology_event_root
     OR methodology.status <> 'draft'
     OR policy.subject <> 'methodology_publication'
     OR policy.policy_root <> NEW.policy_root
     OR policy.governance_organization_id <> NEW.governance_organization_id
     OR EXISTS (
       SELECT 1 FROM governance.proof_policy_versions successor
       WHERE successor.supersedes_policy_id = policy.id
     )
     OR EXISTS (
       SELECT 1 FROM governance.methodology_publications publication
       WHERE publication.methodology_id = NEW.methodology_id
     ) THEN
    RAISE EXCEPTION 'methodology publication approval source policy or methodology is not current' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.actor_snapshot_is_valid(
    NEW.approver_snapshot, NEW.approver_id, NEW.governance_organization_id,
    'human', policy.allowed_reviewer_roles
  ) OR NOT (NEW.approver_snapshot->>'role' = ANY(policy.allowed_reviewer_roles)) THEN
    RAISE EXCEPTION 'methodology publication approver authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.approver_snapshot->>'role' = 'verifier' THEN
    IF NEW.approver_snapshot->>'accreditationStatus' <> 'approved' THEN
      RAISE EXCEPTION 'methodology publication verifier accreditation is not approved' USING ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO STRICT accreditation
    FROM organizations.accreditations WHERE id = NEW.approver_snapshot->>'accreditationId';
    IF accreditation.decided_at > NEW.decided_at THEN
      RAISE EXCEPTION 'methodology publication verifier accreditation postdates approval' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.approver_id = methodology.created_by
     OR EXISTS (
       SELECT 1 FROM governance.methodology_publication_approvals prior_actor
       WHERE prior_actor.methodology_id = NEW.methodology_id
         AND prior_actor.approver_id = NEW.approver_id
     ) THEN
    RAISE EXCEPTION 'methodology publication approval requires author and reviewer independence' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO latest_prior
  FROM governance.methodology_publication_approvals
  WHERE methodology_id = NEW.methodology_id
  ORDER BY methodology_sequence DESC LIMIT 1 FOR SHARE;
  IF latest_prior.id IS NULL THEN
    IF NEW.prior_approval_id IS NOT NULL
       OR NEW.prior_approval_root IS NOT NULL
       OR NEW.methodology_sequence <> 2
       OR NEW.previous_event_root <> methodology.event_root THEN
      RAISE EXCEPTION 'first methodology publication approval predecessor is invalid' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.prior_approval_id IS DISTINCT FROM latest_prior.id
     OR NEW.prior_approval_root IS DISTINCT FROM latest_prior.approval_root
     OR NEW.methodology_sequence <> latest_prior.methodology_sequence + 1
     OR NEW.previous_event_root <> latest_prior.audit_event_root THEN
    RAISE EXCEPTION 'methodology publication approval predecessor is missing or forked' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.decided_at < methodology.created_at
     OR NEW.decided_at < policy.created_at
     OR NOT audit.is_sorted_unique_text_array(NEW.limitations)
     OR NOT audit.is_bounded_text_array(NEW.limitations, 1, 1000, 32)
     OR NOT audit.is_sha256_hash_array(NEW.source_event_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.source_event_roots)
     OR NOT (methodology.event_root = ANY(NEW.source_event_roots))
     OR NOT (policy.audit_event_root = ANY(NEW.source_event_roots))
     OR (latest_prior.id IS NOT NULL AND NOT (latest_prior.audit_event_root = ANY(NEW.source_event_roots)))
     OR projects.contains_unsafe_claim(ARRAY[
       NEW.id, NEW.rationale, NEW.conflict_disclosure
     ] || NEW.limitations)
     OR NEW.safety <> governance.methodology_governance_safety_canonical()
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.source_event_roots) root
       LEFT JOIN audit.domain_events event ON event.event_root = root
       WHERE event.id IS NULL OR NOT (
         (event.stream_id = NEW.methodology_id AND event.sequence_no < NEW.methodology_sequence)
         OR event.event_root = policy.audit_event_root
       )
     ) THEN
    RAISE EXCEPTION 'methodology publication approval sources or safety are invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence
  FROM audit.domain_events WHERE stream_id = NEW.methodology_id;
  IF semantic_event.stream_id <> NEW.methodology_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.methodology_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.approver_id
     OR semantic_event.entity_type <> 'methodology_publication_approval'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> (CASE NEW.decision
       WHEN 'approve' THEN 'FULFILL' WHEN 'reject' THEN 'CHALLENGE' ELSE 'REASON' END)
     OR semantic_event.created_at <> NEW.decided_at
     OR semantic_event.rationale <> NEW.rationale THEN
    RAISE EXCEPTION 'methodology publication approval semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.source_root <> governance.methodology_publication_approval_source_root(NEW)
     OR NEW.command_hash <> governance.methodology_publication_approval_command_hash(NEW)
     OR NEW.id <> 'cp_methodology_publication_approval_' || left(NEW.command_hash, 24)
     OR NEW.approval_hash <> governance.methodology_publication_approval_hash(NEW)
     OR NEW.approval_root <> governance.methodology_publication_approval_root(NEW)
     OR semantic_event.payload_hash <> governance.methodology_publication_approval_payload_hash(NEW) THEN
    RAISE EXCEPTION 'methodology publication approval canonical lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS governance_methodology_publication_approvals_validate
  ON governance.methodology_publication_approvals;
CREATE TRIGGER governance_methodology_publication_approvals_validate
BEFORE INSERT ON governance.methodology_publication_approvals
FOR EACH ROW EXECUTE FUNCTION governance.validate_methodology_publication_approval_insert();

DROP TRIGGER IF EXISTS governance_methodology_publication_approvals_no_update
  ON governance.methodology_publication_approvals;
CREATE TRIGGER governance_methodology_publication_approvals_no_update
BEFORE UPDATE ON governance.methodology_publication_approvals
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
DROP TRIGGER IF EXISTS governance_methodology_publication_approvals_no_delete
  ON governance.methodology_publication_approvals;
CREATE TRIGGER governance_methodology_publication_approvals_no_delete
BEFORE DELETE ON governance.methodology_publication_approvals
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
DROP TRIGGER IF EXISTS governance_methodology_publication_approvals_audit
  ON governance.methodology_publication_approvals;
CREATE TRIGGER governance_methodology_publication_approvals_audit
AFTER INSERT OR UPDATE OR DELETE ON governance.methodology_publication_approvals
FOR EACH ROW EXECUTE FUNCTION audit.capture_row_mutation();

CREATE OR REPLACE FUNCTION governance.methodology_publication_command_hash(
  publication governance.methodology_publications
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-methodology-publication-command-v1',
    'methodologyId', publication.methodology_id,
    'methodologyHash', publication.methodology_hash,
    'methodologyQualityGateRoot', publication.methodology_quality_gate_root,
    'methodologyEventRoot', publication.methodology_event_root,
    'policyId', publication.policy_id,
    'policyRoot', publication.policy_root,
    'approvalIds', to_jsonb(publication.approval_ids),
    'approvalRoots', to_jsonb(publication.approval_roots),
    'approvalQuorumRoot', publication.approval_quorum_root,
    'publisher', publication.publisher_snapshot,
    'rationale', publication.rationale,
    'limitations', to_jsonb(publication.limitations),
    'sourceEventRoots', to_jsonb(publication.source_event_roots),
    'publishedAt', audit.iso8601_millis(publication.published_at)
  ));
$$;

CREATE OR REPLACE FUNCTION governance.methodology_publication_source_root(
  publication governance.methodology_publications
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.merkle_root(ARRAY(
    SELECT leaf FROM (
      SELECT publication.methodology_hash AS leaf
      UNION ALL SELECT publication.methodology_quality_gate_root
      UNION ALL SELECT publication.policy_root
      UNION ALL SELECT unnest(publication.approval_roots)
      UNION ALL SELECT unnest(publication.source_event_roots)
    ) leaves ORDER BY leaf
  ));
$$;

CREATE OR REPLACE FUNCTION governance.methodology_publication_hash(
  publication governance.methodology_publications
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-methodology-publication-v1') ||
    jsonb_build_object(
      'methodologyId', publication.methodology_id,
      'methodologyHash', publication.methodology_hash,
      'methodologyQualityGateRoot', publication.methodology_quality_gate_root,
      'methodologyEventRoot', publication.methodology_event_root,
      'policyId', publication.policy_id,
      'policyRoot', publication.policy_root,
      'governanceOrganizationId', publication.governance_organization_id,
      'approvalIds', to_jsonb(publication.approval_ids),
      'approvalRoots', to_jsonb(publication.approval_roots),
      'approvalQuorumRoot', publication.approval_quorum_root,
      'publisher', publication.publisher_snapshot,
      'rationale', publication.rationale,
      'limitations', to_jsonb(publication.limitations),
      'sourceEventRoots', to_jsonb(publication.source_event_roots),
      'sourceRoot', publication.source_root,
      'publishedAt', audit.iso8601_millis(publication.published_at),
      'commandHash', publication.command_hash,
      'methodologySequence', publication.methodology_sequence,
      'previousEventRoot', publication.previous_event_root
    )
  );
$$;

CREATE OR REPLACE FUNCTION governance.methodology_publication_root(
  publication governance.methodology_publications
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-methodology-publication-root-v1',
    'methodologyHash', publication.methodology_hash,
    'policyRoot', publication.policy_root,
    'approvalQuorumRoot', publication.approval_quorum_root,
    'sourceRoot', publication.source_root,
    'publicationHash', publication.publication_hash,
    'previousEventRoot', publication.previous_event_root,
    'methodologySequence', publication.methodology_sequence
  ));
$$;

CREATE OR REPLACE FUNCTION governance.methodology_publication_payload_hash(
  publication governance.methodology_publications
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('factType', 'methodology_publication', 'id', publication.id) ||
    jsonb_build_object(
      'methodologyId', publication.methodology_id,
      'methodologyHash', publication.methodology_hash,
      'methodologyQualityGateRoot', publication.methodology_quality_gate_root,
      'methodologyEventRoot', publication.methodology_event_root,
      'policyId', publication.policy_id,
      'policyRoot', publication.policy_root,
      'governanceOrganizationId', publication.governance_organization_id,
      'approvalIds', to_jsonb(publication.approval_ids),
      'approvalRoots', to_jsonb(publication.approval_roots),
      'approvalQuorumRoot', publication.approval_quorum_root,
      'publisher', publication.publisher_snapshot,
      'rationale', publication.rationale,
      'limitations', to_jsonb(publication.limitations),
      'sourceEventRoots', to_jsonb(publication.source_event_roots),
      'sourceRoot', publication.source_root,
      'publishedAt', audit.iso8601_millis(publication.published_at),
      'commandHash', publication.command_hash,
      'methodologySequence', publication.methodology_sequence,
      'previousEventRoot', publication.previous_event_root,
      'publicationHash', publication.publication_hash,
      'publicationRoot', publication.publication_root,
      'safety', publication.safety
    )
  );
$$;

CREATE OR REPLACE FUNCTION governance.methodology_publication_bundle_root(
  publication governance.methodology_publications
)
RETURNS text
LANGUAGE sql
STABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-methodology-publication-bundle-v1',
    'methodologyHash', publication.methodology_hash,
    'methodologyEventRoot', publication.methodology_event_root,
    'policyRoot', publication.policy_root,
    'policyEventRoot', policy.audit_event_root,
    'approvalRoots', to_jsonb(publication.approval_roots),
    'publicationRoot', publication.publication_root,
    'publicationEventRoot', publication.audit_event_root
  ))
  FROM governance.proof_policy_versions policy
  WHERE policy.id = publication.policy_id;
$$;

CREATE OR REPLACE FUNCTION governance.validate_methodology_publication_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  methodology governance.methodologies%ROWTYPE;
  policy governance.proof_policy_versions%ROWTYPE;
  latest_approval governance.methodology_publication_approvals%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  latest_sequence bigint;
  expected_approval_ids text[];
  expected_approval_roots text[];
  approval_count integer;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.publisher_id THEN
    RAISE EXCEPTION 'methodology publication requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT methodology FROM governance.methodologies WHERE id = NEW.methodology_id FOR SHARE;
  SELECT * INTO STRICT policy FROM governance.proof_policy_versions WHERE id = NEW.policy_id FOR SHARE;
  IF methodology.methodology_hash <> NEW.methodology_hash
     OR methodology.quality_gate_root <> NEW.methodology_quality_gate_root
     OR methodology.event_root <> NEW.methodology_event_root
     OR methodology.status <> 'draft'
     OR policy.subject <> 'methodology_publication'
     OR policy.policy_root <> NEW.policy_root
     OR policy.governance_organization_id <> NEW.governance_organization_id
     OR EXISTS (
       SELECT 1 FROM governance.proof_policy_versions successor
       WHERE successor.supersedes_policy_id = policy.id
     ) THEN
    RAISE EXCEPTION 'methodology publication source policy or methodology is not current' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.actor_snapshot_is_valid(
    NEW.publisher_snapshot, NEW.publisher_id, NEW.governance_organization_id,
    'human', ARRAY['owner', 'admin']::text[]
  ) OR NEW.publisher_snapshot->>'role' NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'methodology publication publisher authority is invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT
    COALESCE(array_agg(approval.id ORDER BY approval.id), ARRAY[]::text[]),
    COALESCE(array_agg(approval.approval_root ORDER BY approval.approval_root), ARRAY[]::text[]),
    count(*)::integer
  INTO expected_approval_ids, expected_approval_roots, approval_count
  FROM governance.methodology_publication_approvals approval
  WHERE approval.methodology_id = NEW.methodology_id;
  SELECT * INTO STRICT latest_approval
  FROM governance.methodology_publication_approvals
  WHERE methodology_id = NEW.methodology_id
  ORDER BY methodology_sequence DESC LIMIT 1 FOR SHARE;
  IF NEW.approval_ids <> expected_approval_ids
     OR NEW.approval_roots <> expected_approval_roots
     OR approval_count < policy.required_approvals
     OR NEW.methodology_sequence <> latest_approval.methodology_sequence + 1
     OR NEW.previous_event_root <> latest_approval.audit_event_root
     OR EXISTS (
       SELECT 1 FROM governance.methodology_publication_approvals approval
       WHERE approval.methodology_id = NEW.methodology_id
         AND (
           approval.policy_id <> policy.id
           OR approval.policy_root <> policy.policy_root
           OR approval.decision <> 'approve'
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM governance.methodology_publication_approvals approval
       WHERE approval.methodology_id = NEW.methodology_id
         AND approval.approver_snapshot->>'role' = 'verifier'
     )
     OR NOT EXISTS (
       SELECT 1 FROM governance.methodology_publication_approvals approval
       WHERE approval.methodology_id = NEW.methodology_id
         AND approval.approver_snapshot->>'role' IN ('researcher', 'owner', 'admin')
     ) THEN
    RAISE EXCEPTION 'methodology publication approval quorum is incomplete, stale, or adverse' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.publisher_id = methodology.created_by
     OR EXISTS (
       SELECT 1 FROM governance.methodology_publication_approvals approval
       WHERE approval.methodology_id = NEW.methodology_id
         AND approval.approver_id = NEW.publisher_id
     ) THEN
    RAISE EXCEPTION 'methodology publication requires an independent human publisher' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.published_at < latest_approval.decided_at
     OR NEW.published_at < policy.created_at
     OR NOT audit.is_sorted_unique_text_array(NEW.approval_ids)
     OR NOT audit.is_sha256_hash_array(NEW.approval_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.approval_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.limitations)
     OR NOT audit.is_bounded_text_array(NEW.limitations, 1, 1000, 32)
     OR NOT audit.is_sha256_hash_array(NEW.source_event_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.source_event_roots)
     OR NOT (methodology.event_root = ANY(NEW.source_event_roots))
     OR NOT (policy.audit_event_root = ANY(NEW.source_event_roots))
     OR EXISTS (
       SELECT 1 FROM governance.methodology_publication_approvals approval
       WHERE approval.methodology_id = NEW.methodology_id
         AND NOT (approval.audit_event_root = ANY(NEW.source_event_roots))
     )
     OR projects.contains_unsafe_claim(ARRAY[NEW.id, NEW.rationale] || NEW.limitations)
     OR NEW.safety <> governance.methodology_governance_safety_canonical()
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.source_event_roots) root
       LEFT JOIN audit.domain_events event ON event.event_root = root
       WHERE event.id IS NULL OR NOT (
         (event.stream_id = NEW.methodology_id AND event.sequence_no < NEW.methodology_sequence)
         OR event.event_root = policy.audit_event_root
       )
     ) THEN
    RAISE EXCEPTION 'methodology publication sources or safety are invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence
  FROM audit.domain_events WHERE stream_id = NEW.methodology_id;
  IF semantic_event.stream_id <> NEW.methodology_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.methodology_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.publisher_id
     OR semantic_event.entity_type <> 'methodology_publication'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> 'FULFILL'
     OR semantic_event.created_at <> NEW.published_at
     OR semantic_event.rationale <> NEW.rationale THEN
    RAISE EXCEPTION 'methodology publication semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.approval_quorum_root <> audit.merkle_root(NEW.approval_roots)
     OR NEW.source_root <> governance.methodology_publication_source_root(NEW)
     OR NEW.command_hash <> governance.methodology_publication_command_hash(NEW)
     OR NEW.id <> 'cp_methodology_publication_' || left(NEW.command_hash, 24)
     OR NEW.publication_hash <> governance.methodology_publication_hash(NEW)
     OR NEW.publication_root <> governance.methodology_publication_root(NEW)
     OR semantic_event.payload_hash <> governance.methodology_publication_payload_hash(NEW) THEN
    RAISE EXCEPTION 'methodology publication canonical lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS governance_methodology_publications_validate
  ON governance.methodology_publications;
CREATE TRIGGER governance_methodology_publications_validate
BEFORE INSERT ON governance.methodology_publications
FOR EACH ROW EXECUTE FUNCTION governance.validate_methodology_publication_insert();
DROP TRIGGER IF EXISTS governance_methodology_publications_no_update
  ON governance.methodology_publications;
CREATE TRIGGER governance_methodology_publications_no_update
BEFORE UPDATE ON governance.methodology_publications
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
DROP TRIGGER IF EXISTS governance_methodology_publications_no_delete
  ON governance.methodology_publications;
CREATE TRIGGER governance_methodology_publications_no_delete
BEFORE DELETE ON governance.methodology_publications
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
DROP TRIGGER IF EXISTS governance_methodology_publications_audit
  ON governance.methodology_publications;
CREATE TRIGGER governance_methodology_publications_audit
AFTER INSERT OR UPDATE OR DELETE ON governance.methodology_publications
FOR EACH ROW EXECUTE FUNCTION audit.capture_row_mutation();

-- Canonical Environmental Proof authority. The preliminary
-- certificates.environmental_proof_records table remains a compatibility
-- projection and is never read by the durable authority adapter below.
CREATE TABLE IF NOT EXISTS certificates.environmental_proof_candidates (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  project_status text NOT NULL CHECK (project_status IN ('active', 'monitored')),
  project_root text NOT NULL CHECK (project_root ~ '^[0-9a-f]{64}$'),
  project_event_root text NOT NULL CHECK (project_event_root ~ '^[0-9a-f]{64}$'),
  methodology_id text NOT NULL REFERENCES governance.methodologies(id),
  methodology_hash text NOT NULL CHECK (methodology_hash ~ '^[0-9a-f]{64}$'),
  methodology_quality_gate_root text NOT NULL CHECK (methodology_quality_gate_root ~ '^[0-9a-f]{64}$'),
  methodology_event_root text NOT NULL CHECK (methodology_event_root ~ '^[0-9a-f]{64}$'),
  methodology_publication_id text NOT NULL REFERENCES governance.methodology_publications(id),
  methodology_publication_root text NOT NULL CHECK (methodology_publication_root ~ '^[0-9a-f]{64}$'),
  methodology_publication_event_root text NOT NULL CHECK (methodology_publication_event_root ~ '^[0-9a-f]{64}$'),
  methodology_publication_bundle_root text NOT NULL CHECK (methodology_publication_bundle_root ~ '^[0-9a-f]{64}$'),
  methodology_publication_policy_root text NOT NULL CHECK (methodology_publication_policy_root ~ '^[0-9a-f]{64}$'),
  methodology_publication_policy_event_root text NOT NULL CHECK (methodology_publication_policy_event_root ~ '^[0-9a-f]{64}$'),
  methodology_approval_roots text[] NOT NULL CHECK (cardinality(methodology_approval_roots) BETWEEN 2 AND 32),
  methodology_approval_quorum_root text NOT NULL CHECK (methodology_approval_quorum_root ~ '^[0-9a-f]{64}$'),
  policy_id text NOT NULL REFERENCES governance.proof_policy_versions(id),
  policy_hash text NOT NULL CHECK (policy_hash ~ '^[0-9a-f]{64}$'),
  policy_root text NOT NULL CHECK (policy_root ~ '^[0-9a-f]{64}$'),
  policy_event_root text NOT NULL CHECK (policy_event_root ~ '^[0-9a-f]{64}$'),
  required_approvals integer NOT NULL CHECK (required_approvals BETWEEN 2 AND 32),
  allowed_reviewer_roles text[] NOT NULL CHECK (cardinality(allowed_reviewer_roles) BETWEEN 2 AND 4),
  evidence_ids text[] NOT NULL CHECK (cardinality(evidence_ids) BETWEEN 1 AND 256),
  evidence_registration_roots text[] NOT NULL CHECK (cardinality(evidence_registration_roots) BETWEEN 1 AND 256),
  evidence_final_decision_ids text[] NOT NULL CHECK (cardinality(evidence_final_decision_ids) BETWEEN 1 AND 256),
  evidence_final_decision_roots text[] NOT NULL CHECK (cardinality(evidence_final_decision_roots) BETWEEN 1 AND 256),
  evidence_final_verification_roots text[] NOT NULL CHECK (cardinality(evidence_final_verification_roots) BETWEEN 1 AND 256),
  evidence_root text NOT NULL CHECK (evidence_root ~ '^[0-9a-f]{64}$'),
  final_decision_root text NOT NULL CHECK (final_decision_root ~ '^[0-9a-f]{64}$'),
  monitoring_event_ids text[] NOT NULL CHECK (cardinality(monitoring_event_ids) BETWEEN 1 AND 256),
  monitoring_roots text[] NOT NULL CHECK (cardinality(monitoring_roots) BETWEEN 1 AND 256),
  monitoring_root text NOT NULL CHECK (monitoring_root ~ '^[0-9a-f]{64}$'),
  contributor_ids text[] NOT NULL CHECK (cardinality(contributor_ids) BETWEEN 1 AND 256),
  source_actor_ids text[] NOT NULL CHECK (cardinality(source_actor_ids) BETWEEN 1 AND 1024),
  public_location jsonb NOT NULL CHECK (jsonb_typeof(public_location) = 'object'),
  confidence_score integer NOT NULL CHECK (confidence_score BETWEEN 0 AND 100),
  limitations text[] NOT NULL CHECK (cardinality(limitations) BETWEEN 1 AND 32),
  source_event_roots text[] NOT NULL CHECK (cardinality(source_event_roots) BETWEEN 1 AND 1024),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  authority_root text NOT NULL UNIQUE CHECK (authority_root ~ '^[0-9a-f]{64}$'),
  derived_by_id text NOT NULL REFERENCES identity.participants(id),
  derived_by_snapshot jsonb NOT NULL CHECK (jsonb_typeof(derived_by_snapshot) = 'object'),
  derived_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  candidate_hash text NOT NULL UNIQUE CHECK (candidate_hash ~ '^[0-9a-f]{64}$'),
  candidate_root text NOT NULL UNIQUE CHECK (candidate_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  CHECK (cardinality(evidence_ids) = cardinality(evidence_registration_roots)),
  CHECK (cardinality(evidence_ids) = cardinality(evidence_final_decision_ids)),
  CHECK (cardinality(evidence_ids) = cardinality(evidence_final_decision_roots)),
  CHECK (cardinality(evidence_ids) = cardinality(evidence_final_verification_roots)),
  CHECK (cardinality(monitoring_event_ids) = cardinality(monitoring_roots))
);

CREATE INDEX IF NOT EXISTS environmental_proof_candidates_project_time
  ON certificates.environmental_proof_candidates (project_id, derived_at DESC, id);
CREATE INDEX IF NOT EXISTS environmental_proof_candidates_organization_time
  ON certificates.environmental_proof_candidates (organization_id, derived_at DESC, id);
CREATE INDEX IF NOT EXISTS environmental_proof_candidates_methodology
  ON certificates.environmental_proof_candidates (methodology_id, methodology_publication_id, derived_at DESC);

CREATE TABLE IF NOT EXISTS governance.environmental_proof_candidate_approvals (
  id text PRIMARY KEY,
  candidate_id text NOT NULL REFERENCES certificates.environmental_proof_candidates(id),
  candidate_root text NOT NULL CHECK (candidate_root ~ '^[0-9a-f]{64}$'),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  policy_id text NOT NULL REFERENCES governance.proof_policy_versions(id),
  policy_hash text NOT NULL CHECK (policy_hash ~ '^[0-9a-f]{64}$'),
  prior_approval_id text REFERENCES governance.environmental_proof_candidate_approvals(id),
  prior_approval_root text CHECK (prior_approval_root IS NULL OR prior_approval_root ~ '^[0-9a-f]{64}$'),
  decision text NOT NULL CHECK (decision IN ('approve', 'reject', 'request_changes')),
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 24 AND 4000),
  conflict_disclosure text NOT NULL CHECK (length(btrim(conflict_disclosure)) BETWEEN 24 AND 2000),
  limitations text[] NOT NULL CHECK (cardinality(limitations) <= 32),
  source_event_roots text[] NOT NULL CHECK (cardinality(source_event_roots) BETWEEN 1 AND 256),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  approver_id text NOT NULL REFERENCES identity.participants(id),
  approver_snapshot jsonb NOT NULL CHECK (jsonb_typeof(approver_snapshot) = 'object'),
  decided_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  candidate_sequence bigint NOT NULL CHECK (candidate_sequence > 1),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  approval_hash text NOT NULL UNIQUE CHECK (approval_hash ~ '^[0-9a-f]{64}$'),
  approval_root text NOT NULL UNIQUE CHECK (approval_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (candidate_id, candidate_sequence),
  UNIQUE (candidate_id, approver_id),
  CHECK ((prior_approval_id IS NULL) = (prior_approval_root IS NULL))
);

CREATE INDEX IF NOT EXISTS environmental_proof_candidate_approvals_candidate_sequence
  ON governance.environmental_proof_candidate_approvals (candidate_id, candidate_sequence, id);
CREATE INDEX IF NOT EXISTS environmental_proof_candidate_approvals_policy_time
  ON governance.environmental_proof_candidate_approvals (policy_id, decided_at DESC, id);

CREATE TABLE IF NOT EXISTS certificates.environmental_proof_record_facts (
  id text PRIMARY KEY,
  record_type text NOT NULL CHECK (record_type = 'environmental_proof_record'),
  candidate_id text NOT NULL UNIQUE REFERENCES certificates.environmental_proof_candidates(id),
  candidate_root text NOT NULL CHECK (candidate_root ~ '^[0-9a-f]{64}$'),
  authority_root text NOT NULL CHECK (authority_root ~ '^[0-9a-f]{64}$'),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  project_root text NOT NULL CHECK (project_root ~ '^[0-9a-f]{64}$'),
  methodology_id text NOT NULL REFERENCES governance.methodologies(id),
  methodology_hash text NOT NULL CHECK (methodology_hash ~ '^[0-9a-f]{64}$'),
  methodology_publication_id text NOT NULL REFERENCES governance.methodology_publications(id),
  methodology_publication_root text NOT NULL CHECK (methodology_publication_root ~ '^[0-9a-f]{64}$'),
  policy_id text NOT NULL REFERENCES governance.proof_policy_versions(id),
  policy_root text NOT NULL CHECK (policy_root ~ '^[0-9a-f]{64}$'),
  evidence_ids text[] NOT NULL CHECK (cardinality(evidence_ids) BETWEEN 1 AND 256),
  evidence_root text NOT NULL CHECK (evidence_root ~ '^[0-9a-f]{64}$'),
  evidence_final_decision_ids text[] NOT NULL CHECK (cardinality(evidence_final_decision_ids) BETWEEN 1 AND 256),
  evidence_final_decision_roots text[] NOT NULL CHECK (cardinality(evidence_final_decision_roots) BETWEEN 1 AND 256),
  monitoring_event_ids text[] NOT NULL CHECK (cardinality(monitoring_event_ids) BETWEEN 1 AND 256),
  monitoring_root text NOT NULL CHECK (monitoring_root ~ '^[0-9a-f]{64}$'),
  contributor_ids text[] NOT NULL CHECK (cardinality(contributor_ids) BETWEEN 1 AND 256),
  public_location jsonb NOT NULL CHECK (jsonb_typeof(public_location) = 'object'),
  confidence_score integer NOT NULL CHECK (confidence_score BETWEEN 0 AND 100),
  governance_approval_ids text[] NOT NULL CHECK (cardinality(governance_approval_ids) BETWEEN 2 AND 32),
  governance_approval_roots text[] NOT NULL CHECK (cardinality(governance_approval_roots) BETWEEN 2 AND 32),
  governance_quorum_root text NOT NULL CHECK (governance_quorum_root ~ '^[0-9a-f]{64}$'),
  issuer_id text NOT NULL REFERENCES identity.participants(id),
  issuer_snapshot jsonb NOT NULL CHECK (jsonb_typeof(issuer_snapshot) = 'object'),
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 24 AND 4000),
  limitations text[] NOT NULL CHECK (cardinality(limitations) <= 32),
  source_event_roots text[] NOT NULL CHECK (cardinality(source_event_roots) BETWEEN 1 AND 512),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  issued_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  candidate_sequence bigint NOT NULL CHECK (candidate_sequence > 2),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  record_hash text NOT NULL UNIQUE CHECK (record_hash ~ '^[0-9a-f]{64}$'),
  record_root text NOT NULL UNIQUE CHECK (record_root ~ '^[0-9a-f]{64}$'),
  status text NOT NULL CHECK (status = 'issued'),
  claim_boundary jsonb NOT NULL CHECK (jsonb_typeof(claim_boundary) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  CHECK (cardinality(evidence_ids) = cardinality(evidence_final_decision_ids)),
  CHECK (cardinality(evidence_ids) = cardinality(evidence_final_decision_roots)),
  CHECK (cardinality(governance_approval_ids) = cardinality(governance_approval_roots))
);

CREATE INDEX IF NOT EXISTS environmental_proof_record_facts_project_time
  ON certificates.environmental_proof_record_facts (project_id, issued_at DESC, id);
CREATE INDEX IF NOT EXISTS environmental_proof_record_facts_organization_time
  ON certificates.environmental_proof_record_facts (organization_id, issued_at DESC, id);

CREATE OR REPLACE FUNCTION certificates.environmental_proof_safety_canonical()
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT jsonb_build_object(
    'environmentalAccountabilityOnly', true,
    'sourceAuthorityReplayed', true,
    'currentFinalEvidenceOnly', true,
    'governedMethodologyRequired', true,
    'acceptedMonitoringRequired', true,
    'independentHumanGovernanceRequired', true,
    'publicChallengeRequiredBeforePublicReliance', true,
    'noRawEvidence', true,
    'notCertifiedCarbonCredit', true,
    'notCarbonTaxOffset', true,
    'notFinancialAsset', true,
    'notGuaranteedYield', true,
    'noMainnetFunds', true,
    'notAutomaticCanopyDistribution', true
  );
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_candidate_authority_seed(
  candidate certificates.environmental_proof_candidates
)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT jsonb_build_object(
    'organizationId', candidate.organization_id,
    'projectId', candidate.project_id,
    'projectStatus', candidate.project_status,
    'projectRoot', candidate.project_root,
    'projectEventRoot', candidate.project_event_root,
    'methodologyId', candidate.methodology_id,
    'methodologyHash', candidate.methodology_hash,
    'methodologyQualityGateRoot', candidate.methodology_quality_gate_root,
    'methodologyEventRoot', candidate.methodology_event_root,
    'methodologyPublicationId', candidate.methodology_publication_id,
    'methodologyPublicationRoot', candidate.methodology_publication_root,
    'methodologyPublicationEventRoot', candidate.methodology_publication_event_root,
    'methodologyPublicationBundleRoot', candidate.methodology_publication_bundle_root,
    'methodologyPublicationPolicyRoot', candidate.methodology_publication_policy_root,
    'methodologyPublicationPolicyEventRoot', candidate.methodology_publication_policy_event_root,
    'methodologyApprovalRoots', to_jsonb(candidate.methodology_approval_roots),
    'methodologyApprovalQuorumRoot', candidate.methodology_approval_quorum_root,
    'policyId', candidate.policy_id,
    'policyHash', candidate.policy_hash,
    'policyRoot', candidate.policy_root,
    'policyEventRoot', candidate.policy_event_root,
    'requiredApprovals', candidate.required_approvals,
    'allowedReviewerRoles', to_jsonb(candidate.allowed_reviewer_roles),
    'evidenceIds', to_jsonb(candidate.evidence_ids),
    'evidenceRegistrationRoots', to_jsonb(candidate.evidence_registration_roots),
    'evidenceFinalDecisionIds', to_jsonb(candidate.evidence_final_decision_ids),
    'evidenceFinalDecisionRoots', to_jsonb(candidate.evidence_final_decision_roots),
    'evidenceFinalVerificationRoots', to_jsonb(candidate.evidence_final_verification_roots),
    'evidenceRoot', candidate.evidence_root,
    'finalDecisionRoot', candidate.final_decision_root,
    'monitoringEventIds', to_jsonb(candidate.monitoring_event_ids),
    'monitoringRoots', to_jsonb(candidate.monitoring_roots),
    'monitoringRoot', candidate.monitoring_root,
    'contributorIds', to_jsonb(candidate.contributor_ids),
    'sourceActorIds', to_jsonb(candidate.source_actor_ids),
    'publicLocation', candidate.public_location,
    'confidenceScore', candidate.confidence_score,
    'limitations', to_jsonb(candidate.limitations),
    'sourceEventRoots', to_jsonb(candidate.source_event_roots),
    'sourceRoot', candidate.source_root
  );
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_candidate_source_root(
  candidate certificates.environmental_proof_candidates
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.merkle_root(ARRAY(
    SELECT leaf FROM (
      SELECT candidate.project_root AS leaf
      UNION ALL SELECT candidate.methodology_hash
      UNION ALL SELECT candidate.methodology_quality_gate_root
      UNION ALL SELECT candidate.methodology_publication_root
      UNION ALL SELECT candidate.methodology_publication_bundle_root
      UNION ALL SELECT candidate.methodology_publication_policy_root
      UNION ALL SELECT unnest(candidate.methodology_approval_roots)
      UNION ALL SELECT candidate.policy_hash
      UNION ALL SELECT candidate.policy_root
      UNION ALL SELECT unnest(candidate.evidence_registration_roots)
      UNION ALL SELECT unnest(candidate.evidence_final_decision_roots)
      UNION ALL SELECT unnest(candidate.evidence_final_verification_roots)
      UNION ALL SELECT unnest(candidate.monitoring_roots)
      UNION ALL SELECT unnest(candidate.source_event_roots)
    ) leaves ORDER BY leaf
  ));
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_candidate_authority_root(
  candidate certificates.environmental_proof_candidates
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-environmental-proof-authority-v1') ||
    certificates.environmental_proof_candidate_authority_seed(candidate)
  );
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_candidate_command_hash(
  candidate certificates.environmental_proof_candidates
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-environmental-proof-candidate-command-v1') ||
    certificates.environmental_proof_candidate_authority_seed(candidate) ||
    jsonb_build_object(
      'authorityRoot', candidate.authority_root,
      'derivedBy', candidate.derived_by_snapshot,
      'derivedAt', audit.iso8601_millis(candidate.derived_at)
    )
  );
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_candidate_hash(
  candidate certificates.environmental_proof_candidates
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-environmental-proof-candidate-v1') ||
    certificates.environmental_proof_candidate_authority_seed(candidate) ||
    jsonb_build_object(
      'authorityRoot', candidate.authority_root,
      'derivedBy', candidate.derived_by_snapshot,
      'derivedAt', audit.iso8601_millis(candidate.derived_at),
      'commandHash', candidate.command_hash
    )
  );
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_candidate_root(
  candidate certificates.environmental_proof_candidates
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-environmental-proof-candidate-root-v1',
    'authorityRoot', candidate.authority_root,
    'sourceRoot', candidate.source_root,
    'candidateHash', candidate.candidate_hash
  ));
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_candidate_payload_hash(
  candidate certificates.environmental_proof_candidates
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('factType', 'environmental_proof_candidate', 'id', candidate.id) ||
    certificates.environmental_proof_candidate_authority_seed(candidate) ||
    jsonb_build_object(
      'authorityRoot', candidate.authority_root,
      'derivedBy', candidate.derived_by_snapshot,
      'derivedAt', audit.iso8601_millis(candidate.derived_at),
      'commandHash', candidate.command_hash,
      'candidateHash', candidate.candidate_hash,
      'candidateRoot', candidate.candidate_root,
      'safety', candidate.safety
    )
  );
$$;

CREATE OR REPLACE FUNCTION certificates.validate_environmental_proof_candidate_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  project_registration projects.projects%ROWTYPE;
  current_project record;
  methodology governance.methodologies%ROWTYPE;
  publication governance.methodology_publications%ROWTYPE;
  publication_policy governance.proof_policy_versions%ROWTYPE;
  proof_policy governance.proof_policy_versions%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  latest_sequence bigint;
  expected_methodology_approval_roots text[];
  expected_evidence_roots text[];
  expected_decision_ids text[];
  expected_decision_roots text[];
  expected_final_verification_roots text[];
  expected_monitoring_roots text[];
  expected_contributor_ids text[];
  expected_source_actor_ids text[];
  expected_source_event_roots text[];
  expected_public_location jsonb;
  expected_confidence integer;
  registration_confidence integer;
  analysis_confidence integer;
  evidence_count integer;
  monitoring_count integer;
  latest_decision_at timestamptz;
  latest_monitoring_at timestamptz;
  expected_bundle_root text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.derived_by_id THEN
    RAISE EXCEPTION 'environmental proof candidate requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.actor_snapshot_is_valid(
    NEW.derived_by_snapshot, NEW.derived_by_id, NEW.organization_id,
    'human', ARRAY['owner', 'admin', 'verifier', 'researcher']::text[]
  ) OR NEW.derived_by_snapshot->>'role' NOT IN ('owner', 'admin', 'verifier', 'researcher') THEN
    RAISE EXCEPTION 'environmental proof candidate derivation authority is invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT project_registration
  FROM projects.projects WHERE id = NEW.project_id FOR SHARE;
  SELECT * INTO STRICT current_project FROM projects.current_authority(NEW.project_id);
  IF project_registration.organization_id <> NEW.organization_id
     OR current_project.status <> NEW.project_status
     OR current_project.status NOT IN ('active', 'monitored')
     OR current_project.project_root <> NEW.project_root
     OR current_project.audit_event_root <> NEW.project_event_root THEN
    RAISE EXCEPTION 'environmental proof candidate project authority is not current or eligible' USING ERRCODE = 'check_violation';
  END IF;
  expected_public_location := jsonb_build_object(
    'latitude', (project_registration.location->>'latitude')::double precision,
    'longitude', (project_registration.location->>'longitude')::double precision,
    'regionId', project_registration.region_id,
    'areaHectares', (project_registration.location->>'areaHectares')::double precision
  );
  IF NEW.public_location <> expected_public_location
     OR (NEW.public_location->>'latitude')::double precision NOT BETWEEN -90 AND 90
     OR (NEW.public_location->>'longitude')::double precision NOT BETWEEN -180 AND 180
     OR (NEW.public_location->>'areaHectares')::double precision <= 0
     OR length(btrim(NEW.public_location->>'regionId')) = 0 THEN
    RAISE EXCEPTION 'environmental proof candidate public location is invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT methodology
  FROM governance.methodologies WHERE id = NEW.methodology_id FOR SHARE;
  SELECT * INTO STRICT publication
  FROM governance.methodology_publications WHERE id = NEW.methodology_publication_id FOR SHARE;
  SELECT * INTO STRICT publication_policy
  FROM governance.proof_policy_versions WHERE id = publication.policy_id FOR SHARE;
  SELECT * INTO STRICT proof_policy
  FROM governance.proof_policy_versions WHERE id = NEW.policy_id FOR SHARE;
  IF methodology.status <> 'draft'
     OR methodology.published_at IS NOT NULL
     OR cardinality(methodology.governance_approval_ids) <> 0
     OR methodology.methodology_hash <> NEW.methodology_hash
     OR methodology.quality_gate_root <> NEW.methodology_quality_gate_root
     OR methodology.event_root <> NEW.methodology_event_root
     OR publication.methodology_id <> methodology.id
     OR publication.methodology_hash <> methodology.methodology_hash
     OR publication.methodology_quality_gate_root <> methodology.quality_gate_root
     OR publication.methodology_event_root <> methodology.event_root
     OR publication.publication_root <> NEW.methodology_publication_root
     OR publication.audit_event_root <> NEW.methodology_publication_event_root
     OR publication_policy.subject <> 'methodology_publication'
     OR publication_policy.policy_root <> NEW.methodology_publication_policy_root
     OR publication_policy.audit_event_root <> NEW.methodology_publication_policy_event_root
     OR proof_policy.subject <> 'environmental_proof_record'
     OR proof_policy.policy_hash <> NEW.policy_hash
     OR proof_policy.policy_root <> NEW.policy_root
     OR proof_policy.audit_event_root <> NEW.policy_event_root
     OR proof_policy.required_approvals <> NEW.required_approvals
     OR proof_policy.allowed_reviewer_roles <> NEW.allowed_reviewer_roles
     OR proof_policy.governance_organization_id <> NEW.organization_id
     OR publication_policy.governance_organization_id <> NEW.organization_id
     OR EXISTS (
       SELECT 1 FROM governance.proof_policy_versions successor
       WHERE successor.supersedes_policy_id IN (publication_policy.id, proof_policy.id)
     )
     OR EXISTS (
       SELECT 1 FROM governance.methodologies successor_methodology
       JOIN governance.methodology_publications successor_publication
         ON successor_publication.methodology_id = successor_methodology.id
       WHERE successor_methodology.supersedes = methodology.id
     ) THEN
    RAISE EXCEPTION 'environmental proof candidate methodology or policy authority is not current' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT (ARRAY[
       'human_review_required', 'governance_approval_required',
       'public_challenge_window_required', 'monitoring_timeline_required'
     ]::text[] <@ methodology.quality_gates)
     OR methodology.scope <> 'multi_scope' AND EXISTS (
       SELECT 1 FROM evidence.evidence_objects evidence_record
       WHERE evidence_record.id = ANY(NEW.evidence_ids)
         AND evidence_record.evidence_type <> methodology.scope
     ) THEN
    RAISE EXCEPTION 'environmental proof candidate methodology scope or quality gates are invalid' USING ERRCODE = 'check_violation';
  END IF;
  SELECT COALESCE(array_agg(approval_root ORDER BY approval_root), ARRAY[]::text[])
  INTO expected_methodology_approval_roots
  FROM governance.methodology_publication_approvals
  WHERE id = ANY(publication.approval_ids);
  expected_bundle_root := audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-methodology-publication-bundle-v1',
    'methodologyHash', methodology.methodology_hash,
    'methodologyEventRoot', methodology.event_root,
    'policyRoot', publication_policy.policy_root,
    'policyEventRoot', publication_policy.audit_event_root,
    'approvalRoots', to_jsonb(expected_methodology_approval_roots),
    'publicationRoot', publication.publication_root,
    'publicationEventRoot', publication.audit_event_root
  ));
  IF expected_methodology_approval_roots <> NEW.methodology_approval_roots
     OR NEW.methodology_approval_quorum_root <> audit.merkle_root(NEW.methodology_approval_roots)
     OR NEW.methodology_publication_bundle_root <> expected_bundle_root THEN
    RAISE EXCEPTION 'environmental proof candidate methodology publication bundle is invalid' USING ERRCODE = 'check_violation';
  END IF;

  WITH current_evidence AS (
    SELECT registration.*,
      terminal.sequence_no AS terminal_sequence,
      verification.evidence_final_verification_seed_at(registration.id, terminal.sequence_no) AS final_seed,
      verification.evidence_final_verification_root_at(registration.id, terminal.sequence_no) AS final_root
    FROM unnest(NEW.evidence_ids) requested(id)
    JOIN evidence.evidence_objects registration ON registration.id = requested.id
    JOIN LATERAL (
      SELECT max(sequence_no) AS sequence_no
      FROM audit.domain_events WHERE stream_id = registration.id
    ) terminal ON terminal.sequence_no IS NOT NULL
  ), eligible AS (
    SELECT source.*, decision.id AS decision_id, decision.decision_root,
      decision.decided_at, decision.audit_event_root AS decision_event_root,
      decision.verifier_id, decision.human_review_id, decision.ai_analysis_ids
    FROM current_evidence source
    JOIN verification.evidence_final_decisions decision
      ON decision.id = source.final_seed->>'currentDecisionId'
    WHERE source.final_seed->>'state' = 'verified'
      AND decision.decision = 'verify'
      AND decision.decision_root = source.final_seed->>'currentDecisionRoot'
      AND decision.audit_event_root = source.final_seed->>'terminalEventRoot'
  )
  SELECT
    COALESCE(array_agg(evidence_root ORDER BY evidence_root), ARRAY[]::text[]),
    COALESCE(array_agg(decision_id ORDER BY decision_id), ARRAY[]::text[]),
    COALESCE(array_agg(decision_root ORDER BY decision_root), ARRAY[]::text[]),
    COALESCE(array_agg(final_root ORDER BY final_root), ARRAY[]::text[]),
    COALESCE(array_agg(DISTINCT contributor_id ORDER BY contributor_id), ARRAY[]::text[]),
    min(confidence_score), max(decided_at), count(*)::integer
  INTO expected_evidence_roots, expected_decision_ids, expected_decision_roots,
    expected_final_verification_roots, expected_contributor_ids,
    registration_confidence, latest_decision_at, evidence_count
  FROM eligible
  WHERE project_id = NEW.project_id AND organization_id = NEW.organization_id;
  IF evidence_count <> cardinality(NEW.evidence_ids)
     OR NEW.evidence_registration_roots <> expected_evidence_roots
     OR NEW.evidence_final_decision_ids <> expected_decision_ids
     OR NEW.evidence_final_decision_roots <> expected_decision_roots
     OR NEW.evidence_final_verification_roots <> expected_final_verification_roots
     OR NEW.contributor_ids <> expected_contributor_ids
     OR NEW.evidence_root <> audit.merkle_root(NEW.evidence_registration_roots)
     OR NEW.final_decision_root <> audit.merkle_root(NEW.evidence_final_decision_roots) THEN
    RAISE EXCEPTION 'environmental proof candidate evidence final authority is incomplete or stale' USING ERRCODE = 'check_violation';
  END IF;
  SELECT min(analysis.confidence_score)
  INTO analysis_confidence
  FROM verification.evidence_final_decisions decision
  JOIN verification.evidence_ai_analyses analysis ON analysis.id = ANY(decision.ai_analysis_ids)
  WHERE decision.id = ANY(NEW.evidence_final_decision_ids);
  expected_confidence := LEAST(registration_confidence, analysis_confidence);
  IF expected_confidence IS NULL OR NEW.confidence_score <> expected_confidence THEN
    RAISE EXCEPTION 'environmental proof candidate confidence derivation is invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT COALESCE(array_agg(monitoring_root ORDER BY monitoring_root), ARRAY[]::text[]),
    max(observed_at), count(*)::integer
  INTO expected_monitoring_roots, latest_monitoring_at, monitoring_count
  FROM projects.monitoring_events
  WHERE id = ANY(NEW.monitoring_event_ids)
    AND project_id = NEW.project_id
    AND organization_id = NEW.organization_id
    AND state = 'accepted';
  IF monitoring_count <> cardinality(NEW.monitoring_event_ids)
     OR NEW.monitoring_roots <> expected_monitoring_roots
     OR NEW.monitoring_root <> audit.merkle_root(NEW.monitoring_roots)
     OR EXISTS (
       SELECT 1 FROM projects.monitoring_events monitoring
       WHERE monitoring.id = ANY(NEW.monitoring_event_ids)
         AND monitoring.observed_at <= latest_decision_at
     )
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.evidence_ids) evidence_id
       WHERE NOT EXISTS (
         SELECT 1 FROM projects.monitoring_events monitoring
         WHERE monitoring.id = ANY(NEW.monitoring_event_ids)
           AND evidence_id = ANY(monitoring.evidence_ids)
       )
     )
     OR NEW.derived_at < latest_monitoring_at
     OR NEW.derived_at - latest_monitoring_at > make_interval(days => methodology.monitoring_cadence_days) THEN
    RAISE EXCEPTION 'environmental proof candidate monitoring authority is incomplete or outside cadence' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(methodology.required_data_sources) required_source
    WHERE CASE required_source
      WHEN 'field_photo' THEN EXISTS (
        SELECT 1 FROM evidence.evidence_objects evidence_record
        WHERE evidence_record.id = ANY(NEW.evidence_ids) AND evidence_record.media_hash IS NULL
      )
      WHEN 'gps_trace' THEN EXISTS (
        SELECT 1 FROM evidence.evidence_objects evidence_record
        WHERE evidence_record.id = ANY(NEW.evidence_ids) AND evidence_record.gps_hash IS NULL
      )
      WHEN 'satellite_scene' THEN NOT EXISTS (
        SELECT 1 FROM projects.monitoring_events monitoring
        WHERE monitoring.id = ANY(NEW.monitoring_event_ids) AND cardinality(monitoring.terra_scene_ids) > 0
      )
      WHEN 'sensor_reading' THEN NOT EXISTS (
        SELECT 1 FROM projects.monitoring_events monitoring
        WHERE monitoring.id = ANY(NEW.monitoring_event_ids)
          AND jsonb_typeof(monitoring.metrics) = 'object' AND monitoring.metrics <> '{}'::jsonb
      )
      WHEN 'governance_approval' THEN false
      ELSE true
    END
  ) THEN
    RAISE EXCEPTION 'environmental proof candidate lacks a required durable methodology source' USING ERRCODE = 'check_violation';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT actor_id ORDER BY actor_id), ARRAY[]::text[])
  INTO expected_source_actor_ids
  FROM (
    SELECT methodology.created_by AS actor_id
    UNION ALL SELECT publication_policy.creator_id
    UNION ALL SELECT approval.approver_id
      FROM governance.methodology_publication_approvals approval
      WHERE approval.id = ANY(publication.approval_ids)
    UNION ALL SELECT publication.publisher_id
    UNION ALL SELECT proof_policy.creator_id
    UNION ALL SELECT event.actor_id FROM audit.domain_events event WHERE event.stream_id = NEW.project_id
    UNION ALL SELECT registration.contributor_id
      FROM evidence.evidence_objects registration WHERE registration.id = ANY(NEW.evidence_ids)
    UNION ALL SELECT decision.verifier_id
      FROM verification.evidence_final_decisions decision WHERE decision.id = ANY(NEW.evidence_final_decision_ids)
    UNION ALL SELECT review.reviewer_id
      FROM verification.evidence_final_decisions decision
      JOIN verification.evidence_human_reviews review ON review.id = decision.human_review_id
      WHERE decision.id = ANY(NEW.evidence_final_decision_ids)
    UNION ALL SELECT analysis.agent_id
      FROM verification.evidence_final_decisions decision
      JOIN verification.evidence_ai_analyses analysis ON analysis.id = ANY(decision.ai_analysis_ids)
      WHERE decision.id = ANY(NEW.evidence_final_decision_ids)
    UNION ALL SELECT monitoring.observed_by
      FROM projects.monitoring_events monitoring WHERE monitoring.id = ANY(NEW.monitoring_event_ids)
  ) actors;
  SELECT COALESCE(array_agg(DISTINCT event_root ORDER BY event_root), ARRAY[]::text[])
  INTO expected_source_event_roots
  FROM (
    SELECT NEW.project_event_root AS event_root
    UNION ALL SELECT methodology.event_root
    UNION ALL SELECT publication_policy.audit_event_root
    UNION ALL SELECT approval.audit_event_root
      FROM governance.methodology_publication_approvals approval
      WHERE approval.id = ANY(publication.approval_ids)
    UNION ALL SELECT publication.audit_event_root
    UNION ALL SELECT proof_policy.audit_event_root
    UNION ALL SELECT registration.audit_event_root
      FROM evidence.evidence_objects registration WHERE registration.id = ANY(NEW.evidence_ids)
    UNION ALL SELECT decision.audit_event_root
      FROM verification.evidence_final_decisions decision WHERE decision.id = ANY(NEW.evidence_final_decision_ids)
    UNION ALL SELECT monitoring.audit_event_root
      FROM projects.monitoring_events monitoring WHERE monitoring.id = ANY(NEW.monitoring_event_ids)
  ) events;
  IF NEW.source_actor_ids <> expected_source_actor_ids
     OR NEW.source_event_roots <> expected_source_event_roots
     OR NEW.derived_at < GREATEST(
       publication.published_at, proof_policy.created_at, current_project.updated_at,
       latest_decision_at, latest_monitoring_at
     ) THEN
    RAISE EXCEPTION 'environmental proof candidate source actors, events, or time are invalid' USING ERRCODE = 'check_violation';
  END IF;

  IF NOT audit.is_sorted_unique_text_array(NEW.methodology_approval_roots)
     OR NOT audit.is_sha256_hash_array(NEW.methodology_approval_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.allowed_reviewer_roles)
     OR NOT audit.is_sorted_unique_text_array(NEW.evidence_ids)
     OR NOT audit.is_sorted_unique_text_array(NEW.evidence_registration_roots)
     OR NOT audit.is_sha256_hash_array(NEW.evidence_registration_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.evidence_final_decision_ids)
     OR NOT audit.is_sorted_unique_text_array(NEW.evidence_final_decision_roots)
     OR NOT audit.is_sha256_hash_array(NEW.evidence_final_decision_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.evidence_final_verification_roots)
     OR NOT audit.is_sha256_hash_array(NEW.evidence_final_verification_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.monitoring_event_ids)
     OR NOT audit.is_sorted_unique_text_array(NEW.monitoring_roots)
     OR NOT audit.is_sha256_hash_array(NEW.monitoring_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.contributor_ids)
     OR NOT audit.is_sorted_unique_text_array(NEW.source_actor_ids)
     OR NOT audit.is_sorted_unique_text_array(NEW.limitations)
     OR NOT audit.is_bounded_text_array(NEW.limitations, 1, 1000, 32)
     OR NOT audit.is_sorted_unique_text_array(NEW.source_event_roots)
     OR NOT audit.is_sha256_hash_array(NEW.source_event_roots)
     OR projects.contains_unsafe_claim(ARRAY[NEW.id] || NEW.limitations)
     OR NEW.safety <> certificates.environmental_proof_safety_canonical() THEN
    RAISE EXCEPTION 'environmental proof candidate canonical arrays or safety are invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT semantic_event
  FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence
  FROM audit.domain_events WHERE stream_id = NEW.id;
  IF semantic_event.stream_id <> NEW.id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> 1
     OR semantic_event.previous_root <> audit.genesis_root()
     OR semantic_event.actor_id <> NEW.derived_by_id
     OR semantic_event.entity_type <> 'environmental_proof_candidate'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> 'ASSERT'
     OR semantic_event.created_at <> NEW.derived_at
     OR semantic_event.rationale <> 'A bounded Environmental Proof candidate was derived from current durable source authority.' THEN
    RAISE EXCEPTION 'environmental proof candidate semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.source_root <> certificates.environmental_proof_candidate_source_root(NEW)
     OR NEW.authority_root <> certificates.environmental_proof_candidate_authority_root(NEW)
     OR NEW.command_hash <> certificates.environmental_proof_candidate_command_hash(NEW)
     OR NEW.id <> 'cp_environmental_proof_candidate_' || left(NEW.command_hash, 24)
     OR NEW.candidate_hash <> certificates.environmental_proof_candidate_hash(NEW)
     OR NEW.candidate_root <> certificates.environmental_proof_candidate_root(NEW)
     OR semantic_event.payload_hash <> certificates.environmental_proof_candidate_payload_hash(NEW) THEN
    RAISE EXCEPTION 'environmental proof candidate canonical hash lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS environmental_proof_candidates_validate
  ON certificates.environmental_proof_candidates;
CREATE TRIGGER environmental_proof_candidates_validate
BEFORE INSERT ON certificates.environmental_proof_candidates
FOR EACH ROW EXECUTE FUNCTION certificates.validate_environmental_proof_candidate_insert();
DROP TRIGGER IF EXISTS environmental_proof_candidates_no_update
  ON certificates.environmental_proof_candidates;
CREATE TRIGGER environmental_proof_candidates_no_update
BEFORE UPDATE ON certificates.environmental_proof_candidates
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
DROP TRIGGER IF EXISTS environmental_proof_candidates_no_delete
  ON certificates.environmental_proof_candidates;
CREATE TRIGGER environmental_proof_candidates_no_delete
BEFORE DELETE ON certificates.environmental_proof_candidates
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
DROP TRIGGER IF EXISTS environmental_proof_candidates_audit
  ON certificates.environmental_proof_candidates;
CREATE TRIGGER environmental_proof_candidates_audit
AFTER INSERT OR UPDATE OR DELETE ON certificates.environmental_proof_candidates
FOR EACH ROW EXECUTE FUNCTION audit.capture_row_mutation();

CREATE OR REPLACE FUNCTION governance.environmental_proof_approval_command_hash(
  approval governance.environmental_proof_candidate_approvals
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-environmental-proof-candidate-approval-command-v1',
    'candidateId', approval.candidate_id,
    'candidateRoot', approval.candidate_root,
    'policyId', approval.policy_id,
    'policyHash', approval.policy_hash,
    'priorApprovalId', approval.prior_approval_id,
    'priorApprovalRoot', approval.prior_approval_root,
    'decision', approval.decision,
    'rationale', approval.rationale,
    'conflictDisclosure', approval.conflict_disclosure,
    'limitations', to_jsonb(approval.limitations),
    'sourceEventRoots', to_jsonb(approval.source_event_roots),
    'approver', approval.approver_snapshot,
    'decidedAt', audit.iso8601_millis(approval.decided_at)
  ));
$$;

CREATE OR REPLACE FUNCTION governance.environmental_proof_approval_source_root(
  approval governance.environmental_proof_candidate_approvals
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.merkle_root(ARRAY(
    SELECT leaf FROM (
      SELECT approval.candidate_root AS leaf
      UNION ALL SELECT unnest(approval.source_event_roots)
      UNION ALL SELECT approval.prior_approval_root WHERE approval.prior_approval_root IS NOT NULL
    ) leaves ORDER BY leaf
  ));
$$;

CREATE OR REPLACE FUNCTION governance.environmental_proof_approval_hash(
  approval governance.environmental_proof_candidate_approvals
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-environmental-proof-candidate-approval-v1') ||
    jsonb_strip_nulls(jsonb_build_object(
      'candidateId', approval.candidate_id,
      'candidateRoot', approval.candidate_root,
      'organizationId', approval.organization_id,
      'projectId', approval.project_id,
      'policyId', approval.policy_id,
      'policyHash', approval.policy_hash,
      'priorApprovalId', approval.prior_approval_id,
      'priorApprovalRoot', approval.prior_approval_root,
      'decision', approval.decision,
      'rationale', approval.rationale,
      'conflictDisclosure', approval.conflict_disclosure,
      'limitations', to_jsonb(approval.limitations),
      'sourceEventRoots', to_jsonb(approval.source_event_roots),
      'sourceRoot', approval.source_root,
      'approver', approval.approver_snapshot,
      'decidedAt', audit.iso8601_millis(approval.decided_at),
      'commandHash', approval.command_hash,
      'candidateSequence', approval.candidate_sequence,
      'previousEventRoot', approval.previous_event_root
    ))
  );
$$;

CREATE OR REPLACE FUNCTION governance.environmental_proof_approval_root(
  approval governance.environmental_proof_candidate_approvals
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-environmental-proof-candidate-approval-root-v1',
    'candidateRoot', approval.candidate_root,
    'sourceRoot', approval.source_root,
    'approvalHash', approval.approval_hash,
    'previousEventRoot', approval.previous_event_root,
    'candidateSequence', approval.candidate_sequence
  ));
$$;

CREATE OR REPLACE FUNCTION governance.environmental_proof_approval_payload_hash(
  approval governance.environmental_proof_candidate_approvals
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('factType', 'environmental_proof_candidate_approval', 'id', approval.id) ||
    jsonb_strip_nulls(jsonb_build_object(
      'candidateId', approval.candidate_id,
      'candidateRoot', approval.candidate_root,
      'organizationId', approval.organization_id,
      'projectId', approval.project_id,
      'policyId', approval.policy_id,
      'policyHash', approval.policy_hash,
      'priorApprovalId', approval.prior_approval_id,
      'priorApprovalRoot', approval.prior_approval_root,
      'decision', approval.decision,
      'rationale', approval.rationale,
      'conflictDisclosure', approval.conflict_disclosure,
      'limitations', to_jsonb(approval.limitations),
      'sourceEventRoots', to_jsonb(approval.source_event_roots),
      'sourceRoot', approval.source_root,
      'approver', approval.approver_snapshot,
      'decidedAt', audit.iso8601_millis(approval.decided_at),
      'commandHash', approval.command_hash,
      'candidateSequence', approval.candidate_sequence,
      'previousEventRoot', approval.previous_event_root,
      'approvalHash', approval.approval_hash,
      'approvalRoot', approval.approval_root,
      'safety', approval.safety
    ))
  );
$$;

CREATE OR REPLACE FUNCTION governance.validate_environmental_proof_approval_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  candidate certificates.environmental_proof_candidates%ROWTYPE;
  policy governance.proof_policy_versions%ROWTYPE;
  latest_prior governance.environmental_proof_candidate_approvals%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  accreditation organizations.accreditations%ROWTYPE;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.approver_id THEN
    RAISE EXCEPTION 'environmental proof approval requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT candidate
  FROM certificates.environmental_proof_candidates WHERE id = NEW.candidate_id FOR SHARE;
  SELECT * INTO STRICT policy
  FROM governance.proof_policy_versions WHERE id = candidate.policy_id FOR SHARE;
  IF candidate.candidate_root <> NEW.candidate_root
     OR candidate.organization_id <> NEW.organization_id
     OR candidate.project_id <> NEW.project_id
     OR candidate.policy_id <> NEW.policy_id
     OR candidate.policy_hash <> NEW.policy_hash
     OR policy.policy_hash <> NEW.policy_hash
     OR policy.subject <> 'environmental_proof_record'
     OR EXISTS (
       SELECT 1 FROM certificates.environmental_proof_record_facts record
       WHERE record.candidate_id = NEW.candidate_id
     ) THEN
    RAISE EXCEPTION 'environmental proof approval candidate or policy binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.actor_snapshot_is_valid(
    NEW.approver_snapshot, NEW.approver_id, NEW.organization_id,
    'human', candidate.allowed_reviewer_roles
  ) OR NOT (NEW.approver_snapshot->>'role' = ANY(candidate.allowed_reviewer_roles)) THEN
    RAISE EXCEPTION 'environmental proof approver authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.approver_snapshot->>'role' = 'verifier' THEN
    IF NEW.approver_snapshot->>'accreditationStatus' <> 'approved' THEN
      RAISE EXCEPTION 'environmental proof verifier accreditation is not approved' USING ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO STRICT accreditation
    FROM organizations.accreditations WHERE id = NEW.approver_snapshot->>'accreditationId';
    IF accreditation.decided_at > NEW.decided_at THEN
      RAISE EXCEPTION 'environmental proof verifier accreditation postdates approval' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.approver_id = candidate.derived_by_id
     OR NEW.approver_id = ANY(candidate.source_actor_ids)
     OR EXISTS (
       SELECT 1 FROM governance.environmental_proof_candidate_approvals prior_actor
       WHERE prior_actor.candidate_id = NEW.candidate_id
         AND prior_actor.approver_id = NEW.approver_id
     ) THEN
    RAISE EXCEPTION 'environmental proof approval requires an independent human approver' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO latest_prior
  FROM governance.environmental_proof_candidate_approvals
  WHERE candidate_id = NEW.candidate_id
  ORDER BY candidate_sequence DESC LIMIT 1 FOR SHARE;
  IF latest_prior.id IS NULL THEN
    IF NEW.prior_approval_id IS NOT NULL
       OR NEW.prior_approval_root IS NOT NULL
       OR NEW.candidate_sequence <> 2
       OR NEW.previous_event_root <> candidate.audit_event_root THEN
      RAISE EXCEPTION 'first environmental proof approval predecessor is invalid' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.prior_approval_id IS DISTINCT FROM latest_prior.id
     OR NEW.prior_approval_root IS DISTINCT FROM latest_prior.approval_root
     OR NEW.candidate_sequence <> latest_prior.candidate_sequence + 1
     OR NEW.previous_event_root <> latest_prior.audit_event_root THEN
    RAISE EXCEPTION 'environmental proof approval predecessor is missing or forked' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.decided_at < (
       SELECT max(created_at) FROM audit.domain_events WHERE stream_id = NEW.candidate_id
     )
     OR NOT audit.is_sorted_unique_text_array(NEW.limitations)
     OR NOT audit.is_bounded_text_array(NEW.limitations, 1, 1000, 32)
     OR NOT audit.is_sorted_unique_text_array(NEW.source_event_roots)
     OR NOT audit.is_sha256_hash_array(NEW.source_event_roots)
     OR NOT (candidate.audit_event_root = ANY(NEW.source_event_roots))
     OR (latest_prior.id IS NOT NULL AND NOT (latest_prior.audit_event_root = ANY(NEW.source_event_roots)))
     OR projects.contains_unsafe_claim(ARRAY[
       NEW.id, NEW.rationale, NEW.conflict_disclosure
     ] || NEW.limitations)
     OR NEW.safety <> certificates.environmental_proof_safety_canonical()
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.source_event_roots) source_root
       LEFT JOIN audit.domain_events source_event
         ON source_event.event_root = source_root
        AND source_event.stream_id = NEW.candidate_id
        AND source_event.sequence_no < NEW.candidate_sequence
       WHERE source_event.id IS NULL
     ) THEN
    RAISE EXCEPTION 'environmental proof approval source events or safety are invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence
  FROM audit.domain_events WHERE stream_id = NEW.candidate_id;
  IF semantic_event.stream_id <> NEW.candidate_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.candidate_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.approver_id
     OR semantic_event.entity_type <> 'environmental_proof_candidate_approval'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> (CASE NEW.decision
       WHEN 'approve' THEN 'FULFILL' WHEN 'reject' THEN 'CHALLENGE' ELSE 'REASON' END)
     OR semantic_event.created_at <> NEW.decided_at
     OR semantic_event.rationale <> NEW.rationale THEN
    RAISE EXCEPTION 'environmental proof approval semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.source_root <> governance.environmental_proof_approval_source_root(NEW)
     OR NEW.command_hash <> governance.environmental_proof_approval_command_hash(NEW)
     OR NEW.id <> 'cp_environmental_proof_approval_' || left(NEW.command_hash, 24)
     OR NEW.approval_hash <> governance.environmental_proof_approval_hash(NEW)
     OR NEW.approval_root <> governance.environmental_proof_approval_root(NEW)
     OR semantic_event.payload_hash <> governance.environmental_proof_approval_payload_hash(NEW) THEN
    RAISE EXCEPTION 'environmental proof approval canonical lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

