CREATE OR REPLACE FUNCTION certificates.environmental_proof_record_command_hash(
  record_fact certificates.environmental_proof_record_facts
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-environmental-proof-record-command-v1',
    'candidateId', record_fact.candidate_id,
    'candidateRoot', record_fact.candidate_root,
    'authorityRoot', record_fact.authority_root,
    'governanceApprovalIds', to_jsonb(record_fact.governance_approval_ids),
    'governanceApprovalRoots', to_jsonb(record_fact.governance_approval_roots),
    'governanceQuorumRoot', record_fact.governance_quorum_root,
    'issuer', record_fact.issuer_snapshot,
    'rationale', record_fact.rationale,
    'limitations', to_jsonb(record_fact.limitations),
    'sourceEventRoots', to_jsonb(record_fact.source_event_roots),
    'issuedAt', audit.iso8601_millis(record_fact.issued_at)
  ));
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_record_source_root(
  record_fact certificates.environmental_proof_record_facts
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.merkle_root(ARRAY(
    SELECT leaf FROM (
      SELECT record_fact.candidate_root AS leaf
      UNION ALL SELECT record_fact.authority_root
      UNION ALL SELECT unnest(record_fact.governance_approval_roots)
      UNION ALL SELECT unnest(record_fact.source_event_roots)
    ) leaves ORDER BY leaf
  ));
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_record_seed(
  record_fact certificates.environmental_proof_record_facts
)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT jsonb_build_object(
    'recordType', record_fact.record_type,
    'candidateId', record_fact.candidate_id,
    'candidateRoot', record_fact.candidate_root,
    'authorityRoot', record_fact.authority_root,
    'organizationId', record_fact.organization_id,
    'projectId', record_fact.project_id,
    'projectRoot', record_fact.project_root,
    'methodologyId', record_fact.methodology_id,
    'methodologyHash', record_fact.methodology_hash,
    'methodologyPublicationId', record_fact.methodology_publication_id,
    'methodologyPublicationRoot', record_fact.methodology_publication_root,
    'policyId', record_fact.policy_id,
    'policyRoot', record_fact.policy_root,
    'evidenceIds', to_jsonb(record_fact.evidence_ids),
    'evidenceRoot', record_fact.evidence_root,
    'evidenceFinalDecisionIds', to_jsonb(record_fact.evidence_final_decision_ids),
    'evidenceFinalDecisionRoots', to_jsonb(record_fact.evidence_final_decision_roots),
    'monitoringEventIds', to_jsonb(record_fact.monitoring_event_ids),
    'monitoringRoot', record_fact.monitoring_root,
    'contributorIds', to_jsonb(record_fact.contributor_ids),
    'publicLocation', record_fact.public_location,
    'confidenceScore', record_fact.confidence_score,
    'governanceApprovalIds', to_jsonb(record_fact.governance_approval_ids),
    'governanceApprovalRoots', to_jsonb(record_fact.governance_approval_roots),
    'governanceQuorumRoot', record_fact.governance_quorum_root,
    'issuer', record_fact.issuer_snapshot,
    'rationale', record_fact.rationale,
    'limitations', to_jsonb(record_fact.limitations),
    'sourceEventRoots', to_jsonb(record_fact.source_event_roots),
    'sourceRoot', record_fact.source_root,
    'issuedAt', audit.iso8601_millis(record_fact.issued_at),
    'commandHash', record_fact.command_hash,
    'candidateSequence', record_fact.candidate_sequence,
    'previousEventRoot', record_fact.previous_event_root
  );
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_record_hash(
  record_fact certificates.environmental_proof_record_facts
