$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_record_root(
  record_fact certificates.environmental_proof_record_facts
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-environmental-proof-record-root-v1',
    'candidateRoot', record_fact.candidate_root,
    'governanceQuorumRoot', record_fact.governance_quorum_root,
    'sourceRoot', record_fact.source_root,
    'recordHash', record_fact.record_hash,
    'previousEventRoot', record_fact.previous_event_root,
    'candidateSequence', record_fact.candidate_sequence
  ));
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_record_payload_hash(
  record_fact certificates.environmental_proof_record_facts
)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('factType', 'environmental_proof_record', 'id', record_fact.id) ||
    certificates.environmental_proof_record_seed(record_fact) ||
    jsonb_build_object(
      'recordHash', record_fact.record_hash,
      'recordRoot', record_fact.record_root,
      'status', record_fact.status,
      'claimBoundary', record_fact.claim_boundary
    )
  );
$$;

CREATE OR REPLACE FUNCTION certificates.validate_environmental_proof_record_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  candidate certificates.environmental_proof_candidates%ROWTYPE;
  latest_approval governance.environmental_proof_candidate_approvals%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  current_project record;
  expected_approval_ids text[];
  expected_approval_roots text[];
  expected_decision_ids text[];
  expected_decision_roots text[];
  expected_final_verification_roots text[];
  approval_count integer;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.issuer_id THEN
    RAISE EXCEPTION 'environmental proof record requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT candidate
  FROM certificates.environmental_proof_candidates WHERE id = NEW.candidate_id FOR SHARE;
  IF NEW.record_type <> 'environmental_proof_record'
     OR NEW.candidate_root <> candidate.candidate_root
     OR NEW.authority_root <> candidate.authority_root
     OR NEW.organization_id <> candidate.organization_id
     OR NEW.project_id <> candidate.project_id
     OR NEW.project_root <> candidate.project_root
     OR NEW.methodology_id <> candidate.methodology_id
     OR NEW.methodology_hash <> candidate.methodology_hash
     OR NEW.methodology_publication_id <> candidate.methodology_publication_id
     OR NEW.methodology_publication_root <> candidate.methodology_publication_root
     OR NEW.policy_id <> candidate.policy_id
     OR NEW.policy_root <> candidate.policy_root
     OR NEW.evidence_ids <> candidate.evidence_ids
     OR NEW.evidence_root <> candidate.evidence_root
     OR NEW.evidence_final_decision_ids <> candidate.evidence_final_decision_ids
     OR NEW.evidence_final_decision_roots <> candidate.evidence_final_decision_roots
     OR NEW.monitoring_event_ids <> candidate.monitoring_event_ids
     OR NEW.monitoring_root <> candidate.monitoring_root
     OR NEW.contributor_ids <> candidate.contributor_ids
     OR NEW.public_location <> candidate.public_location
     OR NEW.confidence_score <> candidate.confidence_score THEN
    RAISE EXCEPTION 'environmental proof record does not preserve its candidate authority' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.actor_snapshot_is_valid(
    NEW.issuer_snapshot, NEW.issuer_id, NEW.organization_id,
    'human', ARRAY['owner', 'admin']::text[]
  ) OR NEW.issuer_snapshot->>'role' NOT IN ('owner', 'admin')
     OR NEW.issuer_id = candidate.derived_by_id
     OR NEW.issuer_id = ANY(candidate.source_actor_ids)
     OR EXISTS (
       SELECT 1 FROM governance.environmental_proof_candidate_approvals approval
       WHERE approval.candidate_id = NEW.candidate_id
         AND approval.approver_id = NEW.issuer_id
     ) THEN
    RAISE EXCEPTION 'environmental proof record issuer authority is invalid or conflicted' USING ERRCODE = 'check_violation';
  END IF;

  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::text[]),
    COALESCE(array_agg(approval_root ORDER BY approval_root), ARRAY[]::text[]),
    count(*)::integer
  INTO expected_approval_ids, expected_approval_roots, approval_count
  FROM governance.environmental_proof_candidate_approvals
  WHERE candidate_id = NEW.candidate_id;
  SELECT * INTO STRICT latest_approval
  FROM governance.environmental_proof_candidate_approvals
  WHERE candidate_id = NEW.candidate_id
  ORDER BY candidate_sequence DESC LIMIT 1 FOR SHARE;
  IF NEW.governance_approval_ids <> expected_approval_ids
     OR NEW.governance_approval_roots <> expected_approval_roots
     OR NEW.governance_quorum_root <> audit.merkle_root(expected_approval_roots)
     OR approval_count < candidate.required_approvals
     OR NEW.candidate_sequence <> latest_approval.candidate_sequence + 1
     OR NEW.previous_event_root <> latest_approval.audit_event_root
     OR EXISTS (
       SELECT 1 FROM governance.environmental_proof_candidate_approvals approval
       WHERE approval.candidate_id = NEW.candidate_id
         AND (
           approval.decision <> 'approve'
           OR approval.policy_id <> candidate.policy_id
           OR approval.policy_hash <> candidate.policy_hash
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM governance.environmental_proof_candidate_approvals approval
       WHERE approval.candidate_id = NEW.candidate_id
         AND approval.approver_snapshot->>'role' = 'verifier'
     )
     OR NOT EXISTS (
       SELECT 1 FROM governance.environmental_proof_candidate_approvals approval
       WHERE approval.candidate_id = NEW.candidate_id
         AND approval.approver_snapshot->>'role' IN ('owner', 'admin')
     ) THEN
    RAISE EXCEPTION 'environmental proof record governance quorum is incomplete, stale, or adverse' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT current_project FROM projects.current_authority(candidate.project_id);
  IF current_project.status <> candidate.project_status
     OR current_project.project_root <> candidate.project_root
     OR current_project.audit_event_root <> candidate.project_event_root
     OR EXISTS (
       SELECT 1 FROM governance.proof_policy_versions successor
       WHERE successor.supersedes_policy_id = candidate.policy_id
     )
     OR EXISTS (
       SELECT 1 FROM governance.proof_policy_versions current_policy
       JOIN governance.methodology_publications publication
         ON publication.id = candidate.methodology_publication_id
       WHERE current_policy.id = publication.policy_id
         AND EXISTS (
           SELECT 1 FROM governance.proof_policy_versions successor
           WHERE successor.supersedes_policy_id = current_policy.id
         )
     )
     OR EXISTS (
       SELECT 1 FROM governance.methodologies successor_methodology
       JOIN governance.methodology_publications successor_publication
         ON successor_publication.methodology_id = successor_methodology.id
       WHERE successor_methodology.supersedes = candidate.methodology_id
     ) THEN
    RAISE EXCEPTION 'environmental proof record candidate source authority is stale' USING ERRCODE = 'check_violation';
  END IF;
  WITH current_evidence AS (
    SELECT registration.id,
      verification.evidence_final_verification_seed_at(registration.id, terminal.sequence_no) AS final_seed,
      verification.evidence_final_verification_root_at(registration.id, terminal.sequence_no) AS final_root
    FROM evidence.evidence_objects registration
    JOIN LATERAL (
      SELECT max(sequence_no) AS sequence_no
      FROM audit.domain_events WHERE stream_id = registration.id
    ) terminal ON terminal.sequence_no IS NOT NULL
    WHERE registration.id = ANY(candidate.evidence_ids)
  ), eligible AS (
    SELECT source.*, decision.id AS decision_id, decision.decision_root
    FROM current_evidence source
    JOIN verification.evidence_final_decisions decision
      ON decision.id = source.final_seed->>'currentDecisionId'
    WHERE source.final_seed->>'state' = 'verified'
      AND decision.decision = 'verify'
      AND decision.decision_root = source.final_seed->>'currentDecisionRoot'
      AND decision.audit_event_root = source.final_seed->>'terminalEventRoot'
  )
  SELECT COALESCE(array_agg(decision_id ORDER BY decision_id), ARRAY[]::text[]),
    COALESCE(array_agg(decision_root ORDER BY decision_root), ARRAY[]::text[]),
    COALESCE(array_agg(final_root ORDER BY final_root), ARRAY[]::text[])
  INTO expected_decision_ids, expected_decision_roots, expected_final_verification_roots
  FROM eligible;
  IF expected_decision_ids <> candidate.evidence_final_decision_ids
     OR expected_decision_roots <> candidate.evidence_final_decision_roots
     OR expected_final_verification_roots <> candidate.evidence_final_verification_roots THEN
    RAISE EXCEPTION 'environmental proof record final evidence authority is stale' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.issued_at < latest_approval.decided_at
     OR NOT audit.is_sorted_unique_text_array(NEW.governance_approval_ids)
     OR NOT audit.is_sorted_unique_text_array(NEW.governance_approval_roots)
     OR NOT audit.is_sha256_hash_array(NEW.governance_approval_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.limitations)
     OR NOT audit.is_bounded_text_array(NEW.limitations, 1, 1000, 32)
     OR NOT audit.is_sorted_unique_text_array(NEW.source_event_roots)
     OR NOT audit.is_sha256_hash_array(NEW.source_event_roots)
     OR NOT (candidate.audit_event_root = ANY(NEW.source_event_roots))
     OR EXISTS (
       SELECT 1 FROM governance.environmental_proof_candidate_approvals approval
       WHERE approval.candidate_id = NEW.candidate_id
         AND NOT (approval.audit_event_root = ANY(NEW.source_event_roots))
     )
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.source_event_roots) source_root
       LEFT JOIN audit.domain_events source_event
         ON source_event.event_root = source_root
        AND source_event.stream_id = NEW.candidate_id
        AND source_event.sequence_no < NEW.candidate_sequence
       WHERE source_event.id IS NULL
     )
     OR projects.contains_unsafe_claim(ARRAY[NEW.id, NEW.rationale] || NEW.limitations)
     OR NEW.status <> 'issued'
     OR NEW.claim_boundary <> certificates.environmental_proof_safety_canonical() THEN
    RAISE EXCEPTION 'environmental proof record sources, status, or claim boundary are invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence
  FROM audit.domain_events WHERE stream_id = NEW.candidate_id;
  IF semantic_event.stream_id <> NEW.candidate_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.candidate_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.issuer_id
     OR semantic_event.entity_type <> 'environmental_proof_record'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> 'FULFILL'
     OR semantic_event.created_at <> NEW.issued_at
     OR semantic_event.rationale <> NEW.rationale THEN
    RAISE EXCEPTION 'environmental proof record semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.source_root <> certificates.environmental_proof_record_source_root(NEW)
     OR NEW.command_hash <> certificates.environmental_proof_record_command_hash(NEW)
     OR NEW.id <> 'cp_environmental_proof_record_' || left(NEW.command_hash, 24)
     OR NEW.record_hash <> certificates.environmental_proof_record_hash(NEW)
     OR NEW.record_root <> certificates.environmental_proof_record_root(NEW)
     OR semantic_event.payload_hash <> certificates.environmental_proof_record_payload_hash(NEW) THEN
    RAISE EXCEPTION 'environmental proof record canonical lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS environmental_proof_record_facts_validate
  ON certificates.environmental_proof_record_facts;
CREATE TRIGGER environmental_proof_record_facts_validate
BEFORE INSERT ON certificates.environmental_proof_record_facts
FOR EACH ROW EXECUTE FUNCTION certificates.validate_environmental_proof_record_insert();
DROP TRIGGER IF EXISTS environmental_proof_record_facts_no_update
  ON certificates.environmental_proof_record_facts;
CREATE TRIGGER environmental_proof_record_facts_no_update
BEFORE UPDATE ON certificates.environmental_proof_record_facts
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
DROP TRIGGER IF EXISTS environmental_proof_record_facts_no_delete
  ON certificates.environmental_proof_record_facts;
CREATE TRIGGER environmental_proof_record_facts_no_delete
BEFORE DELETE ON certificates.environmental_proof_record_facts
FOR EACH ROW EXECUTE FUNCTION audit.prevent_event_log_update_or_delete();
DROP TRIGGER IF EXISTS environmental_proof_record_facts_audit
  ON certificates.environmental_proof_record_facts;
CREATE TRIGGER environmental_proof_record_facts_audit
AFTER INSERT OR UPDATE OR DELETE ON certificates.environmental_proof_record_facts
FOR EACH ROW EXECUTE FUNCTION audit.capture_row_mutation();

CREATE OR REPLACE FUNCTION certificates.environmental_proof_candidate_is_current(
  target_candidate_id text
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  candidate certificates.environmental_proof_candidates%ROWTYPE;
  publication governance.methodology_publications%ROWTYPE;
  current_project record;
  current_decision_ids text[];
  current_decision_roots text[];
  current_final_verification_roots text[];
BEGIN
  SELECT * INTO STRICT candidate
  FROM certificates.environmental_proof_candidates WHERE id = target_candidate_id;
  SELECT * INTO STRICT publication
  FROM governance.methodology_publications WHERE id = candidate.methodology_publication_id;
  SELECT * INTO STRICT current_project FROM projects.current_authority(candidate.project_id);
  IF current_project.status <> candidate.project_status
     OR current_project.project_root <> candidate.project_root
     OR current_project.audit_event_root <> candidate.project_event_root
     OR EXISTS (
       SELECT 1 FROM governance.proof_policy_versions successor
       WHERE successor.supersedes_policy_id = candidate.policy_id
     )
     OR EXISTS (
       SELECT 1 FROM governance.proof_policy_versions successor
       WHERE successor.supersedes_policy_id = publication.policy_id
     )
     OR EXISTS (
       SELECT 1 FROM governance.methodologies successor_methodology
       JOIN governance.methodology_publications successor_publication
         ON successor_publication.methodology_id = successor_methodology.id
       WHERE successor_methodology.supersedes = candidate.methodology_id
     ) THEN
    RETURN false;
  END IF;
  WITH current_evidence AS (
    SELECT registration.id,
      verification.evidence_final_verification_seed_at(registration.id, terminal.sequence_no) AS final_seed,
      verification.evidence_final_verification_root_at(registration.id, terminal.sequence_no) AS final_root
    FROM evidence.evidence_objects registration
    JOIN LATERAL (
      SELECT max(sequence_no) AS sequence_no
      FROM audit.domain_events WHERE stream_id = registration.id
    ) terminal ON terminal.sequence_no IS NOT NULL
    WHERE registration.id = ANY(candidate.evidence_ids)
  ), eligible AS (
    SELECT source.*, decision.id AS decision_id, decision.decision_root
    FROM current_evidence source
    JOIN verification.evidence_final_decisions decision
      ON decision.id = source.final_seed->>'currentDecisionId'
    WHERE source.final_seed->>'state' = 'verified'
      AND decision.decision = 'verify'
      AND decision.decision_root = source.final_seed->>'currentDecisionRoot'
      AND decision.audit_event_root = source.final_seed->>'terminalEventRoot'
  )
  SELECT COALESCE(array_agg(decision_id ORDER BY decision_id), ARRAY[]::text[]),
    COALESCE(array_agg(decision_root ORDER BY decision_root), ARRAY[]::text[]),
    COALESCE(array_agg(final_root ORDER BY final_root), ARRAY[]::text[])
  INTO current_decision_ids, current_decision_roots, current_final_verification_roots
  FROM eligible;
  RETURN current_decision_ids = candidate.evidence_final_decision_ids
    AND current_decision_roots = candidate.evidence_final_decision_roots
    AND current_final_verification_roots = candidate.evidence_final_verification_roots;
EXCEPTION
  WHEN no_data_found THEN RETURN false;
END;
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_record_projection(
  target_record_id text
)
RETURNS TABLE (
  record_id text,
  record_root text,
  state text,
  source_authority_current boolean,
  authority_root_at_issuance text,
  current_authority_root text,
  projection_root text,
  safety jsonb
)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  record_fact certificates.environmental_proof_record_facts%ROWTYPE;
  authority_current boolean;
  projected_state text;
  projected_authority_root text;
  projected_root text;
BEGIN
  SELECT * INTO STRICT record_fact
  FROM certificates.environmental_proof_record_facts WHERE id = target_record_id;
  authority_current := certificates.environmental_proof_candidate_is_current(record_fact.candidate_id);
  projected_state := CASE WHEN authority_current THEN 'issued' ELSE 'stale' END;
  projected_authority_root := CASE
    WHEN authority_current THEN record_fact.authority_root
    ELSE audit.sha256_stable_json(jsonb_build_object(
      'kind', 'canopyproof-environmental-proof-unavailable-authority-v1'
    ))
  END;
  projected_root := audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-environmental-proof-record-projection-v1',
    'recordId', record_fact.id,
    'recordRoot', record_fact.record_root,
    'state', projected_state,
    'sourceAuthorityCurrent', authority_current,
    'authorityRootAtIssuance', record_fact.authority_root,
    'currentAuthorityRoot', projected_authority_root
  ));
  RETURN QUERY SELECT
    record_fact.id,
    record_fact.record_root,
    projected_state,
    authority_current,
    record_fact.authority_root,
    projected_authority_root,
    projected_root,
    certificates.environmental_proof_safety_canonical();
END;
$$;

-- Environmental Proof challenge authority. These are immutable facts layered
-- over an immutable Environmental Proof Record; no challenge mutates issuance.
CREATE TABLE IF NOT EXISTS certificates.environmental_proof_challenges (
  id text PRIMARY KEY,
  record_id text NOT NULL REFERENCES certificates.environmental_proof_record_facts(id),
  record_root text NOT NULL CHECK (record_root ~ '^[0-9a-f]{64}$'),
  candidate_id text NOT NULL REFERENCES certificates.environmental_proof_candidates(id),
  candidate_root text NOT NULL CHECK (candidate_root ~ '^[0-9a-f]{64}$'),
  authority_root text NOT NULL CHECK (authority_root ~ '^[0-9a-f]{64}$'),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  policy_id text NOT NULL REFERENCES governance.proof_policy_versions(id),
  policy_hash text NOT NULL CHECK (policy_hash ~ '^[0-9a-f]{64}$'),
  policy_root text NOT NULL CHECK (policy_root ~ '^[0-9a-f]{64}$'),
  challenged_record_state text NOT NULL CHECK (challenged_record_state IN ('issued', 'stale')),
  challenged_record_projection_root text NOT NULL CHECK (challenged_record_projection_root ~ '^[0-9a-f]{64}$'),
  challenged_source_authority_current boolean NOT NULL,
  challenged_current_authority_root text NOT NULL CHECK (challenged_current_authority_root ~ '^[0-9a-f]{64}$'),
  prior_challenge_id text REFERENCES certificates.environmental_proof_challenges(id),
  prior_resolution_id text,
  prior_resolution_root text CHECK (prior_resolution_root IS NULL OR prior_resolution_root ~ '^[0-9a-f]{64}$'),
  reason text NOT NULL CHECK (reason IN (
    'evidence_integrity', 'methodology_defect', 'monitoring_contradiction',
    'location_conflict', 'identity_conflict', 'undisclosed_conflict',
    'governance_failure', 'external_observation', 'other'
  )),
  severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 24 AND 4000),
  supporting_artifact_hashes text[] NOT NULL CHECK (cardinality(supporting_artifact_hashes) BETWEEN 1 AND 64),
  source_event_roots text[] NOT NULL CHECK (cardinality(source_event_roots) BETWEEN 1 AND 512),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  challenger_id text NOT NULL REFERENCES identity.participants(id),
  challenger_snapshot jsonb NOT NULL CHECK (jsonb_typeof(challenger_snapshot) = 'object'),
  challenger_organization_id text NOT NULL REFERENCES organizations.organizations(id),
  opened_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  record_sequence bigint NOT NULL CHECK (record_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  challenge_hash text NOT NULL UNIQUE CHECK (challenge_hash ~ '^[0-9a-f]{64}$'),
  challenge_root text NOT NULL UNIQUE CHECK (challenge_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (candidate_id, record_sequence),
  CHECK ((prior_challenge_id IS NULL) = (prior_resolution_id IS NULL)),
  CHECK ((prior_challenge_id IS NULL) = (prior_resolution_root IS NULL))
);

CREATE TABLE IF NOT EXISTS certificates.environmental_proof_challenge_risk_signals (
  id text PRIMARY KEY,
  challenge_id text NOT NULL UNIQUE REFERENCES certificates.environmental_proof_challenges(id),
  challenge_root text NOT NULL CHECK (challenge_root ~ '^[0-9a-f]{64}$'),
  record_id text NOT NULL REFERENCES certificates.environmental_proof_record_facts(id),
  record_root text NOT NULL CHECK (record_root ~ '^[0-9a-f]{64}$'),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  reason text NOT NULL CHECK (reason IN (
    'evidence_integrity', 'methodology_defect', 'monitoring_contradiction',
    'location_conflict', 'identity_conflict', 'undisclosed_conflict',
    'governance_failure', 'external_observation', 'other'
  )),
  risk_level text NOT NULL CHECK (risk_level IN ('low', 'medium', 'high', 'critical')),
  source_event_roots text[] NOT NULL CHECK (cardinality(source_event_roots) BETWEEN 1 AND 512),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  detected_by_id text NOT NULL REFERENCES identity.participants(id),
  detected_by_snapshot jsonb NOT NULL CHECK (jsonb_typeof(detected_by_snapshot) = 'object'),
  detected_at timestamptz NOT NULL,
  record_sequence bigint NOT NULL CHECK (record_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  risk_hash text NOT NULL UNIQUE CHECK (risk_hash ~ '^[0-9a-f]{64}$'),
  risk_root text NOT NULL UNIQUE CHECK (risk_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (record_id, record_sequence)
);

CREATE TABLE IF NOT EXISTS governance.environmental_proof_challenge_reviews (
  id text PRIMARY KEY,
  challenge_id text NOT NULL REFERENCES certificates.environmental_proof_challenges(id),
  challenge_root text NOT NULL CHECK (challenge_root ~ '^[0-9a-f]{64}$'),
  risk_signal_id text NOT NULL REFERENCES certificates.environmental_proof_challenge_risk_signals(id),
  risk_root text NOT NULL CHECK (risk_root ~ '^[0-9a-f]{64}$'),
  record_id text NOT NULL REFERENCES certificates.environmental_proof_record_facts(id),
  record_root text NOT NULL CHECK (record_root ~ '^[0-9a-f]{64}$'),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  policy_id text NOT NULL REFERENCES governance.proof_policy_versions(id),
  policy_hash text NOT NULL CHECK (policy_hash ~ '^[0-9a-f]{64}$'),
  policy_root text NOT NULL CHECK (policy_root ~ '^[0-9a-f]{64}$'),
  prior_review_id text REFERENCES governance.environmental_proof_challenge_reviews(id),
  prior_review_root text CHECK (prior_review_root IS NULL OR prior_review_root ~ '^[0-9a-f]{64}$'),
  decision text NOT NULL CHECK (decision IN ('uphold', 'reject', 'needs_more_evidence')),
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 24 AND 4000),
  conflict_disclosure text NOT NULL CHECK (length(btrim(conflict_disclosure)) BETWEEN 24 AND 2000),
  limitations text[] NOT NULL CHECK (cardinality(limitations) <= 32),
  source_event_roots text[] NOT NULL CHECK (cardinality(source_event_roots) BETWEEN 1 AND 512),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  reviewer_id text NOT NULL REFERENCES identity.participants(id),
  reviewer_snapshot jsonb NOT NULL CHECK (jsonb_typeof(reviewer_snapshot) = 'object'),
  reviewed_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  record_sequence bigint NOT NULL CHECK (record_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  review_hash text NOT NULL UNIQUE CHECK (review_hash ~ '^[0-9a-f]{64}$'),
  review_root text NOT NULL UNIQUE CHECK (review_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (challenge_id, reviewer_id),
  UNIQUE (record_id, record_sequence),
  CHECK ((prior_review_id IS NULL) = (prior_review_root IS NULL))
);

CREATE TABLE IF NOT EXISTS governance.environmental_proof_challenge_resolutions (
  id text PRIMARY KEY,
  challenge_id text NOT NULL UNIQUE REFERENCES certificates.environmental_proof_challenges(id),
  challenge_root text NOT NULL CHECK (challenge_root ~ '^[0-9a-f]{64}$'),
  risk_signal_id text NOT NULL REFERENCES certificates.environmental_proof_challenge_risk_signals(id),
  risk_root text NOT NULL CHECK (risk_root ~ '^[0-9a-f]{64}$'),
  record_id text NOT NULL REFERENCES certificates.environmental_proof_record_facts(id),
  record_root text NOT NULL CHECK (record_root ~ '^[0-9a-f]{64}$'),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  policy_id text NOT NULL REFERENCES governance.proof_policy_versions(id),
  policy_hash text NOT NULL CHECK (policy_hash ~ '^[0-9a-f]{64}$'),
  policy_root text NOT NULL CHECK (policy_root ~ '^[0-9a-f]{64}$'),
  review_ids text[] NOT NULL CHECK (cardinality(review_ids) BETWEEN 2 AND 32),
  review_roots text[] NOT NULL CHECK (cardinality(review_roots) BETWEEN 2 AND 32),
  review_quorum_root text NOT NULL CHECK (review_quorum_root ~ '^[0-9a-f]{64}$'),
  decision text NOT NULL CHECK (decision IN ('uphold', 'reject')),
  rationale text NOT NULL CHECK (length(btrim(rationale)) BETWEEN 24 AND 4000),
  limitations text[] NOT NULL CHECK (cardinality(limitations) <= 32),
  source_event_roots text[] NOT NULL CHECK (cardinality(source_event_roots) BETWEEN 1 AND 512),
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  resolver_id text NOT NULL REFERENCES identity.participants(id),
  resolver_snapshot jsonb NOT NULL CHECK (jsonb_typeof(resolver_snapshot) = 'object'),
  resolved_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  record_sequence bigint NOT NULL CHECK (record_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  resolution_hash text NOT NULL UNIQUE CHECK (resolution_hash ~ '^[0-9a-f]{64}$'),
  resolution_root text NOT NULL UNIQUE CHECK (resolution_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (record_id, record_sequence),
  CHECK (cardinality(review_ids) = cardinality(review_roots))
);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'environmental_proof_challenges_prior_resolution_fk'
      AND conrelid = 'certificates.environmental_proof_challenges'::regclass
  ) THEN
    ALTER TABLE certificates.environmental_proof_challenges
      ADD CONSTRAINT environmental_proof_challenges_prior_resolution_fk
      FOREIGN KEY (prior_resolution_id)
      REFERENCES governance.environmental_proof_challenge_resolutions(id);
  END IF;
END;
$$;

CREATE INDEX IF NOT EXISTS environmental_proof_challenges_record_sequence
  ON certificates.environmental_proof_challenges (record_id, record_sequence DESC, id);
CREATE INDEX IF NOT EXISTS environmental_proof_challenge_reviews_challenge_sequence
  ON governance.environmental_proof_challenge_reviews (challenge_id, record_sequence, id);

CREATE OR REPLACE FUNCTION certificates.environmental_proof_challenge_safety_canonical()
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT jsonb_build_object(
    'environmentalAccountabilityOnly', true,
    'immutableRecordPreserved', true,
    'riskSignalAdvisoryOnly', true,
    'independentHumanGovernanceRequired', true,
    'crossOrganizationStandingGrantsNoDataAccess', true,
    'noRawEvidence', true,
    'notCertifiedCarbonCredit', true,
    'notCarbonTaxOffset', true,
    'notFinancialAsset', true,
    'notGuaranteedYield', true,
    'noMainnetFunds', true,
    'notAutomaticCanopyDistribution', true
  );
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_challenge_command_seed(
  challenge certificates.environmental_proof_challenges
)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT jsonb_build_object(
    'recordId', challenge.record_id,
    'recordRoot', challenge.record_root,
    'candidateId', challenge.candidate_id,
    'candidateRoot', challenge.candidate_root,
    'authorityRoot', challenge.authority_root,
    'organizationId', challenge.organization_id,
    'projectId', challenge.project_id,
    'policyId', challenge.policy_id,
    'policyHash', challenge.policy_hash,
    'policyRoot', challenge.policy_root,
    'challengedRecordState', challenge.challenged_record_state,
    'challengedRecordProjectionRoot', challenge.challenged_record_projection_root,
    'challengedSourceAuthorityCurrent', challenge.challenged_source_authority_current,
    'challengedCurrentAuthorityRoot', challenge.challenged_current_authority_root
  ) || CASE WHEN challenge.prior_challenge_id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object(
    'priorChallengeId', challenge.prior_challenge_id,
    'priorResolutionId', challenge.prior_resolution_id,
    'priorResolutionRoot', challenge.prior_resolution_root
  ) END || jsonb_build_object(
    'reason', challenge.reason,
    'severity', challenge.severity,
    'rationale', challenge.rationale,
    'supportingArtifactHashes', to_jsonb(challenge.supporting_artifact_hashes),
    'sourceEventRoots', to_jsonb(challenge.source_event_roots),
    'challenger', challenge.challenger_snapshot,
    'challengerOrganizationId', challenge.challenger_organization_id,
    'openedAt', audit.iso8601_millis(challenge.opened_at)
  );
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_challenge_command_hash(
  challenge certificates.environmental_proof_challenges
)
RETURNS text LANGUAGE sql IMMUTABLE STRICT AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-environmental-proof-challenge-command-v1') ||
    certificates.environmental_proof_challenge_command_seed(challenge)
  );
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_challenge_source_root(
  challenge certificates.environmental_proof_challenges
)
RETURNS text LANGUAGE sql IMMUTABLE STRICT AS $$
  SELECT audit.merkle_root(ARRAY(
    SELECT leaf FROM (
      SELECT challenge.record_root AS leaf
      UNION ALL SELECT challenge.candidate_root
      UNION ALL SELECT challenge.authority_root
      UNION ALL SELECT challenge.policy_root
      UNION ALL SELECT challenge.challenged_record_projection_root
      UNION ALL SELECT challenge.challenged_current_authority_root
      UNION ALL SELECT unnest(challenge.supporting_artifact_hashes)
      UNION ALL SELECT unnest(challenge.source_event_roots)
      UNION ALL SELECT challenge.prior_resolution_root WHERE challenge.prior_resolution_root IS NOT NULL
    ) leaves ORDER BY leaf
  ));
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_challenge_hash(
  challenge certificates.environmental_proof_challenges
)
RETURNS text LANGUAGE sql IMMUTABLE STRICT AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-environmental-proof-challenge-v1') ||
    jsonb_build_object('id', challenge.id) ||
    certificates.environmental_proof_challenge_command_seed(challenge) ||
    jsonb_build_object(
      'commandHash', challenge.command_hash,
      'sourceRoot', challenge.source_root,
      'recordSequence', challenge.record_sequence,
