CREATE OR REPLACE FUNCTION certificates.validate_environmental_proof_challenge_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  record_fact certificates.environmental_proof_record_facts%ROWTYPE;
  candidate certificates.environmental_proof_candidates%ROWTYPE;
  latest_challenge certificates.environmental_proof_challenges%ROWTYPE;
  prior_resolution governance.environmental_proof_challenge_resolutions%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  base_projection record;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.challenger_id THEN
    RAISE EXCEPTION 'environmental proof challenge requires matching app.actor_id' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT record_fact
  FROM certificates.environmental_proof_record_facts WHERE id = NEW.record_id FOR SHARE;
  SELECT * INTO STRICT candidate
  FROM certificates.environmental_proof_candidates WHERE id = record_fact.candidate_id FOR SHARE;
  SELECT * INTO STRICT base_projection
  FROM certificates.environmental_proof_record_projection(NEW.record_id);
  IF NEW.record_root <> record_fact.record_root
     OR NEW.candidate_id <> record_fact.candidate_id
     OR NEW.candidate_root <> candidate.candidate_root
     OR NEW.authority_root <> record_fact.authority_root
     OR NEW.organization_id <> record_fact.organization_id
     OR NEW.project_id <> record_fact.project_id
     OR NEW.policy_id <> candidate.policy_id
     OR NEW.policy_hash <> candidate.policy_hash
     OR NEW.policy_root <> candidate.policy_root
     OR NEW.challenged_record_state <> base_projection.state
     OR NEW.challenged_record_projection_root <> base_projection.projection_root
     OR NEW.challenged_source_authority_current <> base_projection.source_authority_current
     OR NEW.challenged_current_authority_root <> base_projection.current_authority_root THEN
    RAISE EXCEPTION 'environmental proof challenge record authority is stale or inconsistent' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT verification.actor_snapshot_is_valid(
    NEW.challenger_snapshot, NEW.challenger_id, NEW.challenger_organization_id,
    'human', ARRAY['owner', 'admin', 'verifier', 'researcher']::text[]
  ) THEN
    RAISE EXCEPTION 'environmental proof challenge requires verified active human standing' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO latest_challenge
  FROM certificates.environmental_proof_challenges
  WHERE record_id = NEW.record_id
  ORDER BY record_sequence DESC, id DESC LIMIT 1 FOR SHARE;
  IF latest_challenge.id IS NULL THEN
    IF NEW.prior_challenge_id IS NOT NULL OR NEW.prior_resolution_id IS NOT NULL OR NEW.prior_resolution_root IS NOT NULL THEN
      RAISE EXCEPTION 'first environmental proof challenge predecessor is invalid' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    SELECT * INTO prior_resolution
    FROM governance.environmental_proof_challenge_resolutions
    WHERE challenge_id = latest_challenge.id FOR SHARE;
    IF prior_resolution.id IS NULL THEN
      RAISE EXCEPTION 'environmental proof record already has an unresolved challenge' USING ERRCODE = 'check_violation';
    END IF;
    IF prior_resolution.decision = 'uphold' THEN
      RAISE EXCEPTION 'revoked environmental proof record cannot accept another challenge' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.prior_challenge_id <> latest_challenge.id
       OR NEW.prior_resolution_id <> prior_resolution.id
       OR NEW.prior_resolution_root <> prior_resolution.resolution_root
       OR NOT (prior_resolution.audit_event_root = ANY(NEW.source_event_roots)) THEN
      RAISE EXCEPTION 'environmental proof successor challenge predecessor is invalid' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NOT audit.is_sorted_unique_text_array(NEW.supporting_artifact_hashes)
     OR NOT audit.is_sha256_hash_array(NEW.supporting_artifact_hashes)
     OR NOT audit.is_sorted_unique_text_array(NEW.source_event_roots)
     OR NOT audit.is_sha256_hash_array(NEW.source_event_roots)
     OR NOT (record_fact.audit_event_root = ANY(NEW.source_event_roots))
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.source_event_roots) root
       LEFT JOIN audit.domain_events source_event
         ON source_event.event_root = root
        AND source_event.stream_id = NEW.candidate_id
        AND source_event.sequence_no < NEW.record_sequence
       WHERE source_event.id IS NULL
     )
     OR projects.contains_unsafe_claim(ARRAY[NEW.id, NEW.rationale])
     OR NEW.safety <> certificates.environmental_proof_challenge_safety_canonical() THEN
    RAISE EXCEPTION 'environmental proof challenge sources or safety are invalid' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence
  FROM audit.domain_events WHERE stream_id = NEW.candidate_id;
  IF semantic_event.stream_id <> NEW.candidate_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.record_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.challenger_id
     OR semantic_event.entity_type <> 'environmental_proof_challenge'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> 'CHALLENGE'
     OR semantic_event.created_at <> NEW.opened_at
     OR semantic_event.rationale <> NEW.rationale THEN
    RAISE EXCEPTION 'environmental proof challenge semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.opened_at < COALESCE((
       SELECT max(created_at) FROM audit.domain_events
       WHERE stream_id = NEW.candidate_id AND sequence_no < NEW.record_sequence
     ), NEW.opened_at)
     OR NEW.source_root <> certificates.environmental_proof_challenge_source_root(NEW)
     OR NEW.command_hash <> certificates.environmental_proof_challenge_command_hash(NEW)
     OR NEW.id <> 'cp_environmental_proof_challenge_' || left(NEW.command_hash, 24)
     OR NEW.challenge_hash <> certificates.environmental_proof_challenge_hash(NEW)
     OR NEW.challenge_root <> certificates.environmental_proof_challenge_root(NEW)
     OR semantic_event.payload_hash <> certificates.environmental_proof_challenge_payload_hash(NEW) THEN
    RAISE EXCEPTION 'environmental proof challenge canonical lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION certificates.validate_environmental_proof_challenge_risk_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  challenge certificates.environmental_proof_challenges%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  SELECT * INTO STRICT challenge
  FROM certificates.environmental_proof_challenges WHERE id = NEW.challenge_id FOR SHARE;
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.detected_by_id
     OR NEW.challenge_root <> challenge.challenge_root
     OR NEW.record_id <> challenge.record_id
     OR NEW.record_root <> challenge.record_root
     OR NEW.organization_id <> challenge.organization_id
     OR NEW.project_id <> challenge.project_id
     OR NEW.reason <> challenge.reason
     OR NEW.risk_level <> challenge.severity
     OR NEW.detected_by_id <> challenge.challenger_id
     OR NEW.detected_by_snapshot <> challenge.challenger_snapshot
     OR NEW.detected_at <> challenge.opened_at
     OR NEW.record_sequence <> challenge.record_sequence + 1
     OR NEW.previous_event_root <> challenge.audit_event_root
     OR NEW.source_event_roots <> ARRAY[challenge.audit_event_root]::text[]
     OR NEW.safety <> certificates.environmental_proof_challenge_safety_canonical() THEN
    RAISE EXCEPTION 'environmental proof challenge risk authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence
  FROM audit.domain_events WHERE stream_id = challenge.candidate_id;
  IF semantic_event.stream_id <> challenge.candidate_id
     OR semantic_event.sequence_no <> latest_sequence
     OR semantic_event.sequence_no <> NEW.record_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.detected_by_id
     OR semantic_event.entity_type <> 'environmental_proof_challenge_risk'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> 'ASSERT'
     OR semantic_event.created_at <> NEW.detected_at
     OR semantic_event.rationale <> 'A deterministic operational risk signal was emitted for the Environmental Proof challenge.' THEN
    RAISE EXCEPTION 'environmental proof challenge risk semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.source_root <> certificates.environmental_proof_challenge_risk_source_root(NEW)
     OR NEW.risk_hash <> certificates.environmental_proof_challenge_risk_hash(NEW)
     OR NEW.id <> 'cp_environmental_proof_challenge_risk_' || left(NEW.risk_hash, 24)
     OR NEW.risk_root <> certificates.environmental_proof_challenge_risk_root(NEW)
     OR semantic_event.payload_hash <> certificates.environmental_proof_challenge_risk_payload_hash(NEW) THEN
    RAISE EXCEPTION 'environmental proof challenge risk canonical lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION governance.validate_environmental_proof_challenge_review_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  challenge certificates.environmental_proof_challenges%ROWTYPE;
  risk certificates.environmental_proof_challenge_risk_signals%ROWTYPE;
  record_fact certificates.environmental_proof_record_facts%ROWTYPE;
  candidate certificates.environmental_proof_candidates%ROWTYPE;
  prior_review governance.environmental_proof_challenge_reviews%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  SELECT * INTO STRICT challenge FROM certificates.environmental_proof_challenges WHERE id = NEW.challenge_id FOR SHARE;
  SELECT * INTO STRICT risk FROM certificates.environmental_proof_challenge_risk_signals WHERE challenge_id = NEW.challenge_id FOR SHARE;
  SELECT * INTO STRICT record_fact FROM certificates.environmental_proof_record_facts WHERE id = challenge.record_id FOR SHARE;
  SELECT * INTO STRICT candidate FROM certificates.environmental_proof_candidates WHERE id = challenge.candidate_id FOR SHARE;
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.reviewer_id
     OR NEW.challenge_root <> challenge.challenge_root
     OR NEW.risk_signal_id <> risk.id OR NEW.risk_root <> risk.risk_root
     OR NEW.record_id <> record_fact.id OR NEW.record_root <> record_fact.record_root
     OR NEW.organization_id <> record_fact.organization_id OR NEW.project_id <> record_fact.project_id
     OR NEW.policy_id <> challenge.policy_id OR NEW.policy_hash <> challenge.policy_hash
     OR NEW.policy_root <> challenge.policy_root
     OR EXISTS (SELECT 1 FROM governance.environmental_proof_challenge_resolutions WHERE challenge_id = NEW.challenge_id)
     OR NOT verification.actor_snapshot_is_valid(
       NEW.reviewer_snapshot, NEW.reviewer_id, NEW.organization_id,
       'human', candidate.allowed_reviewer_roles
     )
     OR (NEW.reviewer_snapshot->>'role' = 'verifier' AND NEW.reviewer_snapshot->>'accreditationStatus' <> 'approved') THEN
    RAISE EXCEPTION 'environmental proof challenge reviewer authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reviewer_id IN (challenge.challenger_id, record_fact.issuer_id, candidate.derived_by_id)
     OR NEW.reviewer_id = ANY(candidate.source_actor_ids)
     OR EXISTS (
       SELECT 1 FROM governance.environmental_proof_candidate_approvals approval
       WHERE approval.candidate_id = candidate.id AND approval.approver_id = NEW.reviewer_id
     )
     OR EXISTS (
       SELECT 1 FROM governance.environmental_proof_challenge_reviews existing
       WHERE existing.challenge_id = NEW.challenge_id AND existing.reviewer_id = NEW.reviewer_id
     ) THEN
    RAISE EXCEPTION 'environmental proof challenge review requires an independent human reviewer' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO prior_review
  FROM governance.environmental_proof_challenge_reviews
  WHERE challenge_id = NEW.challenge_id
  ORDER BY record_sequence DESC, id DESC LIMIT 1 FOR SHARE;
  IF prior_review.id IS NULL THEN
    IF NEW.prior_review_id IS NOT NULL OR NEW.prior_review_root IS NOT NULL THEN
      RAISE EXCEPTION 'first environmental proof challenge review predecessor is invalid' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.prior_review_id <> prior_review.id OR NEW.prior_review_root <> prior_review.review_root THEN
    RAISE EXCEPTION 'environmental proof challenge review predecessor is missing or forked' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT audit.is_sorted_unique_text_array(NEW.limitations)
     OR NOT audit.is_bounded_text_array(NEW.limitations, 1, 1000, 32)
     OR NOT audit.is_sorted_unique_text_array(NEW.source_event_roots)
     OR NOT audit.is_sha256_hash_array(NEW.source_event_roots)
     OR NOT (challenge.audit_event_root = ANY(NEW.source_event_roots))
     OR NOT (risk.audit_event_root = ANY(NEW.source_event_roots))
     OR (prior_review.id IS NOT NULL AND NOT (prior_review.audit_event_root = ANY(NEW.source_event_roots)))
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.source_event_roots) root
       LEFT JOIN audit.domain_events source_event
         ON source_event.event_root = root
        AND source_event.stream_id = challenge.candidate_id
        AND source_event.sequence_no < NEW.record_sequence
       WHERE source_event.id IS NULL
     )
     OR projects.contains_unsafe_claim(ARRAY[NEW.id, NEW.rationale, NEW.conflict_disclosure] || NEW.limitations)
     OR NEW.safety <> certificates.environmental_proof_challenge_safety_canonical() THEN
    RAISE EXCEPTION 'environmental proof challenge review sources or safety are invalid' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence FROM audit.domain_events WHERE stream_id = challenge.candidate_id;
  IF semantic_event.stream_id <> challenge.candidate_id
     OR semantic_event.sequence_no <> latest_sequence OR semantic_event.sequence_no <> NEW.record_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.reviewer_id
     OR semantic_event.entity_type <> 'environmental_proof_challenge_review'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> (CASE WHEN NEW.decision = 'uphold' THEN 'CHALLENGE' ELSE 'REASON' END)
     OR semantic_event.created_at <> NEW.reviewed_at OR semantic_event.rationale <> NEW.rationale THEN
    RAISE EXCEPTION 'environmental proof challenge review semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reviewed_at < COALESCE((
       SELECT max(created_at) FROM audit.domain_events
       WHERE stream_id = challenge.candidate_id AND sequence_no < NEW.record_sequence
     ), NEW.reviewed_at)
     OR NEW.source_root <> governance.environmental_proof_challenge_review_source_root(NEW)
     OR NEW.command_hash <> governance.environmental_proof_challenge_review_command_hash(NEW)
     OR NEW.id <> 'cp_environmental_proof_challenge_review_' || left(NEW.command_hash, 24)
     OR NEW.review_hash <> governance.environmental_proof_challenge_review_hash(NEW)
     OR NEW.review_root <> governance.environmental_proof_challenge_review_root(NEW)
     OR semantic_event.payload_hash <> governance.environmental_proof_challenge_review_payload_hash(NEW) THEN
    RAISE EXCEPTION 'environmental proof challenge review canonical lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION governance.validate_environmental_proof_challenge_resolution_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  challenge certificates.environmental_proof_challenges%ROWTYPE;
  risk certificates.environmental_proof_challenge_risk_signals%ROWTYPE;
  record_fact certificates.environmental_proof_record_facts%ROWTYPE;
  candidate certificates.environmental_proof_candidates%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  expected_review_ids text[];
  expected_review_roots text[];
  review_count integer;
  latest_sequence bigint;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  SELECT * INTO STRICT challenge FROM certificates.environmental_proof_challenges WHERE id = NEW.challenge_id FOR SHARE;
  SELECT * INTO STRICT risk FROM certificates.environmental_proof_challenge_risk_signals WHERE challenge_id = NEW.challenge_id FOR SHARE;
  SELECT * INTO STRICT record_fact FROM certificates.environmental_proof_record_facts WHERE id = challenge.record_id FOR SHARE;
  SELECT * INTO STRICT candidate FROM certificates.environmental_proof_candidates WHERE id = challenge.candidate_id FOR SHARE;
  IF transaction_actor_id IS NULL OR transaction_actor_id <> NEW.resolver_id
     OR NEW.challenge_root <> challenge.challenge_root
     OR NEW.risk_signal_id <> risk.id OR NEW.risk_root <> risk.risk_root
     OR NEW.record_id <> record_fact.id OR NEW.record_root <> record_fact.record_root
     OR NEW.organization_id <> record_fact.organization_id OR NEW.project_id <> record_fact.project_id
     OR NEW.policy_id <> challenge.policy_id OR NEW.policy_hash <> challenge.policy_hash
     OR NEW.policy_root <> challenge.policy_root
     OR NOT verification.actor_snapshot_is_valid(
       NEW.resolver_snapshot, NEW.resolver_id, NEW.organization_id,
       'human', ARRAY['owner', 'admin']::text[]
     ) THEN
    RAISE EXCEPTION 'environmental proof challenge resolver authority is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.resolver_id IN (challenge.challenger_id, record_fact.issuer_id, candidate.derived_by_id)
     OR NEW.resolver_id = ANY(candidate.source_actor_ids)
     OR EXISTS (
       SELECT 1 FROM governance.environmental_proof_candidate_approvals approval
       WHERE approval.candidate_id = candidate.id AND approval.approver_id = NEW.resolver_id
     )
     OR EXISTS (
       SELECT 1 FROM governance.environmental_proof_challenge_reviews review
       WHERE review.challenge_id = NEW.challenge_id AND review.reviewer_id = NEW.resolver_id
     ) THEN
    RAISE EXCEPTION 'environmental proof challenge resolution requires an independent human resolver' USING ERRCODE = 'check_violation';
  END IF;
  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::text[]),
    COALESCE(array_agg(review_root ORDER BY review_root), ARRAY[]::text[]), count(*)::integer
  INTO expected_review_ids, expected_review_roots, review_count
  FROM governance.environmental_proof_challenge_reviews WHERE challenge_id = NEW.challenge_id;
  IF NEW.review_ids <> expected_review_ids
     OR NEW.review_roots <> expected_review_roots
     OR NEW.review_quorum_root <> audit.merkle_root(expected_review_roots)
     OR review_count < candidate.required_approvals
     OR EXISTS (
       SELECT 1 FROM governance.environmental_proof_challenge_reviews review
       WHERE review.challenge_id = NEW.challenge_id AND review.decision <> NEW.decision
     )
     OR NOT EXISTS (
       SELECT 1 FROM governance.environmental_proof_challenge_reviews review
       WHERE review.challenge_id = NEW.challenge_id AND review.reviewer_snapshot->>'role' = 'verifier'
     )
     OR NOT EXISTS (
       SELECT 1 FROM governance.environmental_proof_challenge_reviews review
       WHERE review.challenge_id = NEW.challenge_id AND review.reviewer_snapshot->>'role' IN ('owner', 'admin')
     ) THEN
    RAISE EXCEPTION 'environmental proof challenge review quorum is incomplete, mixed, or non-terminal' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT audit.is_sorted_unique_text_array(NEW.review_ids)
     OR NOT audit.is_sorted_unique_text_array(NEW.review_roots)
     OR NOT audit.is_sha256_hash_array(NEW.review_roots)
     OR NOT audit.is_sorted_unique_text_array(NEW.limitations)
     OR NOT audit.is_bounded_text_array(NEW.limitations, 1, 1000, 32)
     OR NOT audit.is_sorted_unique_text_array(NEW.source_event_roots)
     OR NOT audit.is_sha256_hash_array(NEW.source_event_roots)
     OR NOT (challenge.audit_event_root = ANY(NEW.source_event_roots))
     OR NOT (risk.audit_event_root = ANY(NEW.source_event_roots))
     OR EXISTS (
       SELECT 1 FROM governance.environmental_proof_challenge_reviews review
       WHERE review.challenge_id = NEW.challenge_id AND NOT (review.audit_event_root = ANY(NEW.source_event_roots))
     )
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.source_event_roots) root
       LEFT JOIN audit.domain_events source_event
         ON source_event.event_root = root
        AND source_event.stream_id = challenge.candidate_id
        AND source_event.sequence_no < NEW.record_sequence
       WHERE source_event.id IS NULL
     )
     OR projects.contains_unsafe_claim(ARRAY[NEW.id, NEW.rationale] || NEW.limitations)
     OR NEW.safety <> certificates.environmental_proof_challenge_safety_canonical() THEN
    RAISE EXCEPTION 'environmental proof challenge resolution sources or safety are invalid' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  SELECT max(sequence_no) INTO latest_sequence FROM audit.domain_events WHERE stream_id = challenge.candidate_id;
  IF semantic_event.stream_id <> challenge.candidate_id
     OR semantic_event.sequence_no <> latest_sequence OR semantic_event.sequence_no <> NEW.record_sequence
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.actor_id <> NEW.resolver_id
     OR semantic_event.entity_type <> 'environmental_proof_challenge_resolution'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.action <> (CASE WHEN NEW.decision = 'uphold' THEN 'CHALLENGE' ELSE 'FULFILL' END)
     OR semantic_event.created_at <> NEW.resolved_at OR semantic_event.rationale <> NEW.rationale THEN
    RAISE EXCEPTION 'environmental proof challenge resolution semantic event binding is invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.resolved_at < COALESCE((
       SELECT max(created_at) FROM audit.domain_events
       WHERE stream_id = challenge.candidate_id AND sequence_no < NEW.record_sequence
     ), NEW.resolved_at)
     OR NEW.source_root <> governance.environmental_proof_challenge_resolution_source_root(NEW)
     OR NEW.command_hash <> governance.environmental_proof_challenge_resolution_command_hash(NEW)
     OR NEW.id <> 'cp_environmental_proof_challenge_resolution_' || left(NEW.command_hash, 24)
     OR NEW.resolution_hash <> governance.environmental_proof_challenge_resolution_hash(NEW)
     OR NEW.resolution_root <> governance.environmental_proof_challenge_resolution_root(NEW)
     OR semantic_event.payload_hash <> governance.environmental_proof_challenge_resolution_payload_hash(NEW) THEN
    RAISE EXCEPTION 'environmental proof challenge resolution canonical lineage is invalid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

