CREATE OR REPLACE FUNCTION certificates.environmental_proof_challenge_projection(target_challenge_id text)
RETURNS TABLE (
  challenge_id text,
  challenge_root text,
  record_id text,
  record_root text,
  state text,
  review_count integer,
  resolution_id text,
  resolution_root text,
  projection_root text,
  safety jsonb
)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  challenge certificates.environmental_proof_challenges%ROWTYPE;
  resolution governance.environmental_proof_challenge_resolutions%ROWTYPE;
  projected_state text;
  projected_review_count integer;
  projected_root text;
BEGIN
  SELECT challenge_fact.* INTO STRICT challenge
  FROM certificates.environmental_proof_challenges challenge_fact
  WHERE challenge_fact.id = target_challenge_id;
  SELECT resolution_fact.* INTO resolution
  FROM governance.environmental_proof_challenge_resolutions resolution_fact
  WHERE resolution_fact.challenge_id = challenge.id;
  SELECT count(*)::integer INTO projected_review_count
  FROM governance.environmental_proof_challenge_reviews review_fact
  WHERE review_fact.challenge_id = challenge.id;
  projected_state := CASE
    WHEN resolution.id IS NOT NULL AND resolution.decision = 'uphold' THEN 'resolved'
    WHEN resolution.id IS NOT NULL AND resolution.decision = 'reject' THEN 'rejected'
    WHEN projected_review_count > 0 THEN 'under_review'
    ELSE 'open'
  END;
  projected_root := audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-environmental-proof-challenge-projection-v1',
    'challengeId', challenge.id,
    'challengeRoot', challenge.challenge_root,
    'recordId', challenge.record_id,
    'recordRoot', challenge.record_root,
    'state', projected_state,
    'reviewCount', projected_review_count,
    'resolutionId', resolution.id,
    'resolutionRoot', resolution.resolution_root
  ));
  RETURN QUERY SELECT challenge.id, challenge.challenge_root, challenge.record_id,
    challenge.record_root, projected_state, projected_review_count, resolution.id,
    resolution.resolution_root, projected_root,
    certificates.environmental_proof_challenge_safety_canonical();
END;
$$;

CREATE OR REPLACE FUNCTION certificates.environmental_proof_governed_record_projection(target_record_id text)
RETURNS TABLE (
  record_id text,
  record_root text,
  state text,
  base_state text,
  source_authority_current boolean,
  challenge_state text,
  challenge_id text,
  challenge_root text,
  resolution_id text,
  resolution_root text,
  projection_root text,
  safety jsonb
)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  base record;
  latest_challenge certificates.environmental_proof_challenges%ROWTYPE;
  challenge_state_value text;
  challenge_id_value text;
  challenge_root_value text;
  resolution_id_value text;
  resolution_root_value text;
  projected_state text;
  projected_root text;
BEGIN
  SELECT * INTO STRICT base FROM certificates.environmental_proof_record_projection(target_record_id);
  SELECT challenge_fact.* INTO latest_challenge
  FROM certificates.environmental_proof_challenges challenge_fact
  WHERE challenge_fact.record_id = target_record_id
  ORDER BY challenge_fact.record_sequence DESC, challenge_fact.id DESC LIMIT 1;
  IF latest_challenge.id IS NOT NULL THEN
    SELECT projection.state, projection.challenge_id, projection.challenge_root,
      projection.resolution_id, projection.resolution_root
    INTO STRICT challenge_state_value, challenge_id_value, challenge_root_value,
      resolution_id_value, resolution_root_value
    FROM certificates.environmental_proof_challenge_projection(latest_challenge.id) AS projection;
  END IF;
  projected_state := CASE
    WHEN latest_challenge.id IS NULL THEN base.state
    WHEN challenge_state_value = 'resolved' THEN 'revoked'
    WHEN challenge_state_value = 'rejected' THEN base.state
    ELSE 'challenged'
  END;
  projected_root := audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-environmental-proof-challenged-record-projection-v1',
    'recordId', base.record_id,
    'recordRoot', base.record_root,
    'state', projected_state,
    'baseState', base.state,
    'sourceAuthorityCurrent', base.source_authority_current,
    'challengeState', challenge_state_value,
    'challengeId', challenge_id_value,
    'challengeRoot', challenge_root_value,
    'resolutionId', resolution_id_value,
    'resolutionRoot', resolution_root_value
  ));
  RETURN QUERY SELECT base.record_id, base.record_root, projected_state, base.state,
    base.source_authority_current, challenge_state_value,
    challenge_id_value, challenge_root_value,
    resolution_id_value, resolution_root_value,
    projected_root, certificates.environmental_proof_challenge_safety_canonical();
END;
$$;

CREATE OR REPLACE FUNCTION evidence.evidence_custody_safety_canonical()
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT jsonb_build_object(
    'appendOnly', true,
    'subjectBound', true,
    'organizationBound', true,
    'semanticEventBound', true,
    'noRawDeviceIdentifier', true,
    'noRawProviderCredential', true,
    'providerVerificationRequiredForHardwareTrust', true,
    'notFinalProofAuthority', true,
    'notCertifiedCarbonCredit', true,
    'notCarbonTaxOffset', true,
    'notFinancialAsset', true,
    'notGuaranteedYield', true,
    'noMainnetFunds', true,
    'notAutomaticCanopyDistribution', true
  );
$$;

CREATE OR REPLACE FUNCTION evidence.evidence_custody_actor_authority_root(actor_snapshot jsonb)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-evidence-custody-actor-authority-v2') ||
    (actor_snapshot - 'authorityRoot')
  );
$$;

CREATE OR REPLACE FUNCTION evidence.evidence_custody_actor_is_valid(
  actor_snapshot jsonb,
  expected_subject_id text,
  expected_organization_id text
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  participant identity.participants%ROWTYPE;
  organization organizations.organizations%ROWTYPE;
  membership organizations.memberships%ROWTYPE;
BEGIN
  IF jsonb_typeof(actor_snapshot) <> 'object'
     OR actor_snapshot->>'id' <> expected_subject_id
     OR actor_snapshot->>'participantType' <> 'human'
     OR actor_snapshot->>'role' NOT IN ('owner', 'admin', 'verifier', 'researcher', 'community')
     OR actor_snapshot->>'verificationStatus' <> 'verified'
     OR actor_snapshot->>'organizationId' <> expected_organization_id
     OR actor_snapshot->>'organizationVerificationStatus' <> 'verified'
     OR actor_snapshot->>'participantRoot' !~ '^[0-9a-f]{64}$'
     OR actor_snapshot->>'organizationRoot' !~ '^[0-9a-f]{64}$'
     OR actor_snapshot->>'membershipStatus' <> 'active'
     OR actor_snapshot->>'membershipRoot' !~ '^[0-9a-f]{64}$'
     OR actor_snapshot->>'authorityRoot' <> evidence.evidence_custody_actor_authority_root(actor_snapshot) THEN
    RETURN false;
  END IF;
  SELECT * INTO participant FROM identity.participants WHERE id = expected_subject_id;
  SELECT * INTO organization FROM organizations.organizations WHERE id = expected_organization_id;
  SELECT * INTO membership FROM organizations.memberships WHERE id = actor_snapshot->>'membershipId';
  RETURN participant.id IS NOT NULL
    AND participant.participant_type = 'human'
    AND participant.verification_status = 'verified'
    AND participant.subject_hash = actor_snapshot->>'participantRoot'
    AND actor_snapshot->>'role' = ANY(participant.roles)
    AND organization.id IS NOT NULL
    AND organization.verification_status = 'verified'
    AND organization.profile_hash = actor_snapshot->>'organizationRoot'
    AND membership.id IS NOT NULL
    AND membership.organization_id = expected_organization_id
    AND membership.actor_id = expected_subject_id
    AND membership.role = actor_snapshot->>'role'
    AND membership.status = 'active'
    AND membership.audit_event_root = actor_snapshot->>'membershipRoot';
END;
$$;

CREATE OR REPLACE FUNCTION evidence.consent_receipt_command_seed(receipt evidence.consent_receipts)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT jsonb_strip_nulls(jsonb_build_object(
    'organizationId', receipt.organization_id,
    'subjectRoot', receipt.subject_root,
    'subjectAuthorityRoot', receipt.subject_authority_root,
    'subjectId', receipt.subject_id,
    'deviceFingerprintHash', receipt.device_fingerprint_hash,
    'purposes', to_jsonb(receipt.purposes),
    'lawfulBasis', receipt.lawful_basis,
    'privacyMode', receipt.privacy_mode,
    'policyVersion', receipt.policy_version,
    'evidenceHash', receipt.evidence_hash,
    'grantedAt', audit.iso8601_millis(receipt.granted_at),
    'expiresAt', CASE WHEN receipt.expires_at IS NULL THEN NULL ELSE audit.iso8601_millis(receipt.expires_at) END,
    'retentionDays', receipt.retention_days
  ));
$$;

CREATE OR REPLACE FUNCTION evidence.consent_receipt_command_hash(receipt evidence.consent_receipts)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-evidence-consent-receipt-command-v2') ||
    evidence.consent_receipt_command_seed(receipt)
  );
$$;

CREATE OR REPLACE FUNCTION evidence.consent_receipt_fact_seed(receipt evidence.consent_receipts)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT jsonb_build_object(
    'id', receipt.id,
    'organizationId', receipt.organization_id,
    'subjectRoot', receipt.subject_root,
    'subjectAuthorityRoot', receipt.subject_authority_root
  ) ||
  (evidence.consent_receipt_command_seed(receipt) - 'organizationId' - 'subjectRoot' - 'subjectAuthorityRoot') ||
  jsonb_build_object(
    'actor', receipt.actor_snapshot,
    'commandHash', receipt.command_hash,
    'subjectSequence', receipt.subject_sequence,
    'previousEventRoot', receipt.previous_event_root
  );
$$;

