CREATE OR REPLACE FUNCTION evidence.validate_consent_receipt_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  semantic_event audit.domain_events%ROWTYPE;
BEGIN
  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  IF NEW.subject_id <> NEW.created_by
     OR NEW.revoked_at IS NOT NULL
     OR NEW.revocation_reason IS NOT NULL
     OR NOT audit.is_sorted_unique_text_array(NEW.purposes)
     OR NEW.subject_root <> NEW.actor_snapshot->>'participantRoot'
     OR NEW.subject_authority_root <> NEW.actor_snapshot->>'authorityRoot'
     OR NOT evidence.evidence_custody_actor_is_valid(NEW.actor_snapshot, NEW.subject_id, NEW.organization_id)
     OR NEW.safety <> evidence.evidence_custody_safety_canonical() THEN
    RAISE EXCEPTION 'evidence consent receipt authority is invalid';
  END IF;
  IF semantic_event.stream_id <> 'evidence-custody:' || NEW.subject_id
     OR semantic_event.sequence_no <> NEW.subject_sequence
     OR semantic_event.action <> 'ASSERT'
     OR semantic_event.actor_id <> NEW.subject_id
     OR semantic_event.entity_type <> 'consent_receipt'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.created_at <> NEW.granted_at
     OR semantic_event.payload_hash <> evidence.consent_receipt_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence consent receipt semantic event binding is invalid';
  END IF;
  IF NEW.command_hash <> evidence.consent_receipt_command_hash(NEW)
     OR NEW.id <> 'cp_evidence_consent_' || left(NEW.command_hash, 24)
     OR NEW.receipt_hash <> evidence.consent_receipt_hash(NEW)
     OR NEW.receipt_root <> evidence.consent_receipt_root(NEW) THEN
    RAISE EXCEPTION 'evidence consent receipt hash lineage is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION evidence.validate_consent_revocation_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  receipt evidence.consent_receipts%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
BEGIN
  SELECT * INTO STRICT receipt FROM evidence.consent_receipts WHERE id = NEW.receipt_id FOR SHARE;
  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  IF NEW.receipt_root <> receipt.receipt_root
     OR NEW.organization_id <> receipt.organization_id
     OR NEW.subject_id <> receipt.subject_id
     OR NEW.subject_root <> receipt.subject_root
     OR NEW.revoked_by <> NEW.subject_id
     OR NEW.revoked_at < receipt.granted_at
     OR NOT evidence.evidence_custody_actor_is_valid(NEW.actor_snapshot, NEW.subject_id, NEW.organization_id)
     OR NEW.safety <> evidence.evidence_custody_safety_canonical() THEN
    RAISE EXCEPTION 'evidence consent revocation authority is invalid';
  END IF;
  IF semantic_event.stream_id <> 'evidence-custody:' || NEW.subject_id
     OR semantic_event.sequence_no <> NEW.subject_sequence
     OR semantic_event.action <> 'CHALLENGE'
     OR semantic_event.actor_id <> NEW.subject_id
     OR semantic_event.entity_type <> 'consent_revocation'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.created_at <> NEW.revoked_at
     OR semantic_event.payload_hash <> evidence.consent_revocation_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence consent revocation semantic event binding is invalid';
  END IF;
  IF NEW.command_hash <> evidence.consent_revocation_command_hash(NEW)
     OR NEW.id <> 'cp_evidence_consent_revocation_' || left(NEW.command_hash, 24)
     OR NEW.revocation_hash <> evidence.consent_revocation_hash(NEW)
     OR NEW.revocation_root <> evidence.consent_revocation_root(NEW) THEN
    RAISE EXCEPTION 'evidence consent revocation hash lineage is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION evidence.validate_device_attestation_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  receipt evidence.consent_receipts%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  expected_action text;
BEGIN
  SELECT * INTO STRICT receipt FROM evidence.consent_receipts WHERE id = NEW.consent_receipt_id FOR SHARE;
  SELECT * INTO STRICT semantic_event FROM audit.domain_events WHERE event_root = NEW.audit_event_root;
  expected_action := CASE
    WHEN NEW.provider_verification_state <> 'verified' OR cardinality(NEW.risk_flags) > 0 THEN 'CHALLENGE'
    ELSE 'ASSERT'
  END;
  IF NEW.subject_id <> NEW.created_by
     OR NEW.organization_id <> receipt.organization_id
     OR NEW.subject_id <> receipt.subject_id
     OR NEW.subject_root <> receipt.subject_root
     OR NEW.subject_authority_root <> NEW.actor_snapshot->>'authorityRoot'
     OR NEW.consent_receipt_root <> receipt.receipt_root
     OR receipt.expires_at IS NOT NULL AND receipt.expires_at <= NEW.issued_at
     OR EXISTS (
       SELECT 1 FROM evidence.consent_revocations revocation
       WHERE revocation.receipt_id = receipt.id AND revocation.revoked_at <= NEW.issued_at
     )
     OR NOT ('evidence_collection' = ANY(receipt.purposes))
     OR receipt.device_fingerprint_hash IS NOT NULL
        AND receipt.device_fingerprint_hash <> NEW.device_fingerprint_hash
     OR NOT audit.is_sorted_unique_text_array(NEW.risk_flags)
     OR NOT evidence.evidence_custody_actor_is_valid(NEW.actor_snapshot, NEW.subject_id, NEW.organization_id)
     OR NEW.safety <> evidence.evidence_custody_safety_canonical() THEN
    RAISE EXCEPTION 'evidence device attestation authority is invalid';
  END IF;
  IF semantic_event.stream_id <> 'evidence-custody:' || NEW.subject_id
     OR semantic_event.sequence_no <> NEW.subject_sequence
     OR semantic_event.action <> expected_action
     OR semantic_event.actor_id <> NEW.subject_id
     OR semantic_event.entity_type <> 'device_attestation'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.created_at <> NEW.issued_at
     OR semantic_event.payload_hash <> evidence.device_attestation_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence device attestation semantic event binding is invalid';
  END IF;
  IF NEW.command_hash <> evidence.device_attestation_command_hash(NEW)
     OR NEW.id <> 'cp_evidence_device_' || left(NEW.command_hash, 24)
     OR NEW.device_hash <> evidence.device_attestation_hash(NEW)
     OR NEW.attestation_root <> evidence.device_attestation_root(NEW) THEN
    RAISE EXCEPTION 'evidence device attestation hash lineage is invalid';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS evidence_consent_receipts_validate ON evidence.consent_receipts;
CREATE TRIGGER evidence_consent_receipts_validate
BEFORE INSERT ON evidence.consent_receipts
FOR EACH ROW EXECUTE FUNCTION evidence.validate_consent_receipt_insert();

DROP TRIGGER IF EXISTS evidence_consent_revocations_validate ON evidence.consent_revocations;
CREATE TRIGGER evidence_consent_revocations_validate
BEFORE INSERT ON evidence.consent_revocations
FOR EACH ROW EXECUTE FUNCTION evidence.validate_consent_revocation_insert();

DROP TRIGGER IF EXISTS identity_device_attestations_validate ON identity.device_attestations;
CREATE TRIGGER identity_device_attestations_validate
BEFORE INSERT ON identity.device_attestations
FOR EACH ROW EXECUTE FUNCTION evidence.validate_device_attestation_insert();

CREATE OR REPLACE FUNCTION evidence.consent_receipt_projection(target_receipt_id text, evaluated_at timestamptz)
RETURNS TABLE (
  receipt_id text,
  receipt_root text,
  organization_id text,
  subject_id text,
  state text,
  evaluated_at_utc timestamptz,
  revocation_id text,
  revocation_root text,
  projection_root text,
  safety jsonb
)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  receipt evidence.consent_receipts%ROWTYPE;
  revocation evidence.consent_revocations%ROWTYPE;
  projected_state text;
  projected_root text;
BEGIN
  SELECT * INTO STRICT receipt FROM evidence.consent_receipts WHERE id = target_receipt_id;
  SELECT candidate.* INTO revocation
  FROM evidence.consent_revocations candidate
  WHERE candidate.receipt_id = target_receipt_id;
  projected_state := CASE
    WHEN revocation.id IS NOT NULL THEN 'revoked'
    WHEN receipt.expires_at IS NOT NULL AND receipt.expires_at <= evaluated_at THEN 'expired'
    ELSE 'active'
  END;
  projected_root := audit.sha256_stable_json(jsonb_strip_nulls(jsonb_build_object(
    'kind', 'canopyproof-evidence-consent-projection-v2',
    'receiptId', receipt.id,
    'receiptRoot', receipt.receipt_root,
    'organizationId', receipt.organization_id,
    'subjectId', receipt.subject_id,
    'state', projected_state,
    'evaluatedAt', audit.iso8601_millis(evaluated_at),
    'revocationId', revocation.id,
    'revocationRoot', revocation.revocation_root,
    'safety', evidence.evidence_custody_safety_canonical()
  )));
  RETURN QUERY SELECT receipt.id, receipt.receipt_root, receipt.organization_id,
    receipt.subject_id, projected_state, evaluated_at, revocation.id,
    revocation.revocation_root, projected_root, evidence.evidence_custody_safety_canonical();
END;
$$;

CREATE OR REPLACE FUNCTION evidence.device_attestation_projection(target_attestation_id text, evaluated_at timestamptz)
RETURNS TABLE (
  attestation_id text,
  attestation_root text,
  organization_id text,
  subject_id text,
  consent_receipt_id text,
  state text,
  evaluated_at_utc timestamptz,
  consent_projection_root text,
  projection_root text,
  safety jsonb
)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  attestation identity.device_attestations%ROWTYPE;
  consent record;
  projected_state text;
  projected_root text;
BEGIN
  SELECT * INTO STRICT attestation FROM identity.device_attestations WHERE id = target_attestation_id;
  SELECT * INTO STRICT consent FROM evidence.consent_receipt_projection(attestation.consent_receipt_id, evaluated_at);
  projected_state := CASE
    WHEN consent.state = 'revoked' THEN 'consent_revoked'
    WHEN consent.state = 'expired' THEN 'consent_expired'
    WHEN attestation.expires_at <= evaluated_at THEN 'expired'
    WHEN attestation.provider_verification_state <> 'verified' OR cardinality(attestation.risk_flags) > 0 THEN 'needs_review'
    ELSE 'current'
  END;
  projected_root := audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-evidence-device-projection-v2',
    'attestationId', attestation.id,
    'attestationRoot', attestation.attestation_root,
    'organizationId', attestation.organization_id,
    'subjectId', attestation.subject_id,
    'consentReceiptId', attestation.consent_receipt_id,
    'state', projected_state,
    'evaluatedAt', audit.iso8601_millis(evaluated_at),
    'consentProjectionRoot', consent.projection_root,
    'safety', evidence.evidence_custody_safety_canonical()
  ));
  RETURN QUERY SELECT attestation.id, attestation.attestation_root,
    attestation.organization_id, attestation.subject_id,
    attestation.consent_receipt_id, projected_state, evaluated_at,
    consent.projection_root, projected_root, evidence.evidence_custody_safety_canonical();
END;
$$;

-- Evidence Protocol E2: immutable media custody facts. These tables deliberately
-- exclude upload grants, provider credentials, endpoints, and mutable scan state.
CREATE TABLE IF NOT EXISTS evidence.media_upload_intent_facts (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  project_root text NOT NULL CHECK (project_root ~ '^[0-9a-f]{64}$'),
  project_status text NOT NULL CHECK (
    project_status IN ('submitted', 'under_review', 'active', 'monitored', 'challenged')
  ),
  evidence_id text NOT NULL UNIQUE REFERENCES evidence.evidence_objects(id),
  subject_id text NOT NULL REFERENCES identity.participants(id),
  subject_root text NOT NULL CHECK (subject_root ~ '^[0-9a-f]{64}$'),
  subject_authority_root text NOT NULL CHECK (subject_authority_root ~ '^[0-9a-f]{64}$'),
  consent_receipt_id text NOT NULL REFERENCES evidence.consent_receipts(id),
  consent_receipt_root text NOT NULL CHECK (consent_receipt_root ~ '^[0-9a-f]{64}$'),
  consent_projection_root text NOT NULL CHECK (consent_projection_root ~ '^[0-9a-f]{64}$'),
  device_attestation_id text NOT NULL REFERENCES identity.device_attestations(id),
  device_attestation_root text NOT NULL CHECK (device_attestation_root ~ '^[0-9a-f]{64}$'),
  device_projection_root text NOT NULL CHECK (device_projection_root ~ '^[0-9a-f]{64}$'),
  device_trust_state text NOT NULL CHECK (device_trust_state IN ('current', 'needs_review')),
  content_hash text NOT NULL CHECK (content_hash ~ '^[0-9a-f]{64}$'),
  content_type text NOT NULL CHECK (
    content_type IN ('image/jpeg', 'image/png', 'image/webp', 'application/json')
  ),
  byte_length bigint NOT NULL CHECK (byte_length > 0 AND byte_length <= 52428800),
  object_key text NOT NULL UNIQUE CHECK (length(btrim(object_key)) BETWEEN 1 AND 1024),
  captured_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  actor_snapshot jsonb NOT NULL CHECK (jsonb_typeof(actor_snapshot) = 'object'),
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  intent_hash text NOT NULL UNIQUE CHECK (intent_hash ~ '^[0-9a-f]{64}$'),
  intent_root text NOT NULL UNIQUE CHECK (intent_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence),
  CHECK (captured_at < expires_at)
);

CREATE INDEX IF NOT EXISTS evidence_media_upload_intent_org_project
  ON evidence.media_upload_intent_facts (organization_id, project_id, captured_at DESC, id);

CREATE INDEX IF NOT EXISTS evidence_media_upload_intent_content
  ON evidence.media_upload_intent_facts (organization_id, content_hash, id);

CREATE TABLE IF NOT EXISTS evidence.media_object_facts (
  id text PRIMARY KEY,
  intent_id text NOT NULL UNIQUE REFERENCES evidence.media_upload_intent_facts(id),
  intent_root text NOT NULL CHECK (intent_root ~ '^[0-9a-f]{64}$'),
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  project_root text NOT NULL CHECK (project_root ~ '^[0-9a-f]{64}$'),
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  content_hash text NOT NULL CHECK (content_hash ~ '^[0-9a-f]{64}$'),
  content_type text NOT NULL CHECK (
    content_type IN ('image/jpeg', 'image/png', 'image/webp', 'application/json')
  ),
  byte_length bigint NOT NULL CHECK (byte_length > 0 AND byte_length <= 52428800),
  object_key text NOT NULL UNIQUE CHECK (length(btrim(object_key)) BETWEEN 1 AND 1024),
  storage_provider text NOT NULL CHECK (storage_provider IN ('cloudflare_r2', 's3', 'gcs')),
  provider_namespace text NOT NULL CHECK (length(btrim(provider_namespace)) BETWEEN 1 AND 240),
  object_version text NOT NULL CHECK (length(btrim(object_version)) BETWEEN 1 AND 240),
  etag_hash text NOT NULL CHECK (etag_hash ~ '^[0-9a-f]{64}$'),
  provider_receipt_hash text NOT NULL CHECK (provider_receipt_hash ~ '^[0-9a-f]{64}$'),
  provider_verification_state text NOT NULL CHECK (
    provider_verification_state IN ('modeled_only', 'verified')
  ),
  encryption_mode text NOT NULL CHECK (encryption_mode IN ('r2_managed', 'sse_kms', 'client_side')),
  encryption_key_ref text CHECK (
    encryption_key_ref IS NULL OR length(btrim(encryption_key_ref)) BETWEEN 1 AND 240
  ),
  object_lock_mode text NOT NULL CHECK (object_lock_mode IN ('none', 'governance', 'compliance')),
  retain_until timestamptz,
  stored_at timestamptz NOT NULL,
  agent_snapshot jsonb NOT NULL CHECK (jsonb_typeof(agent_snapshot) = 'object'),
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  object_hash text NOT NULL UNIQUE CHECK (object_hash ~ '^[0-9a-f]{64}$'),
  object_root text NOT NULL UNIQUE CHECK (object_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence),
  CHECK (
    (encryption_mode = 'sse_kms' AND encryption_key_ref IS NOT NULL)
    OR (encryption_mode <> 'sse_kms')
  ),
  CHECK (
    (object_lock_mode = 'none' AND retain_until IS NULL)
    OR (object_lock_mode <> 'none' AND retain_until IS NOT NULL AND retain_until > stored_at)
  )
);

CREATE INDEX IF NOT EXISTS evidence_media_object_org_content
  ON evidence.media_object_facts (organization_id, content_hash, stored_at, id);

CREATE INDEX IF NOT EXISTS evidence_media_object_project_time
  ON evidence.media_object_facts (project_id, stored_at DESC, id);

CREATE TABLE IF NOT EXISTS evidence.media_duplicate_relation_facts (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  object_id text NOT NULL UNIQUE REFERENCES evidence.media_object_facts(id),
  object_root text NOT NULL CHECK (object_root ~ '^[0-9a-f]{64}$'),
  duplicate_of_object_id text NOT NULL REFERENCES evidence.media_object_facts(id),
  duplicate_of_object_root text NOT NULL CHECK (duplicate_of_object_root ~ '^[0-9a-f]{64}$'),
  content_hash text NOT NULL CHECK (content_hash ~ '^[0-9a-f]{64}$'),
  detected_at timestamptz NOT NULL,
  agent_snapshot jsonb NOT NULL CHECK (jsonb_typeof(agent_snapshot) = 'object'),
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  relation_hash text NOT NULL UNIQUE CHECK (relation_hash ~ '^[0-9a-f]{64}$'),
  relation_root text NOT NULL UNIQUE CHECK (relation_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence),
  CHECK (object_id <> duplicate_of_object_id)
);

CREATE INDEX IF NOT EXISTS evidence_media_duplicate_org_content
  ON evidence.media_duplicate_relation_facts (organization_id, content_hash, detected_at, id);

CREATE TABLE IF NOT EXISTS evidence.media_scan_result_facts (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  object_id text NOT NULL REFERENCES evidence.media_object_facts(id),
  object_root text NOT NULL CHECK (object_root ~ '^[0-9a-f]{64}$'),
  scanner_name text NOT NULL CHECK (length(btrim(scanner_name)) BETWEEN 2 AND 100),
  scanner_version text NOT NULL CHECK (length(btrim(scanner_version)) BETWEEN 1 AND 100),
  scanner_image_digest text NOT NULL CHECK (scanner_image_digest ~ '^[0-9a-f]{64}$'),
  signature_database_version text NOT NULL CHECK (
    length(btrim(signature_database_version)) BETWEEN 1 AND 100
  ),
  verdict text NOT NULL CHECK (verdict IN ('clean', 'malicious', 'indeterminate', 'error')),
  finding_hashes text[] NOT NULL CHECK (cardinality(finding_hashes) <= 256),
  provider_receipt_hash text NOT NULL CHECK (provider_receipt_hash ~ '^[0-9a-f]{64}$'),
  provider_verification_state text NOT NULL CHECK (
    provider_verification_state IN ('modeled_only', 'verified')
  ),
  scanned_at timestamptz NOT NULL,
  agent_snapshot jsonb NOT NULL CHECK (jsonb_typeof(agent_snapshot) = 'object'),
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  scan_hash text NOT NULL UNIQUE CHECK (scan_hash ~ '^[0-9a-f]{64}$'),
  scan_root text NOT NULL UNIQUE CHECK (scan_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence)
);

CREATE INDEX IF NOT EXISTS evidence_media_scan_object_sequence
  ON evidence.media_scan_result_facts (object_id, evidence_sequence DESC, id DESC);

CREATE INDEX IF NOT EXISTS evidence_media_scan_org_time
  ON evidence.media_scan_result_facts (organization_id, scanned_at DESC, id);

