    'semanticEventBound', true,
    'noPersistedUploadGrant', true,
    'noProviderCredential', true,
    'quarantineByDefault', true,
    'providerVerificationRequiredForAvailability', true,
    'scannerVerificationRequiredForAvailability', true,
    'notFinalProofAuthority', true,
    'notCertifiedCarbonCredit', true,
    'notCarbonTaxOffset', true,
    'notFinancialAsset', true,
    'notGuaranteedYield', true,
    'noMainnetFunds', true,
    'notAutomaticCanopyDistribution', true
  );
$$;

CREATE OR REPLACE FUNCTION evidence.evidence_media_agent_authority_root(agent_snapshot jsonb)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-evidence-media-agent-authority-v1') ||
    (agent_snapshot - 'authorityRoot')
  );
$$;

CREATE OR REPLACE FUNCTION evidence.evidence_media_agent_is_valid(
  agent_snapshot jsonb,
  expected_organization_id text,
  expected_capability text
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  participant identity.participants%ROWTYPE;
  organization organizations.organizations%ROWTYPE;
  profile identity.agent_profiles%ROWTYPE;
BEGIN
  IF jsonb_typeof(agent_snapshot) <> 'object'
     OR agent_snapshot->>'participantType' <> 'agent'
     OR agent_snapshot->>'role' <> 'agent'
     OR agent_snapshot->>'verificationStatus' <> 'verified'
     OR agent_snapshot->>'organizationId' <> expected_organization_id
     OR agent_snapshot->>'organizationVerificationStatus' <> 'verified'
     OR agent_snapshot->>'participantRoot' !~ '^[0-9a-f]{64}$'
     OR agent_snapshot->>'organizationRoot' !~ '^[0-9a-f]{64}$'
     OR agent_snapshot->>'agentType' <> 'evidence'
     OR agent_snapshot->>'agentStatus' <> 'active'
     OR agent_snapshot->>'capability' <> expected_capability
     OR agent_snapshot->>'agentRegistryHash' !~ '^[0-9a-f]{64}$'
     OR agent_snapshot->>'authorityRoot' <>
        evidence.evidence_media_agent_authority_root(agent_snapshot) THEN
    RETURN false;
  END IF;
  SELECT * INTO participant
  FROM identity.participants
  WHERE id = agent_snapshot->>'id';
  SELECT * INTO organization
  FROM organizations.organizations
  WHERE id = expected_organization_id;
  SELECT * INTO profile
  FROM identity.agent_profiles
  WHERE id = agent_snapshot->>'id';
  RETURN participant.id IS NOT NULL
    AND participant.participant_type = 'agent'
    AND participant.verification_status = 'verified'
    AND participant.organization_id = expected_organization_id
    AND participant.subject_hash = agent_snapshot->>'participantRoot'
    AND 'agent' = ANY(participant.roles)
    AND organization.id IS NOT NULL
    AND organization.verification_status = 'verified'
    AND organization.profile_hash = agent_snapshot->>'organizationRoot'
    AND profile.id IS NOT NULL
    AND profile.agent_type = 'evidence'
    AND profile.status = 'active'
    AND expected_capability = ANY(profile.capabilities)
    AND profile.registry_hash = agent_snapshot->>'agentRegistryHash';
END;
$$;

CREATE OR REPLACE FUNCTION evidence.evidence_media_safe_material(values_to_check text[])
RETURNS boolean
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT NOT EXISTS (
    SELECT 1
    FROM unnest(values_to_check) AS value
    WHERE value ~* '(bearer[[:space:]]+|password|secret|private[_ -]?key|BEGIN [A-Z ]*PRIVATE KEY|https?://|[?&](token|signature|credential)=)'
       OR value ~* '(certified carbon credit|carbon tax offset|guaranteed (rwa )?yield|automatic \$?canopy distribution)'
  );
$$;

