LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT jsonb_build_object(
    'organizationId', scan.organization_id,
    'projectId', scan.project_id,
    'evidenceId', scan.evidence_id,
    'objectId', scan.object_id,
    'objectRoot', scan.object_root,
    'scannerName', scan.scanner_name,
    'scannerVersion', scan.scanner_version,
    'scannerImageDigest', scan.scanner_image_digest,
    'signatureDatabaseVersion', scan.signature_database_version,
    'verdict', scan.verdict,
    'findingHashes', to_jsonb(scan.finding_hashes),
    'providerReceiptHash', scan.provider_receipt_hash,
    'providerVerificationState', scan.provider_verification_state,
    'scannedAt', audit.iso8601_millis(scan.scanned_at),
    'agent', scan.agent_snapshot
  );
$$;

CREATE OR REPLACE FUNCTION evidence.media_scan_command_hash(scan evidence.media_scan_result_facts)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-evidence-media-scan-command-v1') ||
    evidence.media_scan_command_seed(scan)
  );
$$;

CREATE OR REPLACE FUNCTION evidence.media_scan_fact_seed(scan evidence.media_scan_result_facts)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT jsonb_build_object('id', scan.id) ||
    evidence.media_scan_command_seed(scan) ||
    jsonb_build_object(
      'commandHash', scan.command_hash,
      'evidenceSequence', scan.evidence_sequence,
      'previousEventRoot', scan.previous_event_root
    );
$$;

CREATE OR REPLACE FUNCTION evidence.media_scan_hash(scan evidence.media_scan_result_facts)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('kind', 'canopyproof-evidence-media-scan-v1') ||
    evidence.media_scan_fact_seed(scan)
  );
$$;

CREATE OR REPLACE FUNCTION evidence.media_scan_root(scan evidence.media_scan_result_facts)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(jsonb_build_object(
    'kind', 'canopyproof-evidence-media-scan-root-v1',
    'objectRoot', scan.object_root,
    'providerReceiptHash', scan.provider_receipt_hash,
    'verdict', scan.verdict,
    'commandHash', scan.command_hash,
    'scanHash', scan.scan_hash,
    'evidenceSequence', scan.evidence_sequence,
    'previousEventRoot', scan.previous_event_root
  ));
$$;

CREATE OR REPLACE FUNCTION evidence.media_scan_payload_hash(scan evidence.media_scan_result_facts)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT audit.sha256_stable_json(
    jsonb_build_object('factType', 'evidence_media_scan_result') ||
    evidence.media_scan_fact_seed(scan) ||
    jsonb_build_object(
      'scanHash', scan.scan_hash,
      'scanRoot', scan.scan_root,
      'safety', scan.safety
    )
  );
$$;

CREATE OR REPLACE FUNCTION evidence.validate_media_upload_intent_fact_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  evidence_record evidence.evidence_objects%ROWTYPE;
  project_registration projects.projects%ROWTYPE;
  project_authority record;
  receipt evidence.consent_receipts%ROWTYPE;
  device identity.device_attestations%ROWTYPE;
  consent_projection record;
  device_projection record;
  semantic_event audit.domain_events%ROWTYPE;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  SELECT * INTO STRICT evidence_record
  FROM evidence.evidence_objects
  WHERE id = NEW.evidence_id
  FOR SHARE;
  SELECT * INTO STRICT project_registration
  FROM projects.projects
  WHERE id = NEW.project_id
  FOR SHARE;
  SELECT * INTO STRICT project_authority
  FROM projects.current_authority(NEW.project_id);
  SELECT * INTO STRICT receipt
  FROM evidence.consent_receipts
  WHERE id = NEW.consent_receipt_id
  FOR SHARE;
  SELECT * INTO STRICT device
  FROM identity.device_attestations
  WHERE id = NEW.device_attestation_id
  FOR SHARE;
  SELECT * INTO STRICT consent_projection
  FROM evidence.consent_receipt_projection(NEW.consent_receipt_id, NEW.captured_at);
  SELECT * INTO STRICT device_projection
  FROM evidence.effective_device_attestation_projection(
    NEW.device_attestation_id,
    NEW.captured_at
  );
  SELECT * INTO STRICT semantic_event
  FROM audit.domain_events
  WHERE event_root = NEW.audit_event_root;

  IF transaction_actor_id IS NULL
     OR transaction_actor_id <> NEW.subject_id
     OR evidence_record.contributor_id <> NEW.subject_id
     OR evidence_record.organization_id <> NEW.organization_id
     OR evidence_record.project_id <> NEW.project_id
     OR evidence_record.media_hash <> NEW.content_hash
     OR project_registration.organization_id <> NEW.organization_id
     OR project_authority.status NOT IN ('submitted', 'under_review', 'active', 'monitored', 'challenged')
     OR project_authority.status <> NEW.project_status
     OR project_authority.project_root <> NEW.project_root
     OR receipt.organization_id <> NEW.organization_id
     OR receipt.subject_id <> NEW.subject_id
     OR receipt.subject_root <> NEW.subject_root
     OR receipt.receipt_root <> NEW.consent_receipt_root
     OR NOT ('evidence_collection' = ANY(receipt.purposes))
     OR NOT ('media_upload' = ANY(receipt.purposes))
     OR consent_projection.state <> 'active'
     OR consent_projection.projection_root <> NEW.consent_projection_root
     OR device.organization_id <> NEW.organization_id
     OR device.subject_id <> NEW.subject_id
     OR device.subject_root <> NEW.subject_root
     OR device.consent_receipt_id <> NEW.consent_receipt_id
     OR device.attestation_root <> NEW.device_attestation_root
     OR device_projection.state NOT IN ('current', 'needs_review')
     OR device_projection.state <> NEW.device_trust_state
     OR device_projection.projection_root <> NEW.device_projection_root
     OR NEW.subject_authority_root <> NEW.actor_snapshot->>'authorityRoot'
     OR NOT evidence.evidence_custody_actor_is_valid(
       NEW.actor_snapshot,
       NEW.subject_id,
       NEW.organization_id
     )
     OR NEW.object_key <> concat(
       'canopyproof/',
       NEW.organization_id, '/',
       NEW.project_id, '/',
       NEW.evidence_id, '/',
       NEW.content_hash
     )
     OR NEW.expires_at <> NEW.captured_at + interval '24 hours'
     OR NEW.captured_at <> date_trunc('milliseconds', NEW.captured_at)
     OR NEW.expires_at <> date_trunc('milliseconds', NEW.expires_at)
     OR NEW.safety <> evidence.evidence_media_safety_canonical() THEN
    RAISE EXCEPTION 'evidence media upload intent authority is invalid';
  END IF;

  IF semantic_event.stream_id <> 'evidence-media:' || NEW.evidence_id
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.action <> 'ASSERT'
     OR semantic_event.actor_id <> NEW.subject_id
     OR semantic_event.entity_type <> 'media_upload_intent'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.created_at <> NEW.captured_at
     OR semantic_event.payload_hash <> evidence.media_upload_intent_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence media upload intent semantic event binding is invalid';
  END IF;

  IF NEW.command_hash <> evidence.media_upload_intent_command_hash(NEW)
     OR NEW.id <> 'cp_media_intent_' || left(NEW.command_hash, 24)
     OR NEW.intent_hash <> evidence.media_upload_intent_hash(NEW)
     OR NEW.intent_root <> evidence.media_upload_intent_root(NEW) THEN
    RAISE EXCEPTION 'evidence media upload intent hash lineage is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION evidence.validate_media_object_fact_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  intent evidence.media_upload_intent_facts%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  expected_action text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  SELECT * INTO STRICT intent
  FROM evidence.media_upload_intent_facts
  WHERE id = NEW.intent_id
  FOR SHARE;
  SELECT * INTO STRICT semantic_event
  FROM audit.domain_events
  WHERE event_root = NEW.audit_event_root;
  expected_action := CASE
    WHEN NEW.provider_verification_state = 'verified' THEN 'FULFILL'
    ELSE 'REASON'
  END;

  IF transaction_actor_id IS NULL
     OR transaction_actor_id <> NEW.agent_snapshot->>'id'
     OR NEW.intent_root <> intent.intent_root
     OR NEW.organization_id <> intent.organization_id
     OR NEW.project_id <> intent.project_id
     OR NEW.project_root <> intent.project_root
     OR NEW.evidence_id <> intent.evidence_id
     OR NEW.content_hash <> intent.content_hash
     OR NEW.content_type <> intent.content_type
     OR NEW.byte_length <> intent.byte_length
     OR NEW.object_key <> intent.object_key
     OR NEW.stored_at < intent.captured_at
     OR NEW.stored_at > intent.expires_at
     OR NEW.stored_at <> date_trunc('milliseconds', NEW.stored_at)
     OR NEW.provider_verification_state <> 'modeled_only'
     OR NOT evidence.evidence_media_agent_is_valid(
       NEW.agent_snapshot,
       NEW.organization_id,
       'object_storage_receipt'
     )
     OR NOT evidence.evidence_media_safe_material(ARRAY[
       NEW.provider_namespace,
       NEW.object_version,
       COALESCE(NEW.encryption_key_ref, '')
     ])
     OR NEW.safety <> evidence.evidence_media_safety_canonical() THEN
    RAISE EXCEPTION 'evidence media object authority is invalid';
  END IF;

  IF semantic_event.stream_id <> 'evidence-media:' || NEW.evidence_id
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.action <> expected_action
     OR semantic_event.actor_id <> NEW.agent_snapshot->>'id'
     OR semantic_event.entity_type <> 'media_object'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.created_at <> NEW.stored_at
     OR semantic_event.payload_hash <> evidence.media_object_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence media object semantic event binding is invalid';
  END IF;

  IF NEW.command_hash <> evidence.media_object_command_hash(NEW)
     OR NEW.id <> 'cp_media_object_' || left(NEW.command_hash, 24)
     OR NEW.object_hash <> evidence.media_object_hash(NEW)
     OR NEW.object_root <> evidence.media_object_root(NEW) THEN
    RAISE EXCEPTION 'evidence media object hash lineage is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION evidence.validate_media_duplicate_relation_fact_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  object_fact evidence.media_object_facts%ROWTYPE;
  duplicate_of evidence.media_object_facts%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  SELECT * INTO STRICT object_fact
  FROM evidence.media_object_facts
  WHERE id = NEW.object_id
  FOR SHARE;
  SELECT * INTO STRICT duplicate_of
  FROM evidence.media_object_facts
  WHERE id = NEW.duplicate_of_object_id
  FOR SHARE;
  SELECT * INTO STRICT semantic_event
  FROM audit.domain_events
  WHERE event_root = NEW.audit_event_root;

  IF transaction_actor_id IS NULL
     OR transaction_actor_id <> NEW.agent_snapshot->>'id'
     OR NEW.organization_id <> object_fact.organization_id
     OR NEW.organization_id <> duplicate_of.organization_id
     OR NEW.project_id <> object_fact.project_id
     OR NEW.evidence_id <> object_fact.evidence_id
     OR NEW.object_root <> object_fact.object_root
     OR NEW.duplicate_of_object_root <> duplicate_of.object_root
     OR NEW.content_hash <> object_fact.content_hash
     OR NEW.content_hash <> duplicate_of.content_hash
     OR NEW.detected_at <> object_fact.stored_at
     OR NEW.detected_at <> date_trunc('milliseconds', NEW.detected_at)
     OR NOT evidence.evidence_media_agent_is_valid(
       NEW.agent_snapshot,
       NEW.organization_id,
       'object_storage_receipt'
     )
     OR NEW.safety <> evidence.evidence_media_safety_canonical() THEN
    RAISE EXCEPTION 'evidence media duplicate relation authority is invalid';
  END IF;

  IF semantic_event.stream_id <> 'evidence-media:' || NEW.evidence_id
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.action <> 'CHALLENGE'
     OR semantic_event.actor_id <> NEW.agent_snapshot->>'id'
     OR semantic_event.entity_type <> 'media_duplicate_relation'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.created_at <> NEW.detected_at
     OR semantic_event.payload_hash <> evidence.media_duplicate_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence media duplicate relation semantic event binding is invalid';
  END IF;

  IF NEW.command_hash <> evidence.media_duplicate_command_hash(NEW)
     OR NEW.id <> 'cp_media_duplicate_' || left(NEW.command_hash, 24)
     OR NEW.relation_hash <> evidence.media_duplicate_hash(NEW)
     OR NEW.relation_root <> evidence.media_duplicate_root(NEW) THEN
    RAISE EXCEPTION 'evidence media duplicate relation hash lineage is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION evidence.validate_media_scan_result_fact_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  object_fact evidence.media_object_facts%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  expected_action text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  SELECT * INTO STRICT object_fact
  FROM evidence.media_object_facts
  WHERE id = NEW.object_id
  FOR SHARE;
  SELECT * INTO STRICT semantic_event
  FROM audit.domain_events
  WHERE event_root = NEW.audit_event_root;
  expected_action := CASE
    WHEN NEW.verdict = 'clean' AND NEW.provider_verification_state = 'verified' THEN 'FULFILL'
    WHEN NEW.verdict = 'clean' THEN 'REASON'
    ELSE 'CHALLENGE'
  END;

  IF transaction_actor_id IS NULL
     OR transaction_actor_id <> NEW.agent_snapshot->>'id'
     OR NEW.organization_id <> object_fact.organization_id
     OR NEW.project_id <> object_fact.project_id
     OR NEW.evidence_id <> object_fact.evidence_id
     OR NEW.object_root <> object_fact.object_root
     OR NEW.scanned_at < object_fact.stored_at
     OR NEW.scanned_at <> date_trunc('milliseconds', NEW.scanned_at)
     OR NEW.provider_verification_state <> 'modeled_only'
     OR NOT audit.is_sorted_unique_text_array(NEW.finding_hashes)
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.finding_hashes) AS finding_hash
       WHERE finding_hash !~ '^[0-9a-f]{64}$'
     )
     OR NOT evidence.evidence_media_agent_is_valid(
       NEW.agent_snapshot,
       NEW.organization_id,
       'malware_scan_result'
     )
     OR NOT evidence.evidence_media_safe_material(ARRAY[
       NEW.scanner_name,
       NEW.scanner_version,
       NEW.signature_database_version
     ])
     OR NEW.safety <> evidence.evidence_media_safety_canonical() THEN
    RAISE EXCEPTION 'evidence media scan result authority is invalid';
  END IF;

  IF semantic_event.stream_id <> 'evidence-media:' || NEW.evidence_id
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.action <> expected_action
     OR semantic_event.actor_id <> NEW.agent_snapshot->>'id'
     OR semantic_event.entity_type <> 'media_scan_result'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.created_at <> NEW.scanned_at
     OR semantic_event.payload_hash <> evidence.media_scan_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence media scan result semantic event binding is invalid';
  END IF;

  IF NEW.command_hash <> evidence.media_scan_command_hash(NEW)
     OR NEW.id <> 'cp_media_scan_' || left(NEW.command_hash, 24)
     OR NEW.scan_hash <> evidence.media_scan_hash(NEW)
     OR NEW.scan_root <> evidence.media_scan_root(NEW) THEN
    RAISE EXCEPTION 'evidence media scan result hash lineage is invalid';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS evidence_media_upload_intent_facts_validate
  ON evidence.media_upload_intent_facts;
CREATE TRIGGER evidence_media_upload_intent_facts_validate
BEFORE INSERT ON evidence.media_upload_intent_facts
FOR EACH ROW EXECUTE FUNCTION evidence.validate_media_upload_intent_fact_insert();

DROP TRIGGER IF EXISTS evidence_media_object_facts_validate ON evidence.media_object_facts;
CREATE TRIGGER evidence_media_object_facts_validate
BEFORE INSERT ON evidence.media_object_facts
FOR EACH ROW EXECUTE FUNCTION evidence.validate_media_object_fact_insert();

DROP TRIGGER IF EXISTS evidence_media_duplicate_relation_facts_validate
  ON evidence.media_duplicate_relation_facts;
CREATE TRIGGER evidence_media_duplicate_relation_facts_validate
BEFORE INSERT ON evidence.media_duplicate_relation_facts
FOR EACH ROW EXECUTE FUNCTION evidence.validate_media_duplicate_relation_fact_insert();

DROP TRIGGER IF EXISTS evidence_media_scan_result_facts_validate
  ON evidence.media_scan_result_facts;
CREATE TRIGGER evidence_media_scan_result_facts_validate
BEFORE INSERT ON evidence.media_scan_result_facts
FOR EACH ROW EXECUTE FUNCTION evidence.validate_media_scan_result_fact_insert();

CREATE OR REPLACE FUNCTION evidence.media_object_projection(
  target_object_id text,
  evaluated_at timestamptz
)
RETURNS TABLE (
  object_id text,
  object_root text,
  organization_id text,
  project_id text,
  evidence_id text,
  state text,
  evaluated_at_utc timestamptz,
  consent_state text,
  device_state text,
  latest_scan_result_id text,
  latest_scan_root text,
  duplicate_relation_id text,
  duplicate_relation_root text,
  projection_root text,
  safety jsonb
)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  object_fact evidence.media_object_facts%ROWTYPE;
  intent evidence.media_upload_intent_facts%ROWTYPE;
  consent record;
  device record;
  latest_scan evidence.media_scan_result_facts%ROWTYPE;
  duplicate_relation evidence.media_duplicate_relation_facts%ROWTYPE;
  projected_state text;
  projected_root text;
  safety_boundary jsonb;
BEGIN
  SELECT * INTO STRICT object_fact
  FROM evidence.media_object_facts
  WHERE id = target_object_id;
  IF object_fact.stored_at > evaluated_at THEN
    RAISE EXCEPTION 'CANOPYPROOF_MEDIA_OBJECT_NOT_VISIBLE_AT_EVALUATION';
  END IF;
  SELECT * INTO STRICT intent
  FROM evidence.media_upload_intent_facts
  WHERE id = object_fact.intent_id;
  SELECT * INTO STRICT consent
  FROM evidence.consent_receipt_projection(intent.consent_receipt_id, evaluated_at);
  SELECT * INTO STRICT device
  FROM evidence.effective_device_attestation_projection(
    intent.device_attestation_id,
    evaluated_at
  );
  SELECT candidate.* INTO latest_scan
  FROM evidence.media_scan_result_facts candidate
  WHERE candidate.object_id = target_object_id
    AND candidate.scanned_at <= evaluated_at
  ORDER BY candidate.evidence_sequence DESC, candidate.id DESC
  LIMIT 1;
  SELECT candidate.* INTO duplicate_relation
  FROM evidence.media_duplicate_relation_facts candidate
  WHERE candidate.object_id = target_object_id
    AND candidate.detected_at <= evaluated_at
  ORDER BY candidate.evidence_sequence DESC, candidate.id DESC
  LIMIT 1;

  projected_state := CASE
    WHEN duplicate_relation.id IS NOT NULL THEN 'duplicate'
    WHEN latest_scan.id IS NULL THEN 'pending_scan'
    WHEN latest_scan.verdict <> 'clean'
      OR consent.state <> 'active'
      OR device.state IN ('expired', 'consent_expired', 'consent_revoked') THEN 'quarantined'
    WHEN object_fact.provider_verification_state <> 'verified'
      OR latest_scan.provider_verification_state <> 'verified'
      OR device.state <> 'current'
      OR object_fact.object_lock_mode = 'none' THEN 'needs_review'
    ELSE 'available'
  END;
  safety_boundary := evidence.evidence_media_safety_canonical();
  projected_root := audit.sha256_stable_json(jsonb_strip_nulls(jsonb_build_object(
    'kind', 'canopyproof-evidence-media-object-projection-v1',
    'objectId', object_fact.id,
    'objectRoot', object_fact.object_root,
    'organizationId', object_fact.organization_id,
    'projectId', object_fact.project_id,
    'evidenceId', object_fact.evidence_id,
    'state', projected_state,
    'evaluatedAt', audit.iso8601_millis(evaluated_at),
    'consentState', consent.state,
    'deviceState', device.state,
    'latestScanResultId', latest_scan.id,
    'latestScanRoot', latest_scan.scan_root,
    'duplicateRelationId', duplicate_relation.id,
    'duplicateRelationRoot', duplicate_relation.relation_root,
    'safety', safety_boundary
  )));

  RETURN QUERY SELECT
    object_fact.id,
    object_fact.object_root,
    object_fact.organization_id,
    object_fact.project_id,
    object_fact.evidence_id,
    projected_state,
    evaluated_at,
    consent.state,
    device.state,
    latest_scan.id,
    latest_scan.scan_root,
    duplicate_relation.id,
    duplicate_relation.relation_root,
    projected_root,
    safety_boundary;
END;
$$;

-- Evidence Protocol E3a: immutable media review and custody facts. These facts
-- cannot promote provider verification, mutate media state, or issue proof.
CREATE TABLE IF NOT EXISTS evidence.media_review_task_facts (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  object_id text NOT NULL REFERENCES evidence.media_object_facts(id),
  object_root text NOT NULL CHECK (object_root ~ '^[0-9a-f]{64}$'),
  media_projection_state text NOT NULL CHECK (
    media_projection_state IN ('pending_scan', 'quarantined', 'duplicate', 'needs_review', 'available')
  ),
  media_projection_root text NOT NULL CHECK (media_projection_root ~ '^[0-9a-f]{64}$'),
  contributor_id text NOT NULL REFERENCES identity.participants(id),
  review_round integer NOT NULL CHECK (review_round > 0),
  previous_review_task_root text CHECK (
    previous_review_task_root IS NULL OR previous_review_task_root ~ '^[0-9a-f]{64}$'
  ),
  reason_codes text[] NOT NULL CHECK (cardinality(reason_codes) BETWEEN 1 AND 32),
  severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  policy_id text NOT NULL CHECK (length(btrim(policy_id)) BETWEEN 1 AND 240),
  opened_by text NOT NULL REFERENCES identity.participants(id),
  opener_snapshot jsonb NOT NULL CHECK (jsonb_typeof(opener_snapshot) = 'object'),
  opened_at timestamptz NOT NULL,
  due_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  task_hash text NOT NULL UNIQUE CHECK (task_hash ~ '^[0-9a-f]{64}$'),
  task_root text NOT NULL UNIQUE CHECK (task_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (object_id, review_round),
  UNIQUE (evidence_id, evidence_sequence),
  CHECK (opened_at < due_at)
);

CREATE INDEX IF NOT EXISTS evidence_media_review_task_org_time
  ON evidence.media_review_task_facts (organization_id, opened_at DESC, id);
CREATE INDEX IF NOT EXISTS evidence_media_review_task_object_round
  ON evidence.media_review_task_facts (object_id, review_round DESC, id);

CREATE TABLE IF NOT EXISTS evidence.media_review_assignment_facts (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  object_id text NOT NULL REFERENCES evidence.media_object_facts(id),
  task_id text NOT NULL UNIQUE REFERENCES evidence.media_review_task_facts(id),
  task_root text NOT NULL CHECK (task_root ~ '^[0-9a-f]{64}$'),
  contributor_id text NOT NULL REFERENCES identity.participants(id),
  reviewer_id text NOT NULL REFERENCES identity.participants(id),
  reviewer_snapshot jsonb NOT NULL CHECK (jsonb_typeof(reviewer_snapshot) = 'object'),
  assigned_by text NOT NULL REFERENCES identity.participants(id),
  assigner_snapshot jsonb NOT NULL CHECK (jsonb_typeof(assigner_snapshot) = 'object'),
  assigned_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  assignment_hash text NOT NULL UNIQUE CHECK (assignment_hash ~ '^[0-9a-f]{64}$'),
  assignment_root text NOT NULL UNIQUE CHECK (assignment_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence),
  CHECK (reviewer_id <> contributor_id),
  CHECK (reviewer_id <> assigned_by)
);

CREATE INDEX IF NOT EXISTS evidence_media_review_assignment_reviewer_time
  ON evidence.media_review_assignment_facts (reviewer_id, assigned_at DESC, id);

CREATE TABLE IF NOT EXISTS evidence.media_review_decision_facts (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  object_id text NOT NULL REFERENCES evidence.media_object_facts(id),
  task_id text NOT NULL UNIQUE REFERENCES evidence.media_review_task_facts(id),
  task_root text NOT NULL CHECK (task_root ~ '^[0-9a-f]{64}$'),
  assignment_id text NOT NULL UNIQUE REFERENCES evidence.media_review_assignment_facts(id),
  assignment_root text NOT NULL CHECK (assignment_root ~ '^[0-9a-f]{64}$'),
  media_projection_state text NOT NULL CHECK (
    media_projection_state IN ('pending_scan', 'quarantined', 'duplicate', 'needs_review', 'available')
  ),
  media_projection_root text NOT NULL CHECK (media_projection_root ~ '^[0-9a-f]{64}$'),
  reviewer_id text NOT NULL REFERENCES identity.participants(id),
  reviewer_snapshot jsonb NOT NULL CHECK (jsonb_typeof(reviewer_snapshot) = 'object'),
  decision text NOT NULL CHECK (
    decision IN ('accept_for_processing', 'retain_non_final', 'reject', 'quarantine', 'escalate')
  ),
  rationale_hash text NOT NULL CHECK (rationale_hash ~ '^[0-9a-f]{64}$'),
  limitation_hashes text[] NOT NULL CHECK (cardinality(limitation_hashes) BETWEEN 1 AND 32),
  decided_at timestamptz NOT NULL,
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  decision_hash text NOT NULL UNIQUE CHECK (decision_hash ~ '^[0-9a-f]{64}$'),
  decision_root text NOT NULL UNIQUE CHECK (decision_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (evidence_id, evidence_sequence),
  CHECK (decision <> 'accept_for_processing' OR media_projection_state = 'available')
);

CREATE INDEX IF NOT EXISTS evidence_media_review_decision_reviewer_time
  ON evidence.media_review_decision_facts (reviewer_id, decided_at DESC, id);

CREATE TABLE IF NOT EXISTS evidence.media_custody_event_facts (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organizations.organizations(id),
  project_id text NOT NULL REFERENCES projects.projects(id),
  evidence_id text NOT NULL REFERENCES evidence.evidence_objects(id),
  action text NOT NULL CHECK (action IN ('review_opened', 'review_assigned', 'review_decided')),
  artifact_type text NOT NULL CHECK (
    artifact_type IN ('media_review_task', 'media_review_assignment', 'media_review_decision')
  ),
  artifact_id text NOT NULL,
  source_root text NOT NULL CHECK (source_root ~ '^[0-9a-f]{64}$'),
  custodian_id text NOT NULL REFERENCES identity.participants(id),
  custodian_snapshot jsonb NOT NULL CHECK (jsonb_typeof(custodian_snapshot) = 'object'),
  custody_note_hash text NOT NULL CHECK (custody_note_hash ~ '^[0-9a-f]{64}$'),
  policy_id text NOT NULL CHECK (length(btrim(policy_id)) BETWEEN 1 AND 240),
  occurred_at timestamptz NOT NULL,
  previous_custody_root text NOT NULL CHECK (previous_custody_root ~ '^[0-9a-f]{64}$'),
  command_hash text NOT NULL UNIQUE CHECK (command_hash ~ '^[0-9a-f]{64}$'),
  evidence_sequence bigint NOT NULL CHECK (evidence_sequence > 0),
  previous_event_root text NOT NULL CHECK (previous_event_root ~ '^[0-9a-f]{64}$'),
  custody_hash text NOT NULL UNIQUE CHECK (custody_hash ~ '^[0-9a-f]{64}$'),
  custody_root text NOT NULL UNIQUE CHECK (custody_root ~ '^[0-9a-f]{64}$'),
  safety jsonb NOT NULL CHECK (jsonb_typeof(safety) = 'object'),
  audit_event_root text NOT NULL UNIQUE CHECK (audit_event_root ~ '^[0-9a-f]{64}$'),
  UNIQUE (artifact_type, artifact_id),
  UNIQUE (evidence_id, evidence_sequence)
);

CREATE INDEX IF NOT EXISTS evidence_media_custody_evidence_sequence
  ON evidence.media_custody_event_facts (evidence_id, evidence_sequence DESC, id);

CREATE OR REPLACE FUNCTION evidence.evidence_media_review_safety_canonical()
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT jsonb_build_object(
    'appendOnly', true,
    'organizationBound', true,
    'mediaObjectBound', true,
    'mediaProjectionBound', true,
    'semanticEventBound', true,
    'independentAccreditedHumanReviewerRequired', true,
    'reviewCannotOverrideProviderVerification', true,
    'custodyPreviousRootLinked', true,
    'noRawRationale', true,
    'noProviderCredential', true,
    'notFinalProofAuthority', true,
    'notCertifiedCarbonCredit', true,
    'notCarbonTaxOffset', true,
    'notFinancialAsset', true,
    'notGuaranteedYield', true,
    'noMainnetFunds', true,
    'notAutomaticCanopyDistribution', true
  );
$$;

