      WHEN 'review_assigned' THEN 'independent accredited reviewer assigned'
      ELSE 'independent review decision appended without authority promotion'
    END
  ));
$$;

CREATE OR REPLACE FUNCTION evidence.validate_media_review_task_fact_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  object_fact evidence.media_object_facts%ROWTYPE;
  intent evidence.media_upload_intent_facts%ROWTYPE;
  projection record;
  semantic_event audit.domain_events%ROWTYPE;
  previous_task evidence.media_review_task_facts%ROWTYPE;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  SELECT * INTO STRICT object_fact
  FROM evidence.media_object_facts
  WHERE id = NEW.object_id
  FOR SHARE;
  SELECT * INTO STRICT intent
  FROM evidence.media_upload_intent_facts
  WHERE id = object_fact.intent_id
  FOR SHARE;
  SELECT * INTO STRICT projection
  FROM evidence.media_object_projection(NEW.object_id, NEW.opened_at);
  SELECT * INTO STRICT semantic_event
  FROM audit.domain_events
  WHERE event_root = NEW.audit_event_root;
  SELECT candidate.* INTO previous_task
  FROM evidence.media_review_task_facts candidate
  WHERE candidate.object_id = NEW.object_id
  ORDER BY candidate.review_round DESC, candidate.id DESC
  LIMIT 1;

  IF transaction_actor_id IS NULL
     OR transaction_actor_id <> NEW.opened_by
     OR NEW.organization_id <> object_fact.organization_id
     OR NEW.project_id <> object_fact.project_id
     OR NEW.evidence_id <> object_fact.evidence_id
     OR NEW.object_root <> object_fact.object_root
     OR NEW.contributor_id <> intent.subject_id
     OR NEW.media_projection_state <> projection.state
     OR NEW.media_projection_root <> projection.projection_root
     OR NEW.review_round <> COALESCE(previous_task.review_round, 0) + 1
     OR NEW.previous_review_task_root IS DISTINCT FROM previous_task.task_root
     OR EXISTS (
       SELECT 1
       FROM evidence.media_review_task_facts task
       LEFT JOIN evidence.media_review_decision_facts decision ON decision.task_id = task.id
       WHERE task.object_id = NEW.object_id AND decision.id IS NULL
     )
     OR NOT audit.is_sorted_unique_text_array(NEW.reason_codes)
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.reason_codes) reason_code
       WHERE reason_code !~ '^[a-z0-9][a-z0-9_:-]{0,119}$'
     )
     OR NOT verification.actor_snapshot_is_valid(
       NEW.opener_snapshot,
       NEW.opened_by,
       NEW.organization_id,
       'human',
       ARRAY['owner', 'admin', 'verifier', 'researcher']::text[]
     )
     OR NEW.opened_at <> date_trunc('milliseconds', NEW.opened_at)
     OR NEW.due_at <> date_trunc('milliseconds', NEW.due_at)
     OR NEW.safety <> evidence.evidence_media_review_safety_canonical() THEN
    RAISE EXCEPTION 'evidence media review task authority is invalid';
  END IF;

  IF semantic_event.stream_id <> 'evidence-media:' || NEW.evidence_id
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.action <> 'REASON'
     OR semantic_event.actor_id <> NEW.opened_by
     OR semantic_event.entity_type <> 'evidence_media_review_task'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.created_at <> NEW.opened_at
     OR semantic_event.payload_hash <> evidence.media_review_task_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence media review task semantic event binding is invalid';
  END IF;

  IF NEW.command_hash <> evidence.media_review_task_command_hash(NEW)
     OR NEW.id <> 'cp_media_review_task_' || left(NEW.command_hash, 24)
     OR NEW.task_hash <> evidence.media_review_task_hash(NEW)
     OR NEW.task_root <> evidence.media_review_task_root(NEW) THEN
    RAISE EXCEPTION 'evidence media review task hash lineage is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION evidence.validate_media_review_assignment_fact_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  task evidence.media_review_task_facts%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  SELECT * INTO STRICT task
  FROM evidence.media_review_task_facts
  WHERE id = NEW.task_id
  FOR SHARE;
  SELECT * INTO STRICT semantic_event
  FROM audit.domain_events
  WHERE event_root = NEW.audit_event_root;

  IF transaction_actor_id IS NULL
     OR transaction_actor_id <> NEW.assigned_by
     OR NEW.organization_id <> task.organization_id
     OR NEW.project_id <> task.project_id
     OR NEW.evidence_id <> task.evidence_id
     OR NEW.object_id <> task.object_id
     OR NEW.task_root <> task.task_root
     OR NEW.contributor_id <> task.contributor_id
     OR NEW.reviewer_id IN (task.contributor_id, task.opened_by, NEW.assigned_by)
     OR NEW.reviewer_snapshot->>'role' <> 'verifier'
     OR NEW.reviewer_snapshot->>'accreditationStatus' <> 'approved'
     OR NOT (NEW.reviewer_snapshot->'accreditationScope' ? 'evidence_media_review')
     OR NOT verification.actor_snapshot_is_valid(
       NEW.reviewer_snapshot,
       NEW.reviewer_id,
       NEW.organization_id,
       'human',
       ARRAY['verifier']::text[]
     )
     OR NOT verification.actor_snapshot_is_valid(
       NEW.assigner_snapshot,
       NEW.assigned_by,
       NEW.organization_id,
       'human',
       ARRAY['owner', 'admin']::text[]
     )
     OR NEW.assigned_at < task.opened_at
     OR NEW.assigned_at <> date_trunc('milliseconds', NEW.assigned_at)
     OR NEW.safety <> evidence.evidence_media_review_safety_canonical() THEN
    RAISE EXCEPTION 'evidence media review assignment authority is invalid';
  END IF;

  IF semantic_event.stream_id <> 'evidence-media:' || NEW.evidence_id
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.action <> 'DELEGATE'
     OR semantic_event.actor_id <> NEW.assigned_by
     OR semantic_event.entity_type <> 'evidence_media_review_assignment'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.created_at <> NEW.assigned_at
     OR semantic_event.payload_hash <> evidence.media_review_assignment_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence media review assignment semantic event binding is invalid';
  END IF;

  IF NEW.command_hash <> evidence.media_review_assignment_command_hash(NEW)
     OR NEW.id <> 'cp_media_review_assignment_' || left(NEW.command_hash, 24)
     OR NEW.assignment_hash <> evidence.media_review_assignment_hash(NEW)
     OR NEW.assignment_root <> evidence.media_review_assignment_root(NEW) THEN
    RAISE EXCEPTION 'evidence media review assignment hash lineage is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION evidence.validate_media_review_decision_fact_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  task evidence.media_review_task_facts%ROWTYPE;
  assignment evidence.media_review_assignment_facts%ROWTYPE;
  projection record;
  semantic_event audit.domain_events%ROWTYPE;
  expected_action text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');
  SELECT * INTO STRICT task
  FROM evidence.media_review_task_facts
  WHERE id = NEW.task_id
  FOR SHARE;
  SELECT * INTO STRICT assignment
  FROM evidence.media_review_assignment_facts
  WHERE id = NEW.assignment_id
  FOR SHARE;
  SELECT * INTO STRICT projection
  FROM evidence.media_object_projection(NEW.object_id, NEW.decided_at);
  SELECT * INTO STRICT semantic_event
  FROM audit.domain_events
  WHERE event_root = NEW.audit_event_root;
  expected_action := CASE
    WHEN NEW.decision IN ('accept_for_processing', 'retain_non_final') THEN 'FULFILL'
    ELSE 'CHALLENGE'
  END;

  IF transaction_actor_id IS NULL
     OR transaction_actor_id <> NEW.reviewer_id
     OR NEW.organization_id <> task.organization_id
     OR NEW.project_id <> task.project_id
     OR NEW.evidence_id <> task.evidence_id
     OR NEW.object_id <> task.object_id
     OR NEW.task_root <> task.task_root
     OR NEW.assignment_id <> assignment.id
     OR NEW.assignment_root <> assignment.assignment_root
     OR assignment.task_id <> task.id
     OR NEW.reviewer_id <> assignment.reviewer_id
     OR NEW.reviewer_snapshot <> assignment.reviewer_snapshot
     OR NOT verification.actor_snapshot_is_valid(
       NEW.reviewer_snapshot,
       NEW.reviewer_id,
       NEW.organization_id,
       'human',
       ARRAY['verifier']::text[]
     )
     OR NEW.reviewer_snapshot->>'accreditationStatus' <> 'approved'
     OR NOT (NEW.reviewer_snapshot->'accreditationScope' ? 'evidence_media_review')
     OR NEW.media_projection_state <> projection.state
     OR NEW.media_projection_root <> projection.projection_root
     OR (NEW.decision = 'accept_for_processing' AND projection.state <> 'available')
     OR NEW.decided_at < assignment.assigned_at
     OR NEW.decided_at <> date_trunc('milliseconds', NEW.decided_at)
     OR NOT audit.is_sorted_unique_text_array(NEW.limitation_hashes)
     OR EXISTS (
       SELECT 1 FROM unnest(NEW.limitation_hashes) limitation_hash
       WHERE limitation_hash !~ '^[0-9a-f]{64}$'
     )
     OR NEW.safety <> evidence.evidence_media_review_safety_canonical() THEN
    RAISE EXCEPTION 'evidence media review decision authority is invalid';
  END IF;

  IF semantic_event.stream_id <> 'evidence-media:' || NEW.evidence_id
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.action <> expected_action
     OR semantic_event.actor_id <> NEW.reviewer_id
     OR semantic_event.entity_type <> 'evidence_media_review_decision'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.created_at <> NEW.decided_at
     OR semantic_event.payload_hash <> evidence.media_review_decision_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence media review decision semantic event binding is invalid';
  END IF;

  IF NEW.command_hash <> evidence.media_review_decision_command_hash(NEW)
     OR NEW.id <> 'cp_media_review_decision_' || left(NEW.command_hash, 24)
     OR NEW.decision_hash <> evidence.media_review_decision_hash(NEW)
     OR NEW.decision_root <> evidence.media_review_decision_root(NEW) THEN
    RAISE EXCEPTION 'evidence media review decision hash lineage is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION evidence.validate_media_custody_event_fact_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  transaction_actor_id text;
  task evidence.media_review_task_facts%ROWTYPE;
  assignment evidence.media_review_assignment_facts%ROWTYPE;
  decision evidence.media_review_decision_facts%ROWTYPE;
  semantic_event audit.domain_events%ROWTYPE;
  expected_action text;
  expected_artifact_type text;
  expected_source_root text;
  expected_custodian_id text;
  expected_custodian_snapshot jsonb;
  expected_policy_id text;
  expected_occurred_at timestamptz;
  expected_organization_id text;
  expected_project_id text;
  expected_evidence_id text;
  expected_source_event_root text;
  expected_source_sequence bigint;
  expected_previous_custody_root text;
BEGIN
  transaction_actor_id := NULLIF(btrim(current_setting('app.actor_id', true)), '');

  IF NEW.action = 'review_opened' THEN
    SELECT * INTO STRICT task
    FROM evidence.media_review_task_facts
    WHERE id = NEW.artifact_id
    FOR SHARE;

    expected_action := 'REASON';
    expected_artifact_type := 'media_review_task';
    expected_source_root := task.task_root;
    expected_custodian_id := task.opened_by;
    expected_custodian_snapshot := task.opener_snapshot;
    expected_policy_id := task.policy_id;
    expected_occurred_at := task.opened_at;
    expected_organization_id := task.organization_id;
    expected_project_id := task.project_id;
    expected_evidence_id := task.evidence_id;
    expected_source_event_root := task.audit_event_root;
    expected_source_sequence := task.evidence_sequence;
  ELSIF NEW.action = 'review_assigned' THEN
    SELECT * INTO STRICT assignment
    FROM evidence.media_review_assignment_facts
    WHERE id = NEW.artifact_id
    FOR SHARE;
    SELECT * INTO STRICT task
    FROM evidence.media_review_task_facts
    WHERE id = assignment.task_id
    FOR SHARE;

    expected_action := 'DELEGATE';
    expected_artifact_type := 'media_review_assignment';
    expected_source_root := assignment.assignment_root;
    expected_custodian_id := assignment.assigned_by;
    expected_custodian_snapshot := assignment.assigner_snapshot;
    expected_policy_id := task.policy_id;
    expected_occurred_at := assignment.assigned_at;
    expected_organization_id := assignment.organization_id;
    expected_project_id := assignment.project_id;
    expected_evidence_id := assignment.evidence_id;
    expected_source_event_root := assignment.audit_event_root;
    expected_source_sequence := assignment.evidence_sequence;
  ELSE
    SELECT * INTO STRICT decision
    FROM evidence.media_review_decision_facts
    WHERE id = NEW.artifact_id
    FOR SHARE;
    SELECT * INTO STRICT task
    FROM evidence.media_review_task_facts
    WHERE id = decision.task_id
    FOR SHARE;

    expected_action := CASE
      WHEN decision.decision IN ('accept_for_processing', 'retain_non_final') THEN 'FULFILL'
      ELSE 'CHALLENGE'
    END;
    expected_artifact_type := 'media_review_decision';
    expected_source_root := decision.decision_root;
    expected_custodian_id := decision.reviewer_id;
    expected_custodian_snapshot := decision.reviewer_snapshot;
    expected_policy_id := task.policy_id;
    expected_occurred_at := decision.decided_at;
    expected_organization_id := decision.organization_id;
    expected_project_id := decision.project_id;
    expected_evidence_id := decision.evidence_id;
    expected_source_event_root := decision.audit_event_root;
    expected_source_sequence := decision.evidence_sequence;
  END IF;

  SELECT candidate.custody_root INTO expected_previous_custody_root
  FROM evidence.media_custody_event_facts candidate
  WHERE candidate.evidence_id = NEW.evidence_id
  ORDER BY candidate.evidence_sequence DESC, candidate.id DESC
  LIMIT 1
  FOR SHARE;
  expected_previous_custody_root := COALESCE(
    expected_previous_custody_root,
    evidence.media_custody_genesis(NEW.evidence_id)
  );

  SELECT * INTO STRICT semantic_event
  FROM audit.domain_events
  WHERE event_root = NEW.audit_event_root;

  IF transaction_actor_id IS NULL
     OR transaction_actor_id <> NEW.custodian_id
     OR NEW.artifact_type <> expected_artifact_type
     OR NEW.source_root <> expected_source_root
     OR NEW.custodian_id <> expected_custodian_id
     OR NEW.custodian_snapshot <> expected_custodian_snapshot
     OR NEW.policy_id <> expected_policy_id
     OR NEW.occurred_at <> expected_occurred_at
     OR NEW.organization_id <> expected_organization_id
     OR NEW.project_id <> expected_project_id
     OR NEW.evidence_id <> expected_evidence_id
     OR NEW.evidence_sequence <> expected_source_sequence + 1
     OR NEW.previous_event_root <> expected_source_event_root
     OR NEW.previous_custody_root <> expected_previous_custody_root
     OR NEW.custody_note_hash <> evidence.media_custody_note_hash(NEW.action)
     OR NOT verification.actor_snapshot_is_valid(
       NEW.custodian_snapshot,
       NEW.custodian_id,
       NEW.organization_id,
       'human',
       ARRAY['owner', 'admin', 'verifier', 'researcher']::text[]
     )
     OR NEW.occurred_at <> date_trunc('milliseconds', NEW.occurred_at)
     OR NEW.safety <> evidence.evidence_media_review_safety_canonical() THEN
    RAISE EXCEPTION 'evidence media custody authority is invalid';
  END IF;

  IF semantic_event.stream_id <> 'evidence-media:' || NEW.evidence_id
     OR semantic_event.sequence_no <> NEW.evidence_sequence
     OR semantic_event.action <> expected_action
     OR semantic_event.actor_id <> NEW.custodian_id
     OR semantic_event.entity_type <> 'evidence_media_custody_event'
     OR semantic_event.entity_id <> NEW.id
     OR semantic_event.previous_root <> NEW.previous_event_root
     OR semantic_event.created_at <> NEW.occurred_at
     OR semantic_event.payload_hash <> evidence.media_custody_payload_hash(NEW) THEN
    RAISE EXCEPTION 'evidence media custody semantic event binding is invalid';
  END IF;

  IF NEW.command_hash <> evidence.media_custody_command_hash(NEW)
     OR NEW.id <> 'cp_media_custody_' || left(NEW.command_hash, 24)
     OR NEW.custody_hash <> evidence.media_custody_hash(NEW)
     OR NEW.custody_root <> evidence.media_custody_root(NEW) THEN
    RAISE EXCEPTION 'evidence media custody hash lineage is invalid';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS evidence_media_review_task_facts_validate
  ON evidence.media_review_task_facts;
CREATE TRIGGER evidence_media_review_task_facts_validate
BEFORE INSERT ON evidence.media_review_task_facts
FOR EACH ROW EXECUTE FUNCTION evidence.validate_media_review_task_fact_insert();

