-- Idempotent backfill for installations that predate authority fences. These
-- rows are concurrency primitives, never evidence or projected trust state.
INSERT INTO audit.authority_fences (authority_key, revision, updated_at)
SELECT authority_key, 1, clock_timestamp()
FROM (
  SELECT 'project:' || project.id AS authority_key
  FROM projects.projects project
  UNION
  SELECT 'evidence-custody:' || receipt.subject_id AS authority_key
  FROM evidence.consent_receipts receipt
  UNION
  SELECT 'evidence-custody:' || attestation.subject_id AS authority_key
  FROM identity.device_attestations attestation
) authority
ON CONFLICT (authority_key) DO NOTHING;
